"""bootstrap.py - 一键生成 auto-clicker 完整项目

运行方式:
    python bootstrap.py [目标目录]

不传参数时默认在当前目录下创建 auto-clicker/ 子目录。
所有文件内容（含文本与二进制资源）全部硬编码在本脚本中，
运行时不需要读取原始项目的任何文件。

注意：若目标目录已存在且非空，脚本会确认后【清空】该目录再生成，
      因此不要把它指向正在开发的源码目录（脚本会直接拒绝这种情况）。

开发维护:
    python bootstrap.py --sync
        用当前仓库中的最新源码刷新下方 FILES / ASSETS_B64 内嵌快照。
        改动 app/ 等文件后运行一次，避免快照与源码漂移。

关于控制台输出：运行期打印的文案一律保持 ASCII。中文 Windows 的控制台默认是
GBK 代码页，混入「×」「→」这类字符会直接抛 UnicodeEncodeError。注释和文档串
用中文不受影响（它们不经过 stdout）。
"""
from __future__ import annotations

import base64
import shutil
import sys
from pathlib import Path


# ============================================================
# 文本文件内容（硬编码，保留原始行尾）
# 以下两个字典由 `python bootstrap.py --sync` 从当前仓库源码自动生成，
# 改动 app/ 等文件后请运行该命令刷新快照，勿手工编辑。
# 需要新增内嵌文件时，在 FILES 中手工加一个键（值随意），再运行 --sync 填充。
# 需要新增二进制资源时，在 ASSETS_B64 中加一个键即可。
# ============================================================
# <<<SYNC:BEGIN>>>
FILES = {
    '.github/workflows/windows.yml': 'name: Windows 验证\n\n# 为什么必须在 Windows runner 上跑\n# --------------------------------\n# app/win/* 在 import 阶段就调 ctypes.WinDLL，Linux/macOS 上整套逻辑连 import 都过不去；\n# 唯一一处「真的建窗口、真的投消息」的验证（tests/test_win_integration.py）更是只能在\n# Windows 上执行。所以这套 CI 没有别的选择。\n#\n# 仓库公开，GitHub Actions 对公开仓库不计分钟，Windows runner 双倍计费在这里不花钱。\n\non:\n  push:\n    branches: [main]\n  pull_request:\n  workflow_dispatch:\n\nconcurrency:\n  group: windows-${{ github.ref }}\n  cancel-in-progress: true\n\njobs:\n  # ---------------------------------------------------------------- 快照一致性\n  snapshot:\n    name: 内嵌快照与仓库一致\n    # 纯粹的文件读写，不需要 Windows\n    runs-on: ubuntu-latest\n    timeout-minutes: 10\n    steps:\n      - uses: actions/checkout@v4\n\n      - uses: actions/setup-python@v5\n        with:\n          python-version: "3.11"\n\n      - name: 生成一份并逐字节比对\n        run: |\n          python bootstrap.py "$RUNNER_TEMP/generated" >/dev/null\n          python - "$RUNNER_TEMP/generated" <<\'PY\'\n          import sys\n          from pathlib import Path\n\n          generated = Path(sys.argv[1])\n          repo = Path.cwd()\n          ignore = {".git", "__pycache__", ".pytest_cache"}\n\n          def collect(root):\n              found = {}\n              for path in root.rglob("*"):\n                  if not path.is_file():\n                      continue\n                  rel = path.relative_to(root)\n                  if any(part in ignore for part in rel.parts):\n                      continue\n                  found[rel.as_posix()] = path\n              return found\n\n          want = collect(generated)\n          have = collect(repo)\n          have.pop("bootstrap.py", None)  # 生成器自己不进快照\n\n          problems = []\n          for name in sorted(set(want) | set(have)):\n              if name not in have:\n                  problems.append(f"快照里有、仓库里没有: {name}")\n              elif name not in want:\n                  problems.append(f"仓库里有、快照里没有: {name}")\n              elif want[name].read_bytes() != have[name].read_bytes():\n                  problems.append(f"内容不一致: {name}")\n\n          if problems:\n              print("内嵌快照与仓库不一致：")\n              for line in problems:\n                  print("  -", line)\n              print()\n              print("修法：在仓库根目录跑 `python bootstrap.py --sync`，然后提交改动。")\n              sys.exit(1)\n\n          print(f"内嵌快照与仓库逐字节一致（{len(want)} 个文件）")\n          PY\n\n  # ---------------------------------------------------------------- 真实窗口\n  integration:\n    name: 后台点击集成测试（真实 Win32 窗口）\n    runs-on: windows-latest\n    timeout-minutes: 15\n    steps:\n      - uses: actions/checkout@v4\n\n      - uses: actions/setup-python@v5\n        with:\n          python-version: "3.11"\n\n      - name: 环境信息\n        run: python -c "import platform, sys; print(sys.version); print(platform.platform())"\n\n      - name: 跑集成测试\n        # 不需要 PySide6：这个文件只碰 ctypes 与 app.win / app.input 里两个纯 Win32 模块\n        run: python tests/test_win_integration.py\n\n  # ---------------------------------------------------------------- 冒烟\n  smoke:\n    name: 冒烟测试（Qt offscreen）\n    runs-on: windows-latest\n    timeout-minutes: 20\n    env:\n      QT_QPA_PLATFORM: offscreen\n    steps:\n      - uses: actions/checkout@v4\n\n      - uses: actions/setup-python@v5\n        with:\n          python-version: "3.11"\n          cache: pip\n\n      - name: 安装依赖\n        run: |\n          python -m pip install --upgrade pip\n          pip install -r requirements.txt\n\n      - name: 跑冒烟测试\n        run: python tests/test_smoke.py\n',
    'main.py': '"""AutoClicker 入口。\n\n启动顺序很关键：\n1. 声明 DPI 感知（必须在任何窗口 / QApplication 之前，否则坐标会被系统虚拟化）；\n2. 初始化日志；\n3. 创建 QApplication；\n4. 抢占单实例锁，已被占用则直接提示退出；\n5. 装配后端 / 热键 / 主窗口并进入事件循环。\n"""\n\nfrom __future__ import annotations\n\nimport logging\nimport sys\nfrom pathlib import Path\n\n# 以源码方式运行时，保证 `import app.xxx` 可用（打包后由 PyInstaller 处理）\n_ROOT = Path(__file__).resolve().parent\nif str(_ROOT) not in sys.path:\n    sys.path.insert(0, str(_ROOT))\n\nfrom app import APP_NAME, __version__  # noqa: E402\nfrom app.win.dpi import enable_dpi_awareness  # noqa: E402\n\nlogger = logging.getLogger("autoclicker.main")\n\n# 单实例互斥量句柄必须活到进程结束，因此提升到模块级\n_guard = None\n\n\ndef main() -> int:\n    global _guard\n\n    # 1. DPI 感知必须最先执行\n    awareness = enable_dpi_awareness()\n\n    # 2. 日志\n    from app.utils.logger import setup_logging\n\n    setup_logging()\n    logger.info("%s v%s 启动（DPI 感知=%s, Python %s）", APP_NAME, __version__, awareness, sys.version.split()[0])\n\n    # 3. Qt\n    from PySide6.QtWidgets import QApplication, QMessageBox\n\n    from app.input.sendinput import SendInputBackend\n    from app.ui.icon import app_icon\n    from app.ui.main_window import MainWindow\n    from app.win.admin import is_admin\n    from app.win.hotkey import HotkeyManager\n    from app.win.singleton import SingleInstance\n\n    app = QApplication(sys.argv)\n    app.setApplicationName(APP_NAME)\n    app.setApplicationDisplayName(APP_NAME)\n    app.setApplicationVersion(__version__)\n    app.setWindowIcon(app_icon())\n    # 关闭主窗口只是隐藏到托盘，不能顺带退出进程\n    app.setQuitOnLastWindowClosed(False)\n\n    # 4. 单实例\n    _guard = SingleInstance()\n    if not _guard.acquire():\n        logger.warning("检测到已有实例在运行，退出")\n        QMessageBox.information(None, APP_NAME, f"{APP_NAME} 已在运行中。")\n        return 0\n\n    # 5. 装配\n    backend = SendInputBackend()\n    hotkeys = HotkeyManager(app)\n    window = MainWindow(backend, hotkeys)\n\n    if not is_admin():\n        logger.info("当前以普通权限运行")\n        window.log_append.emit(\n            "[注意] 当前为普通权限。若目标程序以管理员身份运行，"\n            "UIPI 会丢弃本工具注入的点击（表现为「点了没反应」），此时请以管理员身份重新运行本工具。"\n        )\n\n    window.show()\n\n    exit_code = app.exec()\n    logger.info("%s 退出，code=%s", APP_NAME, exit_code)\n    return exit_code\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n',
    'requirements.txt': '# 运行期依赖（核心只需要 PySide6，其余全部走标准库 ctypes）\nPySide6>=6.6\n\n# 打包用（开发期依赖）\n# pyinstaller>=6.0\n',
    'build.bat': '@echo off\r\nsetlocal\r\n\r\nREM ===========================================================================\r\nREM  AutoClicker - Windows one-click build (PyInstaller, single-file)\r\nREM\r\nREM  Usage: double-click it, or run `build.bat` from a shell.\r\nREM\r\nREM  NOTE 1: this file must keep CRLF line endings. cmd.exe mis-parses\r\nREM          multi-line blocks (if / for ... ) that use bare LF.\r\nREM  NOTE 2: all console output is kept ASCII on purpose - the OEM code page\r\nREM          on a Chinese Windows is GBK, and mixing encodings garbles it.\r\nREM ===========================================================================\r\n\r\ncd /d "%~dp0"\r\n\r\necho ============================================\r\necho  AutoClicker Build\r\necho ============================================\r\n\r\necho [1/4] Running smoke tests ...\r\npython tests\\test_smoke.py\r\nif errorlevel 1 (\r\n    echo.\r\n    echo [ERROR] Smoke tests failed - not building a broken exe\r\n    pause\r\n    exit /b 1\r\n)\r\necho.\r\n\r\npython -m PyInstaller --version >nul 2>&1\r\nif errorlevel 1 (\r\n    echo [ERROR] PyInstaller is not installed for this python\r\n    echo         Run: python -m pip install pyinstaller\r\n    pause\r\n    exit /b 1\r\n)\r\n\r\nif not exist main.py (\r\n    echo [ERROR] main.py not found - run this script from the project root\r\n    pause\r\n    exit /b 1\r\n)\r\n\r\nREM Optional: put an AutoClicker.ico next to this script and it gets baked\r\nREM into the exe. The window/tray icon is drawn in code either way, so this\r\nREM only changes what Explorer shows for the file itself.\r\nset "ICON_OPT="\r\nif exist AutoClicker.ico set "ICON_OPT=--icon AutoClicker.ico"\r\n\r\necho [2/4] Cleaning build\\ and dist\\ ...\r\nif exist build rmdir /s /q build\r\nif exist dist rmdir /s /q dist\r\n\r\necho [3/4] Building AutoClicker.exe ...\r\nREM --onefile : single exe, no _internal folder\r\nREM --windowed: no console window (this is a GUI app; it logs to a file)\r\nREM excludes : drop the Qt subsystems this app never imports. PySide6 ships\r\nREM            every module as its own DLL, so this is most of the size.\r\nREM            Add --uac-admin here if the target program runs elevated\r\nREM            (UIPI silently drops injected input otherwise).\r\npython -m PyInstaller ^\r\n    --noconfirm ^\r\n    --clean ^\r\n    --onefile ^\r\n    --windowed ^\r\n    --name AutoClicker ^\r\n    %ICON_OPT% ^\r\n    --exclude-module tkinter ^\r\n    --exclude-module matplotlib ^\r\n    --exclude-module numpy ^\r\n    --exclude-module pandas ^\r\n    --exclude-module scipy ^\r\n    --exclude-module PySide6.QtQml ^\r\n    --exclude-module PySide6.QtQuick ^\r\n    --exclude-module PySide6.QtWebEngineCore ^\r\n    --exclude-module PySide6.QtWebEngineWidgets ^\r\n    --exclude-module PySide6.QtWebChannel ^\r\n    --exclude-module PySide6.QtWebSockets ^\r\n    --exclude-module PySide6.QtMultimedia ^\r\n    --exclude-module PySide6.QtCharts ^\r\n    --exclude-module PySide6.QtDataVisualization ^\r\n    --exclude-module PySide6.Qt3DCore ^\r\n    --exclude-module PySide6.QtSql ^\r\n    --exclude-module PySide6.QtTest ^\r\n    --exclude-module PySide6.QtPdf ^\r\n    --exclude-module PySide6.QtBluetooth ^\r\n    --exclude-module PySide6.QtNfc ^\r\n    --exclude-module PySide6.QtPositioning ^\r\n    --exclude-module PySide6.QtSensors ^\r\n    --exclude-module PySide6.QtSerialPort ^\r\n    --exclude-module PySide6.QtSpatialAudio ^\r\n    --exclude-module PySide6.QtStateMachine ^\r\n    --exclude-module PySide6.QtRemoteObjects ^\r\n    --exclude-module PySide6.QtNetworkAuth ^\r\n    --exclude-module PySide6.QtDesigner ^\r\n    --exclude-module PySide6.QtHelp ^\r\n    --exclude-module PySide6.QtUiTools ^\r\n    --exclude-module PySide6.QtSvgWidgets ^\r\n    --exclude-module PySide6.QtTextToSpeech ^\r\n    main.py\r\n\r\nif errorlevel 1 (\r\n    echo.\r\n    echo [ERROR] Build failed\r\n    pause\r\n    exit /b 1\r\n)\r\n\r\nif not exist dist\\AutoClicker.exe (\r\n    echo.\r\n    echo [ERROR] PyInstaller reported success but dist\\AutoClicker.exe is missing\r\n    pause\r\n    exit /b 1\r\n)\r\n\r\nfor %%I in ("dist\\AutoClicker.exe") do set "EXE_SIZE=%%~zI"\r\n\r\necho.\r\necho [4/4] Build success\r\necho Output: dist\\AutoClicker.exe  (%EXE_SIZE% bytes)\r\necho.\r\necho Reminder: profiles and logs live in %%LOCALAPPDATA%%\\AutoClicker,\r\necho           so replacing the exe never loses user settings.\r\npause\r\n',
    '.gitattributes': '# 行尾完全由本文件决定，不跟随各机器上的 core.autocrlf。\n# 本机系统级 core.autocrlf=true，若不加这层约束，克隆下来的 .py 会变成 CRLF，\n# 与 bootstrap.py 内嵌的快照（LF）不一致，--sync 会莫名其妙地把 41 个文件全改一遍。\n* text=auto eol=lf\n\n# 例外：cmd.exe 解析多行 if ( ... ) / for 以及续行 ^ 时依赖 CRLF，\n# 行尾被改成 LF 会直接解析错乱。必须锁定。\n*.bat text eol=crlf\n',
    '.gitignore': '__pycache__/\n*.py[cod]\n*.egg-info/\n.venv/\nvenv/\nenv/\nbuild/\ndist/\n*.spec\n.pytest_cache/\n.idea/\n.vscode/\n',
    'README.md': '# AutoClicker · Windows 10 自动点击器\n\n[![Windows 验证](https://github.com/jimmy-yao/autoClicker/actions/workflows/windows.yml/badge.svg)](https://github.com/jimmy-yao/autoClicker/actions/workflows/windows.yml)\n\n基于 **Python 3 + PySide6** 的桌面自动化工具，输入注入走 Win32 `SendInput`，\n不依赖任何第三方输入库。\n\n当前版本：**P4** — 在 P3 的找图之上加了**后台点击**：用 `PostMessage` 把点击直接投给目标窗口，\n不移动系统光标，运行期间可以正常用鼠标。\n\n- **P3** — 找图：等屏幕上出现某张图片再继续。\n- **P2** — 录制回放。\n- **P1 / P0** — 步骤序列、方案管理、热键、托盘、单实例、DPI。\n\n> 📖 面向使用者的操作说明见 [`docs/USAGE.md`](docs/USAGE.md)。\n\n---\n\n## 功能\n\n| 功能 | 状态 |\n|---|---|\n| 步骤序列：点击 / 延时 / 按键 / 移动 / **找图** 按顺序执行 | ✅ P3 |\n| **后台点击**：`PostMessage` 投递，不占用鼠标、不要求目标窗口在前台 | ✅ P4 |\n| 前台（`SendInput`）/ 后台（`PostMessage`）两种输入方式可切换，后台可**绑定窗口** | ✅ P4 |\n| **找图**：拖框截模板，等它出现再点它，超时可继续可中止 | ✅ P3 |\n| 找图支持容差、轮询间隔、点击偏移、超时策略；可「模拟测试」先试一次 | ✅ P3 |\n| 找图超时中止时自动存一张现场截图，便于事后比对 | ✅ P3 |\n| **录制回放**：F11 开始录，F10 结束，自动生成步骤序列 | ✅ P2 |\n| 录制时可选「屏蔽输入」，空录坐标与节奏、绝不误点 | ✅ P2 |\n| 鼠标轨迹录制（折线 + 总时长，一个移动只占一行） | ✅ P2 |\n| 连点 / 连按自动合并成「重复次数 + 间隔」 | ✅ P2 |\n| 步骤的自增、编辑、删除、上移下移、临时停用 | ✅ P1 |\n| 坐标拾取（F8），支持从主窗口或编辑对话框内触发 | ✅ P1 |\n| 点击参数：按键、次数、间隔、间隔抖动、坐标抖动 | ✅ P1 |\n| 方案管理：新建 / 保存 / 另存为 / 重命名 / 删除，JSON 落盘 | ✅ P1 |\n| 序列轮数（含无限）、轮次间隔、启动延迟 | ✅ P1 |\n| 全局热键 开始 F9 / 停止 F10 / 拾取 F8 / 录制 F11 | ✅ P2 |\n| 系统托盘常驻、关闭即最小化、托盘菜单 | ✅ P1 |\n| 实时进度（第几轮 / 第几步 / 累计动作数）与日志面板 | ✅ P1 |\n| 单实例、DPI 感知、权限检测、滚动日志文件 | ✅ P0 |\n| 找色、限定搜索区域、坐标相对目标窗口（跟随窗口移动） | ⏳ 后续 |\n\n---\n\n## 环境要求\n\n- Windows 10 / 11\n- Python 3.10+（开发环境实测 3.13.14）\n- PySide6\n\n```powershell\npip install -r requirements.txt\n```\n\n---\n\n## 运行\n\n```powershell\npython main.py\n```\n\n### 快速上手\n\n1. **新建一个点击步骤**：点「+ 点击」。\n2. **设定坐标**：在对话框里点「拾取坐标 (F8)」，屏幕变暗后移动鼠标到目标位置，**左键**确认。\n   （对话框会先自动隐藏，拾取完再弹回来。也可以直接在主窗口选中某一行后按 F8 改写坐标。）\n3. **继续加步骤**：比如再加一个「+ 延时」等页面加载，再加一个「+ 按键」。\n4. 需要的话勾掉某几步的「启用」列，临时跳过它们。\n5. 设置**序列轮数**（填 `0` 为无限）和**启动延迟**（留出切窗口的余量）。\n6. 按 **F9** 开始（窗口会自动最小化），**F10** 停止。\n7. 需要**不占用鼠标**、或目标窗口不能拿到前台时，勾上「**后台点击 (不占用鼠标)**」\n   （建议再点「绑定窗口」选定目标）——能力与限制见下文「后台点击」一节。\n\n> ⚠️ 默认的 `SendInput` 是前台注入，会真实移动系统光标并产生真实点击，运行期间**不要移动鼠标**；\n> 改用后台点击后就不再占用鼠标（但适用面更窄，见下文）。\n\n### 录制回放\n\n不用一个个手搭步骤，直接录一遍：\n\n1. 点「录制 (F11)」（或直接按 **F11**）。主窗口会让开，屏幕顶部出现「● 录制中」指示条。\n2. 正常操作鼠标键盘。指示条会实时显示已录到的「点击/按键」数与「移动采样」数。\n3. 按 **F10** 结束录制。\n4. 弹窗让你选：**替换当前步骤** / **追加到末尾** / **丢弃**。\n5. 内容进步骤表后可以直接编辑、调时长、调顺序，再按 F9 回放。\n\n录完之后想微调坐标，不用重录：选中那一行按 **F8** 即可。点击步骤改的是落点坐标，\n移动步骤改的是**终点**（起点保留、中间拐点拉直）。\n\n录制会自动做三件「整理」工作，所以结果通常比想象中干净：\n\n- **连点合并**：同一个点连点 5 下 → 一个「点击 ×5，间隔 150ms」的步骤，而不是 5 行；\n- **连按合并**：同一个键重复按 → 一个「按键 ×N」；\n- **轨迹压缩**：一整段鼠标移动 → **一个**「移动」步骤（内部存折线拐点 + 总时长），\n  默认抽稀到 12px / 80ms 一个点，2px 以内的手抖直接丢掉。\n\n两个可选开关（都在录制按钮右边）：\n\n| 开关 | 默认 | 作用 |\n|---|---|---|\n| 记录鼠标移动 | 开 | 关掉后只录点击和按键，步骤更精简。开着才能还原「移到菜单上再点」这类悬停操作。 |\n| 屏蔽输入 | 关 | 勾上后录制期间鼠标键盘**不会传给任何程序**，纯空录坐标和节奏，绝不会误点。代价是「点开菜单→再点菜单项」这种有依赖的流程录不出来（因为菜单根本不会打开）。 |\n\n> 「屏蔽输入」勾上时 F10 是**唯一**的结束方式，因此本工具会先确认 F10 热键注册成功才允许开录，\n> 避免把你自己锁在一个点不动的系统里。不勾选时 F10 依然是最方便的结束方式，但托盘菜单也能结束。\n\n录制期间不记录「工具自己的控制键」（F8/F9/F10/F11），也不会记录其它程序注入的事件\n（`LLMHF_INJECTED` / `LLKHF_INJECTED`），所以不会把回放动作又录一遍。\n\n### 找图（等某个东西出现）\n\n「录制」只能记下「什么时候做了什么」，记不下「等某个按钮出现再点」。要找图步骤来补：\n\n1. 点「**+ 找图**」，对话框里点「**截取屏幕**」。\n2. 屏幕会压暗，**左键拖一个框**框住要认的目标（比如那个「继续」按钮），松手即完成截取。\n   框太小会被当成误触，直接重拖一次即可；右键或 Esc 取消。\n3. 回到对话框，上方会显示模板预览图和尺寸，并提示这块画面「含多少像素的纯色区域」。\n   出现**橙色警告**说明这块画面没有纯色底色，匹配只能逐像素硬碰，建议把按钮的底色一起框进来。\n4. 调参数（一般默认值就够）：\n\n   | 字段 | 说明 |\n   |---|---|\n   | 容差 | 抽样比对时每个像素通道允许的色差，默认 32。主要用于容忍文字抗锯齿。 |\n   | 超时 | 最多等多久，默认 30 秒。填 `0` 表示只找一次，找不到立刻按「超时后」处理。 |\n   | 轮询间隔 | 每隔多久看屏幕一眼，默认 300ms。每看一眼都要抓一帧整屏，间隔越大越省 CPU。 |\n   | 找到后点击它 | 勾上就点一下模板中心（可加偏移、可换按键）；不勾就只「等它出现」。 |\n   | 超时后 | 「继续下一步」或「停止并报错」。 |\n\n5. 点「**模拟测试**」可以不跑宏、不点鼠标，就地抓一帧看看现在能不能找到——调容差时非常省事。\n   （测试时对话框会先自动隐藏，否则找图会先命中对话框里的模板预览图。）\n\n> 找不到时会话框会告诉你「是颜色完全没对上」还是「有几处颜色接近但形状不对」，\n> 这两种情况的处理方式完全不同：前者基本是目标没显示或界面变了，后者才值得调容差。\n\n### 后台点击（不占用鼠标）\n\n默认的点击走 `SendInput`，是**前台注入**：它真实移动系统光标，所以运行期间不能动鼠标，\n目标窗口也必须在前台。勾上主窗口的「**后台点击 (不占用鼠标)**」后会换用 `PostMessage`：\n\n- 点击变成**往目标窗口的消息队列投递** `WM_MOUSEMOVE` / `WM_LBUTTONDOWN` / `WM_LBUTTONUP`；\n- **不移动系统光标**，宏跑着的时候你照样能用鼠标；\n- **不要求目标窗口在前台**，部分被遮挡也能点（前提是能拿到它的窗口句柄 HWND）。\n\n后台点击需要一个**目标窗口**，用于把屏幕坐标换算成该窗口的**客户区坐标**。两种给法：\n\n1. **绑定窗口**（推荐）：点「绑定窗口」，屏幕压暗后**点一下目标窗口**，就把它定为目标。\n   之后所有点击都投给它——哪怕它被别的窗口挡在前面。未绑定时会退化成第 2 种。\n2. **不绑定**：每次点击时用 `WindowFromPoint` 找该屏幕坐标处**当时最顶层**的窗口来投递。\n   省事，但目标被盖住时会投错对象。\n\n命中目标不是顶尖层窗口，而是**该点下最内层的子窗口**——真实鼠标消息正是由命中测试路由到\n那一层的，只丢给顶层窗口很多程序不会自己再往下转发。点击前还会先补一条 `WM_MOUSEMOVE`，\n因为不少控件靠它更新悬停/热点状态。\n\n> ⚠️ **后台点击的适用面比前台窄**，这是 `PostMessage` 机制的固有局限，不是 bug：\n>\n> - 只对**自己处理鼠标消息**的经典 Win32 窗口有效。Chromium/Electron（大部分新版应用\n>   和浏览器）、DirectX 游戏、不少 UWP 会**直接忽略**投递进来的消息，表现为「点了没反应」；\n> - 不会产生 `WM_ACTIVATE` / 焦点变化，个别控件要先获得焦点才响应；\n> - **发送方与目标进程的权限级别要匹配**：Windows 的 UIPI 会拦掉低权限进程发往高权限进程的\n>   消息（比如本工具没提权、目标程序是管理员运行），表现为投递失败或没反应；\n> - **键盘消息**只能投给绑定窗口（没绑定就退而求其次给前台窗口），后台键盘比后台鼠标更不可靠；\n> - 换台机器、目标程序重新开过之后 HWND 会失效，届时会**自动退回**按坐标识别窗口兜底。\n>\n> 一句话：**能前台就用前台**；只有当「不能占用鼠标 / 目标窗口不能拿到前台」时，才值得\n> 赌一把后台，且优先手动绑定窗口。\n\n**换目标程序前先自检。** `PostMessage` 能不能用，完全取决于目标程序认不认 `WM_*` 消息，\n所以给新程序（尤其是 Java、内嵌网页的程序）配后台点击之前，先跑一次探针：\n\n```powershell\npython tools\\probe_background.py\n```\n\n它会把鼠标下那个控件的**窗口链与类名**打出来并判类（`SunAwt*` / `Qt*` 通常有效，\n`Chrome_*` / `Cef*` 基本无效），列出目标进程里的 JCEF / Chromium 痕迹，最后用**项目自己的\n后台后端**真点一下。装了 `uiautomation` 的话，还会顺带看 UIA 树里有没有那个按钮\n（决定要不要走无障碍接口那条路）。详见「技术要点 · 13」。\n\n### 热键\n\n| 键 | 作用 |\n|---|---|\n| F9 | 开始回放 |\n| F10 | 停止回放 / 结束录制 |\n| F8 | 拾取坐标（编辑对话框开着时由对话框接管） |\n| F11 | 开始录制 |\n\n热键用 `RegisterHotKey` 注册，是系统级独占的。如果提示注册失败，说明已被别的程序占用，\n此时仍然可以用界面按钮或托盘菜单操作。\n\n---\n\n## 数据存放位置\n\n```\n%LOCALAPPDATA%\\AutoClicker\\\n├─ settings.json              # 最近使用的方案\n├─ profiles\\\n│  └─ 默认方案.json\n├─ shots\\\n│  └─ 找图失败-20261017-153012.png   # 找图超时中止时的现场截图，只留最近 10 张\n└─ logs\\\n   └─ autoclicker.log         # 滚动保留，最多 3 个备份\n```\n\n方案文件是纯 JSON，可以直接手改、备份或分享。找图步骤的模板是**自带**的\n（`base64(magic + 宽高 + zlib 压缩的 BGRA)`），所以方案文件可以直接换台机器用，\n不需要额外的图片文件：\n\n```jsonc\n{\n  "version": 1,\n  "name": "默认方案",\n  "repeat": 0,                 // 整个序列重复轮数，0 = 无限\n  "repeat_delay_ms": 0,        // 每轮之间的间隔\n  "start_delay_ms": 300,       // 按开始后的等待时间\n  "steps": [\n    { "kind": "click", "enabled": true, "x": 960, "y": 540, "button": "left",\n      "repeat": 10, "interval_ms": 200, "jitter_ms": 0, "jitter_px": 0, "note": "" },\n    { "kind": "delay", "enabled": true, "delay_ms": 1500, "jitter_ms": 200, "note": "等加载" },\n    { "kind": "wait",  "enabled": true, "template": "QUNUMXgAeAD...", "tolerance": 32,\n      "timeout_ms": 30000, "poll_interval_ms": 300, "click": true, "button": "left",\n      "offset_x": 0, "offset_y": 0, "on_timeout": "continue", "note": "等「继续」弹窗" },\n    { "kind": "move",  "enabled": true, "points": [[100, 200], [180, 205], [300, 260]],\n      "duration_ms": 420, "note": "划过去再点" },\n    { "kind": "key",   "enabled": true, "vk": 116, "repeat": 1, "interval_ms": 50, "note": "F5 刷新" }\n  ]\n}\n```\n\n写入采用「临时文件 + `os.replace`」的原子替换，中途崩溃不会留下半个文件。\n单个步骤损坏只会被跳过并记日志，不会让整个方案打不开。\n\n---\n\n## 技术要点\n\n### 1. 输入注入：SendInput（前台）\n\n用 `ctypes` 直接调用 `user32.SendInput`，一次调用原子地发送「移动 + 按下 + 抬起」。\n\n坐标使用 `MOUSEEVENTF_ABSOLUTE | MOUSEEVENTF_VIRTUALDESK`，把虚拟屏幕物理像素\n归一化到 `0..65535`，可以正确处理多显示器与负坐标。\n\n结构体布局是关键：`INPUT` 在 x64 上是 **40 字节**（`ULONG_PTR` 8 字节 + 8 字节对齐），\n算错会导致 `SendInput` 返回 0 且没有任何报错。测试里有断言守住这一点，也守住了\n`mi` / `ki` / `hi` 共享内存这一语义。\n\n### 2. DPI 感知\n\n入口第一件事就是 `SetProcessDpiAwarenessContext(PER_MONITOR_AWARE_V2)`，\n必须在创建窗口之前。否则 Windows 会对坐标做虚拟化，点击位置出现比例偏移。\n\n### 3. 线程模型\n\n```\n主线程 (UI)                      工作线程\n  MainWindow                       MacroEngine\n     │  start_requested ──────────▶  run(profile)      ← 队列连接投递\n     │  ◀── started / step_changed / progress /\n     │      stopped / failed                            ← 队列连接回传\n     │  request_stop() ────────────▶  stop_event.set()  ← threading.Event，跨线程安全\n```\n\n`MacroEngine` 通过 `moveToThread` 搬到工作线程，UI 线程绝不 `sleep`。\n进度信号按 50ms 节流，避免 1ms 间隔时把事件循环淹掉。\n\n### 4. 时序精度\n\n用 `perf_counter()` 单调时钟维护**下一个绝对触发时刻**，每轮只 sleep 差值，\n不会像 `sleep(interval)` 那样累积漂移；落后过多时重置时间轴，避免「追赶风暴」。\n\n**所有等待**（启动延迟、步骤间隔、延时步骤、轮次间隔）都走 `Event.wait()` 而不是 `sleep()`，\n所以 F10 能立刻打断——哪怕正卡在一个 5 秒的延时步骤里。测试覆盖了这一点。\n\n### 5. 全局热键\n\n`RegisterHotKey` + `QAbstractNativeEventFilter` 拦截 `WM_HOTKEY`。\n\n**刻意不用键盘钩子来做热键**：钩子需要常驻拦截全局按键流，更容易被安全软件误报。\n钩子只在**录制期间**临时安装，录完立刻摘掉（见下一节）。\n\n### 6. 录制：低级钩子（仅录制期间安装）\n\n用 `SetWindowsHookEx` 的 `WH_MOUSE_LL` + `WH_KEYBOARD_LL`，而不是：\n\n- `WH_JOURNALRECORD`：Vista 之后对非提权进程基本失效，已废弃；\n- `GetAsyncKeyState` 轮询：拿不到精确时序，也无法屏蔽事件；\n- `pynput` / `keyboard` 之类第三方库：底层还是同一套钩子，白白多一层依赖。\n\n低级钩子**不注入其它进程**，回调是在「安装钩子的那个线程」上通过消息队列调用的，\n所以不需要写 DLL，Qt 主线程自带消息循环。代价是三条硬约束：\n\n1. **回调必须极快**。Windows 有 `LowLevelHooksTimeout`（默认 300ms），超时会被系统静默摘掉钩子。\n   因此回调里只做「追加一条记录」，绝不做 IO、UI 或加锁。\n2. **必须忽略注入事件**（`LLMHF_INJECTED` / `LLKHF_INJECTED`），否则会录到自己的回放，\n   也可能和其它自动化工具互相打架。\n3. **必须持有 `HOOKPROC` 的引用**。回调是 ctypes 闭包，被 GC 掉以后系统回调到野指针会直接崩进程。\n\n事件到步骤的转换分三段，每段都能单独测试：\n\n```\n原始事件 ──①收敛──▶ 动作 ──②合并──▶ 动作组 ──③补延时──▶ 步骤\n         按下/抬起配对         连点→repeat        按真实间隔插 DelayStep\n         移动采样→折线         连按→repeat\n```\n\n**「一个移动 = 一个步骤」**：录一分钟鼠标会产生上万条 `WM_MOUSEMOVE`。如果逐点成步，步骤表会直接\n爆炸。这里把一整段连续移动抽稀成一条折线（默认 12px / 80ms 一个拐点）加上总时长，\n回放时再按「各段长度比例分配总时长」匀速插值——拐点疏密不同也不会忽快忽慢。\n\n### 7. 坐标拾取器与模态对话框\n\n取点经常发生在「某个窗口正开着」的时候，而这些窗口往往正好挡住要拾取的位置。\n`PickCoordinator` 把「先隐藏请求方 → 显示遮罩 → 回调 → 再恢复请求方」收在一处。\n\n为什么要**隐藏**请求方而不是仅靠遮罩盖在上面：Qt 的**模态**对话框会拦截其它窗口的输入，\n而隐藏的模态窗口不参与输入拦截，遮罩才能正常接到鼠标点击。\n\n### 8. 坐标拾取器的双坐标系\n\n- **视觉布局**用 Qt 逻辑坐标（所有 `QScreen.geometry()` 的并集），保证多显示器时贴合；\n- **实际捕获**用 Win32 `GetCursorPos()` 物理坐标，保证与 `SendInput` 同一坐标系。\n\n### 9. 找图：零依赖的模板匹配\n\n`cv2.matchTemplate` 是标准答案，但 OpenCV 会给 exe 塞进 40MB+ 的依赖，而这个项目一直\n守着「只有 PySide6」的线。这里换一套借用 `bytes.find()` 的做法：\n\n```\n模板 ──▶ 挑 1~2 条「像素签名」 ──▶ 在整帧裸字节上 find() ──▶ 候选位置\n                                        （C 层 memmem）          │\n                                                                 ▼\n                                              8x8 抽样点做容差比对，排除假命中\n```\n\n关键在于**签名要长、要稀有**，这样绝大多数字节位置在第一步就被 C 代码否掉，\n真正进 Python 循环的候选只有个位数（实测：3456×1080 的一帧，找图 1~6ms）。\n\n签名挑两条，**先锐利、后退让**：\n\n1. **内容最丰富的那一行**整行像素（横跨文字和边框）——签名里带着颜色变化，\n   几乎不会在别处误命中；代价是要求这一整行逐像素一致。\n2. **最长的一段纯色横线**——纯色几乎不可能渲染出差异，所以最稳，是 1 号整条落空时的退路；\n   但它太「普通」，在大面积同色背景上会产生一大堆候选。\n\n两个坑值得单独说：\n\n- **搜索区间必须裁到「模板左上角的合法范围」里**。整块同色的桌面上，签名会在每一行都命中，\n  不裁的话前几千个候选全是越界的废命中，配额烧光了才发现真答案在屏幕中间——\n  这个 bug 就是真机联调时才暴露的（离屏测试的合成屏幕太干净，照不出来）。\n- **签名是逐字节比对的，不做模糊搜索**。「容差」只作用于最后那步抽样比对，\n  用来容忍文字抗锯齿一类的细微差异，救不回整体变色。所以目标程序换主题 / 换语言 /\n  改 DPI 缩放后必须重新截模板——这是刻意的取舍，换来的是零依赖 + 每帧几毫秒。\n\n### 10. 抓屏：GDI BitBlt\n\n`BitBlt`（屏幕 DC → 兼容 DC）+ `GetDIBits`（取回裸像素），拿到**自顶向下 32 位 BGRA**。\n一次全虚拟桌面抓屏（本机 3456×1080）约 50ms，是轮询里的大头；默认 300ms 轮询下\n大约占一个核的 15%。GDI 句柄在 `finally` 里成对释放。\n\n`ScreenFrame` 带自己的 `x/y` 原点，所以找图算出来的坐标加上帧原点就是**屏幕绝对坐标**，\n副屏负坐标（本机虚拟桌面原点就是 `-1920`）不需要任何特判。\n\n### 11. 截模板：为什么要「隐藏 → 等 150ms → 再抓」\n\n拖框遮罩是半透明压暗的，如果松手当场抓屏，会把遮罩自己也拍进模板里。\n所以流程是：**遮罩先彻底隐藏 → 等 `HIDE_SETTLE_MS`（150ms）让 DWM 重绘完 → 再抓那一块**。\n\n「模拟测试」同理：对话框里正显示着模板预览图，而预览图**就是模板本身**，\n不先让开的话找图会先命中自己的预览图，测出来的结果毫无意义。\n\n另外 `PickCoordinator.busy` 不能只看遮罩可见性——松手之后遮罩已经隐藏、截取还没完成，\n这一小段窗口期里必须继续拒绝新的取点请求（比如用户又按了一下 F8）。\n\n### 12. 后台注入：PostMessage\n\n前台注入（`SendInput`）驱动的是唯一那一个系统光标，所以「不占用鼠标」这条需求在它身上无解；\n后台注入必须换成 `PostMessageW`，往目标窗口的消息队列里投递鼠标/键盘消息。\n\n两个实现要点：\n\n- **坐标换算成客户区坐标**。`WM_LBUTTONDOWN` 的 `lParam` 是相对**目标窗口客户区**的坐标，\n  而本项目内部一律是虚拟屏幕物理像素，所以要先 `ScreenToClient`。\n- **投给该点下最内层的子窗口**。真实鼠标消息由系统命中测试路由到最内层控件；投递的消息\n  没有这层路由，只发给顶层窗口的话，很多程序的 `WndProc` 并不会自己再往下转发，于是\n  「点了没反应」。这里用 `ChildWindowFromPointEx` 逐层下钻（默认跳过不可见与\n  `WS_EX_TRANSPARENT` 的子窗口，因为真实鼠标会直接穿过它们）。\n\n后端是可插拔的：`MacroEngine` 只依赖 `InputBackend` 抽象接口（`app/input/base.py`），\n前台/后台只是两个实现，引擎与步骤模型一行都不用改。引擎在 `start` 之前用 `set_backend()`\n接收当前选择，运行途中禁止切换，避免同一次运行混用两种注入方式。\n\n### 13. PostMessage 不是万能的：三条备选路\n\n「后台点击」这个词容易让人以为存在一个通吃所有程序的开关，其实**能不能后台点，取决于目标\n程序认不认 `WM_*` 消息**，而这是分阵营的：\n\n| 目标类型 | `PostMessage`（本项目现有） | 说明 |\n|---|---|---|\n| 经典 Win32 / MFC / duilib | ✅ | 消息模拟的舒适区 |\n| Qt / Swing(AWT) | ✅ 通常可以 | AWT 的窗口过程由 Java 处理，会把 `WM_*` 翻译成 Java 鼠标事件 |\n| Chromium / Electron / JCEF | ❌ | 输入不走 `WM_*`，投进去也不产生真正的点击 |\n| DirectX / 部分 UWP | ❌ | 绕过标准输入队列 |\n\n所以「有人的自动点击工具后台点得很好」往往是**目标程序恰好是能收消息的那一类**，而不是工具更强。\n真正通吃现代程序的后台方案只有两条，各有代价：\n\n1. **UI Automation（无障碍接口）** —— 通过 Windows 的 UIA/MSAA 树拿到「继续」这个**控件对象**，\n   调用 `Invoke()`。不移动光标、不需要前台、不怕换主题/DPI。代价是**要求目标程序暴露无障碍树**：\n   Swing 需要开 Java Access Bridge + IDEA 的「Support screen readers」，Chromium 需要 a11y 被激活。\n2. **进程注入 / 挂钩**（大漠插件的 `dx` 模式、各种「后台键鼠」驱动走的就是这条）—— 把 DLL 注入\n   目标进程，挂钩它的消息循环 / DirectX / 输入管线。**什么程序都能点**（包括游戏），但极易被\n   杀软 / 反作弊判定为恶意，每个程序要单独适配、随目标升级失效。本项目**刻意不做**这条路。\n\n还有一条是「伪后台」：保存光标 → `SetCursorPos` + `SendInput` 点击 → 还原光标。看着几乎不打扰，\n但只要光标和焦点被抢走，你就没法同时用别的窗口——它不是真正的后台。\n\n**先自检，再决定。** `tools/probe_background.py` 会在目标程序上打出窗口类名、JCEF 痕迹，\n并用项目自己的后端真点一下，把上面这张表落到你的具体程序上。\n\n---\n\n## 已知限制（技术边界，不是 bug）\n\n1. **前台注入会占用鼠标**：默认的 `SendInput` 点击作用于光标所在位置的窗口，运行期间不能移动鼠标。\n   需要后台点击（不占用鼠标、不要求前台）时可勾选「后台点击 (PostMessage)」，但它只对处理\n   `WM_*` 消息的经典 Win32 窗口有效，适用范围明显窄于前台——细节见上文「后台点击」一节。\n2. **游戏 / DirectX / 部分 UWP 无效**：这些程序绕过标准输入队列。\n3. **管理员权限**：若目标程序以管理员运行，Windows 的 UIPI 会**静默丢弃**本工具注入的点击\n   （表现为「点了没反应」）。此时必须以管理员身份运行本工具。\n4. **杀软误报**：输入注入天然敏感，打包分发时建议做代码签名。\n5. **焦点抢占**：Windows 的 Foreground Lock 可能阻止程序主动激活目标窗口，\n   本工具不做强制抢焦点，请手动把目标窗口切到前台。\n6. **纯按键步骤需要目标窗口处于前台**：鼠标点击靠坐标命中窗口，而前台注入的按键是发到焦点窗口的。\n   （后台模式下按键投给绑定窗口，但后台键盘更不可靠，很多程序会忽略。）\n7. **录制不产生「条件步骤」**：录制只能记录「什么时候做了什么」，记不下「等某个按钮出现再点」。\n   目标界面加载变慢时，回放就会点空——这时候用「**+ 找图**」手动补一个等待步骤。\n8. **找图是原尺寸、逐像素的精确匹配**：目标程序换主题、换语言、改 DPI 缩放之后，\n   原来截的模板就失效了，必须重新截。参数里的「容差」只能容忍文字抗锯齿级别的细微差异。\n9. **找图是全屏搜索，不限定区域**：每轮都要抓一整帧虚拟桌面。在小屏幕上无所谓，\n   4K 多屏下建议把「轮询间隔」调大一些（每帧约 50ms 的抓屏开销）。\n10. **找图要求目标真的显示在屏幕上**：被其它窗口完全挡住、最小化、翻到后台标签页里都找不到。\n    本工具不做后台窗口的**控件级查找**（那需要在绑定窗口上遍历控件树、按控件而不是按像素定位，\n    属于后续计划；现有的「绑定窗口」只是把点击消息投给窗口，仍然按像素坐标命中）。\n11. **找图不适合追动画/渐变**：模板需要有一段稳定的纯色区域才稳。纯色区域太小时对话框会给出橙色提示。\n12. **超时快照只在「停止并报错」模式下生成**：如果是「继续下一步」，一个循环里反复超时的等待步骤\n    会写出一堆几乎一样的图，反而把有用的那张埋掉——那种情况请看日志里的「最接近的相似度」。\n13. **录制期间无法操作本工具之外的窗口切换**：屏蔽输入模式下所有鼠标键盘都被吃掉，\n    这是设计如此，用 F10 结束即可。\n\n---\n\n## 测试\n\n两套测试，按「要不要真实的 Windows 消息循环」分开：\n\n```powershell\npython tests\\test_smoke.py           # 139 个用例，任何平台都能跑\npython tests\\test_win_integration.py # 18 个用例，只认 Windows（其它平台自动 skip）\n```\n\n`test_smoke.py` 使用 Qt 的 `offscreen` 平台插件，不会真的弹窗，也不会真的点鼠标\n（引擎测试使用 `FakeBackend` + 注入的假抓屏函数，并校验完整事件时间线）。\n`test_win_integration.py` 反过来：**真的建窗口、真的投消息**，细节见本节末尾。\n\n两者都在 CI 上跑（`.github/workflows/windows.yml`，`windows-latest`），另外还多一个 job\n校验 `bootstrap.py` 的内嵌快照与仓库**逐字节一致**——改了文件忘记 `--sync` 是这套\n「一个文件就是一个项目」的设计特有的失效模式，交给 CI 守着比靠记性可靠。覆盖：\n\n- `INPUT` 结构体大小与联合体内存共享语义\n- 虚拟屏幕坐标读取、单实例守卫、热键键码表\n- 五种步骤的校验、JSON 往返、坏数据容错\n- **找图模板的序列化往返与坏数据拒绝**（magic 不对 / 宽高为 0 / zlib 坏 / 被截断）\n- **探针挑法**：整行签名优先、纯色签名兜底、没纯色段时不硬塞 1 像素的签名\n- **模板匹配**：精确命中、同分取最左上、容差生效与失效、超大模板、缺席时报 0 候选、\n  大面积同色屏幕上不能「配额被废命中烧光」（真机 bug 的回归测试）\n- **坐标不变量**：命中坐标相对帧左上角，负原点的虚拟桌面靠调用方加回去\n- 方案仓库的增删改查、原子写入、文件名净化、损坏文件处理\n- 引擎的**步骤顺序**、多轮循环、停用跳过、坐标抖动范围、启动延迟\n- 长时间延时步骤、长时间移动轨迹、长时间找图等待能否被立即打断\n- 找图步骤：命中后点模板中心、关掉点击、点击偏移、超时继续 / 超时中止、\n  超时归零只找一次、「继续」模式不写快照而「中止」模式交最后一帧、抓屏失败上报\n- 移动步骤的折线插值（终点必须精确命中、中间点必须真的走过）\n- 录制事件的转换规则：按下/抬起配对、坐标取按下时刻、连点合并、连按合并、\n  自动重复忽略、轨迹抽稀、抖动丢弃、按键时序中断轨迹、延时步骤插入\n- 低级钩子回调：吃事件 / 放行、注入事件忽略、控制热键放行且不入宏、\n  记录函数抛错时仍然保持「不误点」、`n_code < 0` 原样传递\n- 真实安装一次 `WH_MOUSE_LL` + `WH_KEYBOARD_LL` 再摘掉（验证 ctypes 声明与回调引用）\n- 录制整条链路：F11 开始 → F10 结束 → 替换 / 追加 / 丢弃 / 空录制 /\n  热键缺失时拒绝开录\n- 主窗口 / 步骤编辑器 / 编辑对话框的装配，以及「拾取坐标」的隐藏与恢复流程\n  （含「F8 改写移动轨迹终点」「延时步骤拒绝取点」）\n- 找图界面：`+ 找图` 按钮、模板预览与纯色提示、没截模板时不让点「确定」、\n  拖框时对话框让开、模拟测试的命中 / 落空两种文案\n- `PickCoordinator` 的第二种取法：拖框截模板、截取失败时发 `failed` 并让调用方收尾、\n  `busy` 覆盖「遮罩已隐藏但截取还没完成」的窗口期、取点与截模板互斥\n- 现场快照：PNG 通道顺序（BGRA 必须按 RGB32 解读，否则画面整体偏色）、\n  只保留最近 N 张、落盘失败绝不打断宏\n- **后台点击**：`lParam` 的客户区坐标打包（含负坐标截断）、按键 `lParam` 的扫描码与抬起标志、\n  点击的 `move/down/up` 消息序列与左右键分支、命中点投给最内层子窗口、绑定时归一化到顶层窗口、\n  失效句柄拒绝绑定、未绑定时按坐标兜底找窗口、找不到目标时不投递且只警告一次\n- 拆分出来的子系统：托盘菜单转发（`QAction.triggered` 捎带的参数要被丢掉）、\n  无托盘时的降级、录制落地的替换/追加语义、日志 handler 的成对挂载与摘除\n- **真实窗口上的后台点击**（`test_win_integration.py`）：自造带 `WndProc` 的顶层窗口 + 子窗口，\n  验证客户区↔屏幕坐标往返、命中点下钻到最内层子窗口、不可见与 `WS_EX_TRANSPARENT` 子窗口被穿透、\n  点击真的由目标窗口收到（`WM_MOUSEMOVE → 按下 → 抬起`，`lParam` 是正确的客户区坐标）、\n  右键分支、只投 `WM_MOUSEMOVE` 的移动、后台键盘的按键与扫描码、按点绑定归一化到顶层窗口、\n  失效句柄拒绝绑定\n\n`SendInput` 注入与 GDI 抓屏这两层不做自动化断言，改为真机联调验证（抓一帧 → 抠一块当模板 →\n必须一次命中且坐标精确、通道差为 0）。\n\n后台点击则是**两层都测**：`test_smoke.py` 把 `post_message` / 窗口查询函数换成假的，断言\n「逻辑上发给谁、发什么消息、坐标换算对不对」；`test_win_integration.py` 在**真实的** Win32\n窗口上把整条链路跑一遍——消息真的投出去、真的由目标窗口的 `WndProc` 收下。于是\n`PostMessageBackend` 的实现细节在自动化测试里就有断言守着，而不是只能靠肉眼。\n\n真机仍无法被替代的只剩一件事：**目标程序认不认 `WM_*`**。这取决于对方是什么框架，用\n`tools\\probe_background.py` 现场判定（见「后台点击」一节）。\n\n---\n\n## 项目结构\n\n```\nauto-clicker/\n├─ .github/\n│  └─ workflows/\n│     └─ windows.yml           # CI：快照一致性 + 真实窗口集成测试 + 冒烟测试\n├─ main.py                     # 入口：DPI → 日志 → QApplication → 单实例 → 装配\n├─ requirements.txt\n├─ build.bat                   # 一键打包（先跑冒烟测试，再 PyInstaller）\n├─ bootstrap.py                # 自解压式项目生成器（--sync 刷新内嵌快照）\n├─ docs/\n│  └─ USAGE.md                 # 面向使用者的操作说明（怎么用这个工具）\n├─ tools/\n│  └─ probe_background.py      # 后台点击自检探针（判定目标程序适不适合 PostMessage / UIA）\n├─ app/\n│  ├─ win/                     # 平台适配（纯 ctypes）\n│  │  ├─ dpi.py                #   Per-Monitor V2 DPI 感知\n│  │  ├─ admin.py              #   权限检测与提权\n│  │  ├─ singleton.py          #   命名互斥量单实例\n│  │  ├─ geometry.py           #   虚拟屏幕坐标 / 光标位置\n│  │  ├─ screen.py             #   GDI 抓屏（BitBlt + GetDIBits → BGRA）\n│  │  ├─ hooks.py              #   低级钩子录制器（WH_MOUSE_LL / WH_KEYBOARD_LL）\n│  │  ├─ window.py             #   窗口查询：HWND、父子窗口、屏幕/客户区换算、PostMessage\n│  │  └─ hotkey.py             #   全局热键、原生事件过滤器、虚拟键码表\n│  ├─ input/                   # 输入注入后端（可插拔）\n│  │  ├─ base.py               #   抽象接口，前后台后端共用同一套约定\n│  │  ├─ sendinput.py          #   SendInput 前台注入\n│  │  └─ postmessage.py        #   PostMessage 后台注入（不占用鼠标）\n│  ├─ core/                    # 与 UI 无关的核心\n│  │  ├─ models.py             #   Step 子类 / Profile，校验与序列化\n│  │  ├─ matching.py           #   找图：模板序列化 + 探针 + 抽样比对（零依赖）\n│  │  ├─ engine.py             #   MacroEngine：工作线程 + 绝对时刻调度\n│  │  └─ recording.py          #   录制事件 → 步骤序列（收敛 / 合并 / 补延时）\n│  ├─ storage/\n│  │  └─ config.py             #   ProfileStore：方案 JSON 读写 + 最近使用记录\n│  ├─ ui/                      # PySide6 界面\n│  │  ├─ main_window.py        #   主窗口：布局 + 命令入口 + 跨子系统策略\n│  │  ├─ profile_controller.py #   当前方案/未保存标记 + 落盘/改名/删除\n│  │  ├─ run_controller.py     #   工作线程里的 MacroEngine + 进度条 + 超时快照\n│  │  ├─ recording_controller.py # 输入钩子 + 录制指示条 + 事件转步骤\n│  │  ├─ tray_icon.py          #   托盘图标与右键菜单（菜单只负责发信号）\n│  │  ├─ log_panel.py          #   只读日志视图（handler 挂载与其生命周期配对）\n│  │  ├─ step_editor.py        #   步骤表格：增删改排序\n│  │  ├─ step_dialog.py        #   步骤字段编辑对话框（含找图模板与模拟测试）\n│  │  ├─ position_picker.py    #   全屏取点遮罩 + PickCoordinator（兼管截模板）\n│  │  ├─ template_picker.py    #   找图用的全屏拖框遮罩\n│  │  ├─ shot.py               #   找图失败时的现场截图（PNG 落盘 + 只留最近 N 张）\n│  │  ├─ record_overlay.py     #   录制指示条（点击穿透、不抢焦点）\n│  │  └─ icon.py               #   代码绘制图标（零资源文件）\n│  └─ utils/\n│     └─ logger.py             # 滚动文件日志 + 转发给 UI 的 handler\n└─ tests/\n   ├─ test_smoke.py\n   └─ test_win_integration.py     # 真实 Win32 窗口上的后台点击集成测试（仅 Windows）\n```\n\n---\n\n## 打包\n\n双击 `build.bat`（或命令行里跑 `build.bat`）即可。它会按顺序做四件事：\n先跑一遍冒烟测试（**测试不过就不打包**，避免打出一个坏 exe），清掉旧的 `build\\`、`dist\\`，\n再调 PyInstaller，最后报告产物路径与体积。\n\n产物：`dist\\AutoClicker.exe`，单文件、无控制台窗口。\n\n```powershell\n:: 需要先装 PyInstaller（build.bat 会检查并提示）\npip install pyinstaller\nbuild.bat\n```\n\n等价的裸命令就是：\n\n```powershell\npyinstaller --noconfirm --onefile --windowed --name AutoClicker main.py\n```\n\n注意点：\n\n- 裸命令**不带 Qt 裁剪**，产物明显偏大。`build.bat` 里额外排除了 Qml / Quick / WebEngine /\n  Multimedia / Charts / Sql 等本工具用不到的 Qt 子系统——PySide6 每个模块都是独立的 DLL，\n  这才是体积大头（`--exclude-module` 能把对应的 DLL 一起拦掉）；\n- 把 `AutoClicker.ico` 放在项目根目录，`build.bat` 会自动 `--icon` 带上它。不提供也没关系：\n  窗口与托盘图标本来就是 `app/ui/icon.py` 代码画的，只是 exe 文件本身会显示 PyInstaller 的默认图标；\n- 图标用代码绘制，因此没有 `--add-data` 的资源路径问题；找图模板存在方案 JSON 里，\n  也没有额外的图片文件要打包；\n- 若需要开机自启或写入程序目录，建议在 `build.bat` 里加 `--uac-admin`，或改用运行时按需提权；\n- 单实例锁使用 `Local\\` 命名空间，同一用户会话内唯一；\n- 方案文件放在 `%LOCALAPPDATA%`，因此升级 exe 不会丢配置；\n- `build.bat` 必须保持 **CRLF** 行尾：cmd.exe 解析多行 `if (` / 续行 `^` 时依赖它，换成 LF 会错乱。\n  它的输出文案也刻意全部保持 ASCII，因为中文 Windows 的控制台默认是 GBK 代码页，\n  混入非 GBK 字符会直接 `UnicodeEncodeError`。\n\n---\n\n## 从零重建项目（bootstrap.py）\n\n`bootstrap.py` 把整份项目（48 个文件）硬编码在自己内部，不读任何原始文件就能还原出完整项目，\n适合打包分发「一个文件就是一个项目」：\n\n```powershell\npython bootstrap.py D:\\some\\where\\auto-clicker\npython bootstrap.py            :: 不传参数 → 当前目录下的 auto-clicker\\\n```\n\n- 目标目录非空时会列出后果并让你输入 `yes` 确认，确认后**清空**该目录再生成；\n- 若目标目录里存在 `bootstrap.py`（说明指向了源码仓库本身，删掉就找不回来了），脚本直接拒绝执行；\n- 生成的 `build.bat` 会保留 CRLF 行尾。\n\n改了 `app/` 下的源码后，跑一次 `--sync` 刷新内嵌快照，避免快照与源码漂移：\n\n```powershell\npython bootstrap.py --sync\n```\n\n`--sync` 只按 `FILES` 里已有的键刷新内容，不自动增删文件；若仓库里出现了没登记的 `.py`，\n它会打印 `[WARN]` 提醒——不然生成的快照会在 `import` 阶段才炸，那种报错不好查。\n\n---\n\n## 后续计划\n\n**P4 后续**：找色（颜色匹配）、限定找图搜索区域（当前只能全屏搜）、坐标相对目标窗口\n（录制时记相对坐标、跟随窗口移动）、后台点击的窗口选择器（按标题/类名持续追踪）、\n打包实测、开机自启、配置导入导出。\n',
    'docs/USAGE.md': '# AutoClicker 使用手册\n\n面向使用者的操作说明。设计原理、代码结构与测试细节见 [`README.md`](../README.md)。\n\n适用版本：**P4（0.4.0）** — 前台/后台两种点击方式、找图、录制回放。\n\n---\n\n## 目录\n\n- [1. 安装与启动](#1-安装与启动)\n- [2. 界面速览](#2-界面速览)\n- [3. 五分钟上手](#3-五分钟上手)\n- [4. 五种步骤](#4-五种步骤)\n- [5. 录制回放](#5-录制回放)\n- [6. 找图：等某个东西出现](#6-找图等某个东西出现)\n- [7. 后台点击（不占用鼠标）](#7-后台点击不占用鼠标)\n- [8. 热键与托盘](#8-热键与托盘)\n- [9. 方案文件](#9-方案文件)\n- [10. 常见坑](#10-常见坑)\n\n---\n\n## 1. 安装与启动\n\n只能在 **Windows 10 / 11** 上运行（输入注入走 Win32，无法跨平台）。\n\n### 源码方式\n\n```powershell\npip install -r requirements.txt   # 依赖只有 PySide6\npython main.py\n```\n\n### 打包成 exe（给别人用 / 免装 Python）\n\n```powershell\npip install pyinstaller\nbuild.bat            # 会先跑一遍冒烟测试，测试不过就不打包\n```\n\n产物 `dist\\AutoClicker.exe`，单文件、无控制台窗口，双击即用。\n（放一个 `AutoClicker.ico` 在项目根目录，`build.bat` 会自动带上它。）\n\n### 首次启动\n\n会在 `%LOCALAPPDATA%\\AutoClicker\\` 下建好 `settings.json`、`profiles\\`、`shots\\`、`logs\\`。\n程序是**单实例**的，重复启动会唤起已有窗口。\n\n---\n\n## 2. 界面速览\n\n| 区域 | 内容 |\n|---|---|\n| 顶部「方案」组 | 方案下拉切换；`新建 / 保存 / 另存为 / 重命名 / 删除`；第二行：`启动延迟`、`序列轮数`、`轮次间隔`、`开始后最小化窗口` |\n| 中间左侧 | **步骤序列表**，列为 `启用 / 类型 / 参数 / 备注`；下方一排 `+ 点击`、`+ 延时`、`+ 按键`、`+ 移动`、`+ 找图`、`编辑`、`删除`、`↑`、`↓` |\n| 中间右侧 | **日志**面板（分隔条可拖动）与**实时进度**（第几轮 / 第几步 / 累计动作数） |\n| 运行按钮行 | `开始 (F9)`、`停止 (F10)`、`拾取坐标 (F8)`、`录制 (F11)`，以及 `记录鼠标移动`、`屏蔽输入` 两个勾选框 |\n| 输入方式行 | `后台点击 (不占用鼠标)` 勾选框、`绑定窗口` 按钮、目标窗口标签 |\n| 状态栏 | 热键提示 |\n\n---\n\n## 3. 五分钟上手\n\n1. 点 **`+ 点击`**，在弹窗里设置参数（或先点「拾取坐标 (F8)」定坐标）。\n2. **取坐标**：对话框里点「拾取坐标 (F8)」，屏幕压暗后把鼠标移到目标位置、**左键**确认；\n   对话框会先自动隐藏、拾取完再弹回来。也可以关掉对话框，在主窗口**选中某一行**后按 **F8**\n   改写它的坐标。\n3. 继续加 **`+ 延时`**（等界面加载）、**`+ 按键`**（例如 F5 刷新）。\n4. 临时不想跑某一步：取消该行 `启用` 列的勾。\n5. 设 **序列轮数**（填 `0` = 无限，直到按 F10）与 **启动延迟**（留出切换窗口的时间）。\n6. 按 **F9** 开始（勾了「开始后最小化窗口」会自动最小化），**F10** 停止。\n\n> ⚠️ 默认是 `SendInput` **前台注入**：它会真实移动系统光标并产生真实点击，\n> **运行期间不要动鼠标**。要一边跑一边用鼠标，见 [第 7 节 后台点击](#7-后台点击不占用鼠标)。\n\n---\n\n## 4. 五种步骤\n\n| 类型 | 主要字段 | 说明 |\n|---|---|---|\n| **点击** | 坐标 X/Y、按键、次数、间隔 ms、间隔抖动 ms、坐标抖动 px | 「次数 + 间隔」即连点；抖动用来避免被识别成机械点击 |\n| **延时** | 延时 ms、抖动 ms | 等**固定时长**。等「不确定何时出现」的东西请用找图 |\n| **按键** | 按键（下拉）、次数、间隔 ms | 发给**焦点窗口**，所以要先把目标窗口切到前台 |\n| **移动** | 折线点（`拾取终点 (F8)`）、总时长 ms | 用来还原「划过去再点」这类悬停动作 |\n| **找图** | 见 [第 6 节](#6-找图等某个东西出现) | 等屏幕上出现某张图片再继续 / 再点它 |\n\n坐标拾取也可以在对话框里进行：点「拾取坐标 (F8)」，或对移动步骤点「拾取终点 (F8)」。\n\n---\n\n## 5. 录制回放\n\n不用手搭步骤，直接录一遍：\n\n1. 点「录制 (F11)」或按 **F11**，主窗口让开，屏幕顶部出现「● 录制中」指示条。\n2. 正常操作鼠标键盘。指示条实时显示录到的点击/按键数与移动采样数。\n3. 按 **F10** 结束，弹窗选择 **替换当前步骤 / 追加到末尾 / 丢弃**。\n4. 内容进步骤表后可直接编辑、调时长、调顺序，再按 F9 回放。\n\n录制会自动做三件「整理」，结果通常比想象中干净：\n\n- **连点合并**：同一个点连点 5 下 → 一个「点击 ×5，间隔 150ms」，而不是 5 行；\n- **连按合并**：同一个键重复按 → 一个「按键 ×N」；\n- **轨迹压缩**：一整段鼠标移动 → **一个**「移动」步骤（内部存折线拐点 + 总时长），\n  默认抽稀到 12px / 80ms 一个点，2px 以内的手抖直接丢掉。\n\n录完想微调坐标不用重录：选中那一行按 **F8**。点击步骤改的是落点坐标，\n移动步骤改的是**终点**（起点保留、中间拐点拉直）。\n\n### 两个录制开关\n\n| 开关 | 默认 | 作用 |\n|---|---|---|\n| 记录鼠标移动 | 开 | 关掉后只录点击和按键，步骤更精简。开着才能还原「移到菜单上再点」这类悬停操作 |\n| 屏蔽输入 | 关 | 勾上后录制期间鼠标键盘**不会传给任何程序**，纯空录坐标和节奏，绝不会误点。代价是「点开菜单 → 再点菜单项」这种有依赖的流程录不出来（菜单根本不会打开） |\n\n> 勾了「屏蔽输入」时 **F10 是唯一的结束方式**，因此工具会先确认 F10 热键注册成功才允许开录，\n> 避免把你锁在一个点不动的系统里。不勾选时 F10 依然最方便，托盘菜单也能结束。\n>\n> 录制期间不记录工具自己的控制键（F8/F9/F10/F11），也忽略其它程序注入的事件，\n> 所以不会把回放动作又录一遍。\n\n---\n\n## 6. 找图：等某个东西出现\n\n录制只能记下「什么时候做了什么」，记不下「等某个按钮出现再点」；找图步骤来补这一环。\n\n1. 点 **`+ 找图`**，对话框里点「**截取屏幕**」。\n2. 屏幕压暗后**左键拖一个框**框住要认的目标（比如「继续」按钮），松手即完成截取。\n   框太小会被当成误触，直接重拖即可；右键或 Esc 取消。\n3. 回到对话框，上方显示模板预览、尺寸，并提示这块画面「含多少像素的纯色区域」。\n   出现**橙色警告**说明这块没有纯色底色、匹配会更脆，**建议把按钮的底色一起框进来**。\n4. 调参数（一般默认值就够）：\n\n   | 字段 | 说明 |\n   |---|---|\n   | 容差 | 抽样比对时每通道允许的色差，默认 32。主要用于容忍文字抗锯齿 |\n   | 超时 | 最多等多久，默认 30 秒。填 `0` 表示只找一次，找不到立刻按「超时后」处理 |\n   | 轮询间隔 | 每隔多久看屏幕一眼，默认 300ms。每看一眼都要抓一帧整屏，间隔越大越省 CPU |\n   | 找到后点击它 | 勾上就点一下模板中心（可加偏移、可换按键）；不勾就只「等它出现」 |\n   | 超时后 | 「继续下一步」或「停止并报错」 |\n\n5. 点「**模拟测试**」可以不跑宏、不点鼠标，就地抓一帧看看现在能不能找到——调容差时非常省事。\n   （测试时对话框会先自动隐藏，否则会先命中对话框里的模板预览图。）\n\n> 找不到时会提示「是颜色完全没对上」还是「有几处颜色接近但形状不对」：\n> 前者基本是目标没显示或界面变了，后者才值得调容差。\n\n---\n\n## 7. 后台点击（不占用鼠标）\n\n默认点击走 `SendInput`，是**前台注入**：真实移动系统光标，所以运行期间不能动鼠标，\n目标窗口也必须在前台。勾上主窗口的「**后台点击 (不占用鼠标)**」后会换用 `PostMessage`：\n\n- 点击变成**往目标窗口的消息队列投递** `WM_MOUSEMOVE` / `WM_LBUTTONDOWN` / `WM_LBUTTONUP`；\n- **不移动系统光标**，宏跑着的时候你照样能用鼠标；\n- **不要求目标窗口在前台**，部分被遮挡也能点（前提是拿得到它的窗口句柄 HWND）。\n\n后台点击需要一个**目标窗口**，用于把屏幕坐标换算成该窗口的**客户区坐标**。两种给法：\n\n1. **绑定窗口（推荐）**：勾上「后台点击」后点「**绑定窗口**」，屏幕压暗后点一下目标窗口即可。\n   之后所有点击都投给它——哪怕它被别的窗口挡在前面。\n2. **不绑定**：每次点击时找该屏幕坐标处**当时最顶层**的窗口来投递。省事，但目标被盖住时会投错。\n\n> ⚠️ **后台点击适用面比前台窄**，这是 `PostMessage` 机制的固有局限，不是 bug：\n>\n> - 只对**自己处理鼠标消息**的经典 Win32 窗口有效。Chromium/Electron（大部分新版应用与\n>   浏览器）、DirectX 游戏、不少 UWP 会**直接忽略**投递进来的消息，表现为「点了没反应」；\n> - 不会产生 `WM_ACTIVATE` / 焦点变化，个别控件要先获得焦点才响应；\n> - **发送方与目标进程的权限级别要匹配**：Windows 的 UIPI 会拦掉低权限进程发往高权限进程的\n>   消息（例如本工具没提权、目标是管理员程序），表现为投递失败或没反应；\n> - **键盘消息**只能投给绑定窗口（没绑定就退而求其次给前台窗口），后台键盘比后台鼠标更不可靠；\n> - 换台机器、目标程序重开过之后 HWND 会失效，届时会**自动退回**按坐标识别窗口兜底。\n>\n> 一句话：**能前台就用前台**；只有当「不能占用鼠标 / 目标窗口拿不到前台」时，才值得赌一把后台，\n> 且优先手动绑定窗口。\n\n---\n\n## 8. 热键与托盘\n\n| 键 | 作用 |\n|---|---|\n| F9 | 开始回放 |\n| F10 | 停止回放 / 结束录制 |\n| F8 | 拾取坐标（编辑对话框开着时由对话框接管） |\n| F11 | 开始录制 |\n\n热键用 `RegisterHotKey` 注册，是**系统级独占**的。若提示注册失败，说明已被别的程序占用，\n此时仍然可以用界面按钮或托盘菜单操作。\n\n**点窗口的关闭按钮是最小化到托盘**，不是退出。托盘右键菜单：\n`开始点击 (F9)`、`停止 (F10)`、`拾取坐标 (F8)`、`开始/结束录制 (F11)`、`退出`。\n要真正退出，用托盘菜单的「退出」，或菜单栏「方案 → 退出」。\n\n---\n\n## 9. 方案文件\n\n放在 `%LOCALAPPDATA%\\AutoClicker\\profiles\\*.json`，是纯 JSON，可以直接手改、备份或分享。\n找图模板**自带**在 JSON 里（`base64(magic + 宽高 + zlib 压缩的 BGRA)`），\n所以方案文件换台机器也能直接用，不需要额外的图片文件。\n\n```jsonc\n{\n  "version": 1,\n  "name": "默认方案",\n  "repeat": 0,                 // 整个序列重复轮数，0 = 无限\n  "repeat_delay_ms": 0,        // 每轮之间的间隔\n  "start_delay_ms": 300,       // 按开始后的等待时间\n  "steps": [\n    { "kind": "click", "enabled": true, "x": 960, "y": 540, "button": "left",\n      "repeat": 10, "interval_ms": 200, "jitter_ms": 0, "jitter_px": 0, "note": "" },\n    { "kind": "delay", "enabled": true, "delay_ms": 1500, "jitter_ms": 200, "note": "等加载" },\n    { "kind": "wait",  "enabled": true, "template": "QUNUMXgAeAD...", "tolerance": 32,\n      "timeout_ms": 30000, "poll_interval_ms": 300, "click": true, "button": "left",\n      "offset_x": 0, "offset_y": 0, "on_timeout": "continue", "note": "等「继续」弹窗" },\n    { "kind": "move",  "enabled": true, "points": [[100, 200], [180, 205], [300, 260]],\n      "duration_ms": 420, "note": "划过去再点" },\n    { "kind": "key",   "enabled": true, "vk": 116, "repeat": 1, "interval_ms": 50, "note": "F5 刷新" }\n  ]\n}\n```\n\n写入采用「临时文件 + 原子替换」，中途崩溃不会留下半个文件；\n单个步骤损坏只会被跳过并记日志，不会让整个方案打不开。\n\n日志文件在 `%LOCALAPPDATA%\\AutoClicker\\logs\\autoclicker.log`（滚动保留，最多 3 个备份）；\n找图超时中止时的现场截图在 `shots\\`（只留最近 10 张）。\n\n---\n\n## 10. 常见坑\n\n1. **运行期间动鼠标** → 前台注入的点击会跟着光标跑偏。要么别动，要么改用后台点击。\n2. **目标程序以管理员运行** → UIPI 会静默丢掉你的点击。「点了没反应」先想这条，\n   改成以管理员身份运行本工具。\n3. **游戏 / DirectX / 部分 UWP 无效** → 它们绕过标准输入队列，本工具无解。\n4. **纯按键步骤点空** → 按键发给焦点窗口，先把目标窗口切到前台。\n5. **换主题 / 换语言 / 改 DPI 缩放后找图失效** → 找图是原尺寸逐像素精确匹配，\n   必须重新截模板；「容差」救不回整体变色。\n6. **找图在 4K 多屏上吃 CPU** → 它是全屏搜索，每帧抓整屏约 50ms，把「轮询间隔」调大些。\n7. **找图找不到被挡住的窗口** → 被完全遮挡、最小化、翻到后台标签页都找不到；\n   本工具不做控件级查找（现有「绑定窗口」只是把点击消息投给窗口，仍按像素坐标命中）。\n8. **录制期间切不动别的窗口** → 「屏蔽输入」下所有鼠标键盘都被吃掉，这是设计如此，按 F10 结束即可。\n',
    'tools/probe_background.py': '"""后台点击自检探针：先判定「后台点击」在目标程序上到底走哪条路可行。\n\n为什么需要它\n------------\n``PostMessage`` 后台点击能不能用，**完全取决于目标程序认不认 ``WM_*`` 消息**：\n\n- 经典 Win32 / Qt / Swing(AWT) 一般认；\n- Chromium / Electron / JCEF / 游戏 基本不认（它们的输入不走 ``WM_*``）。\n\n所以「我的后台点击对 IDEA 有没有戏」这个问题，不该靠猜，而应该先看一眼按钮\n所在窗口到底是哪一类。本脚本把这件事变成一次运行就能看出来。\n\n它做四件事\n----------\n1. 等你把鼠标移到目标控件上，读光标位置；\n2. 打印该位置下的**窗口链与类名**，并判定属于哪一类 UI 框架；\n3. 列出目标进程的顶层窗口，标出 **JCEF / Chromium 的痕迹**；\n4. 用**项目自己的** ``PostMessageBackend`` 真点一下这个位置（可选），这是最直接的判定。\n\n如果装了 ``uiautomation``，还会额外打印该点的 UIA 元素信息，并在整棵 UIA 树里\n搜索「继续 / 取消」这类按钮，判断能不能走无障碍接口那条路。没装就跳过，不影响其它部分。\n\n用法\n----\n在**项目根目录**运行（Windows + Python 3.10+）::\n\n    python tools\\\\probe_background.py\n\n常用参数::\n\n    python tools\\\\probe_background.py --delay 8          # 给更长的准备时间\n    python tools\\\\probe_background.py --point 1200 800   # 跳过等待，直接分析该坐标\n    python tools\\\\probe_background.py --no-click         # 只分析，不做点击测试\n\n只依赖标准库；要 UIA 部分再额外 ``pip install uiautomation``。\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport ctypes\nimport ctypes.wintypes as wintypes\nimport sys\nimport time\nfrom pathlib import Path\n\n# 允许直接 `python tools\\probe_background.py` 运行（否则 import app.* 会失败）\n_ROOT = Path(__file__).resolve().parent.parent\nif str(_ROOT) not in sys.path:\n    sys.path.insert(0, str(_ROOT))\n\n_user32 = ctypes.WinDLL("user32", use_last_error=True)\n\n_EnumProc = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)\n\n_user32.GetCursorPos.argtypes = (ctypes.POINTER(wintypes.POINT),)\n_user32.GetCursorPos.restype = wintypes.BOOL\n_user32.WindowFromPoint.argtypes = (wintypes.POINT,)\n_user32.WindowFromPoint.restype = wintypes.HWND\n_user32.GetAncestor.argtypes = (wintypes.HWND, wintypes.UINT)\n_user32.GetAncestor.restype = wintypes.HWND\n_user32.GetParent.argtypes = (wintypes.HWND,)\n_user32.GetParent.restype = wintypes.HWND\n_user32.GetClassNameW.argtypes = (wintypes.HWND, wintypes.LPWSTR, ctypes.c_int)\n_user32.GetClassNameW.restype = ctypes.c_int\n_user32.GetWindowTextLengthW.argtypes = (wintypes.HWND,)\n_user32.GetWindowTextLengthW.restype = ctypes.c_int\n_user32.GetWindowTextW.argtypes = (wintypes.HWND, wintypes.LPWSTR, ctypes.c_int)\n_user32.GetWindowTextW.restype = ctypes.c_int\n_user32.GetWindowThreadProcessId.argtypes = (wintypes.HWND, ctypes.POINTER(wintypes.DWORD))\n_user32.GetWindowThreadProcessId.restype = wintypes.DWORD\n_user32.IsWindowVisible.argtypes = (wintypes.HWND,)\n_user32.IsWindowVisible.restype = wintypes.BOOL\n_user32.EnumWindows.argtypes = (_EnumProc, wintypes.LPARAM)\n_user32.EnumWindows.restype = wintypes.BOOL\n_user32.EnumChildWindows.argtypes = (wintypes.HWND, _EnumProc, wintypes.LPARAM)\n_user32.EnumChildWindows.restype = wintypes.BOOL\n\nGA_PARENT = 1\nGA_ROOT = 2\n\n# 类名 → 结论。按前缀匹配，顺序有意义（先匹配到的先用）。\n_CLASS_RULES: tuple[tuple[str, str], ...] = (\n    ("SunAwt", "Java Swing/AWT  → 消息模拟(PostMessage) 通常【有效】"),\n    ("Chrome_RenderWidgetHost", "Chromium 渲染控件 → 消息模拟【无效】，需要 UIA"),\n    ("Chrome_WidgetWin", "Chromium 顶层窗口(JCEF/Electron) → 消息模拟【无效】，需要 UIA"),\n    ("Chrome_", "Chromium → 消息模拟【无效】，需要 UIA"),\n    ("CefBrowserWindow", "CEF 浏览器窗口 → 消息模拟【无效】，需要 UIA"),\n    ("Cef", "CEF/Chromium → 消息模拟【无效】，需要 UIA"),\n    ("Qt", "Qt → 消息模拟通常【有效】"),\n    ("WindowsForms", ".NET WinForms → 消息模拟通常【有效】"),\n    ("HwndWrapper", "WPF → 消息模拟通常【有效】"),\n    ("ApplicationFrameWindow", "UWP/XAML → 消息模拟基本【无效】"),\n    ("WinUIDesktopWin32WindowClass", "WinUI → 消息模拟基本【无效】"),\n    ("Button", "经典 Win32 按钮控件 → 消息模拟【有效】"),\n    ("Static", "经典 Win32 静态文本"),\n    ("Edit", "经典 Win32 编辑框"),\n    ("ComboBox", "经典 Win32 下拉框"),\n    ("#32770", "经典 Win32 对话框"),\n)\n\n\ndef _hwnd_int(handle) -> int | None:\n    if not handle:\n        return None\n    raw = getattr(handle, "value", handle)\n    return int(raw) if raw else None\n\n\ndef classify(class_name: str) -> str | None:\n    for prefix, verdict in _CLASS_RULES:\n        if class_name.startswith(prefix):\n            return verdict\n    return None\n\n\ndef class_of(hwnd: int) -> str:\n    buf = ctypes.create_unicode_buffer(256)\n    _user32.GetClassNameW(wintypes.HWND(hwnd), buf, 256)\n    return buf.value\n\n\ndef title_of(hwnd: int) -> str:\n    length = _user32.GetWindowTextLengthW(wintypes.HWND(hwnd))\n    if length <= 0:\n        return ""\n    buf = ctypes.create_unicode_buffer(length + 1)\n    _user32.GetWindowTextW(wintypes.HWND(hwnd), buf, length + 1)\n    return buf.value\n\n\ndef pid_of(hwnd: int) -> int:\n    out = wintypes.DWORD(0)\n    _user32.GetWindowThreadProcessId(wintypes.HWND(hwnd), ctypes.byref(out))\n    return int(out.value)\n\n\ndef is_visible(hwnd: int) -> bool:\n    return bool(_user32.IsWindowVisible(wintypes.HWND(hwnd)))\n\n\ndef cursor_pos() -> tuple[int, int] | None:\n    point = wintypes.POINT()\n    if not _user32.GetCursorPos(ctypes.byref(point)):\n        return None\n    return int(point.x), int(point.y)\n\n\ndef window_from_point(x: int, y: int) -> int | None:\n    return _hwnd_int(_user32.WindowFromPoint(wintypes.POINT(int(x), int(y))))\n\n\ndef ancestors(hwnd: int) -> list[int]:\n    """从 hwnd 一路往上到顶层（含自身）。"""\n    chain: list[int] = []\n    current: int | None = hwnd\n    seen: set[int] = set()\n    while current and current not in seen:\n        seen.add(current)\n        chain.append(current)\n        parent = _hwnd_int(_user32.GetAncestor(wintypes.HWND(current), GA_PARENT))\n        current = parent\n    return chain\n\n\ndef top_level_windows() -> list[int]:\n    found: list[int] = []\n\n    @_EnumProc\n    def _cb(hwnd, _lparam):\n        value = _hwnd_int(hwnd)\n        if value:\n            found.append(value)\n        return True\n\n    _user32.EnumWindows(_cb, 0)\n    return found\n\n\ndef child_windows(hwnd: int) -> list[int]:\n    found: list[int] = []\n\n    @_EnumProc\n    def _cb(child, _lparam):\n        value = _hwnd_int(child)\n        if value:\n            found.append(value)\n        return True\n\n    _user32.EnumChildWindows(wintypes.HWND(hwnd), _cb, 0)\n    return found\n\n\ndef describe_window(hwnd: int) -> str:\n    name = class_of(hwnd)\n    title = title_of(hwnd)\n    shown = f" \\"{title}\\"" if title else ""\n    return f"0x{hwnd:X}  {name}{shown}  (pid={pid_of(hwnd)}, visible={is_visible(hwnd)})"\n\n\ndef _rule(title: str) -> None:\n    print()\n    print("=" * 72)\n    print(title)\n    print("=" * 72)\n\n\ndef report_point(x: int, y: int) -> tuple[int | None, int | None]:\n    """打印该坐标处的窗口链，返回 (最深窗口, 顶层窗口)。"""\n    _rule(f"① 坐标 ({x}, {y}) 下的窗口链")\n    deepest = window_from_point(x, y)\n    if deepest is None:\n        print("  该坐标处没有窗口（可能落在桌面/空白上）。")\n        return None, None\n\n    chain = ancestors(deepest)\n    verdicts: list[str] = []\n    for level, hwnd in enumerate(chain):\n        cls = class_of(hwnd)\n        verdict = classify(cls)\n        mark = f"   ← {verdict}" if verdict else ""\n        print(f"  第 {level} 层: {describe_window(hwnd)}{mark}")\n        if verdict:\n            verdicts.append(f"{cls} → {verdict}")\n\n    top = chain[-1]\n    print()\n    print("  判定（自上而下第一处能定性的窗口类）：")\n    if verdicts:\n        for item in verdicts:\n            print(f"    · {item}")\n    else:\n        print("    · 未识别出已知框架类名，可能是自绘界面；建议再看下面的 UIA 结果。")\n\n    # 顶层窗口下有没有 Chromium 子窗口 —— JCEF 的典型痕迹\n    kids = child_windows(top)\n    chromium_kids = [h for h in kids if class_of(h).startswith(("Chrome_", "Cef"))]\n    if chromium_kids:\n        print()\n        print("  ⚠ 顶层窗口里发现 Chromium/CEF 子窗口（JCEF 的典型特征）：")\n        for h in chromium_kids[:8]:\n            print(f"    · {describe_window(h)}")\n        print("    → 说明界面里内嵌了网页，网页里的按钮【收不到】PostMessage，只能用 UIA。")\n    return deepest, top\n\n\ndef report_process_windows(pid: int) -> None:\n    _rule(f"② 进程 pid={pid} 的顶层窗口")\n    wins = [h for h in top_level_windows() if pid_of(h) == pid]\n    if not wins:\n        print("  没找到该 pid 的顶层窗口。")\n        return\n    for hwnd in wins:\n        print(f"  {describe_window(hwnd)}")\n        kids = child_windows(hwnd)\n        chromium_kids = [h for h in kids if class_of(h).startswith(("Chrome_", "Cef"))]\n        if chromium_kids:\n            print(f"      ↳ 内含 {len(chromium_kids)} 个 Chromium/CEF 子窗口（JCEF）")\n\n\ndef report_uia(x: int, y: int) -> None:\n    _rule("③ UI Automation（无障碍接口）探测")\n    try:\n        import uiautomation as auto  # type: ignore\n    except Exception:\n        print("  未安装 uiautomation，跳过。想测这条路径请先执行：")\n        print("      pip install uiautomation")\n        print("  装好后重跑本脚本，就能看到按钮能不能被 UIA 找到、支不支持 Invoke。")\n        return\n\n    try:\n        auto.SetGlobalSearchTimeout(3)\n    except Exception:\n        pass\n\n    def _attr(ctrl, name: str, default: str = "?") -> str:\n        try:\n            value = getattr(ctrl, name)\n        except Exception:  # noqa: BLE001 - 某些节点取属性就会抛\n            return default\n        return str(value)\n\n    def _can_invoke(ctrl) -> bool:\n        try:\n            ctrl.GetInvokePattern()\n            return True\n        except Exception:  # noqa: BLE001\n            return False\n\n    # 3.1 光标下的元素\n    print("  · 该坐标下的 UIA 元素：")\n    try:\n        ctrl = auto.ControlFromPoint(x, y)\n        if ctrl is None:\n            print("      （没取到元素）")\n        else:\n            print(f"      名称(Name)      : {_attr(ctrl, \'Name\')!r}")\n            print(f"      控件类型        : {_attr(ctrl, \'ControlTypeName\')}")\n            print(f"      类名(ClassName) : {_attr(ctrl, \'ClassName\')}")\n            print(f"      自动化 Id       : {_attr(ctrl, \'AutomationId\')}")\n            print(f"      进程 Id         : {_attr(ctrl, \'ProcessId\')}")\n            can = _can_invoke(ctrl)\n            print("      支持 InvokePattern: " + ("是   ← 可以『真后台』调用，不移动鼠标" if can else "否"))\n    except Exception as exc:  # noqa: BLE001 - 探针不该因为 UIA 异常中断\n        print(f"      （取元素失败：{exc!r}）")\n\n    # 3.2 全桌面找「继续/取消」这类按钮\n    print()\n    print("  · 在 UIA 树里搜索『继续/取消/Continue/Cancel/Resume』：")\n    keywords = {"继续", "取消", "Continue", "Cancel", "Resume", "continue", "cancel"}\n    hits = 0\n    try:\n        root = auto.GetRootControl()\n        # 手工广度遍历：只用 GetChildren()，比依赖库里的遍历辅助函数更稳\n        queue: list[tuple[object, int]] = [(root, 0)]\n        budget = 6000\n        while queue and budget > 0:\n            ctrl, depth = queue.pop(0)\n            budget -= 1\n            try:\n                name = ctrl.Name\n            except Exception:  # noqa: BLE001\n                name = ""\n            if name in keywords:\n                hits += 1\n                can = "支持 InvokePattern ✅" if _can_invoke(ctrl) else "不支持 Invoke"\n                print(f"      · {name!r}  [{_attr(ctrl, \'ControlTypeName\')}]  "\n                      f"类名={_attr(ctrl, \'ClassName\')}  {can}")\n            if depth >= 24 or budget <= 0:\n                continue\n            try:\n                children = ctrl.GetChildren()\n            except Exception:  # noqa: BLE001\n                children = []\n            for child in children or []:\n                queue.append((child, depth + 1))\n    except Exception as exc:  # noqa: BLE001\n        print(f"      （遍历 UIA 树失败：{exc!r}）")\n\n    if hits == 0:\n        print("      没找到。可能是：按钮在 JCEF 网页里且 a11y 未激活、")\n        print("      或 IDEA 的『Support screen readers』/ Java Access Bridge 没开。")\n        print("      参考：Settings → Appearance & Behavior → Appearance → Support screen readers；")\n        print("      以及 JBR 的 jabswitch -enable（需重启 IDEA）。")\n    else:\n        print()\n        print(f"      ✅ 找到 {hits} 个候选按钮，说明 UIA 这条路可行。")\n\n\ndef report_backend_click(x: int, y: int) -> None:\n    _rule("④ 用项目自带的后台后端真点一下（判定 PostMessage 是否被目标理会）")\n    try:\n        from app.input.base import MouseButton\n        from app.input.postmessage import PostMessageBackend\n    except Exception as exc:  # noqa: BLE001\n        print(f"  无法导入项目模块：{exc!r}")\n        print("  请确认在项目根目录运行，且用的是项目自带的 Python 环境。")\n        return\n\n    try:\n        from app.win.admin import is_admin\n        if not is_admin():\n            print("  注意：当前是普通权限。若目标程序以管理员运行，UIPI 会拦掉注入的点击。")\n    except Exception:\n        pass\n\n    backend = PostMessageBackend()\n    if not backend.bind_point(x, y):\n        print("  bind_point 失败：该坐标处没有可用的窗口。")\n        return\n    print(f"  已绑定顶层窗口：{backend.bound_title}")\n\n    target = backend._resolve(x, y)  # noqa: SLF001 - 探针需要展示解析结果\n    if target is None:\n        print("  目标解析失败（拿不到客户区坐标）。")\n        return\n    hwnd, cx, cy = target\n    print(f"  实际收件窗口：{describe_window(hwnd)}")\n    print(f"      ← 类名 {class_of(hwnd)}：{classify(class_of(hwnd)) or \'未识别\'}")\n    print(f"  客户区坐标  ：({cx}, {cy})")\n\n    backend.click(x, y, MouseButton.LEFT)\n    print("  已投递：WM_MOUSEMOVE → WM_LBUTTONDOWN → WM_LBUTTONUP")\n    print("  → 请观察目标按钮有没有反应。没有反应基本就说明这类窗口不吃 WM_*。")\n\n\ndef main() -> int:\n    parser = argparse.ArgumentParser(\n        description="后台点击自检探针：判定目标程序适不适合 PostMessage / UIA 后台点击"\n    )\n    parser.add_argument("--point", nargs=2, type=int, metavar=("X", "Y"),\n                        help="直接分析该屏幕物理像素坐标，跳过等待")\n    parser.add_argument("--delay", type=int, default=5,\n                        help="等待你把鼠标移到目标控件上的秒数，默认 5")\n    parser.add_argument("--no-click", action="store_true",\n                        help="只分析，不做实际的点击测试")\n    args = parser.parse_args()\n\n    print("后台点击自检探针")\n    print("提示：请先把 IDEA 和那个弹窗摆好，鼠标停在『继续』按钮上。")\n\n    if args.point:\n        x, y = args.point\n    else:\n        print(f"\\n{args.delay} 秒后读取光标位置，请把鼠标移到『继续』按钮上……")\n        for remaining in range(args.delay, 0, -1):\n            print(f"  {remaining}…", end="\\r", flush=True)\n            time.sleep(1)\n        pos = cursor_pos()\n        if pos is None:\n            print("读取光标位置失败。")\n            return 1\n        x, y = pos\n        print(f"  光标位置：({x}, {y})")\n\n    deepest, top = report_point(x, y)\n\n    pid = pid_of(top) if top else None\n    if pid:\n        report_process_windows(pid)\n\n    report_uia(x, y)\n\n    if args.no_click:\n        print("\\n（--no-click：跳过点击测试）")\n    else:\n        print("\\n" + "-" * 72)\n        answer = input("要现在用后台方式真点一下这个位置吗？(y/N) ").strip().lower()\n        if answer == "y":\n            report_backend_click(x, y)\n        else:\n            print("已跳过点击测试。")\n\n    _rule("怎么读这份结果")\n    print("  · 窗口链里出现 SunAwt*/Qt*/Button → PostMessage 有戏；出现 Chrome_*/Cef* → 没戏，走 UIA。")\n    print("  · 第 ③ 节能列出『继续』且『支持 InvokePattern』→ UIA 方案可行。")\n    print("  · 第 ④ 节点了没反应 → 这条路对你的目标无效。")\n    print("  把这份输出贴回来，我按结果给你实现对应的方案。")\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n',
    'app/__init__.py': '"""AutoClicker —— Windows 10 自动点击 GUI 工具。"""\n\n__version__ = "0.4.0"\nAPP_NAME = "AutoClicker"\n',
    'app/core/__init__.py': '"""核心层：数据模型与点击引擎。"""\n',
    'app/core/engine.py': '"""宏执行引擎。\n\n线程模型\n--------\n``MacroEngine`` 会被 ``moveToThread`` 到一个工作线程，主线程只通过信号与它交互：\n\n- 主线程 → 引擎：``start_requested`` 信号（队列连接）投递方案；\n  ``request_stop()`` 直接置位 ``threading.Event``，跨线程调用是安全的。\n- 引擎 → 主线程：``started`` / ``step_changed`` / ``progress`` / ``stopped`` / ``failed``\n  信号，自动排队回到 UI 线程。\n\n时序策略\n--------\n用 ``time.perf_counter()``（单调时钟）维护 **下一个绝对触发时刻**，每轮只 sleep 差值，\n因此不会像 ``sleep(interval)`` 那样累积漂移。\n若因为系统卡顿已经落后太多，则把时间轴重置到当前时刻，避免「追赶风暴」把 CPU 打满。\n\n停止响应\n--------\n所有等待都走 ``Event.wait()`` 而不是 ``sleep()``，所以 F10 能立刻打断等待，\n即使正处在 5 秒的延时步骤里。\n"""\n\nfrom __future__ import annotations\n\nimport logging\nimport math\nimport random\nimport threading\nimport time\n\nfrom PySide6.QtCore import QObject, Signal, Slot\n\nfrom ..input.base import InputBackend\nfrom .matching import find_template\nfrom .models import (\n    ON_TIMEOUT_STOP,\n    ClickStep,\n    DelayStep,\n    KeyStep,\n    MoveStep,\n    Profile,\n    Step,\n    WaitStep,\n)\n\nlogger = logging.getLogger(__name__)\n\n# 落后超过该阈值（秒）就重新对齐时间轴\nLAG_RESET_THRESHOLD = 0.25\n\n# 进度信号的最小间隔（秒）。间隔 1ms 时若每次点击都发信号会淹掉 UI 事件循环\nPROGRESS_THROTTLE = 0.05\n\n# 轨迹插值的步长（秒）。太小会淹没输入队列，太大movement会一顿一顿\nMOVE_TICK = 0.012\n\n\nclass MacroEngine(QObject):\n    """在工作线程中按步骤序列执行方案。"""\n\n    started = Signal()\n    step_changed = Signal(int, int)  # 当前步骤序号（1 起）, 启用步骤总数\n    progress = Signal(int, int, int)  # 累计动作数, 已完成轮数, 总轮数（0 = 无限）\n    stopped = Signal(int)  # 本次运行累计动作数\n    failed = Signal(str)  # 不可恢复的错误信息\n    wait_timeout = Signal(object)  # 找图超时时的最后一帧（ScreenFrame），供 UI 落盘诊断\n\n    def __init__(\n        self,\n        backend: InputBackend,\n        parent: QObject | None = None,\n        screen=None,\n    ) -> None:\n        super().__init__(parent)\n        self._backend = backend\n        # 抓屏函数，默认走 GDI。测试注入假函数就不需要真的有个屏幕\n        self._screen = screen\n        self._stop_event = threading.Event()\n        self._running = False\n        self._lock = threading.Lock()\n\n        # 可变状态只在工作线程里读写\n        self._actions = 0\n        self._rounds_done = 0\n        self._rounds_total = 0\n        self._last_progress_time = 0.0\n\n    # ------------------------------------------------------------------ 状态\n    @property\n    def running(self) -> bool:\n        return self._running\n\n    # ------------------------------------------------------------------ 控制\n    @Slot(object)\n    def run(self, profile: Profile) -> None:\n        """执行方案。本槽由工作线程调用，不要直接在主线程调用。"""\n        with self._lock:\n            if self._running:\n                logger.debug("引擎已在运行，忽略新的启动请求")\n                return\n            self._running = True\n\n        self._stop_event.clear()\n        self._actions = 0\n        self._rounds_done = 0\n        self._rounds_total = profile.repeat\n        self._last_progress_time = 0.0\n        self.started.emit()\n\n        steps = profile.active_steps()\n        logger.info(\n            "开始执行方案「%s」: %s 个启用步骤, 轮数=%s",\n            profile.name,\n            len(steps),\n            "无限" if profile.infinite else profile.repeat,\n        )\n\n        try:\n            profile.validate()\n            self._execute(profile, steps)\n        except Exception as exc:  # noqa: BLE001 - 任何异常都要反馈到 UI\n            logger.exception("执行方案出错")\n            self.failed.emit(str(exc))\n        finally:\n            with self._lock:\n                self._running = False\n            self.stopped.emit(self._actions)\n            logger.info("执行结束，共完成 %s 次动作", self._actions)\n\n    def request_stop(self) -> None:\n        """请求停止。可从任意线程调用。"""\n        self._stop_event.set()\n\n    def set_backend(self, backend: InputBackend) -> None:\n        """切换输入后端（前台 SendInput / 后台 PostMessage）。\n\n        只在未运行时允许切换：``_backend`` 只在工作线程里被读，运行途中替换会让\n        同一次运行混用两种注入方式。UI 侧统一在 start 之前调用，所以碰不到这条限制。\n        """\n        with self._lock:\n            if self._running:\n                raise RuntimeError("运行中不能切换输入后端")\n            self._backend = backend\n\n    # ------------------------------------------------------------------ 主循环\n    def _execute(self, profile: Profile, steps: list[Step]) -> None:\n        if profile.start_delay_ms:\n            logger.info("启动延迟 %s ms", profile.start_delay_ms)\n            if self._stop_event.wait(profile.start_delay_ms / 1000.0):\n                return\n\n        total_steps = len(steps)\n\n        while not self._stop_event.is_set():\n            for index, step in enumerate(steps, start=1):\n                if self._stop_event.is_set():\n                    return\n                self.step_changed.emit(index, total_steps)\n                logger.debug("执行第 %s/%s 步: %s", index, total_steps, step.summary())\n                self._run_step(step)\n\n            self._rounds_done += 1\n            self._emit_progress(force=True)\n\n            if self._stop_event.is_set():\n                return\n            if self._rounds_total and self._rounds_done >= self._rounds_total:\n                return\n            if profile.repeat_delay_ms and self._stop_event.wait(profile.repeat_delay_ms / 1000.0):\n                return\n\n    def _run_step(self, step: Step) -> None:\n        if isinstance(step, ClickStep):\n            self._run_click(step)\n        elif isinstance(step, DelayStep):\n            self._run_delay(step)\n        elif isinstance(step, KeyStep):\n            self._run_key(step)\n        elif isinstance(step, MoveStep):\n            self._run_move(step)\n        elif isinstance(step, WaitStep):\n            self._run_wait(step)\n        else:  # pragma: no cover - 新增步骤类型时忘了加分支\n            raise ValueError(f"不支持的步骤类型: {step.kind}")\n\n    def _run_click(self, step: ClickStep) -> None:\n        interval = step.interval_ms / 1000.0\n        jitter = step.jitter_ms / 1000.0\n        next_time = time.perf_counter()\n        done = 0\n\n        while done < step.repeat and not self._stop_event.is_set():\n            x, y = step.x, step.y\n            if step.jitter_px:\n                x += random.randint(-step.jitter_px, step.jitter_px)\n                y += random.randint(-step.jitter_px, step.jitter_px)\n\n            self._backend.click(x, y, step.button)\n            done += 1\n            self._actions += 1\n\n            now = time.perf_counter()\n            self._emit_progress(now=now, force=done >= step.repeat)\n            if done >= step.repeat:\n                break\n\n            wait = interval + (random.uniform(0.0, jitter) if jitter else 0.0)\n            next_time += wait\n            if next_time < now - LAG_RESET_THRESHOLD:\n                next_time = now\n\n            remaining = next_time - now\n            if remaining > 0 and self._stop_event.wait(remaining):\n                break\n\n    def _run_delay(self, step: DelayStep) -> None:\n        seconds = step.delay_ms / 1000.0\n        if step.jitter_ms:\n            seconds += random.uniform(0.0, step.jitter_ms / 1000.0)\n        if seconds > 0:\n            self._stop_event.wait(seconds)\n\n    def _run_move(self, step: MoveStep) -> None:\n        """沿折线轨迹匀速移动光标。\n\n        用「总时长按各段长度比例分配」的方式插值，而不是固定每段多少毫秒，\n        这样拐点疏密不同时速度依然均匀，视觉上不会忽快忽慢。\n        """\n        points = step.points\n        if not points:\n            return\n\n        self._actions += 1\n        self._emit_progress(force=True)\n\n        if len(points) == 1:\n            self._backend.move_to(points[0][0], points[0][1])\n            return\n\n        lengths = [\n            math.hypot(bx - ax, by - ay)\n            for (ax, ay), (bx, by) in zip(points, points[1:])\n        ]\n        total_length = sum(lengths)\n        total_seconds = step.duration_ms / 1000.0\n\n        # 没有位移或没给时长：直接落点，不做无意义的插值\n        if total_length <= 0 or total_seconds <= 0:\n            self._backend.move_to(points[-1][0], points[-1][1])\n            return\n\n        begin = time.perf_counter()\n        elapsed = 0.0\n\n        for index, segment_length in enumerate(lengths):\n            if self._stop_event.is_set():\n                return\n            (ax, ay), (bx, by) = points[index], points[index + 1]\n            segment_seconds = total_seconds * (segment_length / total_length)\n            ticks = max(1, int(segment_seconds / MOVE_TICK) + 1)\n            step_seconds = segment_seconds / ticks\n\n            for tick in range(1, ticks + 1):\n                fraction = tick / ticks\n                self._backend.move_to(\n                    round(ax + (bx - ax) * fraction),\n                    round(ay + (by - ay) * fraction),\n                )\n                elapsed += step_seconds\n                remaining = (begin + elapsed) - time.perf_counter()\n                if remaining > 0 and self._stop_event.wait(remaining):\n                    return\n\n        self._backend.move_to(points[-1][0], points[-1][1])\n\n    def _run_key(self, step: KeyStep) -> None:\n        interval = step.interval_ms / 1000.0\n        next_time = time.perf_counter()\n        done = 0\n\n        while done < step.repeat and not self._stop_event.is_set():\n            self._backend.press_key(step.vk)\n            done += 1\n            self._actions += 1\n\n            now = time.perf_counter()\n            self._emit_progress(now=now, force=done >= step.repeat)\n            if done >= step.repeat:\n                break\n\n            next_time += interval\n            if next_time < now - LAG_RESET_THRESHOLD:\n                next_time = now\n\n            remaining = next_time - now\n            if remaining > 0 and self._stop_event.wait(remaining):\n                break\n\n    def _run_wait(self, step: WaitStep) -> None:\n        """等屏幕上出现目标图片，出现后（可选）点它。\n\n        每一轮都是「抓一帧 → 找一次 → 睡到下一个轮询点」，等待用 ``Event.wait``\n        分段进行，所以 F10 依然能立刻打断，不会卡在最大 30 秒的等待里。\n\n        超时**只在「中止」模式下**把最后一帧交给 UI 落盘：如果是「继续」模式，\n        一个循环里反复超时的等待步骤会写出一堆截图，反而变成噪声。\n        """\n        template = step.decoded()\n        poll = step.poll_interval_ms / 1000.0\n        deadline = time.perf_counter() + step.timeout_ms / 1000.0\n\n        while True:\n            if self._stop_event.is_set():\n                return\n\n            try:\n                frame = self._capture()\n            except OSError as exc:\n                raise RuntimeError(f"抓取屏幕失败：{exc}") from exc\n\n            result = find_template(frame, template, tolerance=step.tolerance)\n            match = result.match\n            if match is not None:\n                x = frame.x + match.x + template.width // 2 + step.offset_x\n                y = frame.y + match.y + template.height // 2 + step.offset_y\n                logger.info(\n                    "找图命中 %s，位置 (%s, %s)，相似度 %.2f",\n                    template.summary,\n                    x,\n                    y,\n                    match.similarity,\n                )\n                if step.click:\n                    self._backend.click(x, y, step.button)\n                    self._actions += 1\n                    self._emit_progress(force=True)\n                return\n\n            remaining = deadline - time.perf_counter()\n            if remaining <= 0:\n                self._handle_wait_timeout(step, result, frame)\n                return\n            if self._stop_event.wait(min(poll, remaining)):\n                return\n\n    def _handle_wait_timeout(self, step: WaitStep, result, frame) -> None:\n        detail = f"，最接近的相似度只有 {result.best_similarity:.2f}" if result else ""\n        message = f"等图片出现超时（{step.timeout_ms} 毫秒内没找到）{detail}"\n        if step.on_timeout == ON_TIMEOUT_STOP:\n            self.wait_timeout.emit(frame)\n            raise TimeoutError(message)\n        logger.warning("%s，继续下一步", message)\n\n    # ------------------------------------------------------------------ 抓屏\n    def _capture(self):\n        """抓一帧整屏。默认走 GDI；测试注入假函数后就不再需要真屏幕。"""\n        if self._screen is not None:\n            return self._screen()\n        from ..win.screen import capture_screen\n\n        return capture_screen()\n\n    # ------------------------------------------------------------------ 进度\n    def _emit_progress(self, now: float | None = None, force: bool = False) -> None:\n        """按 ``PROGRESS_THROTTLE`` 节流上报进度。"""\n        if now is None:\n            now = time.perf_counter()\n        if not force and now - self._last_progress_time < PROGRESS_THROTTLE:\n            return\n        self._last_progress_time = now\n        self.progress.emit(self._actions, self._rounds_done, self._rounds_total)\n',
    'app/core/matching.py': '"""模板匹配（找图）。\n\n为什么不用 OpenCV\n-----------------\n``cv2.matchTemplate`` 是标准答案，但会往 exe 里塞进 40MB+ 的依赖，而这个项目一直\n守着「只有 PySide6」的线。这里用一套零依赖的做法，核心是**借用 ``bytes.find()``**：\n\n1. 从模板里挑一条**像素签名**（详见 ``pick_probes``）；\n2. 在整帧裸字节上 ``find(签名)`` —— 这是 C 层的 memmem，十几 MB 只需几毫秒；\n3. 对每个候选位置再抽 8x8 个采样点做**容差比对**，排除「像素对上了但整体形状不像」的假命中。\n\n为什么能快\n----------\n签名很长，误命中率很低，绝大多数字节位置在第一步就被 C 代码否决掉了，\n真正进入 Python 循环的只有极少数候选点。\n\n两个探针，先锐利后退让\n----------------------\n单个「纯色横线」探针在**大面积同色背景**上会疯狂命中（整块桌布同一个颜色时，\n每一行都能对上），几千个候选全是废的。所以默认先用一个更长的签名：\n**内容最丰富的那一行整行像素**——它横跨文字和边框，字节多得多，几乎不会误命中。\n只有当它一个候选都拿不到（那一行里有一个像素没渲染成一样）时，\n才退回纯色探针：像素最稳，但选择性差。\n\n限制\n----\n- 签名是**逐字节**比对的，不做模糊搜索：目标程序换主题 / 换语言 / 改 DPI 缩放后\n  必须重新截模板。「容差」只作用于最后那步抽样比对，用来容忍文字抗锯齿一类的\n  细微差异，救不回整体变色。这是刻意的取舍，换来了零依赖 + 每帧几毫秒。\n- 只做**原尺寸**匹配，不做多尺度缩放：同一台机器、同一份界面没有缩放的余地。\n"""\n\nfrom __future__ import annotations\n\nimport base64\nimport binascii\nimport logging\nimport struct\nimport zlib\nfrom dataclasses import dataclass\nfrom typing import TYPE_CHECKING\n\nif TYPE_CHECKING:  # pragma: no cover - 只为类型提示，避免把 Win32 拖进来\n    from ..win.screen import ScreenFrame\n\nlogger = logging.getLogger(__name__)\n\n# 模板序列化格式：magic + 宽高 + zlib 压缩的 BGRA\nMAGIC = b"ACT1"\nBYTES_PER_PIXEL = 4\n\n# 单通道色差容差。32 大约能容忍抗锯齿的文字边缘和轻微的渲染差异\nDEFAULT_TOLERANCE = 32\n\n# 抽样比对需要达到的通过比例。留 15% 的余量给文字/边缘的渲染差异\nDEFAULT_MIN_SIMILARITY = 0.85\n\n# 「纯色探针」至少要这么长才够特征（太短的纯色片段到处都是）\nMIN_PROBE_PX = 6\n# 「纯色探针」也不宜过长：越长越难要求「逐字节完全一致」\nMAX_PROBE_PX = 48\n# 「整行探针」的像素上限。越长越准，但一个像素渲染不同就整条废弃\nMAX_ROW_PROBE_PX = 120\n\n# 抽样网格：8x8 = 64 个点\nSAMPLE_GRID = 8\n\n# 每条探针最多验算多少个候选点。\n# 这是备选位置的上限，不是搜索范围的上限；有界扫描（见 _scan）已经把\n# 越界位置剔掉了，所以正常屏面上根本摸不到这个数\nMAX_CANDIDATES = 5000\n\n\n@dataclass(frozen=True)\nclass Template:\n    """一小块屏幕像素。``data`` 是自顶向下、``stride = width * 4`` 的 BGRA。"""\n\n    width: int\n    height: int\n    data: bytes\n\n    def __post_init__(self) -> None:\n        if self.width < 1 or self.height < 1:\n            raise ValueError("模板尺寸必须大于 0")\n        expected = self.width * self.height * BYTES_PER_PIXEL\n        if len(self.data) != expected:\n            raise ValueError(f"模板像素数量不对（{len(self.data)} != {expected}）")\n\n    @property\n    def stride(self) -> int:\n        return self.width * BYTES_PER_PIXEL\n\n    @property\n    def summary(self) -> str:\n        return f"{self.width} × {self.height}"\n\n    def pixel(self, x: int, y: int) -> tuple[int, int, int]:\n        """返回 ``(B, G, R)``。"""\n        offset = y * self.stride + x * BYTES_PER_PIXEL\n        return self.data[offset], self.data[offset + 1], self.data[offset + 2]\n\n    # ------------------------------------------------------------ 序列化\n    def encode(self) -> str:\n        """压成可放进 JSON 的字符串。\n\n        用 zlib 而不是 PNG：不引入任何编码器依赖，纯色块压缩比也不差，\n        而且这一步完全不碰 Qt，核心层因此保持干净。\n        """\n        if self.width > 0xFFFF or self.height > 0xFFFF:  # pragma: no cover - 现实里到不了\n            raise ValueError("模板尺寸超出存储格式上限")\n        payload = (\n            MAGIC\n            + struct.pack("<HH", self.width, self.height)\n            + zlib.compress(self.data, 9)\n        )\n        return base64.b64encode(payload).decode("ascii")\n\n    @classmethod\n    def decode(cls, text: str) -> "Template":\n        """从 ``encode()`` 的结果还原。数据坏掉时抛 ``ValueError``。"""\n        if not text:\n            raise ValueError("模板为空")\n        try:\n            raw = base64.b64decode(text, validate=True)\n        except (binascii.Error, ValueError) as exc:\n            raise ValueError("模板数据不是合法的 base64") from exc\n\n        if len(raw) < 8 or raw[:4] != MAGIC:\n            raise ValueError("模板数据格式不认识（可能是旧版本或已损坏）")\n\n        width, height = struct.unpack_from("<HH", raw, 4)\n        if width < 1 or height < 1:\n            raise ValueError("模板尺寸无效")\n\n        try:\n            data = zlib.decompress(raw[8:])\n        except zlib.error as exc:\n            raise ValueError("模板数据已损坏") from exc\n\n        return cls(width=width, height=height, data=data)\n\n    @classmethod\n    def from_frame(cls, frame: "ScreenFrame") -> "Template":\n        """把一整帧（通常是刚裁好的那一小块）当成模板。"""\n        return cls(width=frame.width, height=frame.height, data=bytes(frame.data))\n\n\n@dataclass(frozen=True)\nclass Match:\n    """一次命中。``(x, y)`` 相对帧左上角。"""\n\n    x: int\n    y: int\n    similarity: float\n\n\n@dataclass(frozen=True)\nclass SearchResult:\n    """搜索结果。\n\n    ``best`` 是**最高分候选**，即使没达到阈值也保留——超时时把它打日志，\n    用户就能看到「最接近的是 0.62」而不是一句干巴巴的「没找到」。\n\n    ``candidates`` 是扫描时**签名命中的位置数**（多条探针累加），不是完整比对次数；\n    它主要用来判断「屏幕上连颜色接近的地方都没有」还是「有候选但形状对不上」。\n    """\n\n    match: Match | None\n    best: Match | None\n    candidates: int\n\n    @property\n    def found(self) -> bool:\n        return self.match is not None\n\n    @property\n    def best_similarity(self) -> float:\n        return self.best.similarity if self.best else 0.0\n\n\n@dataclass(frozen=True)\nclass Probe:\n    """探针：模板里一段纯色横线，用它在帧里做字节级初筛。"""\n\n    row: int\n    offset: int\n    signature: bytes\n\n    @property\n    def length(self) -> int:\n        return len(self.signature) // BYTES_PER_PIXEL\n\n\ndef solid_run_length(template: Template) -> int:\n    """模板里最长的一段纯色横线的像素数。\n\n    这是「这个模板稳不稳」的指标：纯色段越长、越厚，界面轻微变化时越不容易失配。\n    小到 ``MIN_PROBE_PX`` 以下时纯色签名就没法用了，只能靠整行签名硬碰。\n    UI 用它给用户提示。\n    """\n    return _longest_run(template)[2]\n\n\ndef _longest_run(template: Template) -> tuple[int, int, int]:\n    """返回 ``(行号, 起始列, 长度)``：模板中最长的一段同色横线。"""\n    best_row = 0\n    best_start = 0\n    best_length = 0\n\n    for y in range(template.height):\n        base = y * template.stride\n        run_start = 0\n        run_pixel = template.data[base : base + BYTES_PER_PIXEL]\n        for x in range(1, template.width + 1):\n            if x == template.width:\n                pixel = None\n            else:\n                offset = base + x * BYTES_PER_PIXEL\n                pixel = template.data[offset : offset + BYTES_PER_PIXEL]\n            if pixel != run_pixel:\n                length = x - run_start\n                if length > best_length:\n                    best_length = length\n                    best_row = y\n                    best_start = run_start\n                if pixel is not None:\n                    run_start = x\n                    run_pixel = pixel\n\n    return best_row, best_start, best_length\n\n\ndef pick_probes(template: Template) -> list[Probe]:\n    """挑出模板的签名，按「先锐利、后退让」排序。\n\n    1. **内容最丰富的那一行**（横跨文字/边框）：签名里带着颜色变化，\n       所以几乎不会在别处误命中。代价是要求这整整一行逐像素一致，\n       界面稍微变一点就会整条落空。\n    2. **最长的一段纯色横线**：纯色几乎不可能渲染出差异，所以最稳；\n       但也因为太「普通」，在大面积同色背景上会产生一大堆候选。\n       它同时是 1 号探针整条落空时的退路。\n\n    模板本来就是纯色（没有文字也没有边框）时两者会重合，此时只返回一条。\n    连一段够长的纯色都找不出来时（照片类模板），只返回 1 号签名。\n    """\n    probes = [_busy_probe(template)]\n    solid = _solid_probe(template)\n    if solid is None:\n        logger.debug("模板里没有够长的纯色段，只用「整行签名」这一个探针")\n    elif not any(solid.row == probe.row and solid.offset == probe.offset for probe in probes):\n        probes.append(solid)\n    return probes\n\n\ndef _busy_probe(template: Template) -> Probe:\n    """内容最丰富的那一行的整行像素。"""\n    row = _busiest_row(template)\n    length = min(template.width, MAX_ROW_PROBE_PX)\n    start = (template.width - length) // 2\n    base = row * template.stride\n    return Probe(\n        row=row,\n        offset=start,\n        signature=template.data[base + start * 4 : base + (start + length) * 4],\n    )\n\n\ndef _solid_probe(template: Template) -> Probe | None:\n    """最长的一段纯色横线的中间部分。纯色段太短就返回 ``None``。\n\n    太短的纯色片段（比如 1 个像素）几乎在整帧的每个位置都能命中，\n    拿它当签名只会把候选配额烧光，不如不用。\n    """\n    row, start, run = _longest_run(template)\n    if run < MIN_PROBE_PX:\n        return None\n\n    length = min(run, MAX_PROBE_PX)\n    # 取中间一段：避开与文字/边框接壤的两端\n    start += (run - length) // 2\n    base = row * template.stride\n    return Probe(\n        row=row,\n        offset=start,\n        signature=template.data[base + start * 4 : base + (start + length) * 4],\n    )\n\n\ndef _busiest_row(template: Template) -> int:\n    """返回「相邻像素差异之和」最大的一行，即内容最丰富的一行。"""\n    best_row = 0\n    best_change = -1\n    for y in range(template.height):\n        base = y * template.stride\n        change = 0\n        previous = template.data[base : base + 3]\n        for x in range(1, template.width):\n            offset = base + x * 4\n            current = template.data[offset : offset + 3]\n            change += (\n                abs(current[0] - previous[0])\n                + abs(current[1] - previous[1])\n                + abs(current[2] - previous[2])\n            )\n            previous = current\n        if change > best_change:\n            best_change = change\n            best_row = y\n    return best_row\n\n\ndef sample_points(template: Template, grid: int = SAMPLE_GRID) -> list[tuple[int, int]]:\n    """模板内均匀分布的抽样点（含四角与中心）。"""\n    cols = max(1, min(grid, template.width))\n    rows = max(1, min(grid, template.height))\n    xs = [_spread(index, cols, template.width) for index in range(cols)]\n    ys = [_spread(index, rows, template.height) for index in range(rows)]\n    return [(x, y) for y in ys for x in xs]\n\n\ndef _spread(index: int, count: int, size: int) -> int:\n    if count <= 1:\n        return size // 2\n    return round(index * (size - 1) / (count - 1))\n\n\ndef similarity(\n    frame: "ScreenFrame",\n    template: Template,\n    x: int,\n    y: int,\n    tolerance: int,\n    samples: list[tuple[int, int]],\n) -> float:\n    """模板放在帧内 ``(x, y)`` 处时，抽样点落在容差内的比例。\n\n    只比 BGR 三个通道：屏幕像素的 alpha 通道没有意义。\n    """\n    frame_data = frame.data\n    frame_stride = frame.stride\n    template_data = template.data\n    template_stride = template.stride\n\n    passed = 0\n    for sx, sy in samples:\n        toffset = sy * template_stride + sx * 4\n        foffset = (y + sy) * frame_stride + (x + sx) * 4\n        if (\n            abs(template_data[toffset] - frame_data[foffset]) <= tolerance\n            and abs(template_data[toffset + 1] - frame_data[foffset + 1]) <= tolerance\n            and abs(template_data[toffset + 2] - frame_data[foffset + 2]) <= tolerance\n        ):\n            passed += 1\n    return passed / len(samples)\n\n\ndef find_template(\n    frame: "ScreenFrame",\n    template: Template,\n    *,\n    tolerance: int = DEFAULT_TOLERANCE,\n    min_similarity: float = DEFAULT_MIN_SIMILARITY,\n) -> SearchResult:\n    """在帧里找模板。\n\n    多个候选同分时取**最靠上、再最靠左**的那个（``find`` 按偏移递增返回，\n    而偏移是行主序，所以「第一个达到最高分的」天然就是这个规则）。\n\n    依次尝试 ``pick_probes`` 给的签名，先命中的先用——所以顺序很关键，\n    它也决定了「同分取最左上」这条规则实际落在哪个签名上。\n    """\n    if template.width > frame.width or template.height > frame.height:\n        return SearchResult(match=None, best=None, candidates=0)\n\n    samples = sample_points(template)\n    best: Match | None = None\n    candidates = 0\n    truncated = False\n\n    for probe in pick_probes(template):\n        matched, probe_best, scanned, probe_truncated = _scan(\n            frame, template, probe, samples, tolerance, min_similarity\n        )\n        candidates += scanned\n        truncated = truncated or probe_truncated\n\n        if probe_best is not None and (best is None or probe_best.similarity > best.similarity):\n            best = probe_best\n        if matched is not None:\n            return SearchResult(match=matched, best=matched, candidates=candidates)\n\n    if truncated:\n        logger.warning(\n            "候选位置超过 %s 个，已提前结束搜索（当前最高相似度 %.2f）",\n            MAX_CANDIDATES,\n            best.similarity if best else 0.0,\n        )\n\n    return SearchResult(match=None, best=best, candidates=candidates)\n\n\ndef _scan(\n    frame: "ScreenFrame",\n    template: Template,\n    probe: Probe,\n    samples: list[tuple[int, int]],\n    tolerance: int,\n    min_similarity: float,\n) -> tuple[Match | None, Match | None, int, bool]:\n    """用一条签名扫一遍帧。返回 ``(达标匹配, 最高分候选, 命中数, 是否被截断)``。"""\n    data = frame.data\n    stride = frame.stride\n    max_x = frame.width - template.width\n    max_y = frame.height - template.height\n    signature = probe.signature\n    span = len(signature)\n\n    # 只有落在「模板左上角合法范围」里的签名起点才可能是真命中。\n    # 把搜索区间裁到这一带很重要：整块同色的桌面上，签名在每一行都命中，\n    # 不裁的话前几千个候选全落在这个范围之外，白白把配额烧光。\n    begin = probe.row * stride\n    end = min(len(data), (max_y + probe.row + 1) * stride)\n\n    best: Match | None = None\n    hits = 0\n    truncated = False\n\n    position = data.find(signature, begin, end)\n    while position >= 0:\n        hits += 1\n        if hits > MAX_CANDIDATES:\n            truncated = True\n            break\n\n        # 签名必须整体落在同一行内、且按 4 字节像素对齐，否则只是跨行的巧合\n        row, offset = divmod(position, stride)\n        if offset % 4 == 0 and offset + span <= stride:\n            x = offset // 4 - probe.offset\n            y = row - probe.row\n            if 0 <= x <= max_x and 0 <= y <= max_y:\n                score = similarity(frame, template, x, y, tolerance, samples)\n                if best is None or score > best.similarity:\n                    best = Match(x=x, y=y, similarity=score)\n                    if score >= 1.0:\n                        # 满分不可能被超越，而且 find 按行主序返回，\n                        # 所以这里停下同时也就固定了「同分取最左上」的规则\n                        break\n\n        position = data.find(signature, position + 1, end)\n\n    matched = best if best is not None and best.similarity >= min_similarity else None\n    return matched, best, hits, truncated\n',
    'app/core/models.py': '"""核心数据模型。\n\n坐标一律是虚拟屏幕物理像素。\n\n结构\n----\n``Profile`` 是一个完整方案：一串 ``Step`` + 外层循环设置。\n``Step`` 有五个子类，各自携带自己需要的字段，用 ``kind`` 做区分：\n\n- ``ClickStep`` —— 在指定坐标重复点击\n- ``DelayStep`` —— 纯等待\n- ``KeyStep``   —— 按键\n- ``MoveStep``  —— 沿折线轨迹移动光标\n- ``WaitStep``  —— 等屏幕上出现某张图片（找图），出现后可点它\n\n选择「子类」而不是「一个塞满字段的大 dataclass」，是为了让校验和 UI 都能按类型分派，\n新增步骤类型时只需加一个子类 + 注册到 ``step_from_dict``。\n"""\n\nfrom __future__ import annotations\n\nimport logging\nfrom dataclasses import dataclass, field\nfrom enum import Enum\nfrom typing import Any\n\nfrom ..input.base import MouseButton\nfrom .matching import Template\n\nlogger = logging.getLogger(__name__)\n\n# 循环次数填 0 表示无限\nINFINITE = 0\n\n# 找图步骤的默认参数\nDEFAULT_WAIT_TOLERANCE = 32\nDEFAULT_WAIT_TIMEOUT_MS = 30_000\nDEFAULT_WAIT_POLL_MS = 300\n# 轮询再密就有意义地吃 CPU 了：每轮都要抓一帧整屏\nMIN_WAIT_POLL_MS = 20\n\n# 超时后的两种处理\nON_TIMEOUT_CONTINUE = "continue"\nON_TIMEOUT_STOP = "stop"\n\n\nclass StepKind(str, Enum):\n    CLICK = "click"\n    DELAY = "delay"\n    KEY = "key"\n    MOVE = "move"\n    WAIT = "wait"\n\n    @property\n    def label(self) -> str:\n        return {\n            "click": "点击",\n            "delay": "延时",\n            "key": "按键",\n            "move": "移动",\n            "wait": "找图",\n        }[self.value]\n\n\n# ============================================================== 步骤\n@dataclass\nclass Step:\n    """步骤基类。子类用无注解的类属性声明 ``kind``，因此它不会成为 dataclass 字段。"""\n\n    enabled: bool = True\n    note: str = ""\n\n    def summary(self) -> str:\n        """表格里显示的参数摘要。"""\n        raise NotImplementedError\n\n    def validate(self) -> None:\n        """校验参数，非法时抛 ``ValueError``。"""\n        raise NotImplementedError\n\n    @property\n    def kind(self) -> StepKind:\n        raise NotImplementedError\n\n    def to_dict(self) -> dict[str, Any]:\n        data: dict[str, Any] = {\n            "kind": self.kind.value,\n            "enabled": self.enabled,\n            "note": self.note,\n        }\n        data.update(self._payload())\n        return data\n\n    def _payload(self) -> dict[str, Any]:\n        raise NotImplementedError\n\n\n@dataclass\nclass ClickStep(Step):\n    """在 ``(x, y)`` 处重复点击 ``repeat`` 次。"""\n\n    kind = StepKind.CLICK\n\n    x: int = 0\n    y: int = 0\n    button: MouseButton = MouseButton.LEFT\n    repeat: int = 1\n    interval_ms: int = 100\n    jitter_ms: int = 0\n    jitter_px: int = 0\n\n    def __post_init__(self) -> None:\n        # 统一成枚举类型。``QComboBox.currentData()`` 会把 str 子类还原成普通 str，\n        # 不归一化的话 ``summary()`` 会显示 "left" 而不是 "左键"。\n        self.button = MouseButton(self.button)\n\n    def summary(self) -> str:\n        text = f"({self.x}, {self.y})  {self.button}  ×{self.repeat}  {self.interval_ms}ms"\n        extras = []\n        if self.jitter_ms:\n            extras.append(f"间隔抖动 ±{self.jitter_ms}ms")\n        if self.jitter_px:\n            extras.append(f"坐标抖动 ±{self.jitter_px}px")\n        if extras:\n            text += "  [" + ", ".join(extras) + "]"\n        return text\n\n    def validate(self) -> None:\n        if self.interval_ms < 1:\n            raise ValueError("点击间隔必须大于 0 毫秒")\n        if self.repeat < 1:\n            raise ValueError("点击次数必须大于等于 1")\n        if self.jitter_ms < 0 or self.jitter_px < 0:\n            raise ValueError("抖动参数不能为负数")\n\n    def _payload(self) -> dict[str, Any]:\n        return {\n            "x": self.x,\n            "y": self.y,\n            "button": MouseButton(self.button).value,\n            "repeat": self.repeat,\n            "interval_ms": self.interval_ms,\n            "jitter_ms": self.jitter_ms,\n            "jitter_px": self.jitter_px,\n        }\n\n\n@dataclass\nclass DelayStep(Step):\n    """等待 ``delay_ms`` 毫秒。"""\n\n    kind = StepKind.DELAY\n\n    delay_ms: int = 500\n    jitter_ms: int = 0\n\n    def summary(self) -> str:\n        text = f"{self.delay_ms} ms"\n        if self.jitter_ms:\n            text += f"  [抖动 +0~{self.jitter_ms}ms]"\n        return text\n\n    def validate(self) -> None:\n        if self.delay_ms < 0:\n            raise ValueError("延时不能为负数")\n        if self.jitter_ms < 0:\n            raise ValueError("抖动参数不能为负数")\n\n    def _payload(self) -> dict[str, Any]:\n        return {"delay_ms": self.delay_ms, "jitter_ms": self.jitter_ms}\n\n\n@dataclass\nclass KeyStep(Step):\n    """按下并抬起 ``vk`` 对应的键 ``repeat`` 次。"""\n\n    kind = StepKind.KEY\n\n    vk: int = 0\n    repeat: int = 1\n    interval_ms: int = 50\n\n    def summary(self) -> str:\n        from ..win.hotkey import name_of_vk\n\n        return f"{name_of_vk(self.vk)}  ×{self.repeat}  {self.interval_ms}ms"\n\n    def validate(self) -> None:\n        if self.vk <= 0:\n            raise ValueError("请选择一个按键")\n        if self.repeat < 1:\n            raise ValueError("按键次数必须大于等于 1")\n        if self.interval_ms < 1:\n            raise ValueError("按键间隔必须大于 0 毫秒")\n\n    def _payload(self) -> dict[str, Any]:\n        return {"vk": self.vk, "repeat": self.repeat, "interval_ms": self.interval_ms}\n\n\n@dataclass\nclass MoveStep(Step):\n    """沿一条折线轨迹把光标移到终点。\n\n    为什么要用「一条轨迹 = 一个步骤」而不是「一个点 = 一个步骤」：\n    录一段鼠标移动会产生几百个采样点，逐点成步会让步骤表爆炸。\n    折线 + 总时长既能还原路径，又只占一行。\n\n    只保留 ``points`` 时是「瞬移」；``points`` 有多个点时按总时长匀速插值。\n    """\n\n    kind = StepKind.MOVE\n\n    points: list[tuple[int, int]] = field(default_factory=list)\n    duration_ms: int = 300\n\n    def summary(self) -> str:\n        if not self.points:\n            return "（空轨迹）"\n        if len(self.points) == 1:\n            x, y = self.points[0]\n            return f"移动到 ({x}, {y})"\n        sx, sy = self.points[0]\n        ex, ey = self.points[-1]\n        return f"轨迹 {len(self.points)} 点  ({sx}, {sy}) → ({ex}, {ey})  {self.duration_ms}ms"\n\n    def validate(self) -> None:\n        if not self.points:\n            raise ValueError("移动轨迹不能为空")\n        if self.duration_ms < 0:\n            raise ValueError("移动时长不能为负数")\n\n    @property\n    def start_point(self) -> tuple[int, int] | None:\n        return self.points[0] if self.points else None\n\n    @property\n    def end_point(self) -> tuple[int, int] | None:\n        return self.points[-1] if self.points else None\n\n    def _payload(self) -> dict[str, Any]:\n        return {\n            "points": [[int(x), int(y)] for x, y in self.points],\n            "duration_ms": self.duration_ms,\n        }\n\n\n@dataclass\nclass WaitStep(Step):\n    """等屏幕上出现某张图片，出现后可以点它。\n\n    这是「条件步骤」的第一块拼图：录制只能记下「什么时候做了什么」，\n    记不下「等某个按钮出现再点」；而真实界面经常是先弹窗、再点确认。\n    找图补上的正是这一段。\n\n    模板是**像素级**的：目标程序换主题、换语言、改 DPI 缩放后就得重新截。\n    换来的好处是完全不依赖目标程序的内部结构（自绘界面、网页、游戏都能用）。\n    """\n\n    kind = StepKind.WAIT\n\n    template: str = ""\n    """``matching.Template.encode()`` 的结果：base64(zlib(BGRA))。空 = 还没截。"""\n\n    tolerance: int = DEFAULT_WAIT_TOLERANCE\n    """单通道允许的最大色差（0-255）。越大越宽容，也越容易误命中。"""\n\n    timeout_ms: int = DEFAULT_WAIT_TIMEOUT_MS\n    poll_interval_ms: int = DEFAULT_WAIT_POLL_MS\n    click: bool = True\n    """找到之后是否顺手点一下（绝大多数场景就是「点确认」）。"""\n\n    button: MouseButton = MouseButton.LEFT\n    offset_x: int = 0\n    """点击位置相对**模板中心**的偏移，用来微调到底点哪里。"""\n\n    offset_y: int = 0\n    on_timeout: str = ON_TIMEOUT_CONTINUE\n    """超时后继续下一步（``ON_TIMEOUT_CONTINUE``）还是中止整个任务（``ON_TIMEOUT_STOP``）。"""\n\n    def __post_init__(self) -> None:\n        self.button = MouseButton(self.button)\n\n    def decoded(self) -> Template:\n        """还原模板。数据坏了会抛 ``ValueError``。"""\n        return Template.decode(self.template)\n\n    def summary(self) -> str:\n        try:\n            size = Template.decode(self.template).summary\n        except ValueError:\n            return "（未截取模板）"\n\n        action = f"{self.button} 点击" if self.click else "仅继续"\n        text = f"{size}  ±{self.tolerance}  ≤{_format_ms(self.timeout_ms)}  → {action}"\n        if self.on_timeout == ON_TIMEOUT_STOP:\n            text += "  超时中止"\n        return text\n\n    def validate(self) -> None:\n        if not self.template:\n            raise ValueError("请先截取要查找的图片模板")\n        try:\n            self.decoded()\n        except ValueError as exc:\n            raise ValueError(f"图片模板不可用：{exc}") from exc\n        if not 0 <= self.tolerance <= 255:\n            raise ValueError("容差必须在 0-255 之间")\n        if self.timeout_ms < 0:\n            raise ValueError("超时时间不能为负数")\n        if self.poll_interval_ms < MIN_WAIT_POLL_MS:\n            raise ValueError(\n                f"轮询间隔不能小于 {MIN_WAIT_POLL_MS} 毫秒（每轮都要抓一次整屏）"\n            )\n        if self.on_timeout not in (ON_TIMEOUT_CONTINUE, ON_TIMEOUT_STOP):\n            raise ValueError(f"未知的超时处理方式: {self.on_timeout!r}")\n        if self.click and not isinstance(self.button, MouseButton):\n            raise ValueError(f"未知的鼠标按键: {self.button!r}")\n\n    def _payload(self) -> dict[str, Any]:\n        return {\n            "template": self.template,\n            "tolerance": self.tolerance,\n            "timeout_ms": self.timeout_ms,\n            "poll_interval_ms": self.poll_interval_ms,\n            "click": self.click,\n            "button": MouseButton(self.button).value,\n            "offset_x": self.offset_x,\n            "offset_y": self.offset_y,\n            "on_timeout": self.on_timeout,\n        }\n\n\ndef _format_ms(value: int) -> str:\n    if value == 0:\n        return "不等待"\n    if value % 1000 == 0:\n        return f"{value // 1000}s"\n    return f"{value}ms"\n\n\ndef step_from_dict(data: dict[str, Any]) -> Step:\n    """从字典还原步骤。未知字段会被忽略，缺失字段用默认值补齐。"""\n    if not isinstance(data, dict):\n        raise TypeError(f"步骤必须是对象，实际是 {type(data).__name__}")\n\n    kind = StepKind(data.get("kind", StepKind.CLICK.value))\n    enabled = bool(data.get("enabled", True))\n    note = str(data.get("note", ""))\n\n    if kind is StepKind.CLICK:\n        return ClickStep(\n            enabled=enabled,\n            note=note,\n            x=int(data.get("x", 0)),\n            y=int(data.get("y", 0)),\n            button=MouseButton(data.get("button", MouseButton.LEFT.value)),\n            repeat=int(data.get("repeat", 1)),\n            interval_ms=int(data.get("interval_ms", 100)),\n            jitter_ms=int(data.get("jitter_ms", 0)),\n            jitter_px=int(data.get("jitter_px", 0)),\n        )\n    if kind is StepKind.DELAY:\n        return DelayStep(\n            enabled=enabled,\n            note=note,\n            delay_ms=int(data.get("delay_ms", 500)),\n            jitter_ms=int(data.get("jitter_ms", 0)),\n        )\n    if kind is StepKind.KEY:\n        return KeyStep(\n            enabled=enabled,\n            note=note,\n            vk=int(data.get("vk", 0)),\n            repeat=int(data.get("repeat", 1)),\n            interval_ms=int(data.get("interval_ms", 50)),\n        )\n    if kind is StepKind.MOVE:\n        return MoveStep(\n            enabled=enabled,\n            note=note,\n            points=_parse_points(data.get("points")),\n            duration_ms=int(data.get("duration_ms", 300)),\n        )\n    if kind is StepKind.WAIT:\n        return WaitStep(\n            enabled=enabled,\n            note=note,\n            template=str(data.get("template", "")),\n            tolerance=int(data.get("tolerance", DEFAULT_WAIT_TOLERANCE)),\n            timeout_ms=int(data.get("timeout_ms", DEFAULT_WAIT_TIMEOUT_MS)),\n            poll_interval_ms=int(data.get("poll_interval_ms", DEFAULT_WAIT_POLL_MS)),\n            click=bool(data.get("click", True)),\n            button=MouseButton(data.get("button", MouseButton.LEFT.value)),\n            offset_x=int(data.get("offset_x", 0)),\n            offset_y=int(data.get("offset_y", 0)),\n            on_timeout=str(data.get("on_timeout", ON_TIMEOUT_CONTINUE)),\n        )\n    raise ValueError(f"未知的步骤类型: {kind!r}")  # pragma: no cover\n\n\ndef _parse_points(raw: Any) -> list[tuple[int, int]]:\n    """解析轨迹点。单个点损坏只跳过它，其余照常还原。"""\n    points: list[tuple[int, int]] = []\n    if not isinstance(raw, (list, tuple)):\n        return points\n    for item in raw:\n        try:\n            px, py = item\n            points.append((int(px), int(py)))\n        except (TypeError, ValueError):\n            logger.warning("跳过无法解析的轨迹点 %r", item)\n    return points\n\n\n# ============================================================== 方案\n@dataclass\nclass Profile:\n    """一套完整的自动化方案。"""\n\n    name: str = "默认方案"\n    steps: list[Step] = field(default_factory=list)\n    repeat: int = INFINITE\n    """整个序列重复多少轮，``0`` 表示无限。"""\n\n    repeat_delay_ms: int = 0\n    """每轮之间的额外等待。"""\n\n    start_delay_ms: int = 300\n    """按下开始后的延迟，给用户留出切换窗口的时间。"""\n\n    # ---------------------------------------------------------------- 便利方法\n    @property\n    def infinite(self) -> bool:\n        return self.repeat == INFINITE\n\n    def active_steps(self) -> list[Step]:\n        """只返回被启用的步骤。"""\n        return [step for step in self.steps if step.enabled]\n\n    def validate(self, require_steps: bool = True) -> None:\n        if self.repeat < 0:\n            raise ValueError("重复轮数不能为负数")\n        if self.repeat_delay_ms < 0 or self.start_delay_ms < 0:\n            raise ValueError("延时参数不能为负数")\n        if require_steps and not self.active_steps():\n            raise ValueError("方案里没有任何启用的步骤")\n        for index, step in enumerate(self.steps, start=1):\n            try:\n                step.validate()\n            except ValueError as exc:\n                raise ValueError(f"第 {index} 步（{step.kind.label}）: {exc}") from exc\n\n    # ---------------------------------------------------------------- 序列化\n    def to_dict(self) -> dict[str, Any]:\n        return {\n            "version": 1,\n            "name": self.name,\n            "repeat": self.repeat,\n            "repeat_delay_ms": self.repeat_delay_ms,\n            "start_delay_ms": self.start_delay_ms,\n            "steps": [step.to_dict() for step in self.steps],\n        }\n\n    @classmethod\n    def from_dict(cls, data: dict[str, Any]) -> "Profile":\n        steps: list[Step] = []\n        for raw in data.get("steps", []):\n            try:\n                steps.append(step_from_dict(raw))\n            except Exception as exc:  # noqa: BLE001 - 单个坏步骤不该拖垮整个方案\n                logger.warning("跳过无法解析的步骤 %r: %s", raw, exc)\n\n        return cls(\n            name=str(data.get("name", "未命名方案")),\n            steps=steps,\n            repeat=int(data.get("repeat", INFINITE)),\n            repeat_delay_ms=int(data.get("repeat_delay_ms", 0)),\n            start_delay_ms=int(data.get("start_delay_ms", 300)),\n        )\n\n    @classmethod\n    def default(cls) -> "Profile":\n        """新用户的初始方案：在主显示器中央点 10 次。\n\n        用主显示器而不是虚拟桌面中心，是因为多屏之间可能有「空隙」，\n        居中到空隙上会点不到任何窗口。Windows 上主显示器左上角恒为 (0, 0)。\n        """\n        import ctypes\n\n        user32 = ctypes.windll.user32\n        width = user32.GetSystemMetrics(0)  # SM_CXSCREEN\n        height = user32.GetSystemMetrics(1)  # SM_CYSCREEN\n\n        return cls(\n            name="默认方案",\n            steps=[\n                ClickStep(\n                    x=width // 2,\n                    y=height // 2,\n                    repeat=10,\n                    interval_ms=200,\n                )\n            ],\n            repeat=INFINITE,\n        )\n',
    'app/core/recording.py': '"""把录制的原始输入事件转换成方案步骤。\n\n分三个阶段，每一步都保持可读、可单独测试：\n\n1. **事件 → 动作**：把按键/抬起的成对事件收敛成一个动作，把一串鼠标移动采样\n   细化成一条折线轨迹。\n2. **合并相邻动作**：连续多次「同一按键、同一位置」的点击合成一个 ``repeat``，\n   这是「双击」「连点 5 下」这类操作的天然表达，也能显著压缩步骤数量。\n3. **动作 → 步骤**：按相邻动作之间的真实间隔插入 ``DelayStep``。\n\n刻意不做的事\n------------\n- **不插值移动轨迹**（回放时才插值），录制阶段只保留拐点，避免步骤表爆炸；\n- **不做「智能等待」**（找图/找色），那是独立能力，见 README 的后续计划。\n"""\n\nfrom __future__ import annotations\n\nimport logging\nimport math\nfrom dataclasses import dataclass, field\n\nfrom ..input.base import MouseButton\nfrom ..win.hooks import InputEvent\nfrom .models import ClickStep, DelayStep, KeyStep, MoveStep, Profile, Step\n\nlogger = logging.getLogger(__name__)\n\n# 录制出来的方案默认留 500ms 启动延迟：录制时窗口往往是全屏的，\n# 回放前用户需要时间把目标窗口切到前台。\nRECORDING_START_DELAY_MS = 500\n\n# 录制结果并入当前方案的三种选择。放在这里是为了让两个 UI 控制器共用同一套取值，\n# 而不是各自散落字符串字面量。\nAPPLY_REPLACE = "replace"\nAPPLY_APPEND = "append"\nAPPLY_DISCARD = "discard"\n\n\n@dataclass\nclass RecordSettings:\n    """录制转步骤的可调参数。默认值偏「干净」，宁可少几个点也不要噪音。"""\n\n    record_moves: bool = True\n    """是否记录鼠标移动轨迹。关掉后只录点击和按键。"""\n\n    move_min_distance_px: int = 12\n    """轨迹抽稀：与上一个保留点的距离达到该值就保留一个点。"""\n\n    move_min_interval_ms: int = 80\n    """轨迹抽稀：与上一个保留点的时间差达到该值也保留一个点。"""\n\n    move_min_total_px: int = 5\n    """整段位移小于该值就整段丢弃（手抖）。"""\n\n    min_delay_ms: int = 40\n    """相邻动作间隔小于该值就不单独生成延时步骤。"""\n\n    merge_click_radius_px: int = 4\n    """两次点击的位置差异在该半径内才视为同一个点。"""\n\n    merge_max_gap_ms: int = 400\n    """两次点击/按键间隔超过该值就不再合并。"""\n\n    default_click_interval_ms: int = 100\n    default_key_interval_ms: int = 60\n\n\n@dataclass\nclass _Action:\n    """录制事件收敛后的一个动作。``count`` 是合并后的重复次数。"""\n\n    kind: str  # "click" | "key" | "move"\n    start: float\n    end: float\n    count: int = 1\n    x: int = 0\n    y: int = 0\n    button: str = ""\n    vk: int = 0\n    points: list[tuple[int, int]] = field(default_factory=list)\n    interval_ms: int = 0\n\n\n# ==================================================================== 对外接口\ndef build_profile(\n    events: list[InputEvent],\n    name: str = "录制方案",\n    settings: RecordSettings | None = None,\n) -> Profile:\n    """把录制的原始事件转换成可直接回放的方案。"""\n    settings = settings or RecordSettings()\n\n    actions = _merge_actions(_to_actions(events, settings), settings)\n    steps = _to_steps(actions, settings)\n\n    logger.info(\n        "录制转换完成: %s 条原始事件 → %s 个动作 → %s 个步骤",\n        len(events),\n        len(actions),\n        len(steps),\n    )\n    return Profile(\n        name=name,\n        steps=steps,\n        repeat=1,\n        repeat_delay_ms=0,\n        start_delay_ms=RECORDING_START_DELAY_MS,\n    )\n\n\ndef summarize(profile: Profile) -> str:\n    """给用户看的一句话摘要。"""\n    counts: dict[str, int] = {}\n    for step in profile.steps:\n        counts[step.kind.label] = counts.get(step.kind.label, 0) + 1\n    if not counts:\n        return "没有记录到任何动作"\n    detail = "、".join(f"{label} {count} 个" for label, count in counts.items())\n    return f"共 {len(profile.steps)} 个步骤（{detail}）"\n\n\n# ==================================================================== 阶段 1\ndef _to_actions(events: list[InputEvent], settings: RecordSettings) -> list[_Action]:\n    actions: list[_Action] = []\n    pending_moves: list[tuple[float, int, int]] = []\n    pending_click: InputEvent | None = None\n    held_keys: dict[int, float] = {}\n\n    def flush_moves() -> None:\n        if not pending_moves:\n            return\n        samples = pending_moves.copy()\n        pending_moves.clear()\n\n        kept = _thin(samples, settings)\n        if len(kept) < 2:\n            return\n        origin_x, origin_y = kept[0][1], kept[0][2]\n        if max(math.hypot(s[1] - origin_x, s[2] - origin_y) for s in kept) < settings.move_min_total_px:\n            return\n\n        actions.append(\n            _Action(\n                "move",\n                kept[0][0],\n                kept[-1][0],\n                points=[(s[1], s[2]) for s in kept],\n            )\n        )\n\n    for event in events:\n        if event.kind == "move":\n            if settings.record_moves:\n                pending_moves.append((event.time, event.x, event.y))\n            continue\n\n        if event.kind == "click":\n            if event.is_down:\n                pending_click = event\n                continue\n            flush_moves()\n            if pending_click is not None:\n                actions.append(\n                    _Action(\n                        "click",\n                        pending_click.time,\n                        event.time,\n                        x=pending_click.x,\n                        y=pending_click.y,\n                        button=pending_click.button,\n                    )\n                )\n                pending_click = None\n            continue\n\n        if event.kind == "key":\n            if event.is_down:\n                flush_moves()\n                held_keys.setdefault(event.vk, event.time)\n            else:\n                down_time = held_keys.pop(event.vk, None)\n                if down_time is not None:\n                    actions.append(_Action("key", down_time, event.time, vk=event.vk))\n            continue\n\n    flush_moves()\n\n    # 录制结束时还按着的键补一个「瞬时」动作，否则会整段丢掉\n    for vk, down_time in held_keys.items():\n        actions.append(_Action("key", down_time, down_time, vk=vk))\n\n    return actions\n\n\ndef _thin(samples: list[tuple[float, int, int]], settings: RecordSettings) -> list[tuple[float, int, int]]:\n    """按「距离或时间」二选一达到阈值就保留一个采样点，末尾点一定保留。"""\n    kept = [samples[0]]\n    for sample in samples[1:]:\n        last = kept[-1]\n        moved = math.hypot(sample[1] - last[1], sample[2] - last[2])\n        elapsed_ms = (sample[0] - last[0]) * 1000.0\n        if moved >= settings.move_min_distance_px or elapsed_ms >= settings.move_min_interval_ms:\n            kept.append(sample)\n\n    if kept[-1] is not samples[-1]:\n        kept.append(samples[-1])\n    return kept\n\n\n# ==================================================================== 阶段 2\ndef _merge_actions(actions: list[_Action], settings: RecordSettings) -> list[_Action]:\n    merged: list[_Action] = []\n    for action in actions:\n        previous = merged[-1] if merged else None\n        if previous is not None and _can_merge(previous, action, settings):\n            count = previous.count + action.count\n            span_ms = (action.start - previous.start) * 1000.0\n            # start 始终是第一次的起始时间，因此 span/(count-1) 就是平均间隔\n            previous.interval_ms = max(1, round(span_ms / max(1, count - 1)))\n            previous.count = count\n            previous.end = action.end\n        else:\n            merged.append(action)\n    return merged\n\n\ndef _can_merge(previous: _Action, action: _Action, settings: RecordSettings) -> bool:\n    if previous.kind != action.kind:\n        return False\n\n    if (action.start - previous.end) * 1000.0 > settings.merge_max_gap_ms:\n        return False\n\n    if action.kind == "click":\n        return previous.button == action.button and (\n            abs(previous.x - action.x) <= settings.merge_click_radius_px\n            and abs(previous.y - action.y) <= settings.merge_click_radius_px\n        )\n    if action.kind == "key":\n        return previous.vk == action.vk\n    return False  # 轨迹不合并\n\n\n# ==================================================================== 阶段 3\ndef _to_steps(actions: list[_Action], settings: RecordSettings) -> list[Step]:\n    steps: list[Step] = []\n    previous_end: float | None = None\n\n    for action in actions:\n        if previous_end is not None:\n            gap_ms = (action.start - previous_end) * 1000.0\n            if gap_ms >= settings.min_delay_ms:\n                steps.append(DelayStep(delay_ms=max(1, round(gap_ms))))\n        steps.append(_action_to_step(action, settings))\n        previous_end = action.end\n\n    return steps\n\n\ndef _action_to_step(action: _Action, settings: RecordSettings) -> Step:\n    if action.kind == "click":\n        return ClickStep(\n            x=action.x,\n            y=action.y,\n            button=MouseButton(action.button),\n            repeat=action.count,\n            interval_ms=action.interval_ms or settings.default_click_interval_ms,\n        )\n    if action.kind == "key":\n        return KeyStep(\n            vk=action.vk,\n            repeat=action.count,\n            interval_ms=action.interval_ms or settings.default_key_interval_ms,\n        )\n    return MoveStep(\n        points=list(action.points),\n        duration_ms=max(0, round((action.end - action.start) * 1000.0)),\n    )\n',
    'app/input/__init__.py': '"""输入注入后端。默认使用 SendInput（前台注入）。"""\n',
    'app/input/base.py': '"""输入后端的抽象接口。\n\n引擎只依赖这里的接口，因此前台注入（``SendInput``）与后台注入（``PostMessage``）\n可以互换而无需改动引擎：换后端只是换一个 ``InputBackend`` 实现。\n\n坐标约定：所有坐标都是**虚拟屏幕物理像素**。前台后端直接用它驱动光标；\n后台后端需要先把它换算成目标窗口的客户区坐标（见 ``app.win.window``）。\n"""\n\nfrom __future__ import annotations\n\nfrom abc import ABC, abstractmethod\nfrom enum import Enum\n\n\nclass MouseButton(str, Enum):\n    LEFT = "left"\n    RIGHT = "right"\n    MIDDLE = "middle"\n\n    def __str__(self) -> str:  # pragma: no cover - 仅用于展示\n        return {"left": "左键", "right": "右键", "middle": "中键"}[self.value]\n\n\nclass InputBackend(ABC):\n    """输入注入后端。所有坐标均为虚拟屏幕物理像素。"""\n\n    name: str = "base"\n\n    @abstractmethod\n    def click(self, x: int, y: int, button: MouseButton = MouseButton.LEFT) -> None:\n        """把光标移动到 (x, y) 并在该位置完成一次按下 + 抬起。"""\n\n    @abstractmethod\n    def move_to(self, x: int, y: int) -> None:\n        """仅移动光标，不产生按键。"""\n\n    @abstractmethod\n    def press_key(self, vk: int) -> None:\n        """按下并抬起一个虚拟键码对应的键。"""\n\n    def close(self) -> None:\n        """释放后端占用的资源（默认无操作）。"""\n',
    'app/input/sendinput.py': '"""基于 Win32 ``SendInput`` 的前台输入注入后端。\n\n为什么选 SendInput：\n- 属于系统级输入注入，走的是和真实鼠标键盘相同的输入队列，兼容性最好；\n- 只需要标准库 ``ctypes``，零第三方依赖；\n- 可以一次调用原子地发送「移动 + 按下 + 抬起」，减少被目标程序拆分的可能。\n\n局限（已在 README 说明）：\n- 需要目标位置真的在屏幕上、且没有被其他窗口遮挡；\n- 对 DirectX/游戏、部分 UWP、做消息校验的程序可能无效；\n- 目标程序若以管理员运行，本进程也必须提权，否则注入会被 UIPI 丢弃。\n\n坐标使用 ``MOUSEEVENTF_ABSOLUTE | MOUSEEVENTF_VIRTUALDESK``，\n把虚拟屏幕物理像素归一化到 0..65535，可正确处理多显示器与负坐标。\n"""\n\nfrom __future__ import annotations\n\nimport ctypes\nimport ctypes.wintypes as wintypes\nimport logging\n\nfrom ..win.geometry import virtual_screen_rect\nfrom .base import InputBackend, MouseButton\n\nlogger = logging.getLogger(__name__)\n\nULONG_PTR = ctypes.c_ulonglong if ctypes.sizeof(ctypes.c_void_p) == 8 else ctypes.c_ulong\n\nINPUT_MOUSE = 0\nINPUT_KEYBOARD = 1\n\nMOUSEEVENTF_MOVE = 0x0001\nMOUSEEVENTF_LEFTDOWN = 0x0002\nMOUSEEVENTF_LEFTUP = 0x0004\nMOUSEEVENTF_RIGHTDOWN = 0x0008\nMOUSEEVENTF_RIGHTUP = 0x0010\nMOUSEEVENTF_MIDDLEDOWN = 0x0020\nMOUSEEVENTF_MIDDLEUP = 0x0040\nMOUSEEVENTF_ABSOLUTE = 0x8000\nMOUSEEVENTF_VIRTUALDESK = 0x4000\n\nKEYEVENTF_KEYUP = 0x0002\n\n\nclass MOUSEINPUT(ctypes.Structure):\n    _fields_ = [\n        ("dx", wintypes.LONG),\n        ("dy", wintypes.LONG),\n        ("mouseData", wintypes.DWORD),\n        ("dwFlags", wintypes.DWORD),\n        ("time", wintypes.DWORD),\n        ("dwExtraInfo", ULONG_PTR),\n    ]\n\n\nclass KEYBDINPUT(ctypes.Structure):\n    _fields_ = [\n        ("wVk", wintypes.WORD),\n        ("wScan", wintypes.WORD),\n        ("dwFlags", wintypes.DWORD),\n        ("time", wintypes.DWORD),\n        ("dwExtraInfo", ULONG_PTR),\n    ]\n\n\nclass HARDWAREINPUT(ctypes.Structure):\n    _fields_ = [\n        ("uMsg", wintypes.DWORD),\n        ("wParamL", wintypes.WORD),\n        ("wParamH", wintypes.WORD),\n    ]\n\n\nclass _INPUTUNION(ctypes.Union):\n    _fields_ = [\n        ("mi", MOUSEINPUT),\n        ("ki", KEYBDINPUT),\n        ("hi", HARDWAREINPUT),\n    ]\n\n\nclass INPUT(ctypes.Structure):\n    _anonymous_ = ("u",)\n    _fields_ = [\n        ("type", wintypes.DWORD),\n        ("u", _INPUTUNION),\n    ]\n\n\n_user32 = ctypes.WinDLL("user32", use_last_error=True)\n_user32.SendInput.argtypes = (wintypes.UINT, ctypes.POINTER(INPUT), ctypes.c_int)\n_user32.SendInput.restype = wintypes.UINT\n\n\ndef _normalize(x: int, y: int) -> tuple[int, int]:\n    """把虚拟屏幕物理像素坐标归一化到 SendInput 要求的 0..65535 区间。"""\n    rect = virtual_screen_rect()\n    if rect.width <= 1 or rect.height <= 1:  # pragma: no cover - 异常显示配置\n        raise RuntimeError(f"虚拟屏幕尺寸非法: {rect}")\n\n    nx = round((x - rect.x) * 65535 / (rect.width - 1))\n    ny = round((y - rect.y) * 65535 / (rect.height - 1))\n    return max(0, min(65535, nx)), max(0, min(65535, ny))\n\n\ndef _mouse_input(flags: int, dx: int = 0, dy: int = 0) -> INPUT:\n    item = INPUT()\n    item.type = INPUT_MOUSE\n    item.mi.dx = dx\n    item.mi.dy = dy\n    item.mi.dwFlags = flags\n    return item\n\n\ndef _key_input(vk: int, flags: int = 0) -> INPUT:\n    item = INPUT()\n    item.type = INPUT_KEYBOARD\n    item.ki.wVk = vk\n    item.ki.dwFlags = flags\n    return item\n\n\ndef _send(*inputs: INPUT) -> bool:\n    """批量发送输入事件，返回是否全部被系统接受。"""\n    count = len(inputs)\n    array = (INPUT * count)(*inputs)\n    sent = _user32.SendInput(count, array, ctypes.sizeof(INPUT))\n    if sent != count:\n        logger.warning(\n            "SendInput 部分失败: 期望 %s 条, 实际 %s 条, GetLastError=%s",\n            count,\n            sent,\n            ctypes.get_last_error(),\n        )\n        return False\n    return True\n\n\nclass SendInputBackend(InputBackend):\n    """前台注入后端：点击会作用于光标所在位置的窗口，与窗口焦点无关。"""\n\n    name = "sendinput"\n\n    _BUTTON_FLAGS: dict[MouseButton, tuple[int, int]] = {\n        MouseButton.LEFT: (MOUSEEVENTF_LEFTDOWN, MOUSEEVENTF_LEFTUP),\n        MouseButton.RIGHT: (MOUSEEVENTF_RIGHTDOWN, MOUSEEVENTF_RIGHTUP),\n        MouseButton.MIDDLE: (MOUSEEVENTF_MIDDLEDOWN, MOUSEEVENTF_MIDDLEUP),\n    }\n\n    def _move(self, x: int, y: int) -> INPUT:\n        nx, ny = _normalize(x, y)\n        return _mouse_input(\n            MOUSEEVENTF_MOVE | MOUSEEVENTF_ABSOLUTE | MOUSEEVENTF_VIRTUALDESK, nx, ny\n        )\n\n    def click(self, x: int, y: int, button: MouseButton = MouseButton.LEFT) -> None:\n        down_flag, up_flag = self._BUTTON_FLAGS[MouseButton(button)]\n        _send(\n            self._move(x, y),\n            _mouse_input(down_flag),\n            _mouse_input(up_flag),\n        )\n\n    def move_to(self, x: int, y: int) -> None:\n        _send(self._move(x, y))\n\n    def press_key(self, vk: int) -> None:\n        _send(_key_input(vk), _key_input(vk, KEYEVENTF_KEYUP))\n',
    'app/input/postmessage.py': '"""基于 Win32 ``PostMessage`` 的**后台**输入后端。\n\n它和 :class:`~app.input.sendinput.SendInputBackend` 的根本区别\n------------------------------------------------------------\n``SendInput`` 是**前台**注入：它是往系统输入队列里塞真实事件，驱动的是唯一那一个\n系统光标，所以必须把目标窗口切到前台，运行期间也不能动鼠标。\n\n本后端改成**往目标窗口的消息队列投递** ``WM_MOUSEMOVE`` / ``WM_LBUTTONDOWN`` 之类的\n消息，于是：\n\n- **不移动系统光标**，宏跑着的时候你照样能用鼠标；\n- **不要求目标窗口在前台**，部分被遮挡也能点（前提是拿得到它的 HWND）。\n\n代价（``PostMessage`` 机制本身的固有局限，不是 bug）\n----------------------------------------------------\n- 只对**自己处理鼠标消息**的经典 Win32 窗口有效。Chromium/Electron、DirectX 游戏、\n  不少 UWP 会直接忽略投递进来的消息（它们的输入走别的通道），表现为「没反应」。\n- 需要**绑定目标窗口**才能把屏幕坐标换算成客户区坐标；没绑定时退化为「按屏幕坐标\n  找当时最顶层的窗口」，被遮住就找不准。\n- 不会产生 ``WM_ACTIVATE`` / 焦点变化，个别控件要先获得焦点才响应。\n- 受 Windows 的 UIPI 限制：低权限进程发往高权限进程（本工具没提权、目标是管理员程序）\n  的消息会被拦掉，表现为投递失败或没反应。\n- 键盘消息只能投给绑定窗口（或退而求其次给前台窗口）；后台键盘比后台鼠标更不可靠，\n  很多程序直接忽略。\n\n消息细节\n--------\n- 点击前先补一条 ``WM_MOUSEMOVE``，因为不少控件靠它更新悬停/热点状态；\n- 命中的目标不是顶尖层窗口，而是**该点下最内层的子窗口**——真实鼠标消息正是由命中\n  测试路由到那一层的，只丢给顶层窗口很多程序不会自己再往下转发；\n- ``lParam`` 是**客户区坐标**打包成的 ``MAKELPARAM``；按键消息的 ``lParam`` 带上扫描码\n  与抬起标志位。\n"""\n\nfrom __future__ import annotations\n\nimport logging\n\nfrom ..win.window import (\n    deepest_child_at,\n    describe,\n    foreground_window,\n    is_window,\n    map_virtual_key,\n    post_message,\n    root_window,\n    screen_to_client,\n    window_from_point,\n)\nfrom .base import InputBackend, MouseButton\n\nlogger = logging.getLogger(__name__)\n\n# 鼠标消息\nWM_MOUSEMOVE = 0x0200\nWM_LBUTTONDOWN = 0x0201\nWM_LBUTTONUP = 0x0202\nWM_RBUTTONDOWN = 0x0204\nWM_RBUTTONUP = 0x0205\nWM_MBUTTONDOWN = 0x0207\nWM_MBUTTONUP = 0x0208\n\n# 键盘消息\nWM_KEYDOWN = 0x0100\nWM_KEYUP = 0x0101\n\n# wParam 里的按键状态位\nMK_LBUTTON = 0x0001\nMK_RBUTTON = 0x0002\nMK_MBUTTON = 0x0010\n\n# 按键 → (按下消息, 抬起消息, 按下时的 wParam 状态位)\n_BUTTON_MESSAGES: dict[MouseButton, tuple[int, int, int]] = {\n    MouseButton.LEFT: (WM_LBUTTONDOWN, WM_LBUTTONUP, MK_LBUTTON),\n    MouseButton.RIGHT: (WM_RBUTTONDOWN, WM_RBUTTONUP, MK_RBUTTON),\n    MouseButton.MIDDLE: (WM_MBUTTONDOWN, WM_MBUTTONUP, MK_MBUTTON),\n}\n\n\ndef _make_lparam(x: int, y: int) -> int:\n    """客户区坐标打包进 ``lParam``（低 16 位 x、高 16 位 y）。"""\n    return ((int(y) & 0xFFFF) << 16) | (int(x) & 0xFFFF)\n\n\ndef _key_lparam(scancode: int, up: bool) -> int:\n    """键盘消息的 ``lParam``：重复次数 1 + 扫描码，抬起再置 bit30/31。"""\n    value = 1 | ((int(scancode) & 0xFF) << 16)\n    if up:\n        value |= (1 << 30) | (1 << 31)\n    return value\n\n\nclass PostMessageBackend(InputBackend):\n    """后台注入后端：向绑定窗口投递消息，不占用系统光标。"""\n\n    name = "postmessage"\n\n    def __init__(self) -> None:\n        self._hwnd: int | None = None\n        self._title: str = ""\n        self._warned_no_target = False\n\n    # ---------------------------------------------------------------- 绑定\n    @property\n    def bound_window(self) -> int | None:\n        return self._hwnd\n\n    @property\n    def bound_title(self) -> str:\n        """绑定窗口的「标题 [类名]」，未绑定时为空串。"""\n        return self._title\n\n    def bind_window(self, hwnd: int | None) -> bool:\n        """绑定目标窗口（会归一化到顶层窗口）。\n\n        返回是否绑定成功。句柄失效时返回 ``False`` 且不改动原有绑定。\n        """\n        if not hwnd or not is_window(hwnd):\n            return False\n        root = root_window(int(hwnd)) or int(hwnd)\n        self._hwnd = root\n        self._title = describe(root)\n        self._warned_no_target = False\n        logger.info("后台点击已绑定窗口: %s (hwnd=0x%X)", self._title, root)\n        return True\n\n    def bind_point(self, x: int, y: int) -> bool:\n        """绑定屏幕坐标 ``(x, y)`` 处的顶层窗口。找不到窗口时返回 ``False``。"""\n        hwnd = window_from_point(x, y)\n        if not hwnd:\n            return False\n        return self.bind_window(hwnd)\n\n    def unbind(self) -> None:\n        self._hwnd = None\n        self._title = ""\n        self._warned_no_target = False\n\n    def close(self) -> None:\n        self.unbind()\n\n    # ---------------------------------------------------------------- 目标解析\n    def _resolve(self, x: int, y: int) -> tuple[int, int, int] | None:\n        """把屏幕坐标解析成 ``(hwnd, client_x, client_y)``，解析不了返回 ``None``。"""\n        base = self._hwnd\n        if base is None or not is_window(base):\n            base = window_from_point(x, y)\n            if base is None:\n                return None\n\n        hwnd = deepest_child_at(base, x, y)\n        client = screen_to_client(hwnd, x, y)\n        if client is None:\n            return None\n        return hwnd, client[0], client[1]\n\n    def _warn_no_target(self) -> None:\n        # 一个宏里可能有成百次点击，同一个原因只提醒一次，别刷屏\n        if self._warned_no_target:\n            return\n        self._warned_no_target = True\n        logger.warning(\n            "后台点击找不到目标窗口：请先「绑定窗口」，或确认该坐标处存在可见窗口"\n        )\n\n    # ---------------------------------------------------------------- 注入\n    def click(self, x: int, y: int, button: MouseButton = MouseButton.LEFT) -> None:\n        target = self._resolve(x, y)\n        if target is None:\n            self._warn_no_target()\n            return\n\n        hwnd, cx, cy = target\n        down_message, up_message, pressed = _BUTTON_MESSAGES[MouseButton(button)]\n        lparam = _make_lparam(cx, cy)\n        # 先移动：不少控件靠 WM_MOUSEMOVE 更新悬停/热点状态，直接按下可能不认\n        post_message(hwnd, WM_MOUSEMOVE, 0, lparam)\n        post_message(hwnd, down_message, pressed, lparam)\n        post_message(hwnd, up_message, 0, lparam)\n\n    def move_to(self, x: int, y: int) -> None:\n        target = self._resolve(x, y)\n        if target is None:\n            return\n        hwnd, cx, cy = target\n        post_message(hwnd, WM_MOUSEMOVE, 0, _make_lparam(cx, cy))\n\n    def press_key(self, vk: int) -> None:\n        hwnd = self._hwnd if is_window(self._hwnd) else foreground_window()\n        if not hwnd:\n            self._warn_no_target()\n            return\n\n        scancode = map_virtual_key(vk)\n        post_message(hwnd, WM_KEYDOWN, vk, _key_lparam(scancode, up=False))\n        post_message(hwnd, WM_KEYUP, vk, _key_lparam(scancode, up=True))\n',
    'app/storage/__init__.py': '"""持久化层：方案的 JSON 读写与最近使用记录。"""\n',
    'app/storage/config.py': '"""方案与设置的持久化。\n\n磁盘布局（``base_dir`` 默认是 ``%LOCALAPPDATA%\\\\AutoClicker``）::\n\n    AutoClicker/\n    ├─ settings.json           # 应用设置（最近使用的方案等）\n    ├─ profiles/\n    │  ├─ 默认方案.json\n    │  └─ 日常签到.json\n    └─ logs/\n       └─ autoclicker.log\n\n写入一律走「临时文件 + ``os.replace``」的原子替换，避免中途崩溃留下半个文件。\n单个方案文件损坏时只跳过它，不会连带整个方案列表打不开。\n"""\n\nfrom __future__ import annotations\n\nimport json\nimport logging\nimport os\nimport re\nfrom pathlib import Path\n\nfrom ..core.models import Profile\nfrom ..utils.logger import app_data_dir\n\nlogger = logging.getLogger(__name__)\n\n_INVALID_CHARS = re.compile(r\'[\\\\/:*?"<>|]\')\nSETTINGS_VERSION = 1\n\n\ndef _safe_filename(name: str, fallback: str = "未命名方案") -> str:\n    """把方案名转成安全的文件名（不含扩展名）。"""\n    cleaned = _INVALID_CHARS.sub("_", name).strip().strip(".")\n    return cleaned or fallback\n\n\nclass ProfileStore:\n    """方案仓库。"""\n\n    def __init__(self, base_dir: Path | None = None) -> None:\n        self.base_dir = Path(base_dir) if base_dir else app_data_dir()\n        self.profiles_dir = self.base_dir / "profiles"\n        self.settings_path = self.base_dir / "settings.json"\n        self._settings: dict | None = None\n\n    # ------------------------------------------------------------------ 方案\n    def list_names(self) -> list[str]:\n        """列出全部方案名（按名称排序）。目录不存在时返回空列表。"""\n        if not self.profiles_dir.is_dir():\n            return []\n        return sorted(path.stem for path in self.profiles_dir.glob("*.json"))\n\n    def exists(self, name: str) -> bool:\n        return self._path_for(name).is_file()\n\n    def load(self, name: str) -> Profile:\n        """读取方案。文件不存在或损坏时抛 ``ValueError``。"""\n        path = self._path_for(name)\n        try:\n            raw = json.loads(path.read_text(encoding="utf-8"))\n        except FileNotFoundError as exc:\n            raise ValueError(f"方案文件不存在: {path.name}") from exc\n        except (OSError, json.JSONDecodeError) as exc:\n            raise ValueError(f"方案文件无法读取: {path.name}（{exc}）") from exc\n\n        if not isinstance(raw, dict):\n            raise ValueError(f"方案文件格式不正确: {path.name}")\n\n        profile = Profile.from_dict(raw)\n        # 以文件名为准，避免文件里 name 字段和文件名不一致造成错乱\n        profile.name = name\n        return profile\n\n    def save(self, profile: Profile) -> Path:\n        """保存方案（原子写入），返回落盘路径。"""\n        self.profiles_dir.mkdir(parents=True, exist_ok=True)\n        path = self._path_for(profile.name)\n        self._atomic_write_json(path, profile.to_dict())\n        logger.info("方案已保存: %s", path)\n        return path\n\n    def delete(self, name: str) -> bool:\n        """删除方案。文件不存在时返回 False。"""\n        path = self._path_for(name)\n        try:\n            path.unlink()\n        except FileNotFoundError:\n            return False\n        except OSError as exc:\n            logger.error("删除方案失败 %s: %s", path, exc)\n            return False\n        logger.info("方案已删除: %s", path)\n        return True\n\n    def rename(self, old_name: str, new_name: str) -> bool:\n        """重命名方案。"""\n        old_path = self._path_for(old_name)\n        new_path = self._path_for(new_name)\n        if not old_path.is_file() or new_path.exists():\n            return False\n        try:\n            old_path.replace(new_path)\n        except OSError as exc:\n            logger.error("重命名方案失败 %s -> %s: %s", old_path, new_path, exc)\n            return False\n        return True\n\n    # ------------------------------------------------------------------ 设置\n    @property\n    def settings(self) -> dict:\n        if self._settings is None:\n            self._settings = self._read_settings()\n        return self._settings\n\n    def get_last_profile(self) -> str | None:\n        value = self.settings.get("last_profile")\n        return str(value) if isinstance(value, str) and value else None\n\n    def set_last_profile(self, name: str) -> None:\n        self.settings["last_profile"] = name\n        self._write_settings()\n\n    # ------------------------------------------------------------------ 内部\n    def _path_for(self, name: str) -> Path:\n        return self.profiles_dir / f"{_safe_filename(name)}.json"\n\n    def _read_settings(self) -> dict:\n        try:\n            raw = json.loads(self.settings_path.read_text(encoding="utf-8"))\n        except FileNotFoundError:\n            return {"version": SETTINGS_VERSION}\n        except (OSError, json.JSONDecodeError) as exc:\n            logger.warning("settings.json 无法读取，使用默认设置: %s", exc)\n            return {"version": SETTINGS_VERSION}\n        return raw if isinstance(raw, dict) else {"version": SETTINGS_VERSION}\n\n    def _write_settings(self) -> None:\n        self.settings.setdefault("version", SETTINGS_VERSION)\n        try:\n            self.base_dir.mkdir(parents=True, exist_ok=True)\n            self._atomic_write_json(self.settings_path, self.settings)\n        except OSError as exc:  # pragma: no cover - 磁盘不可写时降级\n            logger.warning("settings.json 写入失败: %s", exc)\n\n    @staticmethod\n    def _atomic_write_json(path: Path, payload: dict) -> None:\n        tmp = path.with_suffix(path.suffix + ".tmp")\n        tmp.write_text(\n            json.dumps(payload, ensure_ascii=False, indent=2),\n            encoding="utf-8",\n        )\n        os.replace(tmp, path)\n',
    'app/ui/__init__.py': '"""UI 层：基于 PySide6。"""\n',
    'app/ui/icon.py': '"""应用图标。\n\n代码绘制、零资源文件，避免打包时漏带 .ico 或路径解析问题。\n"""\n\nfrom __future__ import annotations\n\nfrom PySide6.QtCore import QRectF, Qt\nfrom PySide6.QtGui import QColor, QIcon, QPainter, QPainterPath, QPixmap\n\n_cache: QIcon | None = None\n\n\ndef app_icon() -> QIcon:\n    """返回应用图标（首次调用时生成并缓存）。"""\n    global _cache\n    if _cache is not None:\n        return _cache\n\n    size = 64\n    pixmap = QPixmap(size, size)\n    pixmap.fill(Qt.GlobalColor.transparent)\n\n    painter = QPainter(pixmap)\n    painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)\n    painter.setPen(Qt.PenStyle.NoPen)\n\n    painter.setBrush(QColor("#2d7ff9"))\n    painter.drawRoundedRect(QRectF(3, 3, 58, 58), 14, 14)\n\n    # 白色鼠标指针\n    arrow = QPainterPath()\n    arrow.moveTo(23, 16)\n    arrow.lineTo(23, 47)\n    arrow.lineTo(30, 40)\n    arrow.lineTo(35, 50)\n    arrow.lineTo(40, 47)\n    arrow.lineTo(35, 37)\n    arrow.lineTo(44, 37)\n    arrow.closeSubpath()\n    painter.setBrush(QColor("#ffffff"))\n    painter.drawPath(arrow)\n\n    painter.end()\n    _cache = QIcon(pixmap)\n    return _cache\n',
    'app/ui/log_panel.py': '"""日志面板。\n\n标准 ``logging`` 的 handler 是**全局**的，必须和窗口同生共死：窗口销毁后 handler 还挂在\nroot logger 上，程序就会继续往一块已经释放的控件里写字。把「挂上」和「摘掉」收在同一个\n对象里配套使用，避免只做了一半。\n"""\n\nfrom __future__ import annotations\n\nimport logging\nfrom collections.abc import Callable\n\nfrom PySide6.QtGui import QFont\nfrom PySide6.QtWidgets import QPlainTextEdit, QWidget\n\nfrom ..utils.logger import SignalLogHandler\n\n# 长时间挂机时日志不能把内存吃满，超过上限从最早的开始丢\nMAX_BLOCKS = 2000\n\n\nclass LogPanel(QPlainTextEdit):\n    """只读日志视图。"""\n\n    def __init__(self, parent: QWidget | None = None) -> None:\n        super().__init__(parent)\n        self.setReadOnly(True)\n        self.setMaximumBlockCount(MAX_BLOCKS)\n        self.setFont(QFont("Consolas", 9))\n        self._handler: SignalLogHandler | None = None\n\n    def attach(self, sink: Callable[[str], None]) -> None:\n        """把 root logger 的输出接到 ``sink``（通常是 ``Signal(str).emit``）。"""\n        if self._handler is not None:\n            return\n        self._handler = SignalLogHandler(sink)\n        logging.getLogger().addHandler(self._handler)\n\n    def detach(self) -> None:\n        if self._handler is None:\n            return\n        logging.getLogger().removeHandler(self._handler)\n        self._handler = None\n',
    'app/ui/main_window.py': '"""主窗口：命令入口 + 布局。\n\n职责边界\n--------\n这个类只做三件事：\n\n1. **搭界面**：所有控件的创建与摆放都在这里，一处就能看全（``_build_*``）；\n2. **当命令入口**：按钮、菜单、托盘、全局热键最终都调同一批方法（``start_clicking`` /\n   ``pick_position`` / ``start_recording`` …），因此不会出现「按钮能做、热键不能做」；\n3. **做跨界策略**：例如「录制期间禁用开始」「运行中禁止拾取坐标」，\n   只有同时了解录制和回放的这里才判断得了。\n\n具体事宜全部交给下面这些对象，它们各自持有属于自己的界面控件：\n\n==========================  ==================================================\n``ProfileController``       当前是哪个方案、有无未保存改动、落盘/改名/删除\n``RunController``           工作线程里的 ``MacroEngine`` + 进度条\n``RecordingController``     输入钩子、录制指示条、事件转步骤\n``TrayIcon``                托盘图标与右键菜单\n``LogPanel``                接 ``logging`` 的只读日志视图\n==========================  ==================================================\n\n界面结构\n--------\n::\n\n    ┌ 方案 ── 下拉切换 + 新建/保存/另存为/重命名/删除 ─┐\n    │        启动延迟 · 序列轮数 · 轮次间隔            │\n    ├ 步骤序列（StepEditor）  ┬ 日志（可拖动分隔条）────┤\n    ├─ 开始 / 停止 · 状态 · 进度条 ────────────────────┤\n    ├─ 输入方式：前台 SendInput / 后台 PostMessage ────┤\n    └─ 状态栏：热键提示 ───────────────────────────────┘\n\n跨线程通信一律走信号：``MacroEngine`` 在工作线程里发信号，槽在主线程序列化执行。\n"""\n\nfrom __future__ import annotations\n\nimport logging\n\nfrom PySide6.QtCore import Qt, Signal, Slot\nfrom PySide6.QtGui import QAction, QCloseEvent\nfrom PySide6.QtWidgets import (\n    QApplication,\n    QCheckBox,\n    QComboBox,\n    QGroupBox,\n    QHBoxLayout,\n    QLabel,\n    QMainWindow,\n    QMessageBox,\n    QProgressBar,\n    QPushButton,\n    QSpinBox,\n    QSplitter,\n    QVBoxLayout,\n    QWidget,\n)\n\nfrom ..core.models import ClickStep, MoveStep\nfrom ..core.recording import RecordSettings\nfrom ..input.base import InputBackend\nfrom ..storage.config import ProfileStore\nfrom ..win.hotkey import HotkeyManager\nfrom .icon import app_icon\nfrom .log_panel import LogPanel\nfrom .position_picker import PickCoordinator\nfrom .profile_controller import ProfileController\nfrom .recording_controller import RecordingController\nfrom .run_controller import RunController\nfrom .step_dialog import StepDialog\nfrom .step_editor import StepEditor\nfrom .tray_icon import TrayIcon\n\nlogger = logging.getLogger(__name__)\n\n# 全局热键 id（进程内唯一即可）\nHK_START = 1\nHK_STOP = 2\nHK_PICK = 3\nHK_RECORD = 4\n\nHOTKEY_SPECS = (\n    (HK_START, "F9", "开始"),\n    (HK_STOP, "F10", "停止/结束录制"),\n    (HK_PICK, "F8", "拾取坐标"),\n    (HK_RECORD, "F11", "录制"),\n)\n\n\nclass MainWindow(QMainWindow):\n    """自动点击器主窗口。"""\n\n    # 任意线程 → 主线程：追加日志（队列连接，因此是线程安全的）\n    log_append = Signal(str)\n\n    def __init__(\n        self,\n        backend: InputBackend,\n        hotkeys: HotkeyManager,\n        store: ProfileStore | None = None,\n    ) -> None:\n        super().__init__()\n        self._hotkeys = hotkeys\n        self._picker = PickCoordinator(self)\n        # 前台后端由 main.py 注入；后台后端在用户第一次切到后台模式时才创建，\n        # 免得不开后台模式也去 import 一堆 Win32 消息相关的东西\n        self._foreground_backend = backend\n        self._background_backend = None\n        self._hotkey_ready: dict[int, bool] = {}\n        self._force_quit = False\n        self._shutdown_done = False\n\n        self._build_ui()\n        self._setup_controllers(backend, store)\n        self._setup_hotkeys()\n        self._profiles.bootstrap()\n\n    # ================================================================ UI 构建\n    def _build_ui(self) -> None:\n        self.setWindowTitle("AutoClicker · 自动点击器")\n        self.setWindowIcon(app_icon())\n        self.resize(860, 780)\n\n        central = QWidget()\n        self.setCentralWidget(central)\n        root = QVBoxLayout(central)\n        root.setContentsMargins(14, 14, 14, 14)\n        root.setSpacing(10)\n\n        root.addWidget(self._build_profile_group())\n\n        splitter = QSplitter(Qt.Orientation.Vertical)\n        splitter.addWidget(self._build_steps_group())\n        splitter.addWidget(self._build_log_group())\n        splitter.setStretchFactor(0, 3)\n        splitter.setStretchFactor(1, 2)\n        splitter.setSizes([420, 220])\n        root.addWidget(splitter, 1)\n\n        root.addWidget(self._build_control_group())\n\n        self._build_menu()\n        self.statusBar().showMessage("就绪  ·  F9 开始   F10 停止   F8 拾取坐标   F11 录制")\n\n    def _build_menu(self) -> None:\n        profile_menu = self.menuBar().addMenu("方案(&P)")\n\n        actions = (\n            ("新建方案", self.create_profile),\n            ("保存", lambda: self.save_current(silent=False)),\n            ("另存为…", self.save_as),\n            ("重命名…", self.rename_profile),\n            ("删除…", self.delete_profile),\n        )\n        for text, handler in actions:\n            action = QAction(text, self)\n            action.triggered.connect(handler)\n            profile_menu.addAction(action)\n\n        profile_menu.addSeparator()\n        quit_action = QAction("退出", self)\n        quit_action.triggered.connect(self.quit_app)\n        profile_menu.addAction(quit_action)\n\n        help_menu = self.menuBar().addMenu("帮助(&H)")\n        about_action = QAction("关于", self)\n        about_action.triggered.connect(self.show_about)\n        help_menu.addAction(about_action)\n\n    def _build_profile_group(self) -> QGroupBox:\n        """方案组。控件的读写契约由 ``ProfileController`` 承担，这里只管摆放。"""\n        group = QGroupBox("方案")\n        root = QVBoxLayout(group)\n\n        # ---- 第一行：方案切换与文件操作\n        top = QHBoxLayout()\n        top.addWidget(QLabel("当前方案:"))\n        self._profile_combo = QComboBox()\n        self._profile_combo.setMinimumWidth(180)\n        top.addWidget(self._profile_combo, 1)\n\n        for text, handler in (\n            ("新建", self.create_profile),\n            ("保存", lambda: self.save_current(silent=False)),\n            ("另存为", self.save_as),\n            ("重命名", self.rename_profile),\n            ("删除", self.delete_profile),\n        ):\n            button = QPushButton(text)\n            button.clicked.connect(handler)\n            top.addWidget(button)\n        root.addLayout(top)\n\n        # ---- 第二行：运行参数\n        bottom = QHBoxLayout()\n        self._start_delay_spin = QSpinBox()\n        self._start_delay_spin.setRange(0, 600_000)\n        self._start_delay_spin.setSuffix(" ms")\n        self._start_delay_spin.setToolTip("按下开始后的等待时间，留出切换窗口的余量")\n\n        self._repeat_spin = QSpinBox()\n        self._repeat_spin.setRange(0, 1_000_000)\n        self._repeat_spin.setSpecialValueText("无限")\n        self._repeat_spin.setToolTip("整个步骤序列重复多少轮，填 0 表示无限直到按 F10")\n\n        self._round_delay_spin = QSpinBox()\n        self._round_delay_spin.setRange(0, 3_600_000)\n        self._round_delay_spin.setSuffix(" ms")\n        self._round_delay_spin.setToolTip("每轮结束后额外等待多久再开始下一轮")\n\n        self._minimize_check = QCheckBox("开始后最小化窗口")\n        self._minimize_check.setChecked(True)\n        self._minimize_check.setToolTip("避免本窗口挡住点击位置")\n\n        bottom.addWidget(QLabel("启动延迟:"))\n        bottom.addWidget(self._start_delay_spin)\n        bottom.addWidget(QLabel("序列轮数:"))\n        bottom.addWidget(self._repeat_spin)\n        bottom.addWidget(QLabel("轮次间隔:"))\n        bottom.addWidget(self._round_delay_spin)\n        bottom.addWidget(self._minimize_check)\n        bottom.addStretch(1)\n        root.addLayout(bottom)\n        return group\n\n    def _build_steps_group(self) -> QGroupBox:\n        group = QGroupBox("步骤序列（按顺序执行）")\n        layout = QVBoxLayout(group)\n\n        self._editor = StepEditor(self._picker)\n        layout.addWidget(self._editor)\n        return group\n\n    def _build_log_group(self) -> QGroupBox:\n        group = QGroupBox("日志")\n        layout = QVBoxLayout(group)\n\n        self._log_panel = LogPanel()\n        layout.addWidget(self._log_panel)\n        return group\n\n    def _build_control_group(self) -> QWidget:\n        holder = QWidget()\n        root = QVBoxLayout(holder)\n        root.setContentsMargins(0, 0, 0, 0)\n        root.setSpacing(6)\n\n        row = QHBoxLayout()\n        self._start_button = QPushButton("开始 (F9)")\n        self._start_button.setMinimumHeight(32)\n        self._start_button.clicked.connect(self.start_clicking)\n\n        self._stop_button = QPushButton("停止 (F10)")\n        self._stop_button.setMinimumHeight(32)\n        self._stop_button.clicked.connect(self.stop_clicking)\n        self._stop_button.setEnabled(False)\n\n        self._pick_button = QPushButton("拾取坐标 (F8)")\n        self._pick_button.setMinimumHeight(32)\n        self._pick_button.clicked.connect(self.pick_position)\n\n        self._record_button = QPushButton("录制 (F11)")\n        self._record_button.setMinimumHeight(32)\n        self._record_button.setToolTip(\n            "录制鼠标点击、按键和鼠标轨迹，自动生成步骤序列。\\n"\n            "录制期间按 F10 结束。"\n        )\n        self._record_button.clicked.connect(self.start_recording)\n\n        self._record_moves_check = QCheckBox("记录鼠标移动")\n        self._record_moves_check.setChecked(True)\n        self._record_moves_check.setToolTip(\n            "记录鼠标轨迹，回放时能还原「移动到菜单上再点击」这类操作。\\n"\n            "关掉后只录点击和按键，步骤更精简。"\n        )\n\n        self._record_swallow_check = QCheckBox("屏蔽输入")\n        self._record_swallow_check.setChecked(False)\n        self._record_swallow_check.setToolTip(\n            "勾选后录制期间鼠标键盘不会传到任何程序，纯粹「空录」坐标和节奏。\\n\\n"\n            "不勾选（默认）：录制时操作是真的会发生的，因此可以录「点开菜单→再点菜单项」"\n            "这类有前后依赖的流程，但请自行确认不会误触发重要操作。\\n"\n            "勾选：绝对不会误点，但依赖上一步结果才出现的界面就没法录。"\n        )\n\n        row.addWidget(self._start_button)\n        row.addWidget(self._stop_button)\n        row.addWidget(self._pick_button)\n        row.addWidget(self._record_button)\n        row.addWidget(self._record_moves_check)\n        row.addWidget(self._record_swallow_check)\n        row.addStretch(1)\n        root.addLayout(row)\n\n        root.addLayout(self._build_backend_row())\n\n        self._state_label = QLabel("状态: 空闲")\n        root.addWidget(self._state_label)\n\n        self._progress = QProgressBar()\n        self._progress.setRange(0, 100)\n        self._progress.setValue(0)\n        self._progress.setTextVisible(False)\n        self._progress.setFixedHeight(8)\n        root.addWidget(self._progress)\n        return holder\n\n    def _build_backend_row(self) -> QHBoxLayout:\n        """输入方式一行：前台 SendInput / 后台 PostMessage + 绑定窗口。\n\n        只有「后台」需要目标窗口，所以绑定按钮默认置灰，勾上后台才可用。\n        """\n        self._background_check = QCheckBox("后台点击 (不占用鼠标)")\n        self._background_check.setToolTip(\n            "勾选后点击通过 PostMessage 投递给目标窗口，不会移动系统光标，"\n            "运行期间可以正常用鼠标，也不要求目标窗口在前台。\\n\\n"\n            "代价：只对处理 WM_* 消息的经典 Win32 窗口有效——Chromium/Electron、"\n            "游戏、部分 UWP 会忽略投递进来的消息（表现为「点了没反应」）。"\n        )\n        self._background_check.toggled.connect(self._on_backend_mode_changed)\n\n        self._bind_button = QPushButton("绑定窗口")\n        self._bind_button.setToolTip(\n            "点一下，然后在屏幕上点击目标窗口，把它设为后台点击的目标。\\n"\n            "不绑定也能用：会按每次点击的坐标临时识别当时最顶层的窗口。"\n        )\n        self._bind_button.setEnabled(False)\n        self._bind_button.clicked.connect(self._bind_window)\n\n        self._bind_label = QLabel()\n        self._bind_label.setStyleSheet("color: #9aa4b2;")\n\n        row = QHBoxLayout()\n        row.addWidget(self._background_check)\n        row.addWidget(self._bind_button)\n        row.addWidget(self._bind_label, 1)\n        self._refresh_bind_label()\n        return row\n\n    # ================================================================ 子系统\n    def _setup_controllers(self, backend: InputBackend, store: ProfileStore | None) -> None:\n        """建好各子系统并接线。这里也是唯一知道「谁和谁说话」的地方。"""\n        self._profiles = ProfileController(\n            store=store or ProfileStore(),\n            window=self,\n            combo=self._profile_combo,\n            editor=self._editor,\n            repeat_spin=self._repeat_spin,\n            round_delay_spin=self._round_delay_spin,\n            start_delay_spin=self._start_delay_spin,\n            parent=self,\n        )\n        self._run = RunController(backend, self._progress, parent=self)\n        self._record = RecordingController(self, parent=self)\n        self._tray = TrayIcon(self)\n\n        # 日志：任意线程 emit log_append，队列连接保证落到主线程再改控件\n        self.log_append.connect(\n            self._log_panel.appendPlainText, Qt.ConnectionType.QueuedConnection\n        )\n        self._log_panel.attach(self.log_append.emit)\n\n        self._profiles.log.connect(self.log_append)\n        self._profiles.changed.connect(self._on_profile_changed)\n\n        self._run.log.connect(self.log_append)\n        self._run.status.connect(self._set_state)\n        self._run.started.connect(self._reset_control_buttons)\n        self._run.stopped.connect(self._on_run_stopped)\n        self._run.failed.connect(self._on_run_failed)\n\n        self._record.log.connect(self.log_append)\n        self._record.status.connect(self._set_state)\n        self._record.recording_changed.connect(self._on_recording_changed)\n        self._record.applied.connect(self._profiles.apply_recording)\n\n        self._tray.restore_requested.connect(self._restore_window)\n        self._tray.start_requested.connect(self.start_clicking)\n        self._tray.stop_requested.connect(self.stop_clicking)\n        self._tray.pick_requested.connect(self.pick_position)\n        self._tray.record_toggle_requested.connect(self.toggle_recording)\n        self._tray.quit_requested.connect(self.quit_app)\n\n        # 截取模板失败（抓屏被拒之类）只可能发生在取图流程里，\n        # 那里没有地方弹窗，所以统一走日志面板。\n        self._picker.failed.connect(lambda message: self.log_append.emit(f"[错误] {message}"))\n\n    def _setup_hotkeys(self) -> None:\n        self._hotkeys.activated.connect(self._on_hotkey)\n        for hotkey_id, name, label in HOTKEY_SPECS:\n            registered = self._hotkeys.register_named(name, hotkey_id=hotkey_id) is not None\n            self._hotkey_ready[hotkey_id] = registered\n            if not registered:\n                message = f"全局热键 {name}（{label}）注册失败，可能已被其他程序占用，请使用界面按钮操作"\n                logger.warning(message)\n                self.log_append.emit(f"[警告] {message}")\n\n    # ================================================================ 方案命令\n    @Slot()\n    def create_profile(self) -> None:\n        self._profiles.create()\n\n    def save_current(self, silent: bool = False) -> bool:\n        return self._profiles.save(silent=silent)\n\n    @Slot()\n    def save_as(self) -> None:\n        self._profiles.save_as()\n\n    @Slot()\n    def rename_profile(self) -> None:\n        self._profiles.rename()\n\n    @Slot()\n    def delete_profile(self) -> None:\n        self._profiles.delete()\n\n    @Slot()\n    def show_about(self) -> None:\n        from .. import __version__\n\n        QMessageBox.about(\n            self,\n            "关于 AutoClicker",\n            f"<b>AutoClicker</b> v{__version__}<br><br>"\n            "基于 PySide6 + Win32 SendInput 的桌面自动点击工具。<br><br>"\n            "<b>热键</b>：F9 开始 · F10 停止 · F8 拾取坐标<br><br>"\n            "运行时请不要移动鼠标——点击会在光标位置真实执行。",\n        )\n\n    # ================================================================ 运行命令\n    @Slot()\n    def start_clicking(self) -> None:\n        if self._run.running:\n            self.log_append.emit("[提示] 任务已在运行中")\n            return\n\n        profile = self._profiles.collect()\n        try:\n            profile.validate(require_steps=True)\n        except ValueError as exc:\n            QMessageBox.warning(self, "参数错误", str(exc))\n            self.log_append.emit(f"[错误] {exc}")\n            return\n\n        # 未保存的改动先落盘，避免辛苦编辑的内容丢掉\n        self.save_current(silent=True)\n\n        # 按界面选择决定这次用前台还是后台注入。\n        # 必须在 start 之前：引擎在运行中不允许换后端。\n        backend = self._active_backend()\n        self._run.set_backend(backend)\n        if backend is self._background_backend:\n            if backend.bound_window:\n                self.log_append.emit(f"[后台点击] 目标窗口：{backend.bound_title}")\n            else:\n                self.log_append.emit("[后台点击] 未绑定窗口，将按每次点击的坐标临时识别窗口")\n\n        if self._minimize_check.isChecked():\n            self.hide()\n\n        self._run.start(profile)\n\n    @Slot()\n    def stop_clicking(self) -> None:\n        if not self._run.running:\n            self.log_append.emit("[提示] 当前没有正在运行的任务")\n            return\n        self._stop_button.setEnabled(False)\n        self.log_append.emit("正在停止…")\n        self._run.stop()\n\n    @Slot()\n    def pick_position(self) -> None:\n        """F8 / 按钮：把拾取到的坐标写回选中的「点击」或「移动」步骤。"""\n        if self._record.recording:\n            self.log_append.emit("[提示] 正在录制，请先按 F10 结束录制")\n            return\n        if self._run.running:\n            self.log_append.emit("[提示] 任务运行中，请先按 F10 停止后再拾取坐标")\n            return\n\n        row = self._editor.current_row()\n        if not isinstance(self._editor.step_at(row), (ClickStep, MoveStep)):\n            self.log_append.emit(\n                "[提示] 请先选中一个「点击」或「移动」步骤，再按 F8 拾取坐标"\n            )\n            return\n\n        self._picker.request(\n            lambda x, y: self._on_picked_for_row(row, x, y),\n            on_canceled=lambda: self.log_append.emit("已取消拾取"),\n            hide_widget=self,\n        )\n\n    # ================================================================ 录制命令\n    @Slot()\n    def start_recording(self) -> None:\n        if self._record.recording:\n            self.log_append.emit("[提示] 已经在录制中，按 F10 结束")\n            return\n        if self._run.running:\n            self.log_append.emit("[提示] 任务运行中，请先按 F10 停止后再录制")\n            return\n        if self._picker.busy:\n            self.log_append.emit("[提示] 正在拾取坐标，请先完成或按 Esc 取消")\n            return\n\n        self._record.start(\n            settings=RecordSettings(record_moves=self._record_moves_check.isChecked()),\n            swallow=self._record_swallow_check.isChecked(),\n            name=self._profiles.effective_name,\n            stop_hotkey_ready=self._hotkey_ready.get(HK_STOP, False),\n        )\n\n    @Slot()\n    def stop_recording(self) -> None:\n        self._record.stop()\n\n    @Slot()\n    def toggle_recording(self) -> None:\n        """托盘菜单用：一个入口同时兼顾开始和结束。"""\n        if self._record.recording:\n            self.stop_recording()\n        else:\n            self.start_recording()\n\n    def _on_picked_for_row(self, row: int, x: int, y: int) -> None:\n        if self._editor.update_click_coords(row, x, y):\n            self.log_append.emit(f"已把坐标 ({x}, {y}) 写入第 {row + 1} 步")\n        else:\n            self.log_append.emit("[提示] 该步骤没有「坐标」可写，已忽略")\n\n    # ================================================================ 输入方式\n    def _ensure_background_backend(self):\n        """按需创建后台后端。延迟创建是为了不开后台模式时不碰这些 Win32 消息。"""\n        if self._background_backend is None:\n            from ..input.postmessage import PostMessageBackend\n\n            self._background_backend = PostMessageBackend()\n        return self._background_backend\n\n    def _active_backend(self):\n        """按界面上的选择返回本次运行要用的后端。"""\n        if self._background_check.isChecked():\n            return self._ensure_background_backend()\n        return self._foreground_backend\n\n    @Slot(bool)\n    def _on_backend_mode_changed(self, enabled: bool) -> None:\n        if enabled:\n            self.log_append.emit(\n                "[提示] 已切换到后台点击（PostMessage）：不移动光标、不要求目标窗口在前台；"\n                "建议先点「绑定窗口」选定目标，否则按每次点击的坐标临时识别窗口。"\n            )\n        else:\n            self.log_append.emit("[提示] 已切回前台点击（SendInput）")\n        self._refresh_bind_label()\n        self._sync_backend_controls()\n\n    def _refresh_bind_label(self) -> None:\n        if not self._background_check.isChecked():\n            self._bind_label.setText("默认：前台注入（SendInput）")\n            return\n        backend = self._background_backend\n        if backend is not None and backend.bound_window:\n            self._bind_label.setText(f"目标窗口：{backend.bound_title}")\n        else:\n            self._bind_label.setText("未绑定（将按点击坐标自动识别窗口）")\n\n    def _sync_backend_controls(self) -> None:\n        """按「是否在跑 / 是否在录」刷新这一行控件的可用性。"""\n        busy = self._run.running or self._record.recording\n        self._background_check.setEnabled(not busy)\n        self._bind_button.setEnabled(self._background_check.isChecked() and not busy)\n\n    @Slot()\n    def _bind_window(self) -> None:\n        """走一次取点流程，把屏幕上点到的那个窗口设为后台点击目标。"""\n        if self._run.running or self._record.recording:\n            self.log_append.emit("[提示] 任务运行或录制中，请结束后再绑定窗口")\n            return\n        if self._picker.busy:\n            self.log_append.emit("[提示] 正在拾取坐标，请先完成或按 Esc 取消")\n            return\n        self._picker.request(\n            self._bind_window_at,\n            on_canceled=lambda: self.log_append.emit("已取消绑定窗口"),\n            hide_widget=self,\n        )\n\n    def _bind_window_at(self, x: int, y: int) -> None:\n        backend = self._ensure_background_backend()\n        if backend.bind_point(x, y):\n            self.log_append.emit(f"已绑定目标窗口：{backend.bound_title}")\n        else:\n            self.log_append.emit(f"[错误] 坐标 ({x}, {y}) 处没有可用的窗口，绑定失败")\n        self._refresh_bind_label()\n\n    # ================================================================ 跨界状态\n    @Slot()\n    def _reset_control_buttons(self) -> None:\n        """按「是否在录制 / 是否在回放」统一刷新按钮可用性。\n\n        录制和回放都会禁用「开始/拾取/录制」，只有同时了解两边的这里才判断得了，\n        因此这几个按钮留在 MainWindow，不下放到控制器里。\n        """\n        self._sync_backend_controls()\n\n        if self._record.recording:\n            self._start_button.setEnabled(False)\n            self._pick_button.setEnabled(False)\n            self._record_button.setEnabled(False)\n            self._stop_button.setEnabled(True)\n            return\n\n        busy = self._run.running\n        self._start_button.setEnabled(not busy)\n        self._pick_button.setEnabled(not busy)\n        self._record_button.setEnabled(not busy)\n        self._stop_button.setEnabled(busy)\n\n    @Slot(str)\n    def _set_state(self, text: str) -> None:\n        """状态牌由运行和录制共用，所以「状态: 」这个前缀由视图统一加。"""\n        self._state_label.setText(f"状态: {text}")\n\n    @Slot(str, bool)\n    def _on_profile_changed(self, name: str, dirty: bool) -> None:\n        marker = " *" if dirty else ""\n        self.setWindowTitle(f"AutoClicker · {name or \'未命名方案\'}{marker}")\n\n    @Slot(bool)\n    def _on_recording_changed(self, active: bool) -> None:\n        self._reset_control_buttons()\n\n    @Slot(int)\n    def _on_run_stopped(self, actions: int) -> None:\n        self._reset_control_buttons()\n        if not self.isVisible():\n            self._tray.notify(f"任务已结束，共执行 {actions} 次动作")\n\n    @Slot(str)\n    def _on_run_failed(self, message: str) -> None:\n        QMessageBox.critical(self, "执行失败", message)\n\n    # ================================================================ 通用槽\n    @Slot()\n    def _restore_window(self) -> None:\n        self.show()\n        self.raise_()\n        self.activateWindow()\n\n    @Slot(int)\n    def _on_hotkey(self, hotkey_id: int) -> None:\n        # 录制中：F10 结束录制，其它热键一律不理会（此时输入是被屏蔽的）\n        if self._record.recording:\n            if hotkey_id == HK_STOP:\n                self.stop_recording()\n            return\n\n        # 步骤编辑对话框开着时按 F8，交给对话框自己处理（它需要临时隐藏自己）\n        dialog = QApplication.activeModalWidget()\n        if hotkey_id == HK_PICK and isinstance(dialog, StepDialog):\n            dialog.start_pick()\n            return\n\n        if self._picker.busy:\n            # 遮罩还挂着：先收掉，避免它一直挡着\n            self._picker.cancel()\n            if hotkey_id == HK_PICK:\n                return\n\n        if hotkey_id == HK_START:\n            self.start_clicking()\n        elif hotkey_id == HK_STOP:\n            self.stop_clicking()\n        elif hotkey_id == HK_PICK:\n            self.pick_position()\n        elif hotkey_id == HK_RECORD:\n            self.start_recording()\n\n    # ================================================================ 生命周期\n    def closeEvent(self, event: QCloseEvent) -> None:  # noqa: N802 - Qt 命名\n        """点关闭按钮时最小化到托盘，而不是退出。"""\n        if self._force_quit or not self._tray.available:\n            self._shutdown()\n            event.accept()\n            return\n\n        event.ignore()\n        self.hide()\n        self._tray.notify_once(\n            "tray-hint",\n            "已最小化到托盘，程序仍在后台运行。\\nF9 开始 / F10 停止 / F8 拾取坐标",\n        )\n\n    @Slot()\n    def quit_app(self) -> None:\n        self._force_quit = True\n        self._shutdown()\n        QApplication.quit()\n\n    def _shutdown(self) -> None:\n        """停引擎、收钩子、注销热键、自动保存。可重复调用。"""\n        if self._shutdown_done:\n            return\n        self._shutdown_done = True\n\n        logger.info("正在退出…")\n\n        # 录制中退出：钩子会随进程消失，但主动摘掉更干净，也能保证屏蔽立刻解除\n        self._record.shutdown()\n        self._run.shutdown()\n\n        try:\n            # 未保存的编辑内容自动落盘，避免下次启动丢失\n            self.save_current(silent=True)\n        except Exception:  # noqa: BLE001 - 退出流程不允许抛异常\n            logger.exception("退出前自动保存失败")\n\n        try:\n            self._hotkeys.shutdown()\n        except Exception:  # noqa: BLE001\n            logger.exception("注销热键时出错")\n\n        self._log_panel.detach()\n        self._picker.cancel()\n        if self._background_backend is not None:\n            self._background_backend.close()\n        self._tray.hide()\n',
    'app/ui/position_picker.py': '"""坐标拾取与模板截取：覆盖全部显示器的半透明遮罩。\n\n设计要点\n--------\n- **可视布局用 Qt 逻辑坐标**：几何取所有 ``QScreen.geometry()`` 的并集，\n  这样在多显示器 + 混合缩放时视觉上是贴合的。\n- **实际捕获用 Win32 物理坐标**：通过 ``GetCursorPos()`` 取值，\n  因此无论 Qt 侧如何缩放，落库的坐标始终是 SendInput 需要的物理像素。\n- 实例可复用：``start()`` 会重置状态，拾取或取消后仅 ``hide()`` 不销毁。\n\n两种取法共用一个协调器（``PickCoordinator``）：\n\n- ``request()``          —— 取一个坐标点（``PositionPicker``）\n- ``request_template()`` —— 拖框截一张模板图（``TemplatePicker``）\n\n两者都必须先让开启流程的那个窗口让开：模态对话框会拦住遮罩的鼠标事件，\n而且它还正好挡在要拾取的位置上。截取模板时还多一步「等合成器重绘」，\n否则会把还没消失的遮罩一起拍进模板里（见 ``HIDE_SETTLE_MS``）。\n"""\n\nfrom __future__ import annotations\n\nimport logging\nfrom typing import Callable\n\nfrom PySide6.QtCore import QObject, QPoint, QRect, Qt, QTimer, Signal\nfrom PySide6.QtGui import (\n    QColor,\n    QFont,\n    QFontMetrics,\n    QGuiApplication,\n    QPainter,\n    QPen,\n)\nfrom PySide6.QtWidgets import QWidget\n\nfrom ..core.matching import Template\nfrom ..win.geometry import ScreenRect, get_cursor_pos\nfrom ..win.screen import capture_screen\nfrom .template_picker import TemplatePicker\n\nlogger = logging.getLogger(__name__)\n\n# 隐藏请求方窗口后等合成器重绘的时间（毫秒）。\n# 不等的话截到的还是「遮罩或对话框盖在上面」的那一帧。\nHIDE_SETTLE_MS = 150\n\n_OVERLAY_COLOR = QColor(0, 0, 0, 70)\n_CROSS_COLOR = QColor(0, 255, 140)\n_BOX_COLOR = QColor(20, 24, 32, 235)\n_TEXT_COLOR = QColor(240, 245, 255)\n\nPickCallback = Callable[[int, int], None]\nCancelCallback = Callable[[], None]\nTemplateCallback = Callable[[Template], None]\n\n\nclass PositionPicker(QWidget):\n    """全屏取点遮罩。左键拾取，右键或 Esc 取消。"""\n\n    picked = Signal(int, int)\n    canceled = Signal()\n\n    def __init__(self, parent: QWidget | None = None) -> None:\n        super().__init__(parent)\n        self.setWindowFlags(\n            Qt.WindowType.FramelessWindowHint\n            | Qt.WindowType.WindowStaysOnTopHint\n            | Qt.WindowType.Tool\n            | Qt.WindowType.NoDropShadowWindowHint\n        )\n        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)\n        self.setCursor(Qt.CursorShape.CrossCursor)\n        self.setMouseTracking(True)\n        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)\n\n        self._active = False\n        self._resolved = False\n        self._cursor: tuple[int, int] = (0, 0)\n        self._local: QPoint | None = None\n\n    # ------------------------------------------------------------------ 接口\n    def start(self) -> None:\n        """显示遮罩并开始取点。"""\n        self._active = True\n        self._resolved = False\n        self._apply_geometry()\n        self._cursor = get_cursor_pos()\n        self._local = None\n        self.show()\n        self.raise_()\n        self.activateWindow()\n        self.setFocus(Qt.FocusReason.OtherFocusReason)\n        self.grabKeyboard()\n        self.update()\n        logger.debug("取点器已启动，当前光标 %s", self._cursor)\n\n    def cancel(self) -> None:\n        """外部请求取消取点，等价于按 Esc。"""\n        if not self._active:\n            return\n        self._resolve(self.canceled.emit)\n\n    # ------------------------------------------------------------------ 内部\n    def _apply_geometry(self) -> None:\n        """把遮罩铺满所有显示器（Qt 逻辑坐标下的并集）。"""\n        desktop = QRect()\n        for screen in QGuiApplication.screens():\n            desktop = desktop.united(screen.geometry())\n\n        if desktop.isValid() and not desktop.isEmpty():\n            self.setGeometry(desktop)\n            return\n\n        primary = QGuiApplication.primaryScreen()  # pragma: no cover - 兜底\n        if primary is not None:\n            self.setGeometry(primary.virtualGeometry())\n\n    def _resolve(self, emit_action) -> None:\n        if self._resolved:\n            return\n        self._resolved = True\n        self._active = False\n        self.releaseKeyboard()\n        self.hide()\n        emit_action()\n\n    # ------------------------------------------------------------ Qt 事件\n    def mouseMoveEvent(self, event) -> None:  # noqa: N802 - Qt 命名\n        self._local = event.position().toPoint()\n        self._cursor = get_cursor_pos()\n        self.update()\n\n    def mousePressEvent(self, event) -> None:  # noqa: N802\n        if event.button() == Qt.MouseButton.LeftButton:\n            x, y = get_cursor_pos()\n            self._resolve(lambda: self.picked.emit(x, y))\n        elif event.button() == Qt.MouseButton.RightButton:\n            self._resolve(self.canceled.emit)\n\n    def keyPressEvent(self, event) -> None:  # noqa: N802\n        if event.key() == Qt.Key.Key_Escape:\n            self._resolve(self.canceled.emit)\n        else:\n            super().keyPressEvent(event)\n\n    def closeEvent(self, event) -> None:  # noqa: N802\n        if self._active:\n            self._resolve(self.canceled.emit)\n        super().closeEvent(event)\n\n    # ------------------------------------------------------------------ 绘制\n    def paintEvent(self, event) -> None:  # noqa: N802\n        painter = QPainter(self)\n        painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)\n\n        painter.fillRect(self.rect(), _OVERLAY_COLOR)\n\n        local = self._local\n        if local is not None:\n            painter.setPen(QPen(_CROSS_COLOR, 1))\n            painter.drawLine(0, local.y(), self.width(), local.y())\n            painter.drawLine(local.x(), 0, local.x(), self.height())\n\n        self._paint_hint(painter, local)\n        painter.end()\n\n    def _paint_hint(self, painter: QPainter, local: QPoint | None) -> None:\n        text = f"X: {self._cursor[0]}    Y: {self._cursor[1]}\\n左键拾取 · 右键/Esc 取消"\n        font = QFont("Microsoft YaHei UI", 11)\n        painter.setFont(font)\n        metrics = QFontMetrics(font)\n\n        lines = text.split("\\n")\n        width = max(metrics.horizontalAdvance(line) for line in lines) + 28\n        height = metrics.height() * len(lines) + 18\n\n        anchor = local if local is not None else QPoint(0, 0)\n        bx = anchor.x() + 26\n        by = anchor.y() + 26\n        # 贴近屏幕边缘时自动翻到另一侧\n        if bx + width > self.width():\n            bx = anchor.x() - width - 26\n        if by + height > self.height():\n            by = anchor.y() - height - 26\n        bx = max(0, bx)\n        by = max(0, by)\n\n        painter.setPen(Qt.PenStyle.NoPen)\n        painter.setBrush(_BOX_COLOR)\n        painter.drawRoundedRect(bx, by, width, height, 8, 8)\n\n        painter.setPen(_TEXT_COLOR)\n        painter.drawText(\n            bx + 14,\n            by + 9,\n            width - 28,\n            height - 18,\n            int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter),\n            text,\n        )\n\n\nclass PickCoordinator(QObject):\n    """集中管理取点 / 截模板的整套流程。\n\n    取点经常发生在「某个窗口正开着」的时候（主窗口、步骤编辑对话框），\n    而这些窗口往往正好挡住要拾取的位置。因此把「先隐藏请求方 → 显示遮罩 →\n    回调 → 再恢复请求方」这套流程收在一个地方，调用方只需要传 ``hide_widget``。\n\n    为什么要隐藏请求方而不是仅靠遮罩盖在上面：\n    Qt 的**模态**对话框会拦截其它窗口的输入。把模态对话框临时 ``hide()`` 掉\n    （隐藏的模态窗口不参与输入拦截），遮罩才能正常接到鼠标点击。\n    """\n\n    failed = Signal(str)  # 截取模板失败时的原因，供日志面板显示\n\n    POINT = "point"\n    TEMPLATE = "template"\n    CAPTURE = "capture"\n\n    def __init__(self, parent: QObject | None = None) -> None:\n        super().__init__(parent)\n        # 刻意不给遮罩设 parent：带 parent 的 Qt.Tool 窗口会随 parent 一起隐藏，\n        # 而取点流程恰恰需要先隐藏请求方窗口。\n        self._picker = PositionPicker(None)\n        self._picker.picked.connect(self._handle_picked)\n        self._picker.canceled.connect(self._handle_canceled)\n\n        self._template_picker = TemplatePicker(None)\n        self._template_picker.selected.connect(self._handle_template_selected)\n        self._template_picker.canceled.connect(self._handle_canceled)\n\n        self._mode: str | None = None\n        self._on_picked: PickCallback | None = None\n        self._on_template: TemplateCallback | None = None\n        self._on_captured = None\n        self._on_canceled: CancelCallback | None = None\n        self._hider: QWidget | None = None\n        self._pending_rect: ScreenRect | None = None\n\n    @property\n    def busy(self) -> bool:\n        """是否有取点/截模板流程正在进行（含等待合成器重绘的那一小段）。\n\n        ``busy`` 不能只看遮罩可见性：松手之后遮罩已经隐藏，但截取还没完成，\n        这段时间里必须继续拒绝新的取点请求（比如用户又按了一下 F8）。\n        """\n        return self._mode is not None\n\n    def cancel(self) -> None:\n        """外部请求取消（等价于用户按 Esc）。"""\n        if self._mode == self.POINT:\n            self._picker.cancel()\n        elif self._mode == self.TEMPLATE and self._template_picker.isVisible():\n            self._template_picker.cancel()\n\n    def request(\n        self,\n        on_picked: PickCallback,\n        on_canceled: CancelCallback | None = None,\n        hide_widget: QWidget | None = None,\n    ) -> bool:\n        """开始取点。已有流程在进行时返回 False。"""\n        if self._mode is not None:\n            return False\n\n        self._mode = self.POINT\n        self._on_picked = on_picked\n        self._on_canceled = on_canceled\n        self._hider = hide_widget\n        if hide_widget is not None:\n            hide_widget.hide()\n\n        self._picker.start()\n        return True\n\n    def request_template(\n        self,\n        on_selected: TemplateCallback,\n        on_canceled: CancelCallback | None = None,\n        hide_widget: QWidget | None = None,\n    ) -> bool:\n        """开始拖框截模板。已有流程在进行时返回 False。\n\n        回调拿到的是刚从屏幕上抠下来的 ``Template``；截取失败时走 ``on_canceled``\n        并发出 ``failed`` 信号。\n        """\n        if self._mode is not None:\n            return False\n\n        self._mode = self.TEMPLATE\n        self._on_template = on_selected\n        self._on_canceled = on_canceled\n        self._hider = hide_widget\n        if hide_widget is not None:\n            hide_widget.hide()\n\n        self._template_picker.start()\n        return True\n\n    def capture_screen_after_hide(self, on_captured, hide_widget: QWidget | None = None) -> bool:\n        """让请求方让开一下，抓一帧整屏后把它恢复。\n\n        给「模拟测试」用：对话框里正显示着模板预览图，而预览图**就是模板本身**，\n        不先让开的话找图会先命中自己的预览图，测出来的结果毫无意义。\n        """\n        if self._mode is not None:\n            return False\n\n        self._mode = self.CAPTURE\n        self._on_captured = on_captured\n        self._hider = hide_widget\n        if hide_widget is not None:\n            hide_widget.hide()\n\n        QTimer.singleShot(HIDE_SETTLE_MS, self._capture_full)\n        return True\n\n    # ------------------------------------------------------------------ 内部\n    def _restore(self) -> None:\n        # 遮罩正常路径下会自己 hide 后再发信号，这里再兜一次：\n        # 「回调已交付」与「遮罩已消失」必须是同一时刻成立的不变式，\n        # 否则遮罩会一直挂在屏幕上挡住用户操作。\n        self._picker.hide()\n        self._template_picker.hide()\n\n        widget = self._hider\n        self._hider = None\n        self._on_picked = None\n        self._on_template = None\n        self._on_captured = None\n        self._on_canceled = None\n        self._pending_rect = None\n        self._mode = None\n\n        if widget is not None:\n            widget.show()\n            widget.raise_()\n            widget.activateWindow()\n\n    def _handle_picked(self, x: int, y: int) -> None:\n        callback = self._on_picked\n        self._restore()\n        if callback is not None:\n            callback(x, y)\n\n    def _handle_canceled(self) -> None:\n        callback = self._on_canceled\n        self._restore()\n        if callback is not None:\n            callback()\n\n    def _handle_template_selected(self, rect: ScreenRect) -> None:\n        """松手了，但此刻遮罩刚刚隐藏、屏幕还没重绘完，所以延后一点再抓。"""\n        self._pending_rect = rect\n        QTimer.singleShot(HIDE_SETTLE_MS, self._capture_template)\n\n    def _capture_template(self) -> None:\n        rect = self._pending_rect\n        if rect is None:  # pragma: no cover - 流程被提前清理\n            return\n\n        callback = self._on_template\n        on_canceled = self._on_canceled\n        failure = None\n        template = None\n        try:\n            template = Template.from_frame(capture_screen(rect))\n        except (OSError, ValueError) as exc:\n            failure = f"截取模板失败：{exc}"\n\n        self._restore()\n        if failure is not None:\n            logger.error("%s", failure)\n            self.failed.emit(failure)\n            if on_canceled is not None:\n                on_canceled()\n            return\n        if callback is not None and template is not None:\n            callback(template)\n\n    def _capture_full(self) -> None:\n        callback = self._on_captured\n        failure = None\n        frame = None\n        try:\n            frame = capture_screen()\n        except OSError as exc:\n            failure = f"抓取屏幕失败：{exc}"\n\n        self._restore()\n        if failure is not None:\n            logger.error("%s", failure)\n            self.failed.emit(failure)\n            return\n        if callback is not None and frame is not None:\n            callback(frame)\n\n',
    'app/ui/profile_controller.py': '"""方案管理。\n\n把「当前是哪个方案 / 有没有未保存的改动 / 落盘 / 改名 / 删除」收在一处。\n\n界面控件由 MainWindow 建好之后**注入**进来，本模块不参与布局。这样做的取舍是构造函数\n参数偏多，但换来两件事：布局仍然只有一处（不会为了改个对齐翻两个文件），以及这个类\n碰过哪些控件一目了然。\n"""\n\nfrom __future__ import annotations\n\nimport logging\n\nfrom PySide6.QtCore import QObject, Signal, Slot\nfrom PySide6.QtWidgets import (\n    QComboBox,\n    QInputDialog,\n    QMainWindow,\n    QMessageBox,\n    QSpinBox,\n)\n\nfrom ..core.models import ClickStep, Profile\nfrom ..core.recording import APPLY_REPLACE\nfrom ..storage.config import ProfileStore\nfrom .step_editor import StepEditor\n\nlogger = logging.getLogger(__name__)\n\nAUTOSAVE_NAME = "默认方案"\n\n\nclass ProfileController(QObject):\n    """当前方案的状态与持久化。"""\n\n    log = Signal(str)\n    # (当前方案名, 是否有未保存改动) —— 窗口标题由 MainWindow 拼\n    changed = Signal(str, bool)\n\n    def __init__(\n        self,\n        *,\n        store: ProfileStore,\n        window: QMainWindow,\n        combo: QComboBox,\n        editor: StepEditor,\n        repeat_spin: QSpinBox,\n        round_delay_spin: QSpinBox,\n        start_delay_spin: QSpinBox,\n        parent: QObject | None = None,\n    ) -> None:\n        super().__init__(parent)\n        self._store = store\n        self._window = window\n        self._combo = combo\n        self._editor = editor\n        self._repeat_spin = repeat_spin\n        self._round_delay_spin = round_delay_spin\n        self._start_delay_spin = start_delay_spin\n\n        self._name = ""\n        self._dirty = False\n        # 载入方案时控件会连锁触发 valueChanged，用这个闸门把「装载」和「用户编辑」分开\n        self._loading = False\n\n        self._combo.currentIndexChanged.connect(self._on_selected)\n        # 「哪里改了就算脏」这条规则只写在这一处：三个运行参数 + 步骤表\n        for spin in (repeat_spin, round_delay_spin, start_delay_spin):\n            spin.valueChanged.connect(self.mark_dirty)\n        editor.changed.connect(self.mark_dirty)\n\n    # ---------------------------------------------------------------- 只读状态\n    @property\n    def current_name(self) -> str:\n        return self._name\n\n    @property\n    def effective_name(self) -> str:\n        """没名字时给一个兜底名，避免存出空名文件。"""\n        return self._name or AUTOSAVE_NAME\n\n    @property\n    def dirty(self) -> bool:\n        return self._dirty\n\n    # ---------------------------------------------------------------- 启动\n    def bootstrap(self) -> None:\n        """首次启动时落盘一个默认方案，然后载入最近使用的方案。"""\n        names = self._store.list_names()\n        if not names:\n            default = Profile.default()\n            self._store.save(default)\n            names = self._store.list_names()\n            logger.info("已创建初始方案: %s", default.name)\n\n        self.refresh_combo()\n\n        target = self._store.get_last_profile()\n        if target not in names:\n            target = names[0] if names else None\n        if target:\n            self.load(target)\n\n    # ---------------------------------------------------------------- 读写\n    def collect(self) -> Profile:\n        """从界面收集当前方案。"""\n        return Profile(\n            name=self.effective_name,\n            steps=self._editor.steps(),\n            repeat=self._repeat_spin.value(),\n            repeat_delay_ms=self._round_delay_spin.value(),\n            start_delay_ms=self._start_delay_spin.value(),\n        )\n\n    def apply_recording(self, profile: Profile, mode: str) -> None:\n        """把录制结果并入当前方案。\n\n        ``mode`` 为 ``APPLY_REPLACE`` 时连运行参数一起换成录制出来的默认值，\n        为 ``APPLY_APPEND`` 时只追加步骤、保留用户自己调过的轮数与延迟。\n        """\n        if mode == APPLY_REPLACE:\n            self._editor.set_steps(profile.steps)\n            self._repeat_spin.setValue(profile.repeat)\n            self._round_delay_spin.setValue(profile.repeat_delay_ms)\n            self._start_delay_spin.setValue(profile.start_delay_ms)\n            first_new = 0\n        else:\n            existing = self._editor.steps()\n            self._editor.set_steps(existing + profile.steps)\n            first_new = len(existing)\n\n        # 光标停在「新录进来的第一行」，用户一眼就能看出东西加在哪\n        self._editor.select_row(first_new)\n        self.mark_dirty()\n\n    def refresh_combo(self, select: str | None = None) -> None:\n        self._loading = True\n        try:\n            self._combo.clear()\n            names = self._store.list_names()\n            self._combo.addItems(names)\n            target = select or self._name\n            index = self._combo.findText(target) if target else -1\n            if index < 0 and names:\n                index = 0\n            if index >= 0:\n                self._combo.setCurrentIndex(index)\n        finally:\n            self._loading = False\n\n    def load(self, name: str) -> None:\n        try:\n            profile = self._store.load(name)\n        except ValueError as exc:\n            logger.error("加载方案失败: %s", exc)\n            self.log.emit(f"[错误] {exc}")\n            QMessageBox.warning(self._window, "加载失败", str(exc))\n            return\n\n        self._name = name\n        self._apply(profile)\n        self._store.set_last_profile(name)\n        self._announce()\n        self.log.emit(f"已加载方案「{name}」（{len(profile.steps)} 个步骤）")\n\n    # ---------------------------------------------------------------- 增删改\n    @Slot()\n    def create(self) -> None:\n        name, ok = QInputDialog.getText(self._window, "新建方案", "方案名称:", text="新方案")\n        if not ok or not name.strip():\n            return\n        name = name.strip()\n        if self._store.exists(name):\n            QMessageBox.warning(self._window, "名称冲突", f"方案「{name}」已存在。")\n            return\n\n        self.save(silent=True)\n        profile = Profile(name=name, steps=[])\n        fallback = next(\n            (step for step in Profile.default().steps if isinstance(step, ClickStep)), None\n        )\n        if fallback is not None:\n            profile.steps.append(fallback)\n        try:\n            self._store.save(profile)\n        except OSError as exc:\n            QMessageBox.critical(self._window, "保存失败", str(exc))\n            return\n\n        self._name = name\n        self._apply(profile)\n        self.refresh_combo(select=name)\n        self._store.set_last_profile(name)\n        self._announce()\n        self.log.emit(f"已新建方案「{name}」")\n\n    def save(self, silent: bool = False) -> bool:\n        """保存当前方案（校验失败时只在非静默模式下弹窗）。"""\n        if not self._name:\n            return self.save_as()\n\n        profile = self.collect()\n        try:\n            profile.validate(require_steps=False)\n        except ValueError as exc:\n            if not silent:\n                QMessageBox.warning(self._window, "参数错误", f"无法保存：{exc}")\n            return False\n\n        try:\n            self._store.save(profile)\n        except OSError as exc:\n            QMessageBox.critical(self._window, "保存失败", str(exc))\n            return False\n\n        self.set_dirty(False)\n        if not silent:\n            self.log.emit(f"方案「{profile.name}」已保存")\n        return True\n\n    @Slot()\n    def save_as(self) -> None:\n        current = self.collect()\n        name, ok = QInputDialog.getText(self._window, "另存为", "方案名称:", text=current.name)\n        if not ok or not name.strip():\n            return\n        name = name.strip()\n        if self._store.exists(name) and QMessageBox.question(\n            self._window,\n            "覆盖确认",\n            f"方案「{name}」已存在，是否覆盖？",\n            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,\n        ) != QMessageBox.StandardButton.Yes:\n            return\n\n        current.name = name\n        try:\n            current.validate(require_steps=False)\n            self._store.save(current)\n        except ValueError as exc:\n            QMessageBox.warning(self._window, "参数错误", f"无法保存：{exc}")\n            return\n        except OSError as exc:\n            QMessageBox.critical(self._window, "保存失败", str(exc))\n            return\n\n        self._name = name\n        self.refresh_combo(select=name)\n        self._store.set_last_profile(name)\n        self.set_dirty(False)\n        self.log.emit(f"方案已另存为「{name}」")\n\n    @Slot()\n    def rename(self) -> None:\n        if not self._name:\n            return\n        name, ok = QInputDialog.getText(self._window, "重命名方案", "新名称:", text=self._name)\n        if not ok or not name.strip() or name.strip() == self._name:\n            return\n        name = name.strip()\n        if self._store.exists(name):\n            QMessageBox.warning(self._window, "名称冲突", f"方案「{name}」已存在。")\n            return\n\n        self.save(silent=True)\n        if not self._store.rename(self._name, name):\n            QMessageBox.critical(self._window, "重命名失败", "无法重命名方案文件。")\n            return\n\n        self._name = name\n        self.set_dirty(False)\n        self.refresh_combo(select=name)\n        self._store.set_last_profile(name)\n        self.log.emit(f"方案已重命名为「{name}」")\n\n    @Slot()\n    def delete(self) -> None:\n        if not self._name:\n            return\n        if QMessageBox.question(\n            self._window,\n            "删除方案",\n            f"确定删除方案「{self._name}」吗？此操作不可撤销。",\n            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,\n        ) != QMessageBox.StandardButton.Yes:\n            return\n\n        removed = self._name\n        self._store.delete(removed)\n        self.log.emit(f"方案「{removed}」已删除")\n\n        names = self._store.list_names()\n        if not names:\n            default = Profile.default()\n            self._store.save(default)\n            names = self._store.list_names()\n\n        self._name = ""\n        self.refresh_combo(select=names[0])\n        if names:\n            self.load(names[0])\n\n    # ---------------------------------------------------------------- 脏标记\n    @Slot()\n    def mark_dirty(self) -> None:\n        if self._loading:\n            return\n        self.set_dirty(True)\n\n    def set_dirty(self, dirty: bool) -> None:\n        if self._dirty == dirty:\n            return\n        self._dirty = dirty\n        self._announce()\n\n    # ---------------------------------------------------------------- 内部\n    def _apply(self, profile: Profile) -> None:\n        """把方案渲染到界面。"""\n        self._loading = True\n        try:\n            self._editor.set_steps(profile.steps)\n            self._repeat_spin.setValue(profile.repeat)\n            self._round_delay_spin.setValue(profile.repeat_delay_ms)\n            self._start_delay_spin.setValue(profile.start_delay_ms)\n        finally:\n            self._loading = False\n        self.set_dirty(False)\n\n    def _announce(self) -> None:\n        self.changed.emit(self._name, self._dirty)\n\n    @Slot(int)\n    def _on_selected(self, index: int) -> None:\n        # 切方案前先把当前这份静默存了，避免用户辛苦编辑的内容丢掉\n        if self._loading or index < 0:\n            return\n        name = self._combo.itemText(index)\n        if not name or name == self._name:\n            return\n        self.save(silent=True)\n        self.load(name)\n',
    'app/ui/record_overlay.py': '"""录制中的悬浮指示条。\n\n录制时主窗口会被最小化（否则会挡住用户要操作的目标），所以必须有一个独立的\n视觉反馈告诉用户「正在录」。\n\n两个关键属性：\n\n- ``WindowTransparentForInput``：鼠标点击直接穿透，不会挡住/被点到；\n- ``WindowDoesNotAcceptFocus``：不抢焦点，避免打乱正在录制的目标窗口焦点状态。\n"""\n\nfrom __future__ import annotations\n\nfrom PySide6.QtCore import QRectF, Qt, QTimer\nfrom PySide6.QtGui import QColor, QFont, QFontMetrics, QGuiApplication, QPainter\nfrom PySide6.QtWidgets import QWidget\n\n_BG = QColor(24, 28, 38, 236)\n_BORDER = QColor(220, 70, 70, 200)\n_TEXT = QColor(240, 245, 255)\n_DIM = QColor(160, 172, 190)\n_DOT_ON = QColor(230, 70, 70)\n_DOT_OFF = QColor(120, 90, 90)\n\nWIDTH = 460\nHEIGHT = 74\nTOP_MARGIN = 24\nBLINK_MS = 500\n\n\nclass RecordOverlay(QWidget):\n    """常驻顶部的「● 录制中」指示条。"""\n\n    def __init__(self, parent: QWidget | None = None) -> None:\n        super().__init__(parent)\n        self.setWindowFlags(\n            Qt.WindowType.FramelessWindowHint\n            | Qt.WindowType.WindowStaysOnTopHint\n            | Qt.WindowType.Tool\n            | Qt.WindowType.WindowTransparentForInput\n            | Qt.WindowType.WindowDoesNotAcceptFocus\n            | Qt.WindowType.NoDropShadowWindowHint\n        )\n        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)\n        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)\n        self.setAttribute(Qt.WidgetAttribute.WA_ShowWithoutActivating, True)\n        self.setFixedSize(WIDTH, HEIGHT)\n\n        self._actions = 0\n        self._moves = 0\n        self._swallow = True\n        self._blink_on = True\n\n        self._blink_timer = QTimer(self)\n        self._blink_timer.setInterval(BLINK_MS)\n        self._blink_timer.timeout.connect(self._toggle_blink)\n\n    # ------------------------------------------------------------------ 接口\n    def start(self, swallow: bool) -> None:\n        self._actions = 0\n        self._moves = 0\n        self._swallow = swallow\n        self._blink_on = True\n        self._move_to_default_corner()\n        self.show()\n        self.raise_()\n        self._blink_timer.start()\n        self.update()\n\n    def set_count(self, actions: int, moves: int) -> None:\n        if (actions, moves) == (self._actions, self._moves):\n            return\n        self._actions = actions\n        self._moves = moves\n        self.update()\n\n    def finish(self) -> None:\n        self._blink_timer.stop()\n        self.hide()\n\n    # ------------------------------------------------------------------ 内部\n    def _move_to_default_corner(self) -> None:\n        """摆在主显示器顶部居中。用主显示器而不是虚拟桌面，避免多屏时间隙错位。"""\n        screen = QGuiApplication.primaryScreen()\n        if screen is None:  # pragma: no cover - 无显示器环境\n            return\n        area = screen.availableGeometry()\n        self.move(area.x() + (area.width() - self.width()) // 2, area.y() + TOP_MARGIN)\n\n    def _toggle_blink(self) -> None:\n        self._blink_on = not self._blink_on\n        self.update()\n\n    # ------------------------------------------------------------------ 绘制\n    def paintEvent(self, event) -> None:  # noqa: N802 - Qt 命名\n        painter = QPainter(self)\n        painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)\n\n        bounds = QRectF(0.5, 0.5, self.width() - 1, self.height() - 1)\n        painter.setPen(_BORDER)\n        painter.setBrush(_BG)\n        painter.drawRoundedRect(bounds, 12, 12)\n\n        # 闪烁的红点\n        painter.setPen(Qt.PenStyle.NoPen)\n        painter.setBrush(_DOT_ON if self._blink_on else _DOT_OFF)\n        painter.drawEllipse(18, 26, 14, 14)\n\n        painter.setPen(_TEXT)\n        painter.setFont(QFont("Microsoft YaHei UI", 12, QFont.Weight.Bold))\n        painter.drawText(44, 24, 200, 20, int(Qt.AlignmentFlag.AlignLeft), "录制中")\n\n        painter.setPen(_DIM)\n        painter.setFont(QFont("Microsoft YaHei UI", 9))\n        painter.drawText(44, 44, 400, 18, int(Qt.AlignmentFlag.AlignLeft), self._detail())\n\n        painter.end()\n\n    def _detail(self) -> str:\n        hint = "按 F10 结束录制"\n        if not self._swallow:\n            hint += "（未屏蔽输入）"\n        detail = f"{hint}   ·   点击/按键 {self._actions}"\n        if self._moves:\n            detail += f"   ·   移动采样 {self._moves}"\n        metrics = QFontMetrics(QFont("Microsoft YaHei UI", 9))\n        return metrics.elidedText(detail, Qt.TextElideMode.ElideRight, WIDTH - 60)\n',
    'app/ui/recording_controller.py': '"""录制控制。\n\n钩子录制 + 悬浮指示条 + 「事件 → 步骤」的转换与落地选择。\n\n安全约束（本模块存在的主要理由）\n--------------------------------\n勾选「屏蔽输入」时鼠标键盘不再传给任何程序，**唯一的出口是 F10 全局热键**。\n所以热键不可用时宁可拒绝开录，也不能把用户锁在一个点不动的系统里。\n录制期间放行的控制热键（F8/F9/F10/F11）也是同一个道理：不放行的话低级钩子会把它们\n吃掉，``RegisterHotKey`` 永远收不到。\n\n``ask_how_to_apply`` 故意做成公开方法：自动化测试会替换它，免得弹出没人点的模态框。\n"""\n\nfrom __future__ import annotations\n\nimport logging\n\nfrom PySide6.QtCore import QObject, QTimer, Signal, Slot\nfrom PySide6.QtWidgets import QMainWindow, QMessageBox\n\nfrom ..core.models import Profile, StepKind\nfrom ..core.recording import (\n    APPLY_APPEND,\n    APPLY_DISCARD,\n    APPLY_REPLACE,\n    RecordSettings,\n    build_profile,\n    summarize,\n)\nfrom ..win.hooks import InputRecorder\nfrom ..win.hotkey import vk_of\nfrom .record_overlay import RecordOverlay\n\nlogger = logging.getLogger(__name__)\n\n# 指示条刷新间隔。钩子回调里绝不能刷 UI（超时会掉钩子），所以用定时器轮询计数。\nRECORD_TICK_MS = 200\n\n# 录制时放行这些控制热键，否则它们会被低级钩子吃掉，RegisterHotKey 永远收不到\nPASSTHROUGH_KEYS = ("F8", "F9", "F10", "F11")\n\n\nclass RecordingController(QObject):\n    """录制一次操作并把它转成步骤。"""\n\n    log = Signal(str)\n    status = Signal(str)\n    recording_changed = Signal(bool)\n    # (Profile, mode) —— 由 MainWindow 转交给 ProfileController 落地\n    applied = Signal(object, str)\n\n    def __init__(self, window: QMainWindow, parent: QObject | None = None) -> None:\n        super().__init__(parent)\n        self._window = window\n        self._recorder = InputRecorder()\n        self._overlay = RecordOverlay()\n        self._active = False\n        self._settings = RecordSettings()\n        self._name = ""\n\n        self._timer = QTimer(self)\n        self._timer.setInterval(RECORD_TICK_MS)\n        self._timer.timeout.connect(self._sync_overlay)\n\n    # ---------------------------------------------------------------- 只读\n    @property\n    def recording(self) -> bool:\n        return self._active\n\n    @property\n    def overlay(self) -> RecordOverlay:\n        return self._overlay\n\n    @property\n    def recorder(self) -> InputRecorder:\n        """底层录制器。供测试注入假事件、以及调试时查看计数。"""\n        return self._recorder\n\n    # ---------------------------------------------------------------- 开始\n    def start(\n        self,\n        *,\n        settings: RecordSettings,\n        swallow: bool,\n        name: str,\n        stop_hotkey_ready: bool,\n    ) -> bool:\n        """开始录制，返回是否真的开始了。被拒绝时一定给出可操作的原因。"""\n        if self._active:\n            self.log.emit("[提示] 已经在录制中，按 F10 结束")\n            return False\n\n        if swallow and not stop_hotkey_ready:\n            # 屏蔽模式下鼠标键盘都不通，唯一的出口就是 F10 热键。热键不可用就绝不能开录，\n            # 否则用户会被「锁」在一个点不动的系统里。\n            logger.error("拒绝开始录制：停止热键不可用")\n            self.log.emit("[错误] 无法录制：F10 热键不可用")\n            QMessageBox.warning(\n                self._window,\n                "无法录制",\n                "无法以「屏蔽输入」方式录制：F10（结束录制）热键未注册成功。\\n\\n"\n                "屏蔽输入后鼠标键盘都不再传给任何程序，必须能按 F10 才能安全结束。\\n"\n                "请关闭占用 F10 的程序，或取消勾选「屏蔽输入」后重试。",\n            )\n            return False\n\n        if not stop_hotkey_ready:\n            logger.warning("停止热键 F10 不可用，录制只能从托盘菜单结束")\n            self.log.emit("[警告] F10 热键不可用，录制请用托盘菜单的「开始/结束录制」结束")\n\n        passthrough = [vk for vk in (vk_of(key) for key in PASSTHROUGH_KEYS) if vk]\n        if not self._recorder.start(swallow=swallow, passthrough_vks=passthrough):\n            logger.error("安装输入钩子失败")\n            self.log.emit("[错误] 安装输入钩子失败")\n            QMessageBox.critical(\n                self._window, "无法录制", "安装全局输入钩子失败，无法开始录制。"\n            )\n            return False\n\n        self._active = True\n        self._settings = settings\n        self._name = name\n        self._timer.start()\n        self._overlay.start(swallow=self._recorder.swallow)\n        self._window.hide()\n\n        self.recording_changed.emit(True)\n        self.status.emit("录制中…")\n        mode = "已屏蔽鼠标键盘" if swallow else "正常操作（会真的点到东西）"\n        self.log.emit(f"● 开始录制（{mode}），按 F10 结束")\n        return True\n\n    # ---------------------------------------------------------------- 结束\n    @Slot()\n    def stop(self) -> None:\n        """结束录制，把结果交给用户决定怎么落地。"""\n        if not self._active:\n            return\n        self._active = False\n        self._timer.stop()\n        self._overlay.finish()\n\n        events = self._recorder.stop()\n        self._restore_window()\n        self.recording_changed.emit(False)\n\n        profile = build_profile(events, name=self._name, settings=self._settings)\n        if not profile.steps:\n            self.status.emit("空闲（本次没有录到动作）")\n            self.log.emit("[提示] 没有记录到任何动作")\n            QMessageBox.information(\n                self._window,\n                "录制结束",\n                "没有记录到任何动作。\\n\\n"\n                "如果确实操作了鼠标键盘，请确认没有其他程序也在安装输入钩子。",\n            )\n            return\n\n        summary = summarize(profile)\n        self.log.emit(f"● 录制结束，{summary}")\n\n        mode = self.ask_how_to_apply(summary)\n        if mode == APPLY_DISCARD:\n            self.status.emit("空闲（已丢弃本次录制）")\n            self.log.emit("已丢弃本次录制")\n            return\n\n        # 交给 ProfileController 落地（直接连接，同线程同步执行）\n        self.applied.emit(profile, mode)\n        self.status.emit(f"空闲（{summary}）")\n        if _count_kind(profile, StepKind.MOVE):\n            self.log.emit(\n                "[提示] 轨迹步骤已按「一个移动 = 一个步骤」压缩；双击任意一行可微调时长与终点"\n            )\n\n    def shutdown(self) -> None:\n        """退出流程：丢弃录制中的内容、摘掉钩子、收起指示条。可重复调用。"""\n        if self._active:\n            self._active = False\n            self._timer.stop()\n            self._recorder.stop()\n        self._overlay.finish()\n\n    # ---------------------------------------------------------------- 弹窗\n    def ask_how_to_apply(self, summary: str) -> str:\n        """让用户决定录制结果如何并入当前方案。\n\n        做成公开方法（而不是内部 ``_xxx``）是故意的：自动化测试会整段替换它，\n        免得弹出一个没人点的模态框把测试挂死。\n        """\n        box = QMessageBox(self._window)\n        box.setWindowTitle("录制结束")\n        box.setIcon(QMessageBox.Icon.Question)\n        box.setText(f"{summary}\\n\\n要如何应用这次录制？")\n        replace_button = box.addButton("替换当前步骤", QMessageBox.ButtonRole.AcceptRole)\n        append_button = box.addButton("追加到末尾", QMessageBox.ButtonRole.ActionRole)\n        discard_button = box.addButton("丢弃", QMessageBox.ButtonRole.RejectRole)\n        box.setDefaultButton(append_button)\n        box.exec()\n\n        clicked = box.clickedButton()\n        if clicked is replace_button:\n            return APPLY_REPLACE\n        if clicked is append_button:\n            return APPLY_APPEND\n        if clicked is discard_button:\n            return APPLY_DISCARD\n        return APPLY_DISCARD  # 直接关掉窗口按丢弃处理\n\n    # ---------------------------------------------------------------- 内部\n    @Slot()\n    def _sync_overlay(self) -> None:\n        if self._active:\n            self._overlay.set_count(self._recorder.action_count, self._recorder.move_count)\n\n    def _restore_window(self) -> None:\n        self._window.show()\n        self._window.raise_()\n        self._window.activateWindow()\n\n\ndef _count_kind(profile: Profile, kind: StepKind) -> int:\n    return sum(1 for step in profile.steps if step.kind is kind)\n',
    'app/ui/run_controller.py': '"""执行控制。\n\n把 ``MacroEngine`` 搬到工作线程，并把它报出来的进度翻译成「状态文案 + 进度条」。\n\n**只做执行这一件事**：方案从哪来、要不要先保存、窗口要不要最小化、按了什么键触发、\n按钮该不该置灰——都不归它管。那些是 MainWindow 的策略，这里不碰。\n\n界面上唯一属于它的控件是进度条（纯执行进度）。状态文案通过信号抛出去，\n因为「状态」这块牌子同时也被录制流程使用，由 MainWindow 统一持有。\n"""\n\nfrom __future__ import annotations\n\nimport logging\n\nfrom PySide6.QtCore import QObject, QThread, Signal, Slot\nfrom PySide6.QtWidgets import QProgressBar\n\nfrom ..core.engine import MacroEngine\nfrom ..core.models import Profile\nfrom ..input.base import InputBackend\nfrom .shot import save_frame\n\nlogger = logging.getLogger(__name__)\n\n# 退出时等工作线程收工的上限；超时只记日志，不阻塞退出\nSHUTDOWN_WAIT_MS = 3000\n\n\nclass RunController(QObject):\n    """驱动宏引擎跑一个方案，并汇报进度。"""\n\n    log = Signal(str)\n    # 状态栏正文（不含「状态: 」前缀，那是视图的事）\n    status = Signal(str)\n    started = Signal()\n    stopped = Signal(int)\n    failed = Signal(str)\n\n    # 主线程 → 工作线程：投递方案（队列连接，跨线程安全）\n    _run_requested = Signal(object)\n\n    def __init__(\n        self,\n        backend: InputBackend,\n        progress: QProgressBar,\n        parent: QObject | None = None,\n    ) -> None:\n        super().__init__(parent)\n        self._progress = progress\n        self._actions = 0\n        self._rounds_done = 0\n        self._rounds_total = 0\n        self._step_index = 0\n        self._step_total = 0\n\n        self._thread = QThread(self)\n        self._thread.setObjectName("MacroEngineThread")\n\n        self._engine = MacroEngine(backend)\n        self._engine.moveToThread(self._thread)\n\n        self._run_requested.connect(self._engine.run)\n        self._engine.started.connect(self._on_started)\n        self._engine.step_changed.connect(self._on_step_changed)\n        self._engine.progress.connect(self._on_progress)\n        self._engine.stopped.connect(self._on_stopped)\n        self._engine.failed.connect(self._on_failed)\n        self._engine.wait_timeout.connect(self._on_wait_timeout)\n\n        self._thread.start()\n\n    # ---------------------------------------------------------------- 对外\n    @property\n    def running(self) -> bool:\n        return self._engine.running\n\n    def start(self, profile: Profile) -> None:\n        """投递一个**已经校验通过**的方案给工作线程。"""\n        self._progress.setRange(0, 100)\n        self._progress.setValue(0)\n        self._run_requested.emit(profile)\n\n    def stop(self) -> None:\n        """请求停止。立刻返回，不等工作线程收工。"""\n        self._engine.request_stop()\n\n    def set_backend(self, backend: InputBackend) -> None:\n        """切换输入后端（前台 SendInput / 后台 PostMessage）。\n\n        供 MainWindow 在 ``start`` 之前按界面上的选择调用。\n        """\n        self._engine.set_backend(backend)\n\n    def shutdown(self) -> None:\n        """停引擎 + 回收线程。退出流程用，可以重复调用。"""\n        try:\n            self._engine.request_stop()\n            self._thread.quit()\n            if not self._thread.wait(SHUTDOWN_WAIT_MS):\n                logger.warning("工作线程未在 %s ms 内退出", SHUTDOWN_WAIT_MS)\n        except Exception:  # noqa: BLE001 - 退出流程不允许抛异常\n            logger.exception("关闭引擎时出错")\n\n    # ---------------------------------------------------------------- 引擎回调\n    @Slot()\n    def _on_started(self) -> None:\n        self._actions = 0\n        self._rounds_done = 0\n        self._step_index = 0\n        self._step_total = 0\n        self.started.emit()\n        self.status.emit("运行中")\n        self.log.emit("▶ 开始执行")\n\n    @Slot(int, int)\n    def _on_step_changed(self, index: int, total: int) -> None:\n        self._step_index = index\n        self._step_total = total\n        self._progress.setRange(0, total)\n        self._progress.setValue(index)\n        self._emit_progress_status()\n\n    @Slot(int, int, int)\n    def _on_progress(self, actions: int, rounds_done: int, rounds_total: int) -> None:\n        self._actions = actions\n        self._rounds_done = rounds_done\n        self._rounds_total = rounds_total\n        self._emit_progress_status()\n\n    @Slot(int)\n    def _on_stopped(self, actions: int) -> None:\n        self._progress.setRange(0, 100)\n        self._progress.setValue(0)\n        self._actions = actions\n        self.status.emit(f"空闲（本次共执行 {actions} 次动作）")\n        self.log.emit(f"■ 已停止，本次共执行 {actions} 次动作")\n        # 放在最后：让订阅方看到进度条/状态都已经归档完毕\n        self.stopped.emit(actions)\n\n    @Slot(str)\n    def _on_failed(self, message: str) -> None:\n        self.log.emit(f"[错误] {message}")\n        self.failed.emit(message)\n\n    @Slot(object)\n    def _on_wait_timeout(self, frame) -> None:\n        """找图超时中止：把最后一帧落盘。\n\n        这类失败光看日志没法判断「是模板过期了还是弹窗根本没出现」，\n        一张当时的屏幕截图比什么描述都管用。\n        """\n        path = save_frame(frame)\n        if path is not None:\n            self.log.emit(f"已把失败时的屏幕截图存到 {path}")\n\n    def _emit_progress_status(self) -> None:\n        parts = ["运行中"]\n        if self._step_total:\n            parts.append(f"第 {self._step_index}/{self._step_total} 步")\n        if self._rounds_total:\n            parts.append(f"第 {self._rounds_done + 1}/{self._rounds_total} 轮")\n        else:\n            parts.append(f"已完成 {self._rounds_done} 轮")\n        parts.append(f"共 {self._actions} 次动作")\n        self.status.emit(" · ".join(parts))\n',
    'app/ui/shot.py': '"""找图失败时的现场快照。\n\n找图最难受的失败方式是「什么都没发生」：用户看不出是模板过期了、容差太小，\n还是目标弹窗根本没出现。超时中止时把最后一帧存下来，打开一看就清楚了。\n\n快照只在**中止**模式下保存（``ON_TIMEOUT_STOP``）。如果是「继续」模式，\n一个循环里反复超时的等待步骤会写出一堆几乎一样的图，反而把有用的那张埋掉。\n"""\n\nfrom __future__ import annotations\n\nimport logging\nimport time\nfrom pathlib import Path\n\nfrom PySide6.QtGui import QImage\n\nfrom ..utils.logger import app_data_dir\n\nlogger = logging.getLogger(__name__)\n\n# 只留最近这么多张，避免长时间挂机把磁盘写满\nSHOT_LIMIT = 10\n\n\ndef shots_dir() -> Path:\n    return app_data_dir() / "shots"\n\n\ndef save_frame(frame) -> Path | None:\n    """把一帧屏幕存成 PNG，返回文件路径。失败只记日志，绝不打断宏执行。"""\n    try:\n        directory = shots_dir()\n        directory.mkdir(parents=True, exist_ok=True)\n        path = _unique_path(directory)\n\n        # Format_RGB32 在小端机器上的内存布局正好是 BGRA，和抓屏输出一致；\n        # 它忽略 alpha 通道，这也正是我们要的（GDI 抓回来的 alpha 是 0）。\n        image = QImage(\n            frame.data,\n            frame.width,\n            frame.height,\n            frame.stride,\n            QImage.Format.Format_RGB32,\n        )\n        if image.isNull() or not image.save(str(path), "PNG"):\n            raise OSError("Qt 无法编码这张图")\n\n        _prune(directory)\n        return path\n    except (OSError, ValueError) as exc:\n        logger.warning("保存现场快照失败: %s", exc)\n        return None\n\n\ndef _unique_path(directory: Path) -> Path:\n    stamp = time.strftime("%Y%m%d-%H%M%S")\n    path = directory / f"找图失败-{stamp}.png"\n    index = 2\n    while path.exists():\n        path = directory / f"找图失败-{stamp}-{index}.png"\n        index += 1\n    return path\n\n\ndef _prune(directory: Path) -> None:\n    """按修改时间删掉最旧的快照，只留 ``SHOT_LIMIT`` 张。"""\n    try:\n        shots = sorted(\n            directory.glob("*.png"), key=lambda item: item.stat().st_mtime, reverse=True\n        )\n    except OSError:  # pragma: no cover - 目录刚被删掉之类\n        return\n\n    for stale in shots[SHOT_LIMIT:]:\n        try:\n            stale.unlink()\n        except OSError as exc:  # pragma: no cover - 文件被占用\n            logger.debug("清理旧快照失败 %s: %s", stale.name, exc)\n',
    'app/ui/step_dialog.py': '"""步骤编辑对话框。\n\n一个对话框同时支持所有步骤类型，靠 ``step.kind`` 决定展示哪一组字段。\n比每种类型各写一个对话框省掉大量重复代码，又能保证「确定」后返回的步骤类型不变。\n\n对话框是**模态**的。点「拾取坐标」/「截取屏幕」时会把自己临时隐藏再启动遮罩，\n恢复由 ``PickCoordinator`` 负责（见 ``position_picker.PickCoordinator`` 的说明）。\n\n「模拟测试」也需要先把自己藏起来：对话框里的模板预览图正好**就是模板本身**，\n如果它还在屏幕上，找图会先命中自己的预览图，测出来的结果毫无意义。\n"""\n\nfrom __future__ import annotations\n\nfrom PySide6.QtCore import Qt\nfrom PySide6.QtGui import QImage, QPixmap\nfrom PySide6.QtWidgets import (\n    QCheckBox,\n    QComboBox,\n    QDialog,\n    QDialogButtonBox,\n    QFormLayout,\n    QHBoxLayout,\n    QLabel,\n    QLineEdit,\n    QMessageBox,\n    QPushButton,\n    QSpinBox,\n    QVBoxLayout,\n    QWidget,\n)\n\nfrom ..core.matching import MIN_PROBE_PX, Template, find_template, solid_run_length\nfrom ..core.models import (\n    ON_TIMEOUT_CONTINUE,\n    ClickStep,\n    DelayStep,\n    KeyStep,\n    MoveStep,\n    Step,\n    StepKind,\n    WaitStep,\n)\nfrom ..input.base import MouseButton\nfrom ..win.hotkey import vk_names, vk_of\n\n_TITLES = {\n    StepKind.CLICK: "点击步骤",\n    StepKind.DELAY: "延时步骤",\n    StepKind.KEY: "按键步骤",\n    StepKind.MOVE: "移动步骤",\n    StepKind.WAIT: "找图步骤",\n}\n\n# 预览图最大宽度：缩得比原始像素小，既省地方又不会「预览图 == 模板」自命中\n_MAX_PREVIEW_WIDTH = 220\n\n\nclass StepDialog(QDialog):\n    """新增 / 编辑一个步骤。"""\n\n    def __init__(self, step: Step, picker, parent: QWidget | None = None) -> None:\n        super().__init__(parent)\n        self._kind = step.kind\n        self._picker = picker\n        self._source = step\n        # MoveStep 的轨迹是可变的，单独存一份，避免拾取时污染原对象\n        self._points: list[tuple[int, int]] = (\n            list(step.points) if isinstance(step, MoveStep) else []\n        )\n        # WaitStep 的模板同理：先只存字符串，需要显示/测试时才解码\n        self._template_b64: str = step.template if isinstance(step, WaitStep) else ""\n        self._pending_test: Template | None = None\n\n        self.setWindowTitle(_TITLES[step.kind])\n        self.setModal(True)\n        self.setMinimumWidth(380)\n\n        self._build_ui()\n        self._load(step)\n\n    # ---------------------------------------------------------------- 构建\n    def _build_ui(self) -> None:\n        root = QVBoxLayout(self)\n        form = QFormLayout()\n        form.setLabelAlignment(Qt.AlignmentFlag.AlignRight)\n\n        self._enabled_check = QCheckBox("启用此步骤")\n        self._enabled_check.setChecked(True)\n        form.addRow("", self._enabled_check)\n\n        if self._kind is StepKind.CLICK:\n            form.addRow(self._build_click_fields())\n        elif self._kind is StepKind.DELAY:\n            form.addRow(self._build_delay_fields())\n        elif self._kind is StepKind.MOVE:\n            form.addRow(self._build_move_fields())\n        elif self._kind is StepKind.WAIT:\n            form.addRow(self._build_wait_fields())\n        else:\n            form.addRow(self._build_key_fields())\n\n        self._note_edit = QLineEdit()\n        self._note_edit.setPlaceholderText("可选，例如「等待加载完成」")\n        form.addRow("备注:", self._note_edit)\n\n        root.addLayout(form)\n\n        buttons = QDialogButtonBox(\n            QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel\n        )\n        buttons.button(QDialogButtonBox.StandardButton.Ok).setText("确定")\n        buttons.button(QDialogButtonBox.StandardButton.Cancel).setText("取消")\n        buttons.accepted.connect(self.accept)\n        buttons.rejected.connect(self.reject)\n        root.addWidget(buttons)\n\n    def _build_click_fields(self) -> QWidget:\n        from ..win.geometry import virtual_screen_rect\n\n        limit = virtual_screen_rect()\n        span = max(limit.width, limit.height, 10_000) * 2\n\n        box = QWidget()\n        form = QFormLayout(box)\n        form.setContentsMargins(0, 0, 0, 0)\n\n        self._x_spin = QSpinBox()\n        self._x_spin.setRange(-span, span)\n        self._x_spin.setSuffix(" px")\n        self._y_spin = QSpinBox()\n        self._y_spin.setRange(-span, span)\n        self._y_spin.setSuffix(" px")\n\n        pick_button = QPushButton("拾取坐标 (F8)")\n        pick_button.clicked.connect(self.start_pick)\n\n        position_row = QHBoxLayout()\n        position_row.addWidget(QLabel("X"))\n        position_row.addWidget(self._x_spin)\n        position_row.addWidget(QLabel("Y"))\n        position_row.addWidget(self._y_spin)\n        position_row.addWidget(pick_button)\n\n        self._button_combo = QComboBox()\n        for button in MouseButton:\n            self._button_combo.addItem(str(button), button)\n\n        self._repeat_spin = QSpinBox()\n        self._repeat_spin.setRange(1, 1_000_000)\n        self._interval_spin = QSpinBox()\n        self._interval_spin.setRange(1, 3_600_000)\n        self._interval_spin.setSuffix(" ms")\n        self._jitter_ms_spin = QSpinBox()\n        self._jitter_ms_spin.setRange(0, 60_000)\n        self._jitter_ms_spin.setSuffix(" ms")\n        self._jitter_ms_spin.setToolTip("实际间隔落在 [间隔, 间隔 + 抖动] 之间，避免机械规律")\n        self._jitter_px_spin = QSpinBox()\n        self._jitter_px_spin.setRange(0, 500)\n        self._jitter_px_spin.setSuffix(" px")\n        self._jitter_px_spin.setToolTip("落点在 ±该半径内随机偏移")\n\n        form.addRow("位置:", _wrap(position_row))\n        form.addRow("鼠标按键:", self._button_combo)\n        form.addRow("点击次数:", self._repeat_spin)\n        form.addRow("点击间隔:", self._interval_spin)\n        form.addRow("间隔抖动:", self._jitter_ms_spin)\n        form.addRow("坐标抖动:", self._jitter_px_spin)\n        return box\n\n    def _build_delay_fields(self) -> QWidget:\n        box = QWidget()\n        form = QFormLayout(box)\n        form.setContentsMargins(0, 0, 0, 0)\n\n        self._delay_spin = QSpinBox()\n        self._delay_spin.setRange(0, 86_400_000)\n        self._delay_spin.setSuffix(" ms")\n        self._jitter_ms_spin = QSpinBox()\n        self._jitter_ms_spin.setRange(0, 60_000)\n        self._jitter_ms_spin.setSuffix(" ms")\n\n        form.addRow("等待时长:", self._delay_spin)\n        form.addRow("随机追加:", self._jitter_ms_spin)\n        return box\n\n    def _build_key_fields(self) -> QWidget:\n        box = QWidget()\n        form = QFormLayout(box)\n        form.setContentsMargins(0, 0, 0, 0)\n\n        self._key_combo = QComboBox()\n        self._key_combo.setEditable(False)\n        for name in vk_names():\n            self._key_combo.addItem(name, vk_of(name))\n\n        self._repeat_spin = QSpinBox()\n        self._repeat_spin.setRange(1, 100_000)\n        self._interval_spin = QSpinBox()\n        self._interval_spin.setRange(1, 3_600_000)\n        self._interval_spin.setSuffix(" ms")\n\n        form.addRow("按键:", self._key_combo)\n        form.addRow("按键次数:", self._repeat_spin)\n        form.addRow("按键间隔:", self._interval_spin)\n        return box\n\n    def _build_move_fields(self) -> QWidget:\n        box = QWidget()\n        form = QFormLayout(box)\n        form.setContentsMargins(0, 0, 0, 0)\n\n        self._path_label = QLabel()\n        self._path_label.setWordWrap(True)\n        pick_button = QPushButton("拾取终点 (F8)")\n        pick_button.setToolTip("把轨迹改成「从原起点直线移动到新拾取的点」，时长不变")\n        pick_button.clicked.connect(self.start_pick)\n\n        self._duration_spin = QSpinBox()\n        self._duration_spin.setRange(0, 600_000)\n        self._duration_spin.setSuffix(" ms")\n        self._duration_spin.setToolTip("走完整条轨迹所用的时间；填 0 表示瞬移")\n\n        form.addRow("轨迹:", self._path_label)\n        form.addRow("", pick_button)\n        form.addRow("移动时长:", self._duration_spin)\n        return box\n\n    def _build_wait_fields(self) -> QWidget:\n        box = QWidget()\n        form = QFormLayout(box)\n        form.setContentsMargins(0, 0, 0, 0)\n\n        self._template_label = QLabel()\n        self._template_label.setAlignment(Qt.AlignmentFlag.AlignCenter)\n        self._template_label.setMinimumSize(_MAX_PREVIEW_WIDTH + 20, 64)\n        self._template_label.setStyleSheet(\n            "border: 1px dashed #7a7a7a; border-radius: 6px; color: #9aa4b2;"\n        )\n        self._template_hint = QLabel()\n        self._template_hint.setWordWrap(True)\n\n        crop_button = QPushButton("截取屏幕")\n        crop_button.setToolTip(\n            "把屏幕压暗后拖一个框，框住要让程序去认的那块画面。\\n"\n            "建议连按钮的纯色底色一起框进来——匹配就是靠这段纯色做初筛的。"\n        )\n        crop_button.clicked.connect(self.pick_template)\n\n        self._tolerance_spin = QSpinBox()\n        self._tolerance_spin.setRange(0, 255)\n        self._tolerance_spin.setToolTip(\n            "抽样比对时每个像素通道允许的最大色差。\\n"\n            "用来容忍文字抗锯齿、半透明之类的细微差异。\\n"\n            "注意：整块颜色都变了（换主题 / 改 DPI 缩放）时调它没用，必须重新截模板。"\n        )\n\n        self._timeout_spin = QSpinBox()\n        self._timeout_spin.setRange(0, 3_600_000)\n        self._timeout_spin.setSingleStep(1000)\n        self._timeout_spin.setSuffix(" ms")\n        self._timeout_spin.setToolTip("最多等这么久。填 0 表示只找一次，找不到立刻按「超时后」处理。")\n\n        self._poll_spin = QSpinBox()\n        self._poll_spin.setRange(20, 60_000)\n        self._poll_spin.setSingleStep(50)\n        self._poll_spin.setSuffix(" ms")\n        self._poll_spin.setToolTip("每隔多久看屏幕一眼。每看一眼都要抓一帧整屏，间隔越大越省 CPU。")\n\n        self._click_check = QCheckBox("找到后点击它")\n        self._click_check.toggled.connect(self._sync_click_enabled)\n\n        self._button_combo = QComboBox()\n        for button in MouseButton:\n            self._button_combo.addItem(str(button), button)\n\n        self._offset_x_spin = QSpinBox()\n        self._offset_x_spin.setRange(-10_000, 10_000)\n        self._offset_x_spin.setSuffix(" px")\n        self._offset_y_spin = QSpinBox()\n        self._offset_y_spin.setRange(-10_000, 10_000)\n        self._offset_y_spin.setSuffix(" px")\n        for spin in (self._offset_x_spin, self._offset_y_spin):\n            spin.setToolTip("点击位置相对模板中心的偏移，用来微调到底点哪儿")\n\n        offset_row = QHBoxLayout()\n        offset_row.addWidget(self._offset_x_spin)\n        offset_row.addWidget(self._offset_y_spin)\n\n        self._timeout_combo = QComboBox()\n        self._timeout_combo.addItem("继续下一步", ON_TIMEOUT_CONTINUE)\n        self._timeout_combo.addItem("停止并报错", "stop")\n        self._timeout_combo.setToolTip(\n            "等不到时的处理。\\n"\n            "「停止并报错」会把当时的屏幕存一张图到快照目录，方便事后看是模板过期还是弹窗没出现。"\n        )\n\n        test_button = QPushButton("模拟测试")\n        test_button.setToolTip("不跑宏、不点鼠标，就地抓一帧看看现在能不能找到；用来调容差。")\n        test_button.clicked.connect(self.test_match)\n\n        form.addRow(self._template_label)\n        form.addRow("图片模板:", crop_button)\n        form.addRow("", self._template_hint)\n        form.addRow("容差:", self._tolerance_spin)\n        form.addRow("超时:", self._timeout_spin)\n        form.addRow("轮询间隔:", self._poll_spin)\n        form.addRow("", self._click_check)\n        form.addRow("鼠标按键:", self._button_combo)\n        form.addRow("点击偏移:", _wrap(offset_row))\n        form.addRow("超时后:", self._timeout_combo)\n        form.addRow("", test_button)\n        return box\n\n    def _sync_click_enabled(self) -> None:\n        enabled = self._click_check.isChecked()\n        for widget in (\n            self._button_combo,\n            self._offset_x_spin,\n            self._offset_y_spin,\n        ):\n            widget.setEnabled(enabled)\n\n    # ---------------------------------------------------------------- 读写\n    def _load(self, step: Step) -> None:\n        self._enabled_check.setChecked(step.enabled)\n        self._note_edit.setText(step.note)\n\n        if isinstance(step, ClickStep):\n            self._x_spin.setValue(step.x)\n            self._y_spin.setValue(step.y)\n            self._button_combo.setCurrentIndex(\n                self._button_combo.findData(MouseButton(step.button).value)\n            )\n            self._repeat_spin.setValue(step.repeat)\n            self._interval_spin.setValue(step.interval_ms)\n            self._jitter_ms_spin.setValue(step.jitter_ms)\n            self._jitter_px_spin.setValue(step.jitter_px)\n        elif isinstance(step, DelayStep):\n            self._delay_spin.setValue(step.delay_ms)\n            self._jitter_ms_spin.setValue(step.jitter_ms)\n        elif isinstance(step, KeyStep):\n            index = self._key_combo.findData(step.vk)\n            self._key_combo.setCurrentIndex(index if index >= 0 else 0)\n            self._repeat_spin.setValue(step.repeat)\n            self._interval_spin.setValue(step.interval_ms)\n        elif isinstance(step, MoveStep):\n            self._duration_spin.setValue(step.duration_ms)\n            self._refresh_path_label()\n        elif isinstance(step, WaitStep):\n            self._tolerance_spin.setValue(step.tolerance)\n            self._timeout_spin.setValue(step.timeout_ms)\n            self._poll_spin.setValue(step.poll_interval_ms)\n            self._click_check.setChecked(step.click)\n            self._sync_click_enabled()\n            self._button_combo.setCurrentIndex(\n                self._button_combo.findData(MouseButton(step.button).value)\n            )\n            self._offset_x_spin.setValue(step.offset_x)\n            self._offset_y_spin.setValue(step.offset_y)\n            index = self._timeout_combo.findData(step.on_timeout)\n            self._timeout_combo.setCurrentIndex(index if index >= 0 else 0)\n            self._render_template()\n\n    def result_step(self) -> Step:\n        """把界面上的值组装成一个新的步骤对象。"""\n        common = {"enabled": self._enabled_check.isChecked(), "note": self._note_edit.text().strip()}\n\n        if self._kind is StepKind.CLICK:\n            return ClickStep(\n                x=self._x_spin.value(),\n                y=self._y_spin.value(),\n                button=MouseButton(self._button_combo.currentData()),\n                repeat=self._repeat_spin.value(),\n                interval_ms=self._interval_spin.value(),\n                jitter_ms=self._jitter_ms_spin.value(),\n                jitter_px=self._jitter_px_spin.value(),\n                **common,\n            )\n        if self._kind is StepKind.DELAY:\n            return DelayStep(\n                delay_ms=self._delay_spin.value(),\n                jitter_ms=self._jitter_ms_spin.value(),\n                **common,\n            )\n        if self._kind is StepKind.MOVE:\n            return MoveStep(\n                points=list(self._points),\n                duration_ms=self._duration_spin.value(),\n                **common,\n            )\n        if self._kind is StepKind.WAIT:\n            return WaitStep(\n                template=self._template_b64,\n                tolerance=self._tolerance_spin.value(),\n                timeout_ms=self._timeout_spin.value(),\n                poll_interval_ms=self._poll_spin.value(),\n                click=self._click_check.isChecked(),\n                button=MouseButton(self._button_combo.currentData()),\n                offset_x=self._offset_x_spin.value(),\n                offset_y=self._offset_y_spin.value(),\n                on_timeout=str(self._timeout_combo.currentData()),\n                **common,\n            )\n        return KeyStep(\n            vk=int(self._key_combo.currentData() or 0),\n            repeat=self._repeat_spin.value(),\n            interval_ms=self._interval_spin.value(),\n            **common,\n        )\n\n    # ---------------------------------------------------------------- 取点\n    def start_pick(self) -> None:\n        """隐藏本对话框并启动取点遮罩。延时/按键步骤没有坐标可填，直接忽略。"""\n        if self._kind not in (StepKind.CLICK, StepKind.MOVE):\n            return\n        self._picker.request(self._apply_picked, hide_widget=self)\n\n    def _apply_picked(self, x: int, y: int) -> None:\n        if self._kind is StepKind.MOVE:\n            # 保留原起点，改成直线走到新终点\n            origin = self._points[0] if self._points else (x, y)\n            self._points = [origin, (x, y)]\n            self._refresh_path_label()\n            return\n        self._x_spin.setValue(x)\n        self._y_spin.setValue(y)\n\n    def _refresh_path_label(self) -> None:\n        if not self._points:\n            self._path_label.setText("（空轨迹，请点击下方按钮拾取终点）")\n            return\n        if len(self._points) == 1:\n            self._path_label.setText(f"移动到 ({self._points[0][0]}, {self._points[0][1]})")\n            return\n        sx, sy = self._points[0]\n        ex, ey = self._points[-1]\n        self._path_label.setText(f"{len(self._points)} 个点：({sx}, {sy}) → ({ex}, {ey})")\n\n    # ---------------------------------------------------------------- 找图\n    def pick_template(self) -> None:\n        """隐藏对话框并启动拖框遮罩，把框内的画面截成模板。"""\n        if self._kind is not StepKind.WAIT:\n            return\n        self._picker.request_template(self._apply_template, hide_widget=self)\n\n    def _apply_template(self, template: Template) -> None:\n        self._template_b64 = template.encode()\n        self._render_template()\n\n    def _render_template(self) -> None:\n        """刷新预览图与「这个模板好不好找」的提示。"""\n        template = self._decoded_template()\n        if template is None:\n            self._template_label.setPixmap(QPixmap())\n            self._template_label.setText("（未截取）")\n            self._template_hint.setText("")\n            return\n\n        self._template_label.setText("")\n        self._template_label.setPixmap(_preview_pixmap(template))\n\n        run = solid_run_length(template)\n        if run < MIN_PROBE_PX:\n            self._template_hint.setStyleSheet("color: #e8a33d;")\n            self._template_hint.setText(\n                f"{template.summary} 像素 · 这块画面里没有连续 {MIN_PROBE_PX} 像素的纯色区域，"\n                "匹配只能靠逐像素硬碰：界面稍微变一点（换主题、改 DPI、盖上半透明层）就可能找不到。"\n                "建议把按钮的纯色底色一起框进来。"\n            )\n        else:\n            self._template_hint.setStyleSheet("color: #7fb2e5;")\n            self._template_hint.setText(\n                f"{template.summary} 像素 · 含 {run} 像素纯色区域，颜色微变也扛得住。"\n            )\n\n    def _decoded_template(self) -> Template | None:\n        if not self._template_b64:\n            return None\n        try:\n            return Template.decode(self._template_b64)\n        except ValueError:\n            return None\n\n    def test_match(self) -> None:\n        """就地抓一帧找一次，把结果摆出来——调容差不用来回跑宏。"""\n        template = self._decoded_template()\n        if template is None:\n            QMessageBox.information(self, "模拟测试", "请先截取要查找的图片模板。")\n            return\n\n        self._pending_test = template\n        if not self._picker.capture_screen_after_hide(self._apply_test_frame, hide_widget=self):\n            QMessageBox.information(self, "模拟测试", "另一个拾取流程正在进行，请稍后再试。")\n\n    def _apply_test_frame(self, frame) -> None:\n        template = self._pending_test\n        self._pending_test = None\n        if template is None:  # pragma: no cover - 流程被提前清理\n            return\n\n        result = find_template(frame, template, tolerance=self._tolerance_spin.value())\n        match = result.match\n        if match is not None:\n            x = frame.x + match.x + template.width // 2\n            y = frame.y + match.y + template.height // 2\n            QMessageBox.information(\n                self,\n                "模拟测试",\n                f"找到了。\\n\\n"\n                f"相似度：{match.similarity:.2f}\\n"\n                f"模板尺寸：{template.summary} 像素\\n"\n                f"命中位置：({frame.x + match.x}, {frame.y + match.y})\\n"\n                f"点击位置：({x}, {y})（模板中心）\\n\\n"\n                f"共扫描了 {result.candidates} 个候选位置。",\n            )\n            return\n\n        best = result.best\n        if best is None:\n            detail = (\n                "屏幕上没有任何一处颜色和目标一致。\\n"\n                "多半是目标窗口此刻没显示、被别的窗口挡住，"\n                "或者它的外观变了（换了主题/语言/DPI 缩放）——那就得重新截一次模板。"\n            )\n        else:\n            detail = (\n                f"有几处颜色接近，但形状对不上（最像的一处相似度 {best.similarity:.2f}）。\\n"\n                "可以调大容差，或者重新截取模板时把按钮的纯色底色一起框进来。"\n            )\n        QMessageBox.warning(\n            self,\n            "模拟测试",\n            f"没找到。\\n\\n{detail}\\n\\n"\n            f"（当前容差 {self._tolerance_spin.value()}，扫描了 {result.candidates} 个候选位置）",\n        )\n\n    # ---------------------------------------------------------------- 校验\n    def accept(self) -> None:\n        """确定前先校验，非法时不关闭对话框。"""\n        try:\n            self.result_step().validate()\n        except ValueError as exc:\n            QMessageBox.warning(self, "参数错误", str(exc))\n            return\n        super().accept()\n\n\ndef _wrap(layout) -> QWidget:\n    """把 QHBoxLayout 包成一个 QWidget，方便塞进 QFormLayout 的字段位。"""\n    widget = QWidget()\n    widget.setLayout(layout)\n    layout.setContentsMargins(0, 0, 0, 0)\n    return widget\n\n\ndef _preview_pixmap(template: Template) -> QPixmap:\n    """把模板画成预览图。\n\n    用 ``FastTransformation`` 而不是平滑缩放：缩放后的像素值会和模板不一致，\n    而这种「看起来差不多」的模糊很容易让人误判匹配为什么会偏。\n    """\n    image = QImage(\n        template.data,\n        template.width,\n        template.height,\n        template.stride,\n        QImage.Format.Format_RGB32,\n    ).copy()  # copy：QImage 不持有 buffer，模板对象随时可能被回收\n    pixmap = QPixmap.fromImage(image)\n    if pixmap.width() > _MAX_PREVIEW_WIDTH:\n        pixmap = pixmap.scaledToWidth(\n            _MAX_PREVIEW_WIDTH, Qt.TransformationMode.FastTransformation\n        )\n    return pixmap\n',
    'app/ui/step_editor.py': '"""步骤序列编辑器。\n\n一个表格 + 一排按钮：增 / 改 / 删 / 上移 / 下移。\n\n设计取舍\n--------\n- 表格整体是**只读**的（``NoEditTriggers``），所有改动都走对话框。\n  这样每种步骤类型可以有自己的字段表单，不用写一堆自定义 delegate；\n  只有「启用」列是内联可勾选的。\n- 编辑器只负责一份 ``list[Step]``，不关心持久化和执行，方便单独测试。\n"""\n\nfrom __future__ import annotations\n\nimport logging\n\nfrom PySide6.QtCore import Qt, Signal\nfrom PySide6.QtGui import QColor\nfrom PySide6.QtWidgets import (\n    QAbstractItemView,\n    QDialog,\n    QHBoxLayout,\n    QHeaderView,\n    QMessageBox,\n    QPushButton,\n    QTableWidget,\n    QTableWidgetItem,\n    QVBoxLayout,\n    QWidget,\n)\n\nfrom ..core.models import ClickStep, DelayStep, KeyStep, MoveStep, Step, StepKind, WaitStep\nfrom ..win.geometry import get_cursor_pos, virtual_screen_rect\nfrom ..win.hotkey import vk_of\nfrom .position_picker import PickCoordinator\nfrom .step_dialog import StepDialog\n\nlogger = logging.getLogger(__name__)\n\nCOL_ENABLED = 0\nCOL_KIND = 1\nCOL_SUMMARY = 2\nCOL_NOTE = 3\n\n_ROW_COLORS = {\n    StepKind.CLICK: None,\n    StepKind.DELAY: "#e8a33d",\n    StepKind.KEY: "#3da35d",\n    StepKind.MOVE: "#7d6cf5",\n    StepKind.WAIT: "#e0619b",\n}\n\n\nclass StepEditor(QWidget):\n    """步骤列表。``changed`` 在任何内容变动后发出。"""\n\n    changed = Signal()\n\n    def __init__(self, picker: PickCoordinator, parent: QWidget | None = None) -> None:\n        super().__init__(parent)\n        self._picker = picker\n        self._steps: list[Step] = []\n        self._populating = False\n        self._build_ui()\n\n    # ================================================================ 对外接口\n    def set_steps(self, steps: list[Step]) -> None:\n        """整体替换步骤列表。"""\n        self._steps = list(steps)\n        self._refresh()\n\n    def steps(self) -> list[Step]:\n        """返回步骤列表的副本（浅拷贝，元素仍是原对象）。"""\n        return list(self._steps)\n\n    def current_row(self) -> int:\n        return self._table.currentRow()\n\n    def step_at(self, row: int) -> Step | None:\n        if 0 <= row < len(self._steps):\n            return self._steps[row]\n        return None\n\n    def select_row(self, row: int) -> None:\n        if 0 <= row < self._table.rowCount():\n            self._table.selectRow(row)\n\n    def update_click_coords(self, row: int, x: int, y: int) -> bool:\n        """把拾取到的坐标写回某一行。\n\n        点击步骤改的是坐标；移动步骤改的是**终点**（起点保留，中间拐点拉直），\n        这样「选中轨迹行 → F8 重新瞄一下」也能用。\n        """\n        step = self.step_at(row)\n        if isinstance(step, ClickStep):\n            step.x = x\n            step.y = y\n        elif isinstance(step, MoveStep):\n            step.points = ([step.points[0]] if step.points else []) + [(x, y)]\n            step.validate()\n        else:\n            return False\n        self._refresh()\n        self.select_row(row)\n        self.changed.emit()\n        return True\n\n    # ================================================================ UI 构建\n    def _build_ui(self) -> None:\n        root = QVBoxLayout(self)\n        root.setContentsMargins(0, 0, 0, 0)\n        root.setSpacing(6)\n\n        root.addLayout(self._build_toolbar())\n\n        self._table = QTableWidget(0, 4)\n        self._table.setHorizontalHeaderLabels(["启用", "类型", "参数", "备注"])\n        self._table.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)\n        self._table.setSelectionMode(QAbstractItemView.SelectionMode.ExtendedSelection)\n        self._table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)\n        self._table.setAlternatingRowColors(True)\n        self._table.verticalHeader().setVisible(False)\n        self._table.itemChanged.connect(self._on_item_changed)\n        self._table.doubleClicked.connect(lambda _index: self.edit_current())\n        self._table.itemSelectionChanged.connect(self._sync_buttons)\n\n        header = self._table.horizontalHeader()\n        header.setSectionResizeMode(COL_ENABLED, QHeaderView.ResizeMode.Fixed)\n        header.setSectionResizeMode(COL_KIND, QHeaderView.ResizeMode.Fixed)\n        header.setSectionResizeMode(COL_SUMMARY, QHeaderView.ResizeMode.Stretch)\n        header.setSectionResizeMode(COL_NOTE, QHeaderView.ResizeMode.Interactive)\n        self._table.setColumnWidth(COL_ENABLED, 48)\n        self._table.setColumnWidth(COL_KIND, 56)\n        self._table.setColumnWidth(COL_NOTE, 150)\n\n        root.addWidget(self._table, 1)\n\n    def _build_toolbar(self) -> QHBoxLayout:\n        bar = QHBoxLayout()\n        bar.setSpacing(6)\n\n        self._add_click_button = QPushButton("+ 点击")\n        self._add_click_button.clicked.connect(lambda: self.add_step(StepKind.CLICK))\n        self._add_delay_button = QPushButton("+ 延时")\n        self._add_delay_button.clicked.connect(lambda: self.add_step(StepKind.DELAY))\n        self._add_key_button = QPushButton("+ 按键")\n        self._add_key_button.clicked.connect(lambda: self.add_step(StepKind.KEY))\n        self._add_move_button = QPushButton("+ 移动")\n        self._add_move_button.clicked.connect(lambda: self.add_step(StepKind.MOVE))\n        self._add_wait_button = QPushButton("+ 找图")\n        self._add_wait_button.setToolTip(\n            "等屏幕上出现某张图片再继续（等弹窗、等按钮亮起）。\\n"\n            "可以顺手点一下找到的位置，超时就按设置的策略处理。"\n        )\n        self._add_wait_button.clicked.connect(lambda: self.add_step(StepKind.WAIT))\n\n        self._edit_button = QPushButton("编辑")\n        self._edit_button.clicked.connect(self.edit_current)\n        self._remove_button = QPushButton("删除")\n        self._remove_button.clicked.connect(self.remove_selected)\n        self._up_button = QPushButton("↑")\n        self._up_button.setFixedWidth(34)\n        self._up_button.clicked.connect(lambda: self.move_selected(-1))\n        self._down_button = QPushButton("↓")\n        self._down_button.setFixedWidth(34)\n        self._down_button.clicked.connect(lambda: self.move_selected(1))\n\n        for widget in (\n            self._add_click_button,\n            self._add_delay_button,\n            self._add_key_button,\n            self._add_move_button,\n            self._add_wait_button,\n            self._edit_button,\n            self._remove_button,\n        ):\n            bar.addWidget(widget)\n        bar.addStretch(1)\n        bar.addWidget(self._up_button)\n        bar.addWidget(self._down_button)\n        return bar\n\n    # ================================================================ 步骤操作\n    def add_step(self, kind: StepKind) -> None:\n        """新增一个步骤，插入到当前行之后。"""\n        edited = self._open_dialog(self._make_default(kind))\n        if edited is None:\n            return\n\n        row = self.current_row()\n        insert_at = row + 1 if row >= 0 else len(self._steps)\n        self._steps.insert(insert_at, edited)\n        self._refresh()\n        self.select_row(insert_at)\n        self.changed.emit()\n\n    def edit_current(self) -> None:\n        row = self.current_row()\n        step = self.step_at(row)\n        if step is None:\n            return\n\n        edited = self._open_dialog(step)\n        if edited is None:\n            return\n\n        self._steps[row] = edited\n        self._refresh()\n        self.select_row(row)\n        self.changed.emit()\n\n    def remove_selected(self) -> None:\n        rows = sorted({index.row() for index in self._table.selectedIndexes()}, reverse=True)\n        if not rows:\n            return\n\n        if QMessageBox.question(\n            self,\n            "删除步骤",\n            f"确定删除选中的 {len(rows)} 个步骤吗？",\n            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,\n        ) != QMessageBox.StandardButton.Yes:\n            return\n\n        for row in rows:\n            if 0 <= row < len(self._steps):\n                del self._steps[row]\n\n        self._refresh()\n        if self._steps:\n            self.select_row(min(rows[-1], len(self._steps) - 1))\n        self.changed.emit()\n\n    def move_selected(self, delta: int) -> None:\n        row = self.current_row()\n        target = row + delta\n        if row < 0 or not (0 <= target < len(self._steps)):\n            return\n\n        self._steps[row], self._steps[target] = self._steps[target], self._steps[row]\n        self._refresh()\n        self.select_row(target)\n        self.changed.emit()\n\n    # ================================================================ 内部\n    def _make_default(self, kind: StepKind) -> Step:\n        if kind is StepKind.CLICK:\n            rect = virtual_screen_rect()\n            return ClickStep(\n                x=rect.x + rect.width // 2,\n                y=rect.y + rect.height // 2,\n                repeat=1,\n                interval_ms=200,\n            )\n        if kind is StepKind.DELAY:\n            return DelayStep(delay_ms=500)\n        if kind is StepKind.MOVE:\n            return MoveStep(points=[get_cursor_pos()], duration_ms=300)\n        if kind is StepKind.WAIT:\n            return WaitStep()\n        return KeyStep(vk=vk_of("F5") or 0, repeat=1, interval_ms=50)\n\n    def _open_dialog(self, step: Step) -> Step | None:\n        dialog = StepDialog(step, self._picker, self)\n        if dialog.exec() == QDialog.DialogCode.Accepted:\n            return dialog.result_step()\n        return None\n\n    def _refresh(self) -> None:\n        """按 ``self._steps`` 重建表格。"""\n        self._populating = True\n        try:\n            self._table.setRowCount(len(self._steps))\n            for row, step in enumerate(self._steps):\n                enabled_item = QTableWidgetItem()\n                enabled_item.setFlags(\n                    Qt.ItemFlag.ItemIsEnabled | Qt.ItemFlag.ItemIsSelectable | Qt.ItemFlag.ItemIsUserCheckable\n                )\n                enabled_item.setCheckState(\n                    Qt.CheckState.Checked if step.enabled else Qt.CheckState.Unchecked\n                )\n                enabled_item.setToolTip("取消勾选可临时跳过该步骤")\n                self._table.setItem(row, COL_ENABLED, enabled_item)\n\n                kind_item = QTableWidgetItem(step.kind.label)\n                color = _ROW_COLORS.get(step.kind)\n                if color:\n                    kind_item.setForeground(QColor(color))\n                self._table.setItem(row, COL_KIND, kind_item)\n\n                self._table.setItem(row, COL_SUMMARY, QTableWidgetItem(step.summary()))\n\n                note_item = QTableWidgetItem(step.note)\n                if not step.enabled:\n                    note_item.setToolTip("该步骤已被停用")\n                self._table.setItem(row, COL_NOTE, note_item)\n        finally:\n            self._populating = False\n\n        self._sync_buttons()\n\n    def _sync_buttons(self) -> None:\n        """按当前选择状态启用/禁用按钮。"""\n        rows = {index.row() for index in self._table.selectedIndexes()}\n        has_selection = bool(rows)\n        row = self.current_row()\n\n        self._edit_button.setEnabled(len(rows) == 1)\n        self._remove_button.setEnabled(has_selection)\n        self._up_button.setEnabled(len(rows) == 1 and row > 0)\n        self._down_button.setEnabled(len(rows) == 1 and 0 <= row < len(self._steps) - 1)\n\n    def _on_item_changed(self, item: QTableWidgetItem) -> None:\n        if self._populating:\n            return\n\n        row = item.row()\n        step = self.step_at(row)\n        if step is None:\n            return\n\n        if item.column() == COL_ENABLED:\n            step.enabled = item.checkState() == Qt.CheckState.Checked\n            self.changed.emit()\n        elif item.column() == COL_NOTE:\n            step.note = item.text()\n            self.changed.emit()\n',
    'app/ui/template_picker.py': '"""找图用的全屏拖框遮罩。\n\n和 ``position_picker`` 一样，交互走 **Qt 逻辑坐标**（画框、判位置），\n实际取值走 **Win32 物理坐标**（``GetCursorPos``），\n这样多显示器混合缩放下画得贴合、落库的又是 ``SendInput`` 要的物理像素。\n\n拖框期间遮罩是**半透明压暗**的，为了让用户看清要抠的位置；因此截取不能发生在\n松手的那一刻（会把遮罩自己也拍进去）。松手后由 ``PickCoordinator`` 负责\n「先彻底隐藏 → 等合成器重绘 → 再抓屏」，见 ``HIDE_SETTLE_MS``。\n"""\n\nfrom __future__ import annotations\n\nimport logging\n\nfrom PySide6.QtCore import QPoint, QRect, Qt, Signal\nfrom PySide6.QtGui import (\n    QColor,\n    QFont,\n    QFontMetrics,\n    QGuiApplication,\n    QPainter,\n    QPen,\n)\nfrom PySide6.QtWidgets import QWidget\n\nfrom ..win.geometry import ScreenRect, get_cursor_pos\n\nlogger = logging.getLogger(__name__)\n\n_OVERLAY_COLOR = QColor(0, 0, 0, 110)\n_SELECT_COLOR = QColor(0, 230, 150)\n_HINT_BG = QColor(20, 24, 32, 235)\n_HINT_TEXT = QColor(240, 245, 255)\n\n# 太小的框多半是误触，不当作有效模板\nMIN_TEMPLATE_PX = 8\n\n_HINT = "按住左键拖出一个框 · 右键/Esc 取消"\n\n\nclass TemplatePicker(QWidget):\n    """全屏拖框遮罩。松手后给出**物理像素**矩形。"""\n\n    selected = Signal(object)  # ScreenRect\n    canceled = Signal()\n\n    def __init__(self, parent: QWidget | None = None) -> None:\n        super().__init__(parent)\n        self.setWindowFlags(\n            Qt.WindowType.FramelessWindowHint\n            | Qt.WindowType.WindowStaysOnTopHint\n            | Qt.WindowType.Tool\n            | Qt.WindowType.NoDropShadowWindowHint\n        )\n        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)\n        self.setCursor(Qt.CursorShape.CrossCursor)\n        self.setMouseTracking(True)\n        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)\n\n        self._active = False\n        self._resolved = False\n        self._dragging = False\n        self._start_local: QPoint | None = None\n        self._local: QPoint | None = None\n        self._start_physical: tuple[int, int] | None = None\n        self._end_physical: tuple[int, int] | None = None\n        self._too_small = False\n\n    # ------------------------------------------------------------------ 接口\n    def start(self) -> None:\n        self._active = True\n        self._resolved = False\n        self._dragging = False\n        self._start_local = None\n        self._local = None\n        self._start_physical = None\n        self._end_physical = None\n        self._too_small = False\n\n        self._apply_geometry()\n        self.show()\n        self.raise_()\n        self.activateWindow()\n        self.setFocus(Qt.FocusReason.OtherFocusReason)\n        self.grabKeyboard()\n        self.update()\n\n    def cancel(self) -> None:\n        """外部请求取消，等价于按 Esc。"""\n        if self._active:\n            self._resolve(self.canceled.emit)\n\n    # ------------------------------------------------------------------ 内部\n    def _apply_geometry(self) -> None:\n        desktop = QRect()\n        for screen in QGuiApplication.screens():\n            desktop = desktop.united(screen.geometry())\n        if desktop.isValid() and not desktop.isEmpty():\n            self.setGeometry(desktop)\n            return\n\n        primary = QGuiApplication.primaryScreen()  # pragma: no cover - 兜底\n        if primary is not None:\n            self.setGeometry(primary.virtualGeometry())\n\n    def _resolve(self, emit_action) -> None:\n        if self._resolved:\n            return\n        self._resolved = True\n        self._active = False\n        self._dragging = False\n        self.releaseKeyboard()\n        self.hide()\n        emit_action()\n\n    def selection(self) -> ScreenRect | None:\n        """当前框在**物理像素**下的矩形，无效时返回 ``None``。"""\n        if self._start_physical is None or self._end_physical is None:\n            return None\n        (ax, ay), (bx, by) = self._start_physical, self._end_physical\n        left, top = min(ax, bx), min(ay, by)\n        width, height = abs(bx - ax), abs(by - ay)\n        if width < MIN_TEMPLATE_PX or height < MIN_TEMPLATE_PX:\n            return None\n        return ScreenRect(left, top, width, height)\n\n    def _local_box(self) -> QRect | None:\n        if self._start_local is None or self._local is None:\n            return None\n        return QRect(self._start_local, self._local).normalized()\n\n    # ------------------------------------------------------------ Qt 事件\n    def mousePressEvent(self, event) -> None:  # noqa: N802 - Qt 命名\n        if event.button() == Qt.MouseButton.LeftButton:\n            self._dragging = True\n            self._too_small = False\n            self._start_local = event.position().toPoint()\n            self._local = self._start_local\n            self._start_physical = get_cursor_pos()\n            self._end_physical = self._start_physical\n            self.update()\n        elif event.button() == Qt.MouseButton.RightButton:\n            self._resolve(self.canceled.emit)\n\n    def mouseMoveEvent(self, event) -> None:  # noqa: N802\n        self._local = event.position().toPoint()\n        if self._dragging:\n            self._end_physical = get_cursor_pos()\n        self.update()\n\n    def mouseReleaseEvent(self, event) -> None:  # noqa: N802\n        if event.button() != Qt.MouseButton.LeftButton or not self._dragging:\n            return\n        self._dragging = False\n        self._end_physical = get_cursor_pos()\n        self._local = event.position().toPoint()\n\n        rect = self.selection()\n        if rect is None:\n            # 太小/没拖动：不清场，让用户直接重来一次\n            self._too_small = True\n            self._start_local = None\n            self._local = None\n            self._start_physical = None\n            self._end_physical = None\n            self.update()\n            return\n\n        logger.debug("模板选区（物理像素）: %s", rect)\n        self._resolve(lambda: self.selected.emit(rect))\n\n    def keyPressEvent(self, event) -> None:  # noqa: N802\n        if event.key() == Qt.Key.Key_Escape:\n            self._resolve(self.canceled.emit)\n        else:\n            super().keyPressEvent(event)\n\n    def closeEvent(self, event) -> None:  # noqa: N802\n        if self._active:\n            self._resolve(self.canceled.emit)\n        super().closeEvent(event)\n\n    # ------------------------------------------------------------------ 绘制\n    def paintEvent(self, event) -> None:  # noqa: N802\n        painter = QPainter(self)\n        painter.fillRect(self.rect(), _OVERLAY_COLOR)\n\n        box = self._local_box()\n        if box is not None and box.isValid():\n            # 把选区挖成完全透明，用户看到的就是真实像素\n            painter.setCompositionMode(QPainter.CompositionMode.CompositionMode_Clear)\n            painter.fillRect(box, Qt.GlobalColor.transparent)\n            painter.setCompositionMode(QPainter.CompositionMode.CompositionMode_SourceOver)\n\n            painter.setPen(QPen(_SELECT_COLOR, 2))\n            painter.setBrush(Qt.BrushStyle.NoBrush)\n            painter.drawRect(box.adjusted(1, 1, -1, -1))\n            self._paint_size(painter, box)\n\n        self._paint_hint(painter)\n        painter.end()\n\n    def _paint_size(self, painter: QPainter, box: QRect) -> None:\n        rect = self.selection()\n        text = f"{rect.width} × {rect.height}" if rect else "太小了"\n        font = QFont("Microsoft YaHei UI", 10)\n        painter.setFont(font)\n        metrics = QFontMetrics(font)\n        width = metrics.horizontalAdvance(text) + 16\n        height = metrics.height() + 8\n\n        bx = box.left()\n        by = box.bottom() + 6\n        if by + height > self.height():\n            by = box.top() - height - 6\n        bx = max(0, min(bx, self.width() - width))\n\n        painter.setPen(Qt.PenStyle.NoPen)\n        painter.setBrush(_HINT_BG)\n        painter.drawRoundedRect(bx, by, width, height, 6, 6)\n        painter.setPen(_SELECT_COLOR)\n        painter.drawText(\n            bx, by, width, height, int(Qt.AlignmentFlag.AlignCenter), text\n        )\n\n    def _paint_hint(self, painter: QPainter) -> None:\n        text = f"{_HINT}\\n框太小会重来（至少 {MIN_TEMPLATE_PX}×{MIN_TEMPLATE_PX} 像素）"\n        if self._too_small:\n            text = f"框太小了，请重新拖一个至少 {MIN_TEMPLATE_PX}×{MIN_TEMPLATE_PX} 的框\\n{_HINT}"\n        font = QFont("Microsoft YaHei UI", 11)\n        painter.setFont(font)\n        metrics = QFontMetrics(font)\n\n        lines = text.split("\\n")\n        width = max(metrics.horizontalAdvance(line) for line in lines) + 28\n        height = metrics.height() * len(lines) + 18\n\n        anchor = self._local or QPoint(0, 0)\n        bx, by = anchor.x() + 26, anchor.y() + 26\n        if bx + width > self.width():\n            bx = anchor.x() - width - 26\n        if by + height > self.height():\n            by = anchor.y() - height - 26\n        bx, by = max(0, bx), max(0, by)\n\n        painter.setPen(Qt.PenStyle.NoPen)\n        painter.setBrush(_HINT_BG)\n        painter.drawRoundedRect(bx, by, width, height, 8, 8)\n        painter.setPen(_HINT_TEXT)\n        painter.drawText(\n            bx + 14,\n            by + 9,\n            width - 28,\n            height - 18,\n            int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter),\n            text,\n        )\n',
    'app/ui/tray_icon.py': '"""系统托盘。\n\n托盘不可用时（远程桌面、精简系统）整个对象退化成空壳：``available`` 为 False，\n``notify`` / ``hide`` 什么也不做。这样调用方不需要在每处都判空，MainWindow 的\n``closeEvent`` 也只需要问一句「有托盘吗」。\n\n托盘菜单只负责把动作**转成信号**抛出去，具体做什么由 MainWindow 决定——\n菜单项和热键因此收敛到同一批入口，不会出现两套行为。\n"""\n\nfrom __future__ import annotations\n\nimport logging\n\nfrom PySide6.QtCore import QObject, Signal, Slot\nfrom PySide6.QtGui import QAction\nfrom PySide6.QtWidgets import QMenu, QSystemTrayIcon, QWidget\n\nfrom .icon import app_icon\n\nlogger = logging.getLogger(__name__)\n\nDEFAULT_TITLE = "AutoClicker"\nDEFAULT_MSEC = 3000\n\n\nclass TrayIcon(QObject):\n    """托盘图标 + 右键菜单。"""\n\n    restore_requested = Signal()\n    start_requested = Signal()\n    stop_requested = Signal()\n    pick_requested = Signal()\n    record_toggle_requested = Signal()\n    quit_requested = Signal()\n\n    def __init__(self, parent: QWidget) -> None:\n        super().__init__(parent)\n        self._tray: QSystemTrayIcon | None = None\n        # setContextMenu **不接管** menu 的所有权，必须自己持有引用，\n        # 否则菜单会被 Python 回收，托盘右键变成空白。\n        self._menu: QMenu | None = None\n        self._notified: set[str] = set()\n\n        if not QSystemTrayIcon.isSystemTrayAvailable():\n            logger.warning("系统托盘不可用，关闭窗口将直接退出")\n            return\n\n        tray = QSystemTrayIcon(app_icon(), parent)\n        tray.setToolTip("AutoClicker · 自动点击器")\n\n        menu = QMenu(parent)\n        for text, signal in (\n            ("显示主窗口", self.restore_requested),\n            (None, None),\n            ("开始点击 (F9)", self.start_requested),\n            ("停止 (F10)", self.stop_requested),\n            ("拾取坐标 (F8)", self.pick_requested),\n            ("开始/结束录制 (F11)", self.record_toggle_requested),\n            (None, None),\n            ("退出", self.quit_requested),\n        ):\n            if text is None:\n                menu.addSeparator()\n                continue\n            action = QAction(text, menu)\n            action.triggered.connect(self._relay(signal))\n            menu.addAction(action)\n\n        tray.setContextMenu(menu)\n        tray.activated.connect(self._on_activated)\n        tray.show()\n        self._tray = tray\n        self._menu = menu\n\n    def actions(self) -> list[QAction]:\n        """右键菜单项，跳过分隔线。给测试用。"""\n        return [] if self._menu is None else [a for a in self._menu.actions() if not a.isSeparator()]\n\n    # ---------------------------------------------------------------- 状态\n    @property\n    def available(self) -> bool:\n        return self._tray is not None\n\n    def hide(self) -> None:\n        if self._tray is not None:\n            self._tray.hide()\n\n    # ---------------------------------------------------------------- 提示\n    def notify(self, message: str, title: str = DEFAULT_TITLE, msec: int = DEFAULT_MSEC) -> None:\n        """弹一个托盘气泡。没有托盘时静默忽略。"""\n        if self._tray is None:\n            return\n        self._tray.showMessage(title, message, QSystemTrayIcon.MessageIcon.Information, msec)\n\n    def notify_once(\n        self,\n        key: str,\n        message: str,\n        title: str = DEFAULT_TITLE,\n        msec: int = 4000,\n    ) -> None:\n        """同一条提示只弹一次（例如「已最小化到托盘」）。``key`` 是去重标识。"""\n        if key in self._notified:\n            return\n        self._notified.add(key)\n        self.notify(message, title, msec)\n\n    # ---------------------------------------------------------------- 内部\n    @staticmethod\n    def _relay(signal):\n        """``QAction.triggered`` 会捎带一个 checked 参数，这里丢掉它再转发。"""\n        return lambda *_args: signal.emit()\n\n    @Slot(QSystemTrayIcon.ActivationReason)\n    def _on_activated(self, reason: QSystemTrayIcon.ActivationReason) -> None:\n        if reason in (\n            QSystemTrayIcon.ActivationReason.DoubleClick,\n            QSystemTrayIcon.ActivationReason.Trigger,\n        ):\n            self.restore_requested.emit()\n',
    'app/utils/__init__.py': '',
    'app/utils/logger.py': '"""日志初始化。\n\n两路输出：\n- 文件：``%LOCALAPPDATA%\\\\AutoClicker\\\\logs\\\\autoclicker.log``，滚动保留；\n- UI：通过 ``SignalLogHandler`` 转发到主窗口的日志面板。\n\n``SignalLogHandler`` 可能在任意线程被调用，依赖 Qt 跨线程信号自动排队（queued connection）机制，\n因此是线程安全的。\n"""\n\nfrom __future__ import annotations\n\nimport logging\nimport os\nimport sys\nfrom logging.handlers import RotatingFileHandler\nfrom pathlib import Path\nfrom typing import Callable\n\nLOG_FORMAT = "%(asctime)s [%(levelname)-7s] %(name)s: %(message)s"\nUI_LOG_FORMAT = "%(asctime)s [%(levelname)s] %(message)s"\nDATE_FORMAT = "%H:%M:%S"\n\n_configured = False\n\n\ndef app_data_dir() -> Path:\n    """返回可写的应用数据目录。"""\n    base = os.environ.get("LOCALAPPDATA")\n    root = Path(base) if base else Path.home() / "AppData" / "Local"\n    return root / "AutoClicker"\n\n\ndef log_dir() -> Path:\n    return app_data_dir() / "logs"\n\n\nclass SignalLogHandler(logging.Handler):\n    """把日志记录转发给一个可调用对象（通常绑定到 Qt 信号的 ``emit``）。"""\n\n    def __init__(self, sink: Callable[[str], None], level: int = logging.INFO) -> None:\n        super().__init__(level)\n        self._sink = sink\n        self.setFormatter(logging.Formatter(UI_LOG_FORMAT, DATE_FORMAT))\n\n    def emit(self, record: logging.LogRecord) -> None:\n        try:\n            self._sink(self.format(record))\n        except Exception:  # pragma: no cover - 日志本身绝不能再抛异常\n            self.handleError(record)\n\n\ndef setup_logging(level: int = logging.INFO) -> logging.Logger:\n    """配置根日志器，返回应用日志器。重复调用是幂等的。"""\n    global _configured\n\n    root = logging.getLogger()\n    if _configured:\n        return logging.getLogger("autoclicker")\n\n    root.setLevel(logging.DEBUG)\n\n    # 文件输出\n    try:\n        directory = log_dir()\n        directory.mkdir(parents=True, exist_ok=True)\n        file_handler = RotatingFileHandler(\n            directory / "autoclicker.log",\n            maxBytes=1_000_000,\n            backupCount=3,\n            encoding="utf-8",\n        )\n        file_handler.setLevel(logging.DEBUG)\n        file_handler.setFormatter(logging.Formatter(LOG_FORMAT))\n        root.addHandler(file_handler)\n    except OSError as exc:  # pragma: no cover - 目录不可写时降级\n        print(f"警告: 无法创建日志文件 ({exc})", file=sys.stderr)\n\n    # 控制台输出（源码运行时方便排查）\n    if not getattr(sys, "frozen", False):\n        console = logging.StreamHandler(sys.stderr)\n        console.setLevel(level)\n        console.setFormatter(logging.Formatter(LOG_FORMAT, DATE_FORMAT))\n        root.addHandler(console)\n\n    _configured = True\n    return logging.getLogger("autoclicker")\n',
    'app/win/__init__.py': '"""Windows 平台适配层：DPI、权限、单实例、全局热键、坐标。"""\n',
    'app/win/admin.py': '"""权限检测与提权。\n\nUIPI（用户界面特权隔离）会拦截低完整性级别进程向高完整性级别进程注入的输入。\n因此当目标程序以管理员身份运行时，本工具也必须以管理员身份运行，否则点击会被静默丢弃。\n"""\n\nfrom __future__ import annotations\n\nimport ctypes\nimport logging\nimport sys\n\nlogger = logging.getLogger(__name__)\n\n\ndef is_admin() -> bool:\n    """当前进程是否以管理员身份运行。"""\n    try:\n        return bool(ctypes.windll.shell32.IsUserAnAdmin())\n    except OSError:  # pragma: no cover\n        return False\n\n\ndef _launch_command() -> tuple[str, str]:\n    """构造用于提权重启的可执行文件与参数。"""\n    if getattr(sys, "frozen", False):\n        exe = sys.executable\n        args = sys.argv[1:]\n    else:\n        exe = sys.executable\n        args = sys.argv\n    params = " ".join(f\'"{a}"\' for a in args)\n    return exe, params\n\n\ndef relaunch_as_admin() -> bool:\n    """以管理员身份重新启动当前程序。成功触发 UAC 时返回 True。\n\n    注意：本函数不会退出当前进程，调用方需要在返回 True 后自行退出。\n    """\n    exe, params = _launch_command()\n    try:\n        ret = ctypes.windll.shell32.ShellExecuteW(None, "runas", exe, params, None, 1)\n    except OSError as exc:  # pragma: no cover\n        logger.error("提权启动失败: %s", exc)\n        return False\n    # ShellExecuteW 返回值 > 32 表示成功；5 表示用户拒绝了 UAC\n    return int(ret) > 32\n',
    'app/win/dpi.py': '"""DPI 感知设置。\n\n必须在创建任何窗口（包括 QApplication）之前调用 ``enable_dpi_awareness()``。\n否则 Windows 会对坐标做 DPI 虚拟化，导致点击位置出现比例偏移。\n\n本模块只依赖标准库 ``ctypes``。\n"""\n\nfrom __future__ import annotations\n\nimport ctypes\nimport logging\n\nlogger = logging.getLogger(__name__)\n\n# 伪句柄：SetProcessDpiAwarenessContext 接受负值作为“上下文”\nDPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2 = ctypes.c_void_p(-4)\nDPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V1 = ctypes.c_void_p(-3)\nDPI_AWARENESS_CONTEXT_SYSTEM_AWARE = ctypes.c_void_p(-2)\n\n# shcore.SetProcessDpiAwareness 的枚举值\nPROCESS_DPI_UNAWARE = 0\nPROCESS_SYSTEM_DPI_AWARE = 1\nPROCESS_PER_MONITOR_DPI_AWARE = 2\n\nS_OK = 0\n\n_awareness: str | None = None\n\n\ndef enable_dpi_awareness() -> str:\n    """按优先级尝试设置进程 DPI 感知级别，返回实际生效的级别。\n\n    返回值为 ``"per-monitor-v2"`` / ``"per-monitor"`` / ``"system"`` / ``"none"``。\n    重复调用是安全的（第二次会因权限被拒而返回上一次的结果）。\n    """\n    global _awareness\n    if _awareness is not None:\n        return _awareness\n\n    user32 = ctypes.windll.user32\n\n    # Windows 10 1703+：首选 Per-Monitor V2，它同时解决多屏不同缩放的问题\n    set_ctx = getattr(user32, "SetProcessDpiAwarenessContext", None)\n    if set_ctx is not None:\n        set_ctx.argtypes = [ctypes.c_void_p]\n        set_ctx.restype = ctypes.c_bool\n        try:\n            if set_ctx(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2):\n                _awareness = "per-monitor-v2"\n                logger.info("DPI 感知级别: Per-Monitor V2")\n                return _awareness\n        except OSError:  # pragma: no cover - 仅在异常系统上触发\n            pass\n\n    # Windows 8.1+\n    try:\n        shcore = ctypes.windll.shcore\n        shcore.SetProcessDpiAwareness.argtypes = [ctypes.c_int]\n        shcore.SetProcessDpiAwareness.restype = ctypes.c_long\n        if shcore.SetProcessDpiAwareness(PROCESS_PER_MONITOR_DPI_AWARE) == S_OK:\n            _awareness = "per-monitor"\n            logger.info("DPI 感知级别: Per-Monitor")\n            return _awareness\n    except OSError:  # pragma: no cover\n        pass\n\n    # Vista+\n    try:\n        if user32.SetProcessDPIAware():\n            _awareness = "system"\n            logger.info("DPI 感知级别: System")\n            return _awareness\n    except OSError:  # pragma: no cover\n        pass\n\n    _awareness = "none"\n    logger.warning("无法设置 DPI 感知，坐标可能出现缩放偏移")\n    return _awareness\n\n\ndef current_awareness() -> str | None:\n    """返回已生效的 DPI 感知级别，未设置时返回 ``None``。"""\n    return _awareness\n',
    'app/win/geometry.py': '"""坐标与屏幕几何。\n\n全项目统一使用 **虚拟屏幕物理像素坐标**：\n- 原点在虚拟桌面左上角，多显示器时可能是负数；\n- 单位是物理像素（因为入口已声明 Per-Monitor V2 DPI 感知）。\n"""\n\nfrom __future__ import annotations\n\nimport ctypes\nimport ctypes.wintypes as wintypes\nfrom dataclasses import dataclass\n\n# GetSystemMetrics 索引\nSM_XVIRTUALSCREEN = 76\nSM_YVIRTUALSCREEN = 77\nSM_CXVIRTUALSCREEN = 78\nSM_CYVIRTUALSCREEN = 79\n\n_user32 = ctypes.windll.user32\n\n\n@dataclass(frozen=True)\nclass ScreenRect:\n    """虚拟桌面矩形（物理像素）。"""\n\n    x: int\n    y: int\n    width: int\n    height: int\n\n    @property\n    def right(self) -> int:\n        return self.x + self.width\n\n    @property\n    def bottom(self) -> int:\n        return self.y + self.height\n\n    def contains(self, x: int, y: int) -> bool:\n        return self.x <= x < self.right and self.y <= y < self.bottom\n\n    def __str__(self) -> str:  # pragma: no cover - 仅用于日志\n        return f"({self.x}, {self.y}, {self.width}x{self.height})"\n\n\ndef virtual_screen_rect() -> ScreenRect:\n    """返回覆盖全部显示器的虚拟桌面矩形。"""\n    return ScreenRect(\n        x=_user32.GetSystemMetrics(SM_XVIRTUALSCREEN),\n        y=_user32.GetSystemMetrics(SM_YVIRTUALSCREEN),\n        width=_user32.GetSystemMetrics(SM_CXVIRTUALSCREEN),\n        height=_user32.GetSystemMetrics(SM_CYVIRTUALSCREEN),\n    )\n\n\ndef get_cursor_pos() -> tuple[int, int]:\n    """获取当前鼠标位置（虚拟屏幕物理像素）。"""\n    point = wintypes.POINT()\n    if not _user32.GetCursorPos(ctypes.byref(point)):\n        return 0, 0\n    return int(point.x), int(point.y)\n\n\ndef set_cursor_pos(x: int, y: int) -> bool:\n    """直接设置鼠标位置（不产生点击）。"""\n    return bool(_user32.SetCursorPos(int(x), int(y)))\n',
    'app/win/hooks.py': '"""全局输入录制（Win32 低级钩子）。\n\n方案选择\n--------\n用 ``WH_MOUSE_LL`` + ``WH_KEYBOARD_LL`` 低级钩子，而不是：\n\n- ``WH_JOURNALRECORD``：Vista 之后对非提权进程基本失效，已废弃；\n- ``GetAsyncKeyState`` 轮询：拿不到精确时序，也无法屏蔽事件；\n- 第三方库（``pynput`` / ``keyboard``）：底层还是同一套钩子，白白多一层依赖。\n\n低级钩子**不会注入到其它进程**，回调在「安装钩子的那个线程」上通过消息队列被调用，\n所以只需要普通消息循环，不需要写 DLL。Qt 主线程正好在跑消息循环。\n\n三条必须遵守的约束\n------------------\n1. **回调必须极快**。Windows 有 ``LowLevelHooksTimeout``（默认 300ms），\n   回调超时会被系统静默摘掉钩子。因此这里只做「追加一条记录」，其它什么都不干。\n2. **必须忽略注入事件**（``LLMHF_INJECTED`` / ``LLKHF_INJECTED``），\n   否则会录到本工具自己回放的动作，也可能和其它自动化工具互相打架。\n3. **必须持有 HOOKPROC 的引用**。回调是 ctypes 闭包，一旦被 GC，\n   系统回调到野指针会直接崩掉进程。\n"""\n\nfrom __future__ import annotations\n\nimport ctypes\nimport ctypes.wintypes as wintypes\nimport logging\nimport time\nfrom dataclasses import dataclass\n\nlogger = logging.getLogger(__name__)\n\nULONG_PTR = ctypes.c_ulonglong if ctypes.sizeof(ctypes.c_void_p) == 8 else ctypes.c_ulong\n\n# ---------------------------------------------------------------- 常量\nWH_KEYBOARD_LL = 13\nWH_MOUSE_LL = 14\n\nWM_MOUSEMOVE = 0x0200\nWM_LBUTTONDOWN = 0x0201\nWM_LBUTTONUP = 0x0202\nWM_RBUTTONDOWN = 0x0204\nWM_RBUTTONUP = 0x0205\nWM_MBUTTONDOWN = 0x0207\nWM_MBUTTONUP = 0x0208\nWM_MOUSEWHEEL = 0x020A\nWM_XBUTTONDOWN = 0x020B\nWM_XBUTTONUP = 0x020C\n\nWM_KEYDOWN = 0x0100\nWM_KEYUP = 0x0101\nWM_SYSKEYDOWN = 0x0104\nWM_SYSKEYUP = 0x0105\n\nLLMHF_INJECTED = 0x00000001\nLLKHF_INJECTED = 0x00000010\n\n_BUTTON_DOWN = {\n    WM_LBUTTONDOWN: "left",\n    WM_RBUTTONDOWN: "right",\n    WM_MBUTTONDOWN: "middle",\n}\n_BUTTON_UP = {\n    WM_LBUTTONUP: "left",\n    WM_RBUTTONUP: "right",\n    WM_MBUTTONUP: "middle",\n}\n_KEY_DOWN = (WM_KEYDOWN, WM_SYSKEYDOWN)\n_KEY_UP = (WM_KEYUP, WM_SYSKEYUP)\n\n\n# ---------------------------------------------------------------- 结构体\nclass MSLLHOOKSTRUCT(ctypes.Structure):\n    _fields_ = [\n        ("pt", wintypes.POINT),\n        ("mouseData", wintypes.DWORD),\n        ("flags", wintypes.DWORD),\n        ("time", wintypes.DWORD),\n        ("dwExtraInfo", ULONG_PTR),\n    ]\n\n\nclass KBDLLHOOKSTRUCT(ctypes.Structure):\n    _fields_ = [\n        ("vkCode", wintypes.DWORD),\n        ("scanCode", wintypes.DWORD),\n        ("flags", wintypes.DWORD),\n        ("time", wintypes.DWORD),\n        ("dwExtraInfo", ULONG_PTR),\n    ]\n\n\nHOOKPROC = ctypes.WINFUNCTYPE(ctypes.c_ssize_t, ctypes.c_int, wintypes.WPARAM, wintypes.LPARAM)\n\n_user32 = ctypes.WinDLL("user32", use_last_error=True)\n_kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)\n\n_user32.SetWindowsHookExW.argtypes = (ctypes.c_int, HOOKPROC, wintypes.HINSTANCE, wintypes.DWORD)\n_user32.SetWindowsHookExW.restype = wintypes.HHOOK\n_user32.UnhookWindowsHookEx.argtypes = (wintypes.HHOOK,)\n_user32.UnhookWindowsHookEx.restype = wintypes.BOOL\n_user32.CallNextHookEx.argtypes = (wintypes.HHOOK, ctypes.c_int, wintypes.WPARAM, wintypes.LPARAM)\n_user32.CallNextHookEx.restype = ctypes.c_ssize_t\n_kernel32.GetModuleHandleW.argtypes = (wintypes.LPCWSTR,)\n_kernel32.GetModuleHandleW.restype = wintypes.HMODULE\n\n\n# ---------------------------------------------------------------- 事件\n@dataclass(frozen=True)\nclass InputEvent:\n    """一条原始输入事件。时间戳来自单调时钟，仅用于计算相邻间隔。"""\n\n    kind: str  # "move" | "click" | "key"\n    time: float\n    x: int = 0\n    y: int = 0\n    button: str = ""\n    vk: int = 0\n    is_down: bool = True\n\n\nclass InputRecorder:\n    """全局鼠标/键盘录制器。\n\n    线程说明：低级钩子的回调始终在**安装钩子的线程**上执行（即 Qt 主线程），\n    所以 ``_events`` 的写入和 ``stop()`` 的读取天然串行，不需要加锁。\n    """\n\n    def __init__(self) -> None:\n        self._events: list[InputEvent] = []\n        self._recording = False\n        self._swallow = True\n        self._passthrough_vks: set[int] = set()\n        self._keys_held: set[int] = set()\n        self._action_count = 0\n        self._move_count = 0\n\n        self._mouse_hook: int | None = None\n        self._key_hook: int | None = None\n        # 必须持有引用，否则 ctypes 回调被 GC 后系统回调会踩空指针\n        self._mouse_proc: HOOKPROC | None = None\n        self._key_proc: HOOKPROC | None = None\n\n    # ---------------------------------------------------------------- 状态\n    @property\n    def recording(self) -> bool:\n        return self._recording\n\n    @property\n    def swallow(self) -> bool:\n        return self._swallow\n\n    @property\n    def action_count(self) -> int:\n        """已记录的有效动作数（点击 + 按键），不含鼠标移动。"""\n        return self._action_count\n\n    @property\n    def move_count(self) -> int:\n        return self._move_count\n\n    @property\n    def event_count(self) -> int:\n        return len(self._events)\n\n    # ---------------------------------------------------------------- 生命周期\n    def start(self, swallow: bool = True, passthrough_vks=()) -> bool:\n        """开始录制。返回是否成功安装钩子。\n\n        ``swallow=True`` 时会屏蔽鼠标与键盘事件，使其不再传给任何程序，\n        因此录制过程不会真的点到东西；代价是必须靠全局热键才能结束录制\n        （调用方要先确认该热键注册成功，见 ``MainWindow._start_recording``）。\n\n        ``passthrough_vks`` 里的键不屏蔽，好让 ``RegisterHotKey`` 能收到\n        ——被低级钩子拦掉的按键永远不会进入热键分发流程。\n        """\n        if self._recording:\n            return False\n\n        self._events.clear()\n        self._keys_held.clear()\n        self._action_count = 0\n        self._move_count = 0\n        self._swallow = bool(swallow)\n        self._passthrough_vks = {int(vk) for vk in passthrough_vks}\n\n        self._mouse_proc = HOOKPROC(self._mouse_hook_proc)\n        self._key_proc = HOOKPROC(self._key_hook_proc)\n\n        module = _kernel32.GetModuleHandleW(None)\n        self._mouse_hook = _user32.SetWindowsHookExW(WH_MOUSE_LL, self._mouse_proc, module, 0)\n        self._key_hook = _user32.SetWindowsHookExW(WH_KEYBOARD_LL, self._key_proc, module, 0)\n\n        if not self._mouse_hook or not self._key_hook:\n            logger.error(\n                "安装输入钩子失败: mouse=%s key=%s GetLastError=%s",\n                self._mouse_hook,\n                self._key_hook,\n                ctypes.get_last_error(),\n            )\n            self._unhook()\n            return False\n\n        self._recording = True\n        logger.info("开始录制（屏蔽输入=%s）", self._swallow)\n        return True\n\n    def stop(self) -> list[InputEvent]:\n        """结束录制并返回采集到的事件。"""\n        if self._recording:\n            logger.info(\n                "结束录制: 动作 %s 个, 移动采样 %s 条", self._action_count, self._move_count\n            )\n        self._recording = False\n        self._unhook()\n        return list(self._events)\n\n    @property\n    def events(self) -> list[InputEvent]:\n        return list(self._events)\n\n    def _unhook(self) -> None:\n        for attribute in ("_mouse_hook", "_key_hook"):\n            handle = getattr(self, attribute)\n            if handle:\n                _user32.UnhookWindowsHookEx(handle)\n                setattr(self, attribute, None)\n        # 已摘钩，回调不再会被调用，可以安全释放\n        self._mouse_proc = None\n        self._key_proc = None\n\n    # ---------------------------------------------------------------- 钩子回调\n    # 回调结构：先判断要不要处理，再「尽力记录」（失败只记日志），最后统一决定是否吃掉事件。\n    # 这样即使记录逻辑炸了，「录制期间不会误点到东西」这条保证依然成立。\n    def _mouse_hook_proc(self, n_code, w_param, l_param):  # noqa: N802 - Win32 命名\n        if n_code < 0 or not self._recording:\n            return _user32.CallNextHookEx(None, n_code, w_param, l_param)\n\n        message = int(w_param)\n        injected = False\n        try:\n            info = ctypes.cast(l_param, ctypes.POINTER(MSLLHOOKSTRUCT)).contents\n            injected = bool(info.flags & LLMHF_INJECTED)\n            if not injected:\n                self._handle_mouse(message, int(info.pt.x), int(info.pt.y))\n        except Exception:  # noqa: BLE001 - 钩子里绝不能抛异常\n            logger.exception("鼠标钩子回调出错")\n\n        if self._swallow and not injected:\n            return 1\n        return _user32.CallNextHookEx(None, n_code, w_param, l_param)\n\n    def _key_hook_proc(self, n_code, w_param, l_param):  # noqa: N802 - Win32 命名\n        if n_code < 0 or not self._recording:\n            return _user32.CallNextHookEx(None, n_code, w_param, l_param)\n\n        message = int(w_param)\n        injected = False\n        control_key = False\n        try:\n            info = ctypes.cast(l_param, ctypes.POINTER(KBDLLHOOKSTRUCT)).contents\n            vk = int(info.vkCode)\n            injected = bool(info.flags & LLKHF_INJECTED)\n            control_key = vk in self._passthrough_vks\n            if not injected:\n                self._handle_key(message, vk)\n        except Exception:  # noqa: BLE001\n            logger.exception("键盘钩子回调出错")\n\n        if self._swallow and not injected and not control_key:\n            return 1\n        return _user32.CallNextHookEx(None, n_code, w_param, l_param)\n\n    # ---------------------------------------------------------------- 记录\n    def _handle_mouse(self, message: int, x: int, y: int) -> None:\n        if message == WM_MOUSEMOVE:\n            self._move_count += 1\n            self._events.append(InputEvent("move", time.perf_counter(), x=x, y=y))\n            return\n\n        button = _BUTTON_DOWN.get(message)\n        if button is not None:\n            self._action_count += 1\n            self._events.append(\n                InputEvent("click", time.perf_counter(), x=x, y=y, button=button, is_down=True)\n            )\n            return\n\n        # 抬起事件不单独记录：位置取按下的那一刻，时序用父动作的结束时间表示\n        if message in _BUTTON_UP:\n            self._events.append(\n                InputEvent(\n                    "click",\n                    time.perf_counter(),\n                    x=x,\n                    y=y,\n                    button=_BUTTON_UP[message],\n                    is_down=False,\n                )\n            )\n\n    def _handle_key(self, message: int, vk: int) -> None:\n        # 控制热键（F8/F9/F10/F11）是「操作工具」用的，不是用户宏的一部分，\n        # 混进录制结果里会出现「回放到一半自己按 F10 停掉」这种荒唐情况。\n        if vk in self._passthrough_vks:\n            return\n\n        if message in _KEY_DOWN:\n            # 长按会持续产生 WM_KEYDOWN，只记第一次\n            if vk in self._keys_held:\n                return\n            self._keys_held.add(vk)\n            self._action_count += 1\n            self._events.append(InputEvent("key", time.perf_counter(), vk=vk, is_down=True))\n        elif message in _KEY_UP:\n            if vk not in self._keys_held:\n                return\n            self._keys_held.discard(vk)\n            self._events.append(InputEvent("key", time.perf_counter(), vk=vk, is_down=False))\n',
    'app/win/hotkey.py': '"""全局热键。\n\n使用 Win32 ``RegisterHotKey`` + ``QAbstractNativeEventFilter`` 拦截 ``WM_HOTKEY``。\n\n选择这套方案而不是键盘钩子（``SetWindowsHookEx`` / 第三方 ``keyboard`` 库）的原因：\n- 不需要注入 DLL、不拦截全局按键流，被安全软件误报的概率低得多；\n- 系统级注册，窗口失焦时依然生效；\n- 无第三方依赖。\n\n限制：热键组合会被系统独占，注册失败说明已被其他程序占用，需要提示用户改键。\n"""\n\nfrom __future__ import annotations\n\nimport ctypes\nimport ctypes.wintypes as wintypes\nimport logging\n\nfrom PySide6.QtCore import QAbstractNativeEventFilter, QObject, Signal\n\nlogger = logging.getLogger(__name__)\n\nWM_HOTKEY = 0x0312\n\nMOD_ALT = 0x0001\nMOD_CONTROL = 0x0002\nMOD_SHIFT = 0x0004\nMOD_WIN = 0x0008\nMOD_NOREPEAT = 0x4000\n\n# 常用虚拟键码\nVK_CODES: dict[str, int] = {\n    "BACKSPACE": 0x08,\n    "TAB": 0x09,\n    "ENTER": 0x0D,\n    "SHIFT": 0x10,\n    "CTRL": 0x11,\n    "ALT": 0x12,\n    "PAUSE": 0x13,\n    "CAPSLOCK": 0x14,\n    "ESC": 0x1B,\n    "SPACE": 0x20,\n    "PAGEUP": 0x21,\n    "PAGEDOWN": 0x22,\n    "END": 0x23,\n    "HOME": 0x24,\n    "LEFT": 0x25,\n    "UP": 0x26,\n    "RIGHT": 0x27,\n    "DOWN": 0x28,\n    "INSERT": 0x2D,\n    "DELETE": 0x2E,\n}\nVK_CODES.update({f"F{i}": 0x6F + i for i in range(1, 25)})  # F1=0x70 ... F24=0x87\nVK_CODES.update({f"NUM{i}": 0x60 + i for i in range(10)})  # 小键盘\nVK_CODES.update({str(i): 0x30 + i for i in range(10)})  # 主键盘数字\nVK_CODES.update({chr(c): c for c in range(0x41, 0x5B)})  # A-Z\n\n\ndef vk_of(name: str) -> int | None:\n    """把 ``"F9"`` / ``"A"`` 之类的名字转成虚拟键码。"""\n    return VK_CODES.get(name.strip().upper())\n\n\ndef name_of_vk(vk: int) -> str:\n    """虚拟键码 → 展示用名字。查不到时返回 ``0xNN``。"""\n    return _VK_NAMES.get(int(vk), f"0x{int(vk):02X}")\n\n\ndef vk_names() -> list[str]:\n    """供下拉框使用的按键名列表（常用键优先）。"""\n    return list(_VK_ORDER)\n\n\n# 供下拉框使用的有序列表：功能键 → 字母 → 数字 → 其余\n_F_KEYS = [f"F{i}" for i in range(1, 25)]\n_VK_ORDER: list[str] = list(\n    dict.fromkeys(_F_KEYS + [chr(c) for c in range(0x41, 0x5B)] + [str(i) for i in range(10)] + list(VK_CODES))\n)\n_VK_NAMES: dict[int, str] = {code: name for name, code in VK_CODES.items()}\n\n\nclass _MSG(ctypes.Structure):\n    _fields_ = [\n        ("hwnd", wintypes.HWND),\n        ("message", wintypes.UINT),\n        ("wParam", wintypes.WPARAM),\n        ("lParam", wintypes.LPARAM),\n        ("time", wintypes.DWORD),\n        ("pt", wintypes.POINT),\n    ]\n\n\nclass HotkeyManager(QObject, QAbstractNativeEventFilter):\n    """全局热键管理器。\n\n    必须在 ``QApplication`` 创建之后实例化，并把对象保持存活（否则会被 GC）。\n    """\n\n    activated = Signal(int)  # 参数为注册时使用的 hotkey id\n\n    def __init__(self, parent: QObject | None = None) -> None:\n        QObject.__init__(self, parent)\n        QAbstractNativeEventFilter.__init__(self)\n        self._registered: dict[int, int] = {}\n        self._next_id = 1\n        self._installed = False\n\n    # ---------------------------------------------------------------- 注册\n    def register(self, vk: int, modifiers: int = 0, hotkey_id: int | None = None) -> int | None:\n        """注册一个全局热键，成功返回 id，失败返回 ``None``。"""\n        hid = hotkey_id if hotkey_id is not None else self._next_id\n        if hid in self._registered:\n            self.unregister(hid)\n\n        if not ctypes.windll.user32.RegisterHotKey(None, hid, modifiers | MOD_NOREPEAT, vk):\n            logger.warning("热键注册失败 (id=%s, vk=0x%02X)，可能已被其他程序占用", hid, vk)\n            return None\n\n        self._registered[hid] = vk\n        self._next_id = max(self._next_id, hid + 1)\n        if not self._installed:\n            self.install()\n        logger.debug("热键注册成功 id=%s vk=0x%02X", hid, vk)\n        return hid\n\n    def register_named(self, name: str, modifiers: int = 0, hotkey_id: int | None = None) -> int | None:\n        """按名字（如 ``"F9"``）注册热键。"""\n        vk = vk_of(name)\n        if vk is None:\n            logger.warning("未知热键名: %s", name)\n            return None\n        return self.register(vk, modifiers, hotkey_id)\n\n    def unregister(self, hotkey_id: int) -> None:\n        if hotkey_id in self._registered:\n            ctypes.windll.user32.UnregisterHotKey(None, hotkey_id)\n            del self._registered[hotkey_id]\n\n    def unregister_all(self) -> None:\n        for hid in list(self._registered):\n            self.unregister(hid)\n\n    # ------------------------------------------------------------ 事件过滤\n    def install(self) -> None:\n        """把自身注册为 QApplication 的原生事件过滤器。"""\n        if self._installed:\n            return\n        from PySide6.QtWidgets import QApplication\n\n        app = QApplication.instance()\n        if app is None:  # pragma: no cover - 调用顺序错误\n            raise RuntimeError("HotkeyManager 必须在 QApplication 之后创建")\n        app.installNativeEventFilter(self)\n        self._installed = True\n\n    def nativeEventFilter(self, eventType, message):  # noqa: N802 - Qt 命名\n        try:\n            event_type = bytes(eventType)\n        except TypeError:  # pragma: no cover\n            event_type = eventType\n\n        if event_type in (b"windows_generic_MSG", b"windows_dispatcher_MSG"):\n            msg = ctypes.cast(int(message), ctypes.POINTER(_MSG))\n            if msg.contents.message == WM_HOTKEY:\n                hotkey_id = int(msg.contents.wParam)\n                self.activated.emit(hotkey_id)\n                return True, 0\n        return False, 0\n\n    def shutdown(self) -> None:\n        """注销全部热键并移除事件过滤器。"""\n        self.unregister_all()\n        if self._installed:\n            from PySide6.QtWidgets import QApplication\n\n            app = QApplication.instance()\n            if app is not None:\n                app.removeNativeEventFilter(self)\n            self._installed = False\n',
    'app/win/screen.py': '"""全屏抓图（GDI ``BitBlt`` + ``GetDIBits``）。\n\n为什么不用 Qt 的 ``QScreen.grabWindow(0)``\n------------------------------------------\n它对「整个虚拟桌面」的解释在不同 Qt 版本 / 平台插件下并不一致。而本项目所有坐标\n都锚定在 Win32 的虚拟桌面矩形（``geometry.virtual_screen_rect``）上，\n直接走 GDI 拿到的就是 ``SendInput`` 使用的**同一套物理像素**，不存在对不上的可能。\n\n输出格式\n--------\n自顶向下、32 位、``stride == width * 4`` 的 BGRA 裸字节。\n\n之所以用 32 位而不是 24 位：24 位 BMP 的行要按 4 字节对齐，会引入行填充，\n字节级 ``find`` 就可能在行边界上错位。32 位没有填充，``stride`` 恰好是一行的长度，\n``matching`` 模块因此可以放心地在整块缓冲区上做扁平搜索。\n（``BITMAPINFOHEADER.biHeight`` 传负数即表示自顶向下。）\n\n抓图会短暂占用 GDI 资源，因此所有句柄都在 ``finally`` 里释放；\n这类「忘了 DeleteObject 就泄漏」的坑在长时间挂机时是致命的。\n"""\n\nfrom __future__ import annotations\n\nimport ctypes\nimport ctypes.wintypes as wintypes\nimport logging\nfrom dataclasses import dataclass\n\nfrom .geometry import ScreenRect, virtual_screen_rect\n\nlogger = logging.getLogger(__name__)\n\nSRCCOPY = 0x00CC0020\nDIB_RGB_COLORS = 0\nBI_RGB = 0\n\nBYTES_PER_PIXEL = 4\n\n_user32 = ctypes.WinDLL("user32", use_last_error=True)\n_gdi32 = ctypes.WinDLL("gdi32", use_last_error=True)\n\n_gdi32.CreateCompatibleDC.argtypes = (ctypes.c_void_p,)\n_gdi32.CreateCompatibleDC.restype = ctypes.c_void_p\n_gdi32.CreateCompatibleBitmap.argtypes = (ctypes.c_void_p, ctypes.c_int, ctypes.c_int)\n_gdi32.CreateCompatibleBitmap.restype = ctypes.c_void_p\n_gdi32.SelectObject.argtypes = (ctypes.c_void_p, ctypes.c_void_p)\n_gdi32.SelectObject.restype = ctypes.c_void_p\n_gdi32.BitBlt.argtypes = (\n    ctypes.c_void_p,\n    ctypes.c_int,\n    ctypes.c_int,\n    ctypes.c_int,\n    ctypes.c_int,\n    ctypes.c_void_p,\n    ctypes.c_int,\n    ctypes.c_int,\n    wintypes.DWORD,\n)\n_gdi32.BitBlt.restype = wintypes.BOOL\n_gdi32.GetDIBits.argtypes = (\n    ctypes.c_void_p,\n    ctypes.c_void_p,\n    wintypes.UINT,\n    wintypes.UINT,\n    wintypes.LPVOID,\n    ctypes.c_void_p,\n    wintypes.UINT,\n)\n_gdi32.GetDIBits.restype = ctypes.c_int\n_gdi32.DeleteObject.argtypes = (ctypes.c_void_p,)\n_gdi32.DeleteObject.restype = wintypes.BOOL\n_gdi32.DeleteDC.argtypes = (ctypes.c_void_p,)\n_gdi32.DeleteDC.restype = wintypes.BOOL\n\n_user32.GetDC.argtypes = (wintypes.HWND,)\n_user32.GetDC.restype = ctypes.c_void_p\n_user32.ReleaseDC.argtypes = (wintypes.HWND, ctypes.c_void_p)\n_user32.ReleaseDC.restype = ctypes.c_int\n\n\nclass BITMAPINFOHEADER(ctypes.Structure):\n    _fields_ = (\n        ("biSize", wintypes.DWORD),\n        ("biWidth", wintypes.LONG),\n        ("biHeight", wintypes.LONG),\n        ("biPlanes", wintypes.WORD),\n        ("biBitCount", wintypes.WORD),\n        ("biCompression", wintypes.DWORD),\n        ("biSizeImage", wintypes.DWORD),\n        ("biXPelsPerMeter", wintypes.LONG),\n        ("biYPelsPerMeter", wintypes.LONG),\n        ("biClrUsed", wintypes.DWORD),\n        ("biClrImportant", wintypes.DWORD),\n    )\n\n\n@dataclass(frozen=True)\nclass ScreenFrame:\n    """一帧屏幕像素。``(x, y)`` 是它在虚拟桌面里的左上角（多屏时可能是负数）。"""\n\n    x: int\n    y: int\n    width: int\n    height: int\n    data: bytes\n\n    @property\n    def stride(self) -> int:\n        return self.width * BYTES_PER_PIXEL\n\n    @property\n    def rect(self) -> ScreenRect:\n        return ScreenRect(self.x, self.y, self.width, self.height)\n\n    def pixel(self, x: int, y: int) -> tuple[int, int, int]:\n        """返回帧内 ``(x, y)`` 处的 ``(B, G, R)``。越界抛 ``IndexError``。"""\n        offset = y * self.stride + x * BYTES_PER_PIXEL\n        b, g, r = self.data[offset], self.data[offset + 1], self.data[offset + 2]\n        return b, g, r\n\n\ndef capture_screen(region: ScreenRect | None = None) -> ScreenFrame:\n    """抓取虚拟桌面（或其中一块）的像素。\n\n    用 GDI 而不是 Qt：拿到的一定是 ``SendInput`` 使用的物理像素。\n    失败时抛 ``OSError``。\n    """\n    area = region or virtual_screen_rect()\n    if area.width <= 0 or area.height <= 0:\n        raise OSError(f"抓图区域无效: {area}")\n\n    screen_dc = _user32.GetDC(None)\n    if not screen_dc:\n        raise OSError("GetDC 失败，无法抓取屏幕")\n\n    mem_dc = None\n    bitmap = None\n    previous = None\n    try:\n        mem_dc = _gdi32.CreateCompatibleDC(screen_dc)\n        if not mem_dc:\n            raise OSError("CreateCompatibleDC 失败")\n\n        bitmap = _gdi32.CreateCompatibleBitmap(screen_dc, area.width, area.height)\n        if not bitmap:\n            raise OSError("CreateCompatibleBitmap 失败")\n\n        previous = _gdi32.SelectObject(mem_dc, bitmap)\n        if not _gdi32.BitBlt(\n            mem_dc, 0, 0, area.width, area.height, screen_dc, area.x, area.y, SRCCOPY\n        ):\n            raise OSError("BitBlt 失败，无法抓取屏幕")\n\n        # GetDIBits 要求位图**不在**任何 DC 里，所以先把旧对象选回去\n        _gdi32.SelectObject(mem_dc, previous)\n        previous = None\n\n        header = BITMAPINFOHEADER(\n            biSize=ctypes.sizeof(BITMAPINFOHEADER),\n            biWidth=area.width,\n            biHeight=-area.height,  # 负数 = 自顶向下，省掉一次翻转\n            biPlanes=1,\n            biBitCount=32,\n            biCompression=BI_RGB,\n            biSizeImage=area.width * area.height * BYTES_PER_PIXEL,\n        )\n        size = area.width * area.height * BYTES_PER_PIXEL\n        buffer = ctypes.create_string_buffer(size)\n        copied = _gdi32.GetDIBits(\n            mem_dc, bitmap, 0, area.height, buffer, ctypes.byref(header), DIB_RGB_COLORS\n        )\n        if copied != area.height:\n            raise OSError(f"GetDIBits 只拷回 {copied}/{area.height} 行")\n\n        return ScreenFrame(\n            x=area.x, y=area.y, width=area.width, height=area.height, data=buffer.raw\n        )\n    finally:\n        if previous:\n            _gdi32.SelectObject(mem_dc, previous)\n        if bitmap:\n            _gdi32.DeleteObject(bitmap)\n        if mem_dc:\n            _gdi32.DeleteDC(mem_dc)\n        _user32.ReleaseDC(None, screen_dc)\n',
    'app/win/singleton.py': '"""单实例守卫（命名互斥量）。\n\n第二次启动时 ``acquire()`` 返回 False，调用方应提示用户并退出。\n"""\n\nfrom __future__ import annotations\n\nimport ctypes\nimport logging\nfrom ctypes import wintypes\n\nlogger = logging.getLogger(__name__)\n\nERROR_ALREADY_EXISTS = 183\n\n_kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)\n_kernel32.CreateMutexW.argtypes = (wintypes.LPVOID, wintypes.BOOL, wintypes.LPCWSTR)\n_kernel32.CreateMutexW.restype = wintypes.HANDLE\n_kernel32.CloseHandle.argtypes = (wintypes.HANDLE,)\n_kernel32.CloseHandle.restype = wintypes.BOOL\n\n\nclass SingleInstance:\n    """基于命名互斥量的进程单实例守卫。\n\n    互斥量句柄必须保持存活，因此调用方需要持有本对象的引用。\n    """\n\n    def __init__(self, name: str = r"Local\\AutoClicker.SingleInstance.v1") -> None:\n        self._name = name\n        self._handle: int | None = None\n\n    @property\n    def acquired(self) -> bool:\n        return self._handle is not None\n\n    def acquire(self) -> bool:\n        """尝试获取实例锁。已存在其他实例时返回 False。"""\n        if self._handle is not None:\n            return True\n\n        handle = _kernel32.CreateMutexW(None, False, self._name)\n        last_error = ctypes.get_last_error()\n\n        if not handle:  # pragma: no cover - 极端情况下才发生\n            logger.error("CreateMutexW 失败, GetLastError=%s", last_error)\n            return False\n\n        if last_error == ERROR_ALREADY_EXISTS:\n            _kernel32.CloseHandle(handle)\n            return False\n\n        self._handle = handle\n        return True\n\n    def release(self) -> None:\n        """释放实例锁。"""\n        if self._handle is not None:\n            _kernel32.CloseHandle(self._handle)\n            self._handle = None\n',
    'app/win/window.py': '"""Win32 窗口查询与坐标换算。\n\n后台点击（``PostMessage``）需要两样 ``SendInput`` 用不到的东西：\n\n1. **目标窗口的句柄（HWND）**：消息得指定收件人；\n2. **客户区坐标**：``WM_LBUTTONDOWN`` 的 ``lParam`` 是相对目标窗口客户区的坐标，\n   而不是屏幕绝对坐标。\n\n本模块把这层平台细节收在一处，供 ``app.input.postmessage`` 使用。所有函数都是\n「查得到就返回、查不到返回 ``None`` / ``False``」的风格，不抛异常——调用方\n（输入后端）在拿不到窗口时自行决定如何降级。\n\n坐标语义：本模块仍然只认**虚拟屏幕物理像素**（与 ``geometry`` 一致），\n换算交给 ``ScreenToClient``，与进程的 DPI 感知级别无关。\n"""\n\nfrom __future__ import annotations\n\nimport ctypes\nimport ctypes.wintypes as wintypes\nimport logging\n\nlogger = logging.getLogger(__name__)\n\n# GetAncestor\nGA_PARENT = 1\nGA_ROOT = 2\nGA_ROOTOWNER = 3\n\n# ChildWindowFromPointEx\nCWP_ALL = 0x0000\nCWP_SKIPINVISIBLE = 0x0001\nCWP_SKIPDISABLED = 0x0002\nCWP_SKIPTRANSPARENT = 0x0004\n\n# MapVirtualKey\nMAPVK_VK_TO_VSC = 0\n\n# 消息投递是最多下钻这么多层子窗口就停手，避免畸形窗口树把循环拖死\nMAX_CHILD_DEPTH = 16\n\nHWND = wintypes.HWND\n\n_user32 = ctypes.WinDLL("user32", use_last_error=True)\n\n_user32.IsWindow.argtypes = (wintypes.HWND,)\n_user32.IsWindow.restype = wintypes.BOOL\n_user32.IsWindowVisible.argtypes = (wintypes.HWND,)\n_user32.IsWindowVisible.restype = wintypes.BOOL\n_user32.WindowFromPoint.argtypes = (wintypes.POINT,)\n_user32.WindowFromPoint.restype = wintypes.HWND\n_user32.ChildWindowFromPointEx.argtypes = (wintypes.HWND, wintypes.POINT, wintypes.UINT)\n_user32.ChildWindowFromPointEx.restype = wintypes.HWND\n_user32.GetAncestor.argtypes = (wintypes.HWND, wintypes.UINT)\n_user32.GetAncestor.restype = wintypes.HWND\n_user32.GetForegroundWindow.argtypes = ()\n_user32.GetForegroundWindow.restype = wintypes.HWND\n_user32.ScreenToClient.argtypes = (wintypes.HWND, ctypes.POINTER(wintypes.POINT))\n_user32.ScreenToClient.restype = wintypes.BOOL\n_user32.ClientToScreen.argtypes = (wintypes.HWND, ctypes.POINTER(wintypes.POINT))\n_user32.ClientToScreen.restype = wintypes.BOOL\n_user32.PostMessageW.argtypes = (wintypes.HWND, wintypes.UINT, wintypes.WPARAM, wintypes.LPARAM)\n_user32.PostMessageW.restype = wintypes.BOOL\n_user32.GetWindowTextLengthW.argtypes = (wintypes.HWND,)\n_user32.GetWindowTextLengthW.restype = ctypes.c_int\n_user32.GetWindowTextW.argtypes = (wintypes.HWND, wintypes.LPWSTR, ctypes.c_int)\n_user32.GetWindowTextW.restype = ctypes.c_int\n_user32.GetClassNameW.argtypes = (wintypes.HWND, wintypes.LPWSTR, ctypes.c_int)\n_user32.GetClassNameW.restype = ctypes.c_int\n\n_user32.MapVirtualKeyW.argtypes = (wintypes.UINT, wintypes.UINT)\n_user32.MapVirtualKeyW.restype = wintypes.UINT\n\n\ndef _as_hwnd(value) -> int | None:\n    """把 ctypes 句柄（``c_void_p``）或 int 归一成 Python int；空句柄返回 ``None``。\n\n    ``wintypes.HWND`` 是 ``c_void_p``，``int()`` 它并不成立（会去解析内存内容），\n    必须走 ``.value``。\n    """\n    if not value:\n        return None\n    raw = getattr(value, "value", value)\n    return int(raw) if raw else None\n\n\ndef is_window(hwnd: int | None) -> bool:\n    """句柄是否指向一个仍然存在的窗口。"""\n    if not hwnd:\n        return False\n    return bool(_user32.IsWindow(HWND(hwnd)))\n\n\ndef is_window_visible(hwnd: int | None) -> bool:\n    if not hwnd:\n        return False\n    return bool(_user32.IsWindowVisible(HWND(hwnd)))\n\n\ndef window_from_point(x: int, y: int) -> int | None:\n    """屏幕坐标处**最顶层**的窗口（可能是子窗口）。找不到返回 ``None``。\n\n    注意它只看得到当前可见、位于该点的窗口；被完全遮住的窗口谁也找不到，\n    那种情况必须先手动绑定 HWND。\n    """\n    return _as_hwnd(_user32.WindowFromPoint(wintypes.POINT(int(x), int(y))))\n\n\ndef root_window(hwnd: int) -> int | None:\n    """取顶层窗口（``GA_ROOT``），用于把绑定的目标归一化到稳定的顶层句柄。"""\n    return _as_hwnd(_user32.GetAncestor(HWND(int(hwnd)), GA_ROOT)) or int(hwnd)\n\n\ndef child_window_from_point(\n    hwnd: int, x: int, y: int, flags: int = CWP_SKIPINVISIBLE | CWP_SKIPTRANSPARENT\n) -> int | None:\n    """``hwnd`` 客户区坐标 ``(x, y)`` 处的直接子窗口，没有子窗口时返回 ``None``。\n\n    默认跳过不可见与 ``WS_EX_TRANSPARENT`` 的子窗口——真实鼠标会直接穿过它们，\n    投递消息时也应该穿过去。\n    """\n    found = _as_hwnd(\n        _user32.ChildWindowFromPointEx(HWND(int(hwnd)), wintypes.POINT(int(x), int(y)), flags)\n    )\n    if found is None or found == int(hwnd):\n        return None\n    return found\n\n\ndef deepest_child_at(hwnd: int, screen_x: int, screen_y: int) -> int:\n    """从 ``hwnd`` 出发，逐层下钻到屏幕坐标处最内层的子窗口。\n\n    真正的鼠标消息由命中测试路由到最内层控件，因此投递时也应该发到那一层；\n    只发给顶层窗口，很多程序不会自己再往下转发。\n    """\n    current = int(hwnd)\n    for _ in range(MAX_CHILD_DEPTH):\n        client = screen_to_client(current, screen_x, screen_y)\n        if client is None:\n            break\n        child = child_window_from_point(current, client[0], client[1])\n        if child is None:\n            break\n        current = child\n    return current\n\n\ndef screen_to_client(hwnd: int, x: int, y: int) -> tuple[int, int] | None:\n    """屏幕物理像素 → ``hwnd`` 的客户区坐标。失败返回 ``None``。"""\n    point = wintypes.POINT(int(x), int(y))\n    if not _user32.ScreenToClient(HWND(int(hwnd)), ctypes.byref(point)):\n        return None\n    return int(point.x), int(point.y)\n\n\ndef client_to_screen(hwnd: int, x: int, y: int) -> tuple[int, int] | None:\n    """``hwnd`` 的客户区坐标 → 屏幕物理像素。失败返回 ``None``。"""\n    point = wintypes.POINT(int(x), int(y))\n    if not _user32.ClientToScreen(HWND(int(hwnd)), ctypes.byref(point)):\n        return None\n    return int(point.x), int(point.y)\n\n\ndef foreground_window() -> int | None:\n    return _as_hwnd(_user32.GetForegroundWindow())\n\n\ndef map_virtual_key(vk: int) -> int:\n    """虚拟键码 → 扫描码，失败返回 0（键盘消息的 ``lParam`` 里会用到）。"""\n    try:\n        return int(_user32.MapVirtualKeyW(int(vk), MAPVK_VK_TO_VSC))\n    except OSError:  # pragma: no cover - 仅在异常系统上触发\n        return 0\n\n\ndef post_message(hwnd: int, message: int, wparam: int = 0, lparam: int = 0) -> bool:\n    """向窗口消息队列投递一条消息（``PostMessageW``，异步、不阻塞）。\n\n    失败（窗口已销毁、队列已满等）返回 ``False``，不抛异常。\n    """\n    if not hwnd:\n        return False\n    return bool(_user32.PostMessageW(HWND(int(hwnd)), int(message), int(wparam), int(lparam)))\n\n\ndef window_text(hwnd: int) -> str:\n    length = _user32.GetWindowTextLengthW(HWND(int(hwnd)))\n    if length <= 0:\n        return ""\n    buffer = ctypes.create_unicode_buffer(length + 1)\n    _user32.GetWindowTextW(HWND(int(hwnd)), buffer, length + 1)\n    return buffer.value\n\n\ndef class_name(hwnd: int) -> str:\n    buffer = ctypes.create_unicode_buffer(256)\n    _user32.GetClassNameW(HWND(int(hwnd)), buffer, 256)\n    return buffer.value\n\n\ndef describe(hwnd: int) -> str:\n    """给用户看的窗口描述，形如 ``记事本 [Notepad]``。"""\n    title = window_text(hwnd) or "(无标题)"\n    return f"{title} [{class_name(hwnd)}]"\n',
    'tests/test_smoke.py': '"""冒烟测试：不依赖 pytest，直接 ``python tests/test_smoke.py`` 运行。\n\n覆盖范围\n--------\n- Win32 结构体布局（SendInput 最怕结构体大小算错，会导致静默失败）\n- 虚拟屏幕坐标读取\n- 单实例守卫\n- 步骤模型与方案的 JSON 往返（含找图模板的 base64 + zlib 打包）\n- 找图匹配：探针挑法、抽样比对、容差、同分取最左上、大面积同色屏幕\n- 方案仓库的增删改查与原子写入\n- 引擎的步骤顺序、循环、停用跳过、停止响应（用假后端，不会真的点鼠标）\n- 找图步骤的等待与超时策略（用注入的假抓屏，不需要真的屏幕）\n- 无头模式下主窗口与步骤编辑器能否正常装配\n\nGUI 相关测试使用 Qt 的 offscreen 平台插件，不会真的弹窗。\n"""\n\nfrom __future__ import annotations\n\nimport ctypes\nimport os\nimport sys\nimport tempfile\nimport time\nimport unittest\nfrom pathlib import Path\n\nos.environ.setdefault("QT_QPA_PLATFORM", "offscreen")\n\n_ROOT = Path(__file__).resolve().parent.parent\nif str(_ROOT) not in sys.path:\n    sys.path.insert(0, str(_ROOT))\n\nfrom PySide6.QtCore import Qt  # noqa: E402\n\nfrom app.core.models import (  # noqa: E402\n    ON_TIMEOUT_STOP,\n    ClickStep,\n    DelayStep,\n    KeyStep,\n    MoveStep,\n    Profile,\n    StepKind,\n    WaitStep,\n)\nfrom app.input.base import InputBackend, MouseButton  # noqa: E402\nfrom app.input.sendinput import INPUT  # noqa: E402\nfrom app.win.hooks import InputEvent  # noqa: E402\n\n# 测试通过信号断言，不需要日志输出；挂个 NullHandler 让 root logger 保持安静\n# （存在任何 handler 时，logging 就不会再走 lastResort 直接往 stderr 打）\nimport logging  # noqa: E402\n\nlogging.getLogger().addHandler(logging.NullHandler())\n\n\nclass FakeBackend(InputBackend):\n    """记录调用而不真的操作鼠标，保留完整时间线用于校验执行顺序。"""\n\n    name = "fake"\n\n    def __init__(self) -> None:\n        self.events: list[tuple] = []\n\n    def click(self, x, y, button=MouseButton.LEFT):\n        self.events.append(("click", x, y, button))\n\n    def move_to(self, x, y):\n        self.events.append(("move", x, y))\n\n    def press_key(self, vk):\n        self.events.append(("key", vk))\n\n    # ---- 便利视图\n    @property\n    def kinds(self) -> list[str]:\n        return [event[0] for event in self.events]\n\n    @property\n    def clicks(self) -> list[tuple]:\n        return [event for event in self.events if event[0] == "click"]\n\n    @property\n    def keys(self) -> list[tuple]:\n        return [event for event in self.events if event[0] == "key"]\n\n\n# ==================================================================== 假屏幕\ndef _pixel(b, g, r):\n    """一个 BGRA 像素。抓屏输出就是 BGRA，这里保持一致。"""\n    return bytes((b, g, r, 255))\n\n\ndef _frame(width, height, color=(18, 18, 22), x=0, y=0):\n    from app.win.screen import ScreenFrame\n\n    return ScreenFrame(\n        x=x, y=y, width=width, height=height, data=_pixel(*color) * (width * height)\n    )\n\n\ndef _paint(frame, left, top, width, height, color):\n    """在帧上刷一块矩形。``ScreenFrame`` 是 frozen 的，所以返回新的一帧。"""\n    from app.win.screen import ScreenFrame\n\n    data = bytearray(frame.data)\n    stride = frame.stride\n    block = _pixel(*color) * width\n    for row in range(top, top + height):\n        start = row * stride + left * 4\n        data[start : start + width * 4] = block\n    return ScreenFrame(\n        x=frame.x, y=frame.y, width=frame.width, height=frame.height, data=bytes(data)\n    )\n\n\ndef _crop_frame(frame, left, top, width, height):\n    """从帧上抠一块出来（等价于抓屏的 ``region`` 参数）。"""\n    from app.win.screen import ScreenFrame\n\n    stride = frame.stride\n    rows = [\n        frame.data[(top + row) * stride + left * 4 : (top + row) * stride + (left + width) * 4]\n        for row in range(height)\n    ]\n    return ScreenFrame(x=left, y=top, width=width, height=height, data=b"".join(rows))\n\n\ndef _crop(frame, left, top, width, height):\n    from app.core.matching import Template\n\n    piece = _crop_frame(frame, left, top, width, height)\n    return Template(width=piece.width, height=piece.height, data=piece.data)\n\n\nBUTTON_AT = (70, 50)\nBUTTON_SIZE = (40, 20)\nBUTTON_COLOR = (212, 120, 0)  # BGRA：蓝底\nBUTTON_TEXT_COLOR = (255, 255, 255)\n# 按钮里的「文字」块。刻意做大一点：它决定了抽样校验有多少个点落在非纯色区\nBUTTON_TEXT_AT = (5, 4)\nBUTTON_TEXT_SIZE = (30, 12)\n\n\ndef _screen_with_button(position=BUTTON_AT, origin=(0, 0), size=(200, 120)):\n    """造一屏：深色背景上有一个蓝底白字的按钮。"""\n    frame = _frame(size[0], size[1], x=origin[0], y=origin[1])\n    left, top = position\n    frame = _paint(frame, left, top, BUTTON_SIZE[0], BUTTON_SIZE[1], BUTTON_COLOR)\n    return _paint(\n        frame,\n        left + BUTTON_TEXT_AT[0],\n        top + BUTTON_TEXT_AT[1],\n        BUTTON_TEXT_SIZE[0],\n        BUTTON_TEXT_SIZE[1],\n        BUTTON_TEXT_COLOR,\n    )\n\n\ndef _button_template(origin=(0, 0)):\n    """从假屏幕里抠出那个按钮当模板。"""\n    frame = _screen_with_button(origin=origin)\n    return _crop(frame, BUTTON_AT[0], BUTTON_AT[1], BUTTON_SIZE[0], BUTTON_SIZE[1])\n\n\ndef _gradient_template():\n    """一行渐变：没有任何纯色横线，用来验证「这模板不好找」的提示。"""\n    from app.core.matching import Template\n\n    data = b"".join(\n        _pixel(255 - x * 10, x * 7, x * 3) for x in range(20)\n    )\n    return Template(width=20, height=3, data=data * 3)\n\n\n# ==================================================================== 结构体\nclass TestStructLayout(unittest.TestCase):\n    def test_input_struct_size(self):\n        """INPUT 大小必须和 Win32 一致，否则 SendInput 会静默失败。"""\n        expected = 40 if ctypes.sizeof(ctypes.c_void_p) == 8 else 28\n        self.assertEqual(ctypes.sizeof(INPUT), expected)\n\n    def test_anonymous_union_shares_memory(self):\n        """``mi`` / ``ki`` / ``hi`` 共用同一块内存 —— 这是 INPUT 的设计，不是 bug。\n\n        这个测试把该行为固定下来：以后如果有人「顺手」把联合体拆成独立字段，\n        结构体大小就会变，SendInput 随即静默失败。\n        """\n        item = INPUT()\n        item.type = 0\n\n        item.mi.dx = 123\n        self.assertEqual(item.mi.dx, 123)\n\n        item.ki.wVk = 5\n        self.assertEqual(item.ki.wVk, 5)\n        self.assertNotEqual(item.mi.dx, 123, "ki 与 mi 应共享同一块内存")\n\n\n# ==================================================================== 平台\nclass TestGeometry(unittest.TestCase):\n    def test_virtual_screen_is_sane(self):\n        from app.win.geometry import get_cursor_pos, virtual_screen_rect\n\n        rect = virtual_screen_rect()\n        self.assertGreater(rect.width, 0)\n        self.assertGreater(rect.height, 0)\n\n        x, y = get_cursor_pos()\n        self.assertIsInstance(x, int)\n        self.assertIsInstance(y, int)\n\n\nclass TestSingleInstance(unittest.TestCase):\n    def test_second_acquire_fails(self):\n        from app.win.singleton import SingleInstance\n\n        name = r"Local\\AutoClicker.Test.SmokeTest"\n        first, second = SingleInstance(name), SingleInstance(name)\n        try:\n            self.assertTrue(first.acquire())\n            self.assertFalse(second.acquire())\n        finally:\n            first.release()\n            second.release()\n\n        third = SingleInstance(name)\n        try:\n            self.assertTrue(third.acquire())\n        finally:\n            third.release()\n\n\nclass TestHotkeyTable(unittest.TestCase):\n    def test_vk_mapping(self):\n        from app.win.hotkey import name_of_vk, vk_names, vk_of\n\n        self.assertEqual(vk_of("F9"), 0x78)\n        self.assertEqual(vk_of("f8"), 0x77)\n        self.assertEqual(vk_of("A"), 0x41)\n        self.assertEqual(vk_of("ESC"), 0x1B)\n        self.assertIsNone(vk_of("NOPE"))\n\n        self.assertEqual(name_of_vk(0x78), "F9")\n        self.assertTrue(name_of_vk(0xFF).startswith("0x"))\n\n        names = vk_names()\n        self.assertEqual(names[0], "F1")\n        self.assertIn("A", names)\n        self.assertIn("ENTER", names)\n        self.assertEqual(len(names), len(set(names)), "下拉列表不应有重复项")\n\n\n# ==================================================================== 模型\nclass TestModels(unittest.TestCase):\n    def test_click_step_validation(self):\n        ClickStep(x=1, y=2, interval_ms=100).validate()\n        with self.assertRaises(ValueError):\n            ClickStep(x=0, y=0, interval_ms=0).validate()\n        with self.assertRaises(ValueError):\n            ClickStep(x=0, y=0, repeat=0).validate()\n        with self.assertRaises(ValueError):\n            ClickStep(x=0, y=0, jitter_px=-1).validate()\n\n    def test_key_step_validation(self):\n        from app.win.hotkey import vk_of\n\n        KeyStep(vk=vk_of("F5"), repeat=1, interval_ms=50).validate()\n        with self.assertRaises(ValueError):\n            KeyStep(vk=0).validate()\n\n    def test_step_roundtrip(self):\n        from app.core.models import step_from_dict\n\n        originals = [\n            ClickStep(x=-12, y=34, button=MouseButton.RIGHT, repeat=3, interval_ms=250,\n                      jitter_ms=40, jitter_px=2, note="登录按钮"),\n            DelayStep(delay_ms=1500, jitter_ms=200),\n            KeyStep(vk=0x74, repeat=2, interval_ms=30, enabled=False),\n            MoveStep(points=[(10, 20), (30, 40), (50, 60)], duration_ms=420, note="划过去"),\n            MoveStep(points=[(7, 7)], duration_ms=0),\n            WaitStep(template=_button_template().encode(), tolerance=40, timeout_ms=15000,\n                     poll_interval_ms=250, button=MouseButton.RIGHT, offset_x=3, offset_y=-3,\n                     on_timeout=ON_TIMEOUT_STOP, note="等继续弹窗"),\n        ]\n        for original in originals:\n            restored = step_from_dict(original.to_dict())\n            self.assertIs(type(restored), type(original))\n            self.assertEqual(restored.to_dict(), original.to_dict())\n\n    def test_wait_step_validation(self):\n        WaitStep(template=_button_template().encode()).validate()\n\n        with self.assertRaises(ValueError):\n            WaitStep().validate()  # 还没截模板\n        with self.assertRaises(ValueError):\n            WaitStep(template="这不是模板").validate()  # 模板数据坏了\n        with self.assertRaises(ValueError):\n            WaitStep(template=_button_template().encode(), tolerance=300).validate()\n        with self.assertRaises(ValueError):\n            WaitStep(template=_button_template().encode(), poll_interval_ms=1).validate()\n        with self.assertRaises(ValueError):\n            WaitStep(template=_button_template().encode(), on_timeout="随便").validate()\n\n    def test_wait_step_summary(self):\n        step = WaitStep(template=_button_template().encode(), timeout_ms=30000)\n        text = step.summary()\n        self.assertIn("40 × 20", text)\n        self.assertIn("左键", text)\n        self.assertIn("30s", text)\n\n        self.assertEqual(WaitStep().summary(), "（未截取模板）")\n        self.assertIn(\n            "超时中止", WaitStep(template=step.template, on_timeout=ON_TIMEOUT_STOP).summary()\n        )\n\n    def test_wait_step_without_template_cannot_be_saved(self):\n        """没截模板的找图步骤算「不完整」：能存在，但不让存成方案。\n\n        界面在对话框那一层就拦住了（不截模板点不了「确定」）。这里守的是手改 JSON\n        之类的旁路：拦下来时还必须点名是哪一步，否则用户根本不知道该修哪个。\n        """\n        profile = Profile(name="半成品", steps=[WaitStep(note="还没截图")])\n        with self.assertRaises(ValueError) as ctx:\n            profile.validate(require_steps=False)\n\n        self.assertIn("第 1 步", str(ctx.exception))\n        self.assertIn("找图", str(ctx.exception))\n\n    def test_move_step_validation(self):\n        MoveStep(points=[(1, 2)], duration_ms=0).validate()\n        with self.assertRaises(ValueError):\n            MoveStep(points=[], duration_ms=100).validate()\n        with self.assertRaises(ValueError):\n            MoveStep(points=[(1, 2)], duration_ms=-1).validate()\n\n    def test_move_step_ignores_broken_points(self):\n        profile = Profile.from_dict(\n            {\n                "name": "容错",\n                "steps": [{"kind": "move", "points": [[1, 2], [3], "x", [4, 5]], "duration_ms": 10}],\n            }\n        )\n        step = profile.steps[0]\n        self.assertIsInstance(step, MoveStep)\n        self.assertEqual(step.points, [(1, 2), (4, 5)])\n\n    def test_profile_roundtrip_and_active_steps(self):\n        profile = Profile(\n            name="测试方案",\n            steps=[\n                ClickStep(x=1, y=1, repeat=2),\n                DelayStep(delay_ms=10, enabled=False),\n                KeyStep(vk=0x41),\n            ],\n            repeat=5,\n            repeat_delay_ms=100,\n            start_delay_ms=700,\n        )\n        restored = Profile.from_dict(profile.to_dict())\n\n        self.assertEqual(restored.name, "测试方案")\n        self.assertEqual(restored.repeat, 5)\n        self.assertEqual(restored.repeat_delay_ms, 100)\n        self.assertEqual(restored.start_delay_ms, 700)\n        self.assertEqual(len(restored.steps), 3)\n        self.assertEqual([step.kind for step in restored.active_steps()], [StepKind.CLICK, StepKind.KEY])\n\n    def test_validate_reports_step_index(self):\n        profile = Profile(steps=[ClickStep(x=0, y=0), DelayStep(delay_ms=-1)])\n        with self.assertRaises(ValueError) as ctx:\n            profile.validate()\n        self.assertIn("第 2 步", str(ctx.exception))\n\n    def test_validate_requires_enabled_steps(self):\n        profile = Profile(steps=[ClickStep(x=0, y=0, enabled=False)])\n        with self.assertRaises(ValueError):\n            profile.validate()\n        profile.validate(require_steps=False)  # 保存时允许半成品\n\n    def test_from_dict_skips_broken_steps(self):\n        profile = Profile.from_dict(\n            {\n                "name": "容错",\n                "steps": [\n                    {"kind": "click", "x": 5, "y": 6},\n                    {"kind": "unknown-thing"},\n                    "not-a-dict",\n                ],\n            }\n        )\n        self.assertEqual(len(profile.steps), 1)\n        self.assertEqual(profile.steps[0].x, 5)\n\n    def test_default_profile_points_at_primary_screen(self):\n        profile = Profile.default()\n        self.assertTrue(profile.steps)\n        step = profile.steps[0]\n        self.assertIsInstance(step, ClickStep)\n        self.assertGreaterEqual(step.x, 0)\n        self.assertGreaterEqual(step.y, 0)\n\n\n# ==================================================================== 找图\nclass TestMatching(unittest.TestCase):\n    """模板匹配全部在内存里跑，不需要真的屏幕。"""\n\n    def test_template_encode_decode_roundtrip(self):\n        from app.core.matching import Template\n\n        template = _button_template()\n        restored = Template.decode(template.encode())\n\n        self.assertEqual((restored.width, restored.height), BUTTON_SIZE)\n        self.assertEqual(restored.data, template.data)\n\n    def test_template_decode_rejects_broken_data(self):\n        import base64\n\n        from app.core.matching import Template\n\n        bad_inputs = [\n            "",\n            "这不是-base64!!",\n            base64.b64encode(b"XXXX" + b"\\x00" * 20).decode(),  # magic 不对\n            base64.b64encode(b"ACT1" + b"\\x00" * 8).decode(),  # 宽高为 0\n            base64.b64encode(b"ACT1" + b"\\x04\\x00\\x04\\x00" + "垃圾".encode()).decode(),  # zlib 坏\n            _button_template().encode()[:-6],  # 被截断\n        ]\n        for bad in bad_inputs:\n            with self.assertRaises(ValueError, msg=f"{bad!r} 应该被拒绝"):\n                Template.decode(bad)\n\n    def test_template_rejects_wrong_pixel_count(self):\n        from app.core.matching import Template\n\n        with self.assertRaises(ValueError):\n            Template(width=4, height=4, data=b"\\x00" * 10)\n        with self.assertRaises(ValueError):\n            Template(width=0, height=1, data=b"")\n\n    def test_probes_put_selectivity_first(self):\n        """第一个签名要横跨文字（不是纯色，因此几乎不会误命中），第二个才是纯色退路。"""\n        from app.core.matching import MIN_PROBE_PX, pick_probes\n\n        probes = pick_probes(_button_template())\n        self.assertEqual(len(probes), 2, "按钮模板应该同时给出整行签名和纯色签名")\n\n        first = [\n            probes[0].signature[index * 4 : index * 4 + 4]\n            for index in range(probes[0].length)\n        ]\n        self.assertGreater(len(set(first)), 1, "第一个签名要横跨文字，不能是一整段纯色")\n\n        second = [\n            probes[1].signature[index * 4 : index * 4 + 4]\n            for index in range(probes[1].length)\n        ]\n        self.assertEqual(len(set(second)), 1, "最后那个签名必须是纯色段")\n        self.assertGreaterEqual(probes[1].length, MIN_PROBE_PX)\n\n    def test_probes_skip_useless_solid_signature(self):\n        """没有纯色段时不该硬塞一个 1 像素的签名进去——那玩意儿满屏都是。"""\n        from app.core.matching import pick_probes\n\n        probes = pick_probes(_gradient_template())\n        self.assertEqual(len(probes), 1)\n\n    def test_solid_run_length_flags_photo_like_template(self):\n        from app.core.matching import MIN_PROBE_PX, solid_run_length\n\n        self.assertGreaterEqual(solid_run_length(_button_template()), 40)\n        self.assertEqual(solid_run_length(_gradient_template()), 1)\n        self.assertLess(solid_run_length(_gradient_template()), MIN_PROBE_PX)\n\n    def test_find_template_locates_the_button(self):\n        from app.core.matching import find_template\n\n        result = find_template(_screen_with_button(), _button_template())\n\n        self.assertTrue(result.found)\n        self.assertEqual((result.match.x, result.match.y), BUTTON_AT)\n        self.assertEqual(result.match.similarity, 1.0)\n\n    def test_find_template_on_a_flat_screen_does_not_starve(self):\n        """整屏一个颜色时，签名会在每一行都命中。\n\n        扫描区间必须裁到「模板左上角的合法范围」里，否则前面几千个候选全是越界的废命中，\n        配额被烧光之后，正确答案明明在屏幕中间也会报「没找到」——真机上踩过这个坑。\n        """\n        from app.core.matching import find_template\n\n        flat = _frame(600, 400)\n        template = _crop(flat, 300, 200, 120, 64)  # 从纯色背景里抠，最没特征的一种模板\n\n        result = find_template(flat, template)\n\n        self.assertTrue(result.found, "大面积同色背景也必须能找到")\n        self.assertEqual((result.match.x, result.match.y), (0, 0), "同分取最左上")\n\n    def test_find_template_prefers_the_distinctive_row_over_the_flat_one(self):\n        """先锐利后退让：整行签名先命中时，就不该再去跑纯色签名那一大堆候选。"""\n        from app.core.matching import find_template\n\n        result = find_template(_screen_with_button(), _button_template())\n\n        self.assertTrue(result.found)\n        self.assertEqual(result.match.similarity, 1.0)\n        self.assertLess(result.candidates, 10, "整行签名很锐利，候选应该很少")\n\n\n        from app.core.matching import find_template\n\n        result = find_template(_frame(200, 120), _button_template())\n\n        self.assertFalse(result.found)\n        self.assertIsNone(result.match)\n        self.assertEqual(result.candidates, 0, "屏幕上没有同色区域，应该一个候选都没有")\n        self.assertEqual(result.best_similarity, 0.0)\n\n    def test_find_template_rejects_oversized_template(self):\n        from app.core.matching import find_template\n\n        result = find_template(_frame(20, 20), _button_template())\n\n        self.assertFalse(result.found)\n        self.assertEqual(result.candidates, 0)\n\n    def test_find_template_verification_honours_tolerance(self):\n        """探针所在的那一行没变、只是别处颜色微调时，容差就该起作用。"""\n        from app.core.matching import find_template\n\n        template = _button_template()\n        shifted = _paint(\n            _screen_with_button(),\n            BUTTON_AT[0] + BUTTON_TEXT_AT[0],\n            BUTTON_AT[1] + BUTTON_TEXT_AT[1],\n            *BUTTON_TEXT_SIZE,\n            (235, 235, 235),\n        )\n\n        self.assertTrue(find_template(shifted, template, tolerance=32).found)\n\n        strict = find_template(shifted, template, tolerance=0)\n        self.assertFalse(strict.found)\n        self.assertGreater(strict.best_similarity, 0.5, "该找到候选，只是被容差否决了")\n\n    def test_probe_is_byte_exact(self):\n        """探针是逐字节比对：底色整体换了色调后，连候选都找不出来。\n\n        这是刻意的取舍——不做多尺度、多色调搜索，才能保住「零依赖 + 每帧几十毫秒」。\n        代价是目标程序换主题/DPI 缩放后必须重新截模板。这条测试把这个契约钉住，\n        免得以后有人为了「更宽容一点」偷偷改成模糊搜索，把性能赔进去。\n        """\n        from app.core.matching import find_template\n\n        shifted = _paint(\n            _screen_with_button(), BUTTON_AT[0], BUTTON_AT[1], *BUTTON_SIZE, (200, 112, 8)\n        )\n        result = find_template(shifted, _button_template(), tolerance=200)\n\n        self.assertFalse(result.found)\n        self.assertEqual(result.candidates, 0)\n\n    def test_find_template_picks_top_left_on_ties(self):\n        from app.core.matching import find_template\n\n        frame = _screen_with_button(position=(120, 60))\n        frame = _paint(frame, BUTTON_AT[0], BUTTON_AT[1], *BUTTON_SIZE, BUTTON_COLOR)\n        frame = _paint(\n            frame,\n            BUTTON_AT[0] + BUTTON_TEXT_AT[0],\n            BUTTON_AT[1] + BUTTON_TEXT_AT[1],\n            *BUTTON_TEXT_SIZE,\n            BUTTON_TEXT_COLOR,\n        )\n\n        result = find_template(frame, _button_template())\n\n        self.assertEqual(\n            (result.match.x, result.match.y), BUTTON_AT, "同分时取最靠上、再最靠左的那个"\n        )\n\n    def test_find_template_coordinates_are_frame_local(self):\n        """匹配坐标相对帧左上角；屏幕原点由调用方（引擎）加回去。"""\n        from app.core.matching import find_template\n\n        frame = _screen_with_button(origin=(-1920, -200))\n        result = find_template(frame, _button_template())\n\n        self.assertEqual((result.match.x, result.match.y), BUTTON_AT)\n        self.assertEqual((frame.x + result.match.x, frame.y + result.match.y), (-1850, -150))\n\n\n# ==================================================================== 存储\nclass TestProfileStore(unittest.TestCase):\n    def setUp(self):\n        self._tmp = tempfile.TemporaryDirectory()\n        self.base = Path(self._tmp.name)\n\n    def tearDown(self):\n        self._tmp.cleanup()\n\n    def _store(self):\n        from app.storage.config import ProfileStore\n\n        return ProfileStore(self.base)\n\n    def test_save_load_list_delete(self):\n        store = self._store()\n        self.assertEqual(store.list_names(), [])\n\n        store.save(Profile(name="方案A", steps=[ClickStep(x=9, y=8, repeat=2)]))\n        store.save(Profile(name="方案B", steps=[DelayStep(delay_ms=50)]))\n\n        self.assertEqual(store.list_names(), ["方案A", "方案B"])\n        self.assertTrue(store.exists("方案A"))\n\n        loaded = store.load("方案A")\n        self.assertEqual(loaded.name, "方案A")\n        self.assertEqual(loaded.steps[0].x, 9)\n\n        self.assertTrue(store.delete("方案A"))\n        self.assertFalse(store.delete("方案A"))\n        self.assertEqual(store.list_names(), ["方案B"])\n\n        # 原子写入不应留下临时文件\n        leftovers = list(store.profiles_dir.glob("*.tmp"))\n        self.assertEqual(leftovers, [])\n\n    def test_load_missing_raises(self):\n        with self.assertRaises(ValueError):\n            self._store().load("不存在的方案")\n\n    def test_load_corrupted_raises(self):\n        store = self._store()\n        store.profiles_dir.mkdir(parents=True, exist_ok=True)\n        (store.profiles_dir / "坏文件.json").write_text("{ not json", encoding="utf-8")\n        with self.assertRaises(ValueError):\n            store.load("坏文件")\n\n    def test_invalid_filename_chars_are_sanitized(self):\n        store = self._store()\n        store.save(Profile(name="a/b:c*d", steps=[ClickStep()]))\n        self.assertEqual(len(store.list_names()), 1)\n        self.assertNotIn("/", store.list_names()[0])\n\n    def test_rename(self):\n        store = self._store()\n        store.save(Profile(name="旧名", steps=[ClickStep()]))\n        self.assertTrue(store.rename("旧名", "新名"))\n        self.assertEqual(store.list_names(), ["新名"])\n        self.assertFalse(store.rename("不存在", "别的"))\n\n    def test_last_profile_setting(self):\n        store = self._store()\n        self.assertIsNone(store.get_last_profile())\n        store.set_last_profile("方案B")\n        self.assertEqual(store.get_last_profile(), "方案B")\n\n        # 新实例应能从磁盘读回\n        self.assertEqual(self._store().get_last_profile(), "方案B")\n\n\n# ==================================================================== 引擎\nclass TestEngine(unittest.TestCase):\n    """同一线程内直接调用 run()，信号走直连，无需事件循环。"""\n\n    def setUp(self):\n        from PySide6.QtWidgets import QApplication\n\n        self.app = QApplication.instance() or QApplication([])\n\n    def _engine(self, backend, screen=None):\n        from app.core.engine import MacroEngine\n\n        return MacroEngine(backend, screen=screen)\n\n    def test_step_order_and_rounds(self):\n        backend = FakeBackend()\n        engine = self._engine(backend)\n        engine.run(\n            Profile(\n                name="顺序",\n                steps=[\n                    ClickStep(x=10, y=20, repeat=2, interval_ms=1),\n                    DelayStep(delay_ms=5),\n                    KeyStep(vk=0x41, repeat=1, interval_ms=1),\n                ],\n                repeat=2,\n                start_delay_ms=0,\n            )\n        )\n\n        # 每轮: click click key；共两轮\n        self.assertEqual(backend.kinds, ["click", "click", "key", "click", "click", "key"])\n        self.assertEqual(len(backend.clicks), 4)\n        self.assertEqual([c[1] for c in backend.clicks], [10, 10, 10, 10])\n        self.assertTrue(all(c[3] is MouseButton.LEFT for c in backend.clicks))\n\n    def test_start_delay_is_applied(self):\n        backend = FakeBackend()\n        engine = self._engine(backend)\n\n        begin = time.perf_counter()\n        engine.run(\n            Profile(steps=[ClickStep(x=1, y=1, repeat=1, interval_ms=1)], repeat=1, start_delay_ms=120)\n        )\n        elapsed = time.perf_counter() - begin\n\n        self.assertEqual(len(backend.clicks), 1)\n        self.assertGreaterEqual(elapsed, 0.10)\n\n    def test_disabled_steps_are_skipped(self):\n        backend = FakeBackend()\n        engine = self._engine(backend)\n        engine.run(\n            Profile(\n                steps=[\n                    ClickStep(x=1, y=1, repeat=1, interval_ms=1),\n                    ClickStep(x=2, y=2, repeat=1, interval_ms=1, enabled=False),\n                ],\n                repeat=1,\n                start_delay_ms=0,\n            )\n        )\n        self.assertEqual([c[1] for c in backend.clicks], [1])\n\n    def test_coordinate_jitter_stays_in_range(self):\n        backend = FakeBackend()\n        engine = self._engine(backend)\n        engine.run(\n            Profile(\n                steps=[ClickStep(x=100, y=100, repeat=20, interval_ms=1, jitter_px=3)],\n                repeat=1,\n                start_delay_ms=0,\n            )\n        )\n        self.assertEqual(len(backend.clicks), 20)\n        for _, x, y, _ in backend.clicks:\n            self.assertIn(x, range(97, 104))\n            self.assertIn(y, range(97, 104))\n\n    def test_long_delay_can_be_interrupted(self):\n        """停在 5 秒的延时步骤里也必须能立刻被 F10 打断。"""\n        backend = FakeBackend()\n        engine = self._engine(backend)\n        engine.step_changed.connect(lambda index, total: engine.request_stop())\n\n        begin = time.perf_counter()\n        engine.run(\n            Profile(steps=[DelayStep(delay_ms=5000)], repeat=0, start_delay_ms=0)\n        )\n        elapsed = time.perf_counter() - begin\n\n        self.assertLess(elapsed, 1.0)\n        self.assertFalse(engine.running)\n\n    def test_infinite_repeat_until_stopped(self):\n        backend = FakeBackend()\n        engine = self._engine(backend)\n        engine.progress.connect(lambda actions, *_rest: engine.request_stop() if actions >= 3 else None)\n\n        begin = time.perf_counter()\n        engine.run(Profile(steps=[ClickStep(x=1, y=1, repeat=1, interval_ms=50)], repeat=0))\n        elapsed = time.perf_counter() - begin\n\n        self.assertGreaterEqual(len(backend.clicks), 3)\n        self.assertLess(elapsed, 3.0)\n\n    def test_invalid_profile_reports_failure(self):\n        backend = FakeBackend()\n        engine = self._engine(backend)\n        messages: list[str] = []\n        engine.failed.connect(messages.append)\n\n        engine.run(Profile(steps=[], repeat=1))  # 没有任何步骤\n\n        self.assertEqual(backend.events, [])\n        self.assertEqual(len(messages), 1)\n        self.assertFalse(engine.running)\n\n    def test_progress_signal_reports_rounds(self):\n        backend = FakeBackend()\n        engine = self._engine(backend)\n        seen: list[tuple[int, int, int]] = []\n        engine.progress.connect(lambda a, r, t: seen.append((a, r, t)))\n\n        engine.run(\n            Profile(steps=[ClickStep(x=1, y=1, repeat=2, interval_ms=1)], repeat=3, start_delay_ms=0)\n        )\n\n        self.assertTrue(seen)\n        self.assertEqual(seen[-1][1], 3, "最后一轮应报告已完成 3 轮")\n        self.assertEqual(seen[-1][2], 3, "总轮数应为 3")\n\n    # ---------------------------------------------------------------- 移动轨迹\n    def test_move_step_interpolates_along_polyline(self):\n        """轨迹步骤要在起点和终点之间真的插值，而不是一步跳过去。"""\n        backend = FakeBackend()\n        engine = self._engine(backend)\n        engine.run(\n            Profile(\n                steps=[MoveStep(points=[(0, 0), (100, 0), (100, 100)], duration_ms=80)],\n                repeat=1,\n                start_delay_ms=0,\n            )\n        )\n\n        moves = [event for event in backend.events if event[0] == "move"]\n        self.assertGreater(len(moves), 3, "应当产生一串中间点")\n        self.assertEqual(moves[-1][1:], (100, 100), "最后必须精确落在终点")\n        self.assertTrue(\n            any(x == 100 and 0 < y < 100 for _, x, y in moves),\n            "折线第二段（竖直方向）应当被走到",\n        )\n        self.assertNotIn("click", backend.kinds)\n\n    def test_move_step_with_single_point_is_instant(self):\n        backend = FakeBackend()\n        engine = self._engine(backend)\n        engine.run(\n            Profile(\n                steps=[MoveStep(points=[(5, 6)], duration_ms=500)],\n                repeat=1,\n                start_delay_ms=0,\n            )\n        )\n        self.assertEqual(backend.events, [("move", 5, 6)])\n\n    def test_move_step_zero_duration_jumps_to_end(self):\n        """时长为 0 时不做插值，直接落到终点（避免忙循环）。"""\n        backend = FakeBackend()\n        engine = self._engine(backend)\n        begin = time.perf_counter()\n        engine.run(\n            Profile(\n                steps=[MoveStep(points=[(0, 0), (10, 0), (20, 0)], duration_ms=0)],\n                repeat=1,\n                start_delay_ms=0,\n            )\n        )\n        self.assertLess(time.perf_counter() - begin, 1.0)\n        self.assertEqual(backend.events, [("move", 20, 0)])\n\n    def test_move_step_is_interruptible(self):\n        """一条很长的轨迹也要能被 F10 立刻打断。"""\n        backend = FakeBackend()\n        engine = self._engine(backend)\n        engine.step_changed.connect(lambda index, total: engine.request_stop())\n\n        begin = time.perf_counter()\n        engine.run(\n            Profile(\n                steps=[MoveStep(points=[(0, 0), (5000, 0)], duration_ms=30000)],\n                repeat=0,\n                start_delay_ms=0,\n            )\n        )\n        self.assertLess(time.perf_counter() - begin, 1.0)\n        self.assertFalse(engine.running)\n\n    # ---------------------------------------------------------------- 找图\n    def _wait_step(self, **overrides):\n        params = {\n            "template": _button_template().encode(),\n            "timeout_ms": 500,\n            "poll_interval_ms": 20,\n        }\n        params.update(overrides)\n        return WaitStep(**params)\n\n    def _sequence(self, frames):\n        """按顺序吐帧：前面几帧没有目标，之后才出现目标。"""\n        pending = list(frames)\n        return lambda: pending.pop(0)\n\n    def test_wait_step_waits_then_clicks_the_center(self):\n        """目标出现前一直等，出现后点模板中心，坐标要带上虚拟屏幕原点。"""\n        backend = FakeBackend()\n        empty = _frame(200, 120, x=-1920, y=-200)\n        screen = self._sequence([empty, empty, _screen_with_button(origin=(-1920, -200))])\n        engine = self._engine(backend, screen=screen)\n\n        engine.run(Profile(steps=[self._wait_step()], repeat=1, start_delay_ms=0))\n\n        self.assertEqual(len(backend.clicks), 1)\n        _, x, y, button = backend.clicks[0]\n        self.assertEqual(\n            (x, y), (-1920 + BUTTON_AT[0] + 20, -200 + BUTTON_AT[1] + 10), "应点击模板中心"\n        )\n        self.assertIs(button, MouseButton.LEFT)\n\n    def test_wait_step_can_skip_clicking(self):\n        backend = FakeBackend()\n        engine = self._engine(backend, screen=_screen_with_button)\n\n        engine.run(Profile(steps=[self._wait_step(click=False)], repeat=1, start_delay_ms=0))\n\n        self.assertEqual(backend.events, [], "关掉点击后只等不点")\n\n    def test_wait_step_applies_click_offset(self):\n        backend = FakeBackend()\n        engine = self._engine(backend, screen=_screen_with_button)\n\n        engine.run(\n            Profile(\n                steps=[self._wait_step(button=MouseButton.RIGHT, offset_x=5, offset_y=-4)],\n                repeat=1,\n                start_delay_ms=0,\n            )\n        )\n\n        _, x, y, button = backend.clicks[0]\n        self.assertEqual((x, y), (BUTTON_AT[0] + 20 + 5, BUTTON_AT[1] + 10 - 4))\n        self.assertIs(button, MouseButton.RIGHT)\n\n    def test_wait_step_timeout_continues_by_default(self):\n        backend = FakeBackend()\n        engine = self._engine(backend, screen=lambda: _frame(200, 120))\n        dumps: list = []\n        engine.wait_timeout.connect(dumps.append)\n\n        engine.run(\n            Profile(\n                steps=[\n                    self._wait_step(timeout_ms=30),\n                    ClickStep(x=9, y=9, repeat=1, interval_ms=1),\n                ],\n                repeat=1,\n                start_delay_ms=0,\n            )\n        )\n\n        self.assertEqual([event[0] for event in backend.events], ["click"])\n        self.assertEqual(backend.clicks[0][1:3], (9, 9), "超时后应继续执行下一步")\n        self.assertEqual(dumps, [], "「继续」模式下不该每次超时都写截图")\n\n    def test_wait_step_timeout_stops_and_hands_over_last_frame(self):\n        backend = FakeBackend()\n        frame = _frame(200, 120)\n        engine = self._engine(backend, screen=lambda: frame)\n        failures: list[str] = []\n        dumps: list = []\n        engine.failed.connect(failures.append)\n        engine.wait_timeout.connect(dumps.append)\n\n        engine.run(\n            Profile(\n                steps=[\n                    self._wait_step(timeout_ms=30, on_timeout=ON_TIMEOUT_STOP),\n                    ClickStep(x=9, y=9, repeat=1, interval_ms=1),\n                ],\n                repeat=1,\n                start_delay_ms=0,\n            )\n        )\n\n        self.assertEqual(backend.events, [], "中止时后面的步骤不该再执行")\n        self.assertEqual(len(failures), 1)\n        self.assertIn("超时", failures[0])\n        self.assertEqual(len(dumps), 1, "中止时应把最后一帧交出去供落盘诊断")\n        self.assertIs(dumps[0], frame)\n\n    def test_wait_step_timeout_zero_searches_once(self):\n        """超时填 0 = 只找一次，不等待。"""\n        backend = FakeBackend()\n        calls: list[int] = []\n\n        def screen():\n            calls.append(1)\n            return _frame(200, 120)\n\n        engine = self._engine(backend, screen=screen)\n        engine.run(Profile(steps=[self._wait_step(timeout_ms=0)], repeat=1, start_delay_ms=0))\n\n        self.assertEqual(len(calls), 1)\n        self.assertEqual(backend.events, [])\n\n    def test_wait_step_is_interruptible(self):\n        """一个上限 60 秒的等待也必须能被 F10 立刻打断。"""\n        backend = FakeBackend()\n        engine = self._engine(backend, screen=lambda: _frame(200, 120))\n        engine.step_changed.connect(lambda index, total: engine.request_stop())\n\n        begin = time.perf_counter()\n        engine.run(\n            Profile(steps=[self._wait_step(timeout_ms=60000)], repeat=0, start_delay_ms=0)\n        )\n\n        self.assertLess(time.perf_counter() - begin, 1.0)\n        self.assertEqual(backend.events, [])\n        self.assertFalse(engine.running)\n\n    def test_wait_step_reports_capture_failure(self):\n        def broken():\n            raise OSError("被系统拒绝")\n\n        backend = FakeBackend()\n        engine = self._engine(backend, screen=broken)\n        failures: list[str] = []\n        engine.failed.connect(failures.append)\n\n        engine.run(Profile(steps=[self._wait_step()], repeat=1, start_delay_ms=0))\n\n        self.assertEqual(len(failures), 1)\n        self.assertIn("抓取屏幕", failures[0])\n        self.assertFalse(engine.running)\n\n    def test_engine_switches_backend_only_when_idle(self):\n        """前端可在 start 前换后端；运行途中必须拒绝，免得同一次运行混用两种注入。"""\n        from app.core.engine import MacroEngine\n\n        engine = MacroEngine(FakeBackend())\n        other = FakeBackend()\n        engine.set_backend(other)\n        self.assertIs(engine._backend, other)\n\n        engine._running = True\n        try:\n            with self.assertRaises(RuntimeError):\n                engine.set_backend(FakeBackend())\n        finally:\n            engine._running = False\n\n\n# ==================================================================== 录制转换\ndef _down(t, x=0, y=0, button="left"):\n    return InputEvent("click", t, x=x, y=y, button=button, is_down=True)\n\n\ndef _up(t, x=0, y=0, button="left"):\n    return InputEvent("click", t, x=x, y=y, button=button, is_down=False)\n\n\ndef _kdown(t, vk):\n    return InputEvent("key", t, vk=vk, is_down=True)\n\n\ndef _kup(t, vk):\n    return InputEvent("key", t, vk=vk, is_down=False)\n\n\ndef _move(t, x, y):\n    return InputEvent("move", t, x=x, y=y)\n\n\nclass TestRecording(unittest.TestCase):\n    """录制事件 → 方案步骤的转换规则。"""\n\n    def _build(self, events, **kwargs):\n        from app.core.recording import RecordSettings, build_profile\n\n        return build_profile(events, name="测试录制", settings=RecordSettings(**kwargs))\n\n    def test_single_click_becomes_one_step(self):\n        profile = self._build([_down(1.0, 10, 20), _up(1.05, 10, 20)])\n        self.assertEqual(len(profile.steps), 1)\n        step = profile.steps[0]\n        self.assertIsInstance(step, ClickStep)\n        self.assertEqual((step.x, step.y), (10, 20))\n        self.assertEqual(step.repeat, 1)\n        self.assertIs(step.button, MouseButton.LEFT)\n        profile.validate()  # 生成结果必须能直接回放\n\n    def test_click_uses_press_position(self):\n        """坐标取「按下」那一刻，抬起时手指/鼠标可能已经飘了。"""\n        profile = self._build([_down(1.0, 10, 20), _up(1.05, 13, 27)])\n        step = profile.steps[0]\n        self.assertEqual((step.x, step.y), (10, 20))\n\n    def test_adjacent_clicks_merge_into_repeat(self):\n        """连点两下同一个点 = 一个 repeat=2 的步骤，而不是两个步骤。"""\n        profile = self._build(\n            [\n                _down(1.00, 10, 20),\n                _up(1.05, 10, 20),\n                _down(1.15, 11, 20),  # 有 1px 抖动，仍应合并\n                _up(1.20, 11, 20),\n            ]\n        )\n        self.assertEqual(len(profile.steps), 1)\n        step = profile.steps[0]\n        self.assertIsInstance(step, ClickStep)\n        self.assertEqual(step.repeat, 2)\n        self.assertEqual(step.interval_ms, 150)\n\n    def test_distant_clicks_do_not_merge(self):\n        profile = self._build(\n            [\n                _down(1.00, 10, 20),\n                _up(1.05, 10, 20),\n                _down(1.10, 400, 500),\n                _up(1.15, 400, 500),\n            ]\n        )\n        clicks = [s for s in profile.steps if isinstance(s, ClickStep)]\n        self.assertEqual(len(clicks), 2)\n        self.assertEqual(clicks[1].repeat, 1)\n\n    def test_slow_clicks_do_not_merge(self):\n        """间隔超过 merge_max_gap_ms 就当成两次独立点击（中间还会有延时步骤）。"""\n        profile = self._build(\n            [\n                _down(1.0, 10, 20),\n                _up(1.05, 10, 20),\n                _down(3.0, 10, 20),\n                _up(3.05, 10, 20),\n            ]\n        )\n        clicks = [s for s in profile.steps if isinstance(s, ClickStep)]\n        self.assertEqual(len(clicks), 2)\n        self.assertGreaterEqual(len([s for s in profile.steps if isinstance(s, DelayStep)]), 1)\n\n    def test_gap_becomes_delay_step(self):\n        profile = self._build(\n            [\n                _down(1.0, 10, 10),\n                _up(1.05, 10, 10),\n                _down(1.5, 500, 500),\n                _up(1.55, 500, 500),\n            ]\n        )\n        delays = [s for s in profile.steps if isinstance(s, DelayStep)]\n        self.assertEqual(len(delays), 1)\n        self.assertEqual(delays[0].delay_ms, 450)\n        self.assertEqual([type(s) for s in profile.steps], [ClickStep, DelayStep, ClickStep])\n\n    def test_short_gap_does_not_become_delay(self):\n        """小于 min_delay_ms 的间隔不值得单独占一行。"""\n        profile = self._build(\n            [\n                _down(1.000, 10, 10),\n                _up(1.005, 10, 10),\n                _down(1.020, 10, 10),\n                _up(1.025, 10, 10),\n            ],\n            merge_max_gap_ms=1,\n        )\n        self.assertEqual([type(s) for s in profile.steps], [ClickStep, ClickStep])\n\n    def test_key_press_becomes_key_step(self):\n        profile = self._build([_kdown(2.0, 0x41), _kup(2.05, 0x41)])\n        self.assertEqual(len(profile.steps), 1)\n        step = profile.steps[0]\n        self.assertIsInstance(step, KeyStep)\n        self.assertEqual(step.vk, 0x41)\n        self.assertEqual(step.repeat, 1)\n\n    def test_auto_repeat_keydowns_are_ignored(self):\n        """按住不放会产生一串 WM_KEYDOWN，只能记一次。"""\n        profile = self._build(\n            [\n                _kdown(2.00, 0x41),\n                _kdown(2.03, 0x41),\n                _kdown(2.06, 0x41),\n                _kup(2.09, 0x41),\n                _kdown(2.10, 0x41),\n                _kup(2.15, 0x41),\n            ]\n        )\n        keys = [s for s in profile.steps if isinstance(s, KeyStep)]\n        self.assertEqual(len(keys), 1)\n        self.assertEqual(keys[0].repeat, 2)\n        self.assertEqual(keys[0].interval_ms, 100)\n\n    def test_key_still_held_at_end_is_kept(self):\n        """录制结束时还按着键，也不能把这次按键整段丢掉。"""\n        profile = self._build([_kdown(2.0, 0x41)])\n        keys = [s for s in profile.steps if isinstance(s, KeyStep)]\n        self.assertEqual(len(keys), 1)\n        self.assertEqual(keys[0].vk, 0x41)\n\n    def test_click_without_release_is_dropped(self):\n        """只有按下没有抬起（异常序列）时忽略，而不是崩掉。"""\n        profile = self._build([_down(1.0, 10, 20)])\n        self.assertEqual(profile.steps, [])\n\n    # ---------------------------------------------------------------- 轨迹\n    def test_moves_collapse_into_single_trajectory_step(self):\n        profile = self._build(\n            [_move(1.00, 0, 0), _move(1.01, 5, 0), _move(1.02, 20, 0), _move(1.03, 40, 0)]\n        )\n        self.assertEqual(len(profile.steps), 1)\n        step = profile.steps[0]\n        self.assertIsInstance(step, MoveStep)\n        self.assertEqual(step.points[0], (0, 0))\n        self.assertEqual(step.points[-1], (40, 0))\n        self.assertLess(len(step.points), 4, "抖动点应被抽稀")\n        self.assertEqual(step.duration_ms, 30)\n\n    def test_tiny_movement_is_dropped(self):\n        """2px 的手抖不该产生一个步骤。"""\n        profile = self._build([_move(1.00, 0, 0), _move(1.01, 1, 0), _move(1.02, 2, 0)])\n        self.assertEqual(profile.steps, [])\n\n    def test_moves_can_be_disabled(self):\n        profile = self._build(\n            [_move(1.00, 0, 0), _move(1.02, 80, 0), _down(1.10, 80, 0), _up(1.15, 80, 0)],\n            record_moves=False,\n        )\n        self.assertEqual([type(s) for s in profile.steps], [ClickStep])\n\n    def test_move_precedes_the_click_that_ends_it(self):\n        profile = self._build(\n            [_move(1.00, 0, 0), _move(1.05, 60, 0), _down(1.10, 60, 0), _up(1.15, 60, 0)]\n        )\n        self.assertEqual(\n            [type(s) for s in profile.steps if not isinstance(s, DelayStep)],\n            [MoveStep, ClickStep],\n        )\n\n    def test_trajectory_can_be_interrupted_by_key(self):\n        profile = self._build(\n            [\n                _move(1.00, 0, 0),\n                _move(1.05, 60, 0),\n                _kdown(1.10, 0x0D),\n                _kup(1.15, 0x0D),\n                _move(1.20, 60, 0),\n                _move(1.25, 120, 0),\n            ]\n        )\n        self.assertEqual(\n            [type(s) for s in profile.steps if not isinstance(s, DelayStep)],\n            [MoveStep, KeyStep, MoveStep],\n        )\n        self.assertGreaterEqual(\n            len([s for s in profile.steps if isinstance(s, DelayStep)]), 1\n        )\n\n    def test_recording_gets_a_start_delay(self):\n        from app.core.recording import RECORDING_START_DELAY_MS\n\n        profile = self._build([_down(1.0, 1, 1), _up(1.05, 1, 1)])\n        self.assertEqual(profile.start_delay_ms, RECORDING_START_DELAY_MS)\n        self.assertEqual(profile.repeat, 1)\n\n    def test_summarize_is_readable(self):\n        from app.core.recording import summarize\n\n        profile = self._build(\n            [\n                _down(1.00, 10, 10),\n                _up(1.05, 10, 10),\n                _kdown(1.50, 0x41),\n                _kup(1.55, 0x41),\n            ]\n        )\n        text = summarize(profile)\n        self.assertIn("点击 1 个", text)\n        self.assertIn("按键 1 个", text)\n        self.assertEqual(summarize(Profile()), "没有记录到任何动作")\n\n    def test_empty_recording_produces_empty_profile(self):\n        profile = self._build([])\n        self.assertEqual(profile.steps, [])\n\n\n# ==================================================================== Win32 钩子\nclass TestHooks(unittest.TestCase):\n    """真实安装一次低级钩子，验证 ctypes 声明和回调引用都是对的。"""\n\n    def test_install_and_unhook(self):\n        from app.win.hooks import InputRecorder\n\n        recorder = InputRecorder()\n        self.assertFalse(recorder.recording)\n        try:\n            self.assertTrue(recorder.start(swallow=True, passthrough_vks=[0x79]))\n        except OSError as exc:  # pragma: no cover - 受限环境\n            self.skipTest(f"当前环境无法安装低级钩子: {exc}")\n\n        self.assertTrue(recorder.recording)\n        self.assertTrue(recorder.swallow)\n        events = recorder.stop()\n        self.assertFalse(recorder.recording)\n        self.assertEqual(events, [])\n        self.assertEqual(recorder.action_count, 0)\n\n    def test_stop_without_start_is_safe(self):\n        from app.win.hooks import InputRecorder\n\n        recorder = InputRecorder()\n        self.assertEqual(recorder.stop(), [])\n        self.assertFalse(recorder.recording)\n\n    def test_double_start_is_rejected(self):\n        from app.win.hooks import InputRecorder\n\n        recorder = InputRecorder()\n        try:\n            self.assertTrue(recorder.start())\n        except OSError as exc:  # pragma: no cover - 受限环境\n            self.skipTest(f"当前环境无法安装低级钩子: {exc}")\n        try:\n            self.assertFalse(recorder.start())\n        finally:\n            recorder.stop()\n\n    def test_control_hotkeys_are_not_recorded(self):\n        """F8/F9/F10/F11 是工具自己的控制键，不能混进录制的宏里。"""\n        from app.win.hooks import WM_KEYDOWN, WM_KEYUP, InputRecorder\n\n        recorder = InputRecorder()\n        recorder._passthrough_vks = {0x79}  # F10\n        recorder._handle_key(WM_KEYDOWN, 0x79)\n        recorder._handle_key(WM_KEYUP, 0x79)\n        recorder._handle_key(WM_KEYDOWN, 0x41)\n        recorder._handle_key(WM_KEYUP, 0x41)\n\n        self.assertEqual([event.vk for event in recorder.events], [0x41, 0x41])\n        self.assertEqual(recorder.action_count, 1)\n\n    def test_auto_repeat_is_recorded_once(self):\n        """按住不放只会产生一串 WM_KEYDOWN，动作计数只能加一次。"""\n        from app.win.hooks import WM_KEYDOWN, WM_KEYUP, InputRecorder\n\n        recorder = InputRecorder()\n        for _ in range(5):\n            recorder._handle_key(WM_KEYDOWN, 0x41)\n        recorder._handle_key(WM_KEYUP, 0x41)\n\n        self.assertEqual(recorder.action_count, 1)\n        self.assertEqual(len(recorder.events), 2)\n\n    def test_click_counts_as_one_action(self):\n        from app.win.hooks import (\n            WM_LBUTTONDOWN,\n            WM_LBUTTONUP,\n            WM_MOUSEMOVE,\n            InputRecorder,\n        )\n\n        recorder = InputRecorder()\n        recorder._handle_mouse(WM_MOUSEMOVE, 1, 2)\n        recorder._handle_mouse(WM_MOUSEMOVE, 3, 4)\n        recorder._handle_mouse(WM_LBUTTONDOWN, 5, 6)\n        recorder._handle_mouse(WM_LBUTTONUP, 5, 6)\n\n        self.assertEqual(recorder.action_count, 1, "按下+抬起算一个动作")\n        self.assertEqual(recorder.move_count, 2)\n        kinds = [event.kind for event in recorder.events]\n        self.assertEqual(kinds, ["move", "move", "click", "click"])\n        self.assertTrue(recorder.events[2].is_down)\n        self.assertFalse(recorder.events[3].is_down)\n\n    def test_passthrough_hotkeys_are_kept_by_start(self):\n        from app.win.hooks import InputRecorder\n\n        recorder = InputRecorder()\n        try:\n            self.assertTrue(recorder.start(swallow=False, passthrough_vks=[0x78, 0x79]))\n        except OSError as exc:  # pragma: no cover - 受限环境\n            self.skipTest(f"当前环境无法安装低级钩子: {exc}")\n        try:\n            self.assertEqual(recorder._passthrough_vks, {0x78, 0x79})\n            self.assertFalse(recorder.swallow)\n        finally:\n            recorder.stop()\n\n    # ---------------------------------------------------------------- 钩子回调\n    # 直接调用钩子过程，绕开真实钩子，验证「吃事件 / 放行」的判定逻辑。\n    def _mouse_struct(self, x, y, flags=0):\n        from app.win.hooks import MSLLHOOKSTRUCT\n\n        struct = MSLLHOOKSTRUCT()\n        struct.pt.x = x\n        struct.pt.y = y\n        struct.flags = flags\n        return struct\n\n    def _key_struct(self, vk, flags=0):\n        from app.win.hooks import KBDLLHOOKSTRUCT\n\n        struct = KBDLLHOOKSTRUCT()\n        struct.vkCode = vk\n        struct.flags = flags\n        return struct\n\n    def test_mouse_hook_records_and_swallows(self):\n        from app.win.hooks import (\n            LLMHF_INJECTED,\n            WM_LBUTTONDOWN,\n            WM_MOUSEMOVE,\n            InputRecorder,\n        )\n\n        recorder = InputRecorder()\n        recorder._recording = True\n        recorder._swallow = True\n\n        move = self._mouse_struct(11, 22)\n        self.assertEqual(recorder._mouse_hook_proc(0, WM_MOUSEMOVE, ctypes.addressof(move)), 1)\n        self.assertEqual(recorder.move_count, 1)\n\n        down = self._mouse_struct(33, 44)\n        self.assertEqual(recorder._mouse_hook_proc(0, WM_LBUTTONDOWN, ctypes.addressof(down)), 1)\n        self.assertEqual(recorder.action_count, 1)\n        self.assertEqual((recorder.events[-1].x, recorder.events[-1].y), (33, 44))\n\n        # 注入事件必须放行且不记录，否则回放会把自己录进去、也会和其它工具打架\n        injected = self._mouse_struct(55, 66, flags=LLMHF_INJECTED)\n        self.assertEqual(\n            recorder._mouse_hook_proc(0, WM_LBUTTONDOWN, ctypes.addressof(injected)), 0\n        )\n        self.assertEqual(recorder.action_count, 1)\n        self.assertEqual(recorder.move_count, 1)\n\n    def test_mouse_hook_passes_through_when_not_swallowing(self):\n        from app.win.hooks import WM_LBUTTONDOWN, InputRecorder\n\n        recorder = InputRecorder()\n        recorder._recording = True\n        recorder._swallow = False\n\n        down = self._mouse_struct(1, 2)\n        self.assertEqual(recorder._mouse_hook_proc(0, WM_LBUTTONDOWN, ctypes.addressof(down)), 0)\n        self.assertEqual(recorder.action_count, 1, "不屏蔽时依然要记录")\n\n    def test_key_hook_passes_control_hotkeys(self):\n        from app.win.hooks import LLKHF_INJECTED, WM_KEYDOWN, WM_SYSKEYDOWN, InputRecorder\n\n        recorder = InputRecorder()\n        recorder._recording = True\n        recorder._swallow = True\n        recorder._passthrough_vks = {0x79}  # F10\n\n        hotkey = self._key_struct(0x79)\n        self.assertEqual(\n            recorder._key_hook_proc(0, WM_KEYDOWN, ctypes.addressof(hotkey)), 0,\n            "控制热键必须放行，否则 RegisterHotKey 收不到、录制停不下来",\n        )\n        self.assertEqual(recorder.action_count, 0, "控制热键不该被录进宏里")\n\n        alt_enter = self._key_struct(0x0D)\n        self.assertEqual(\n            recorder._key_hook_proc(0, WM_SYSKEYDOWN, ctypes.addressof(alt_enter)), 1,\n            "Alt+Enter 这类系统按键同样要能被录",\n        )\n        self.assertEqual(recorder.action_count, 1)\n\n        injected = self._key_struct(0x41, flags=LLKHF_INJECTED)\n        self.assertEqual(recorder._key_hook_proc(0, WM_KEYDOWN, ctypes.addressof(injected)), 0)\n        self.assertEqual(recorder.action_count, 1)\n\n    def test_hook_proc_survives_recorder_errors(self):\n        """钩子里抛异常会让系统摘掉钩子，所以必须吞掉记录过程中的任何错误。"""\n        from app.win.hooks import WM_LBUTTONDOWN, InputRecorder\n\n        recorder = InputRecorder()\n        recorder._recording = True\n        recorder._swallow = True\n\n        def boom(*_args):\n            raise RuntimeError("模拟记录失败")\n\n        recorder._handle_mouse = boom\n        down = self._mouse_struct(1, 2)\n        self.assertEqual(\n            recorder._mouse_hook_proc(0, WM_LBUTTONDOWN, ctypes.addressof(down)), 1\n        )\n\n    def test_hook_proc_ignores_negative_code(self):\n        """n_code < 0 表示必须原样传给下一个钩子，不能做任何处理。"""\n        from app.win.hooks import WM_LBUTTONDOWN, InputRecorder\n\n        recorder = InputRecorder()\n        recorder._recording = True\n        recorder._swallow = True\n        down = self._mouse_struct(1, 2)\n        self.assertEqual(\n            recorder._mouse_hook_proc(-1, WM_LBUTTONDOWN, ctypes.addressof(down)), 0\n        )\n        self.assertEqual(recorder.events, [])\n\n\n# ==================================================================== UI 装配\nclass TestUI(unittest.TestCase):\n    @classmethod\n    def setUpClass(cls):\n        from PySide6.QtWidgets import QApplication\n\n        cls.app = QApplication.instance() or QApplication([])\n\n    def test_step_editor_crud(self):\n        from app.ui.position_picker import PickCoordinator\n        from app.ui.step_editor import StepEditor\n\n        editor = StepEditor(PickCoordinator())\n        try:\n            editor.set_steps(\n                [ClickStep(x=1, y=1), DelayStep(delay_ms=5), KeyStep(vk=0x41)]\n            )\n            self.assertEqual(editor._table.rowCount(), 3)\n            self.assertEqual(len(editor.steps()), 3)\n\n            # 上移/下移\n            editor.select_row(0)\n            editor.move_selected(1)\n            self.assertIsInstance(editor.steps()[1], ClickStep)\n\n            # F8 回写坐标\n            row = next(\n                index for index, step in enumerate(editor.steps()) if isinstance(step, ClickStep)\n            )\n            self.assertTrue(editor.update_click_coords(row, 777, 888))\n            step = editor.step_at(row)\n            self.assertEqual((step.x, step.y), (777, 888))\n\n            # 非点击步骤拒绝写入坐标\n            delay_row = next(\n                index for index, step in enumerate(editor.steps()) if isinstance(step, DelayStep)\n            )\n            self.assertFalse(editor.update_click_coords(delay_row, 1, 1))\n\n            # 取消勾选会改变 enabled\n            item = editor._table.item(row, 0)\n            item.setCheckState(Qt.CheckState.Unchecked)\n            self.assertFalse(editor.step_at(row).enabled)\n        finally:\n            editor.deleteLater()\n\n    def test_step_dialog_pick_roundtrip(self):\n        """对话框点「拾取坐标」时应先隐藏自己，拾取后自动恢复并回填坐标。"""\n        from app.ui.position_picker import PickCoordinator\n        from app.ui.step_dialog import StepDialog\n\n        picker = PickCoordinator()\n        dialog = StepDialog(ClickStep(x=1, y=2), picker)\n        try:\n            dialog.show()\n            self.assertTrue(dialog.isVisible())\n\n            dialog.start_pick()\n            self.assertFalse(dialog.isVisible(), "取点时对话框必须让开，否则会挡住目标位置")\n            self.assertTrue(picker.busy)\n\n            picker._picker.picked.emit(321, 654)  # 模拟鼠标左键拾取\n            self.assertTrue(dialog.isVisible(), "拾取后应恢复对话框")\n            self.assertFalse(picker.busy)\n\n            step = dialog.result_step()\n            self.assertEqual((step.x, step.y), (321, 654))\n            self.assertIs(step.button, MouseButton.LEFT)\n            self.assertIn("左键", step.summary(), "按键应显示中文，而不是枚举的原始值")\n        finally:\n            dialog.deleteLater()\n\n    def test_step_dialog_cancel_pick_restores_dialog(self):\n        from app.ui.position_picker import PickCoordinator\n        from app.ui.step_dialog import StepDialog\n\n        picker = PickCoordinator()\n        dialog = StepDialog(ClickStep(x=7, y=8), picker)\n        try:\n            dialog.show()\n            dialog.start_pick()\n            picker._picker.canceled.emit()\n\n            self.assertTrue(dialog.isVisible())\n            self.assertEqual((dialog.result_step().x, dialog.result_step().y), (7, 8))\n        finally:\n            dialog.deleteLater()\n\n    def test_non_click_dialog_ignores_pick(self):\n        from app.ui.position_picker import PickCoordinator\n        from app.ui.step_dialog import StepDialog\n\n        picker = PickCoordinator()\n        dialog = StepDialog(DelayStep(delay_ms=5), picker)\n        try:\n            dialog.show()\n            dialog.start_pick()\n            self.assertFalse(picker.busy, "延时步骤没有坐标可填，不应启动遮罩")\n            self.assertTrue(dialog.isVisible())\n        finally:\n            dialog.deleteLater()\n\n    def test_step_editor_supports_move_steps(self):\n        from unittest import mock\n\n        from app.ui.position_picker import PickCoordinator\n        from app.ui.step_editor import StepEditor\n\n        editor = StepEditor(PickCoordinator())\n        try:\n            editor.set_steps([])\n            # add_step 会弹出模态编辑框；测试里直接放行，只验证默认值的构造\n            with mock.patch.object(StepEditor, "_open_dialog", lambda self, step: step):\n                editor.add_step(StepKind.MOVE)\n            self.assertEqual(len(editor.steps()), 1)\n            step = editor.steps()[0]\n            self.assertIsInstance(step, MoveStep)\n            step.validate()\n\n            # 移动步骤：F8 改的是终点，起点保留、拐点拉直\n            step.points = [(10, 10), (50, 50), (90, 20)]\n            self.assertTrue(editor.update_click_coords(0, 400, 300))\n            self.assertEqual(editor.step_at(0).points, [(10, 10), (400, 300)])\n\n            # 空轨迹也能被拾取成一个单点移动\n            editor.step_at(0).points = []\n            self.assertTrue(editor.update_click_coords(0, 7, 8))\n            self.assertEqual(editor.step_at(0).points, [(7, 8)])\n        finally:\n            editor.deleteLater()\n\n    def test_move_dialog_pick_replaces_endpoint(self):\n        from app.ui.position_picker import PickCoordinator\n        from app.ui.step_dialog import StepDialog\n\n        picker = PickCoordinator()\n        dialog = StepDialog(MoveStep(points=[(10, 10), (50, 50), (90, 20)], duration_ms=700), picker)\n        try:\n            dialog.show()\n            dialog.start_pick()\n            self.assertTrue(picker.busy, "移动步骤也要能取点")\n            picker._picker.picked.emit(400, 300)\n\n            step = dialog.result_step()\n            self.assertIsInstance(step, MoveStep)\n            self.assertEqual(step.points, [(10, 10), (400, 300)], "起点保留，终点换成拾取点")\n            self.assertEqual(step.duration_ms, 700, "时长不应被取点改动")\n        finally:\n            dialog.deleteLater()\n\n    def test_move_dialog_without_points_shows_hint(self):\n        from app.ui.position_picker import PickCoordinator\n        from app.ui.step_dialog import StepDialog\n\n        dialog = StepDialog(MoveStep(points=[], duration_ms=100), PickCoordinator())\n        try:\n            self.assertIn("拾取", dialog._path_label.text())\n        finally:\n            dialog.deleteLater()\n\n    def test_pick_position_accepts_move_and_rejects_delay(self):\n        """主窗口的 F8 也要能改轨迹终点，但延时/按键步骤没有坐标可改。"""\n        from app.input.sendinput import SendInputBackend\n        from app.storage.config import ProfileStore\n        from app.ui.main_window import MainWindow\n        from app.win.hotkey import HotkeyManager\n\n        with tempfile.TemporaryDirectory() as tmp:\n            store = ProfileStore(Path(tmp))\n            window = MainWindow(SendInputBackend(), HotkeyManager(self.app), store=store)\n            try:\n                window._editor.set_steps([DelayStep(delay_ms=5)])\n                window._editor.select_row(0)\n                window.pick_position()\n                self.assertFalse(window._picker.busy, "延时步骤不该启动取点遮罩")\n\n                window._editor.set_steps([MoveStep(points=[(1, 1), (2, 2)], duration_ms=100)])\n                window._editor.select_row(0)\n                window.pick_position()\n                self.assertTrue(window._picker.busy)\n\n                window._picker._picker.picked.emit(500, 600)\n                self.assertEqual(window._editor.step_at(0).points, [(1, 1), (500, 600)])\n                self.assertFalse(window._picker.busy)\n            finally:\n                window._shutdown()\n                self.app.processEvents()\n\n    def test_recording_flow_appends_steps(self):\n        """F11 开始录制 → F10 结束 → 录到的动作进步骤表。"""\n        from app.input.sendinput import SendInputBackend\n        from app.storage.config import ProfileStore\n        from app.ui.main_window import HK_RECORD, HK_START, HK_STOP, MainWindow\n        from app.win.hotkey import HotkeyManager\n\n        with tempfile.TemporaryDirectory() as tmp:\n            store = ProfileStore(Path(tmp))\n            window = MainWindow(SendInputBackend(), HotkeyManager(self.app), store=store)\n            try:\n                before = len(window._editor.steps())\n\n                window._hotkey_ready[HK_STOP] = True\n                window._on_hotkey(HK_RECORD)\n                self.assertTrue(window._record.recording)\n                self.assertTrue(window._record.recorder.recording)\n                self.assertFalse(window._record_button.isEnabled())\n                self.assertTrue(window._stop_button.isEnabled())\n\n                # 录制中其它热键应被忽略\n                window._on_hotkey(HK_START)\n                self.assertFalse(window._run.running)\n\n                # 冒充两条已录到的事件\n                window._record.recorder._events.extend(\n                    [_down(1.0, 11, 22), _up(1.05, 11, 22)]\n                )\n                window._record.recorder._action_count = 1\n\n                window._record.ask_how_to_apply = lambda summary: "append"\n                window._on_hotkey(HK_STOP)\n\n                self.assertFalse(window._record.recording)\n                self.assertFalse(window._record.recorder.recording)\n                self.assertFalse(window._record.overlay.isVisible())\n                self.assertGreater(len(window._editor.steps()), before)\n\n                appended = window._editor.steps()[-1]\n                self.assertIsInstance(appended, ClickStep)\n                self.assertEqual((appended.x, appended.y), (11, 22))\n                self.assertTrue(window._record_button.isEnabled())\n            finally:\n                window._shutdown()\n                self.app.processEvents()\n\n    def test_recording_flow_can_replace_steps(self):\n        from app.input.sendinput import SendInputBackend\n        from app.storage.config import ProfileStore\n        from app.ui.main_window import HK_STOP, MainWindow\n        from app.win.hotkey import HotkeyManager\n\n        with tempfile.TemporaryDirectory() as tmp:\n            store = ProfileStore(Path(tmp))\n            window = MainWindow(SendInputBackend(), HotkeyManager(self.app), store=store)\n            try:\n                window._hotkey_ready[HK_STOP] = True\n                window.start_recording()\n                window._record.recorder._events.extend([_down(1.0, 5, 5), _up(1.05, 5, 5)])\n                window._record.ask_how_to_apply = lambda summary: "replace"\n                window.stop_recording()\n\n                steps = window._editor.steps()\n                self.assertEqual(len(steps), 1)\n                self.assertEqual((steps[0].x, steps[0].y), (5, 5))\n            finally:\n                window._shutdown()\n                self.app.processEvents()\n\n    def test_recording_flow_can_discard(self):\n        from app.input.sendinput import SendInputBackend\n        from app.storage.config import ProfileStore\n        from app.ui.main_window import HK_STOP, MainWindow\n        from app.win.hotkey import HotkeyManager\n\n        with tempfile.TemporaryDirectory() as tmp:\n            store = ProfileStore(Path(tmp))\n            window = MainWindow(SendInputBackend(), HotkeyManager(self.app), store=store)\n            try:\n                window._hotkey_ready[HK_STOP] = True\n                before = [step.to_dict() for step in window._editor.steps()]\n                window.start_recording()\n                window._record.recorder._events.extend([_down(1.0, 5, 5), _up(1.05, 5, 5)])\n                window._record.ask_how_to_apply = lambda summary: "discard"\n                window.stop_recording()\n                self.assertEqual([step.to_dict() for step in window._editor.steps()], before)\n            finally:\n                window._shutdown()\n                self.app.processEvents()\n\n    def test_recording_ignores_empty_capture(self):\n        """什么都没录到时只提示，绝不清空用户已有的步骤。"""\n        from unittest import mock\n\n        from app.input.sendinput import SendInputBackend\n        from app.storage.config import ProfileStore\n        from app.ui.main_window import HK_STOP, MainWindow\n        from app.win.hotkey import HotkeyManager\n\n        with tempfile.TemporaryDirectory() as tmp:\n            store = ProfileStore(Path(tmp))\n            window = MainWindow(SendInputBackend(), HotkeyManager(self.app), store=store)\n            try:\n                window._hotkey_ready[HK_STOP] = True\n                before = len(window._editor.steps())\n                window.start_recording()\n                with mock.patch("app.ui.recording_controller.QMessageBox") as box:\n                    window.stop_recording()\n                self.assertEqual(len(window._editor.steps()), before)\n                self.assertFalse(window._record.recording)\n                self.assertFalse(window._record.overlay.isVisible())\n                self.assertEqual(box.information.call_count, 1)\n                self.assertEqual(box.question.call_count, 0)\n            finally:\n                window._shutdown()\n                self.app.processEvents()\n\n    def test_recording_is_refused_without_stop_hotkey(self):\n        """「屏蔽输入」下 F10 不可用时必须拒绝开录，否则用户会被锁在点不动的系统里。"""\n        from unittest import mock\n\n        from app.input.sendinput import SendInputBackend\n        from app.storage.config import ProfileStore\n        from app.ui.main_window import HK_STOP, MainWindow\n        from app.win.hotkey import HotkeyManager\n\n        with tempfile.TemporaryDirectory() as tmp:\n            store = ProfileStore(Path(tmp))\n            window = MainWindow(SendInputBackend(), HotkeyManager(self.app), store=store)\n            try:\n                window._hotkey_ready[HK_STOP] = False\n                window._record_swallow_check.setChecked(True)\n                with mock.patch("app.ui.recording_controller.QMessageBox") as box:\n                    window.start_recording()\n\n                self.assertFalse(window._record.recording)\n                self.assertFalse(window._record.recorder.recording)\n                self.assertEqual(box.warning.call_count, 1)\n            finally:\n                window._shutdown()\n                self.app.processEvents()\n\n    def test_recording_without_swallow_only_warns_without_stop_hotkey(self):\n        """不屏蔽输入时 F10 只是「方便」，缺了也能录（还可以从托盘结束）。"""\n        from unittest import mock\n\n        from app.input.sendinput import SendInputBackend\n        from app.storage.config import ProfileStore\n        from app.ui.main_window import HK_STOP, MainWindow\n        from app.win.hotkey import HotkeyManager\n\n        with tempfile.TemporaryDirectory() as tmp:\n            store = ProfileStore(Path(tmp))\n            window = MainWindow(SendInputBackend(), HotkeyManager(self.app), store=store)\n            try:\n                window._hotkey_ready[HK_STOP] = False\n                with mock.patch("app.ui.recording_controller.QMessageBox") as box:\n                    window.start_recording()\n\n                self.assertTrue(window._record.recording)\n                self.assertTrue(window._record.recorder.recording)\n                self.assertFalse(window._record.recorder.swallow)\n                box.warning.assert_not_called()\n\n                window._record.recorder._events.extend([_down(1.0, 1, 1), _up(1.05, 1, 1)])\n                window._record.ask_how_to_apply = lambda summary: "discard"\n                window.toggle_recording()\n                self.assertFalse(window._record.recording)\n            finally:\n                window._shutdown()\n                self.app.processEvents()\n\n    def test_recording_swallow_mode_is_honoured(self):\n        """勾了「屏蔽输入」，钩子就必须真的吃掉事件。"""\n        from app.input.sendinput import SendInputBackend\n        from app.storage.config import ProfileStore\n        from app.ui.main_window import MainWindow\n        from app.win.hotkey import HotkeyManager\n\n        with tempfile.TemporaryDirectory() as tmp:\n            store = ProfileStore(Path(tmp))\n            window = MainWindow(SendInputBackend(), HotkeyManager(self.app), store=store)\n            try:\n                window._hotkey_ready[2] = True\n                window._record_swallow_check.setChecked(True)\n                window.start_recording()\n                self.assertTrue(window._record.recorder.swallow)\n                self.assertTrue(window._record.overlay._swallow)\n\n                window._record.recorder._events.extend([_down(1.0, 1, 1), _up(1.05, 1, 1)])\n                window._record.ask_how_to_apply = lambda summary: "discard"\n                window.stop_recording()\n                self.assertFalse(window._record.recording)\n            finally:\n                window._shutdown()\n                self.app.processEvents()\n\n    def test_recording_is_refused_while_engine_runs(self):\n        from unittest import mock\n\n        from app.input.sendinput import SendInputBackend\n        from app.storage.config import ProfileStore\n        from app.ui.main_window import MainWindow\n        from app.ui.run_controller import RunController\n        from app.win.hotkey import HotkeyManager\n\n        with tempfile.TemporaryDirectory() as tmp:\n            store = ProfileStore(Path(tmp))\n            window = MainWindow(SendInputBackend(), HotkeyManager(self.app), store=store)\n            try:\n                # 让回放看起来正在跑，但不动真线程\n                with mock.patch.object(\n                    RunController, "running", new_callable=mock.PropertyMock, return_value=True\n                ):\n                    with mock.patch("app.ui.recording_controller.QMessageBox") as box:\n                        window.start_recording()\n                    self.assertFalse(window._record.recording)\n                    self.assertFalse(window._record.recorder.recording)\n                    box.warning.assert_not_called()  # 只提示日志，不弹窗\n            finally:\n                window._shutdown()\n                self.app.processEvents()\n\n    def test_toggle_recording(self):\n        from app.input.sendinput import SendInputBackend\n        from app.storage.config import ProfileStore\n        from app.ui.main_window import MainWindow\n        from app.win.hotkey import HotkeyManager\n\n        with tempfile.TemporaryDirectory() as tmp:\n            store = ProfileStore(Path(tmp))\n            window = MainWindow(SendInputBackend(), HotkeyManager(self.app), store=store)\n            try:\n                window._hotkey_ready[2] = True\n                window.toggle_recording()\n                self.assertTrue(window._record.recording)\n                self.assertTrue(window._record.recorder.recording)\n\n                window._record.recorder._events.extend([_down(1.0, 3, 4), _up(1.05, 3, 4)])\n                window._record.ask_how_to_apply = lambda summary: "discard"\n                window.toggle_recording()\n                self.assertFalse(window._record.recording)\n                self.assertFalse(window._record.recorder.recording)\n            finally:\n                window._shutdown()\n                self.app.processEvents()\n\n    def test_main_window_exposes_record_controls(self):\n        from app.input.sendinput import SendInputBackend\n        from app.storage.config import ProfileStore\n        from app.ui.main_window import MainWindow\n        from app.win.hotkey import HotkeyManager\n\n        with tempfile.TemporaryDirectory() as tmp:\n            store = ProfileStore(Path(tmp))\n            window = MainWindow(SendInputBackend(), HotkeyManager(self.app), store=store)\n            try:\n                self.assertIn("录制", window._record_button.text())\n                self.assertTrue(window._record_moves_check.isChecked())\n                self.assertFalse(\n                    window._record_swallow_check.isChecked(),\n                    "默认不屏蔽输入：屏蔽后依赖上一步结果的界面就没法录了",\n                )\n                self.assertIn("F11", window.windowTitle() + window.statusBar().currentMessage())\n            finally:\n                window._shutdown()\n                self.app.processEvents()\n\n    def test_main_window_backend_switch(self):\n        """默认前台注入；勾上「后台点击」后换 PostMessage 后端，并可用绑定窗口。"""\n        from unittest import mock\n\n        from app.input import postmessage as pm\n        from app.input.sendinput import SendInputBackend\n        from app.storage.config import ProfileStore\n        from app.ui.main_window import MainWindow\n        from app.win.hotkey import HotkeyManager\n\n        with tempfile.TemporaryDirectory() as tmp:\n            foreground = SendInputBackend()\n            window = MainWindow(\n                foreground, HotkeyManager(self.app), store=ProfileStore(Path(tmp))\n            )\n            try:\n                self.assertFalse(window._background_check.isChecked())\n                self.assertIs(window._active_backend(), foreground)\n                self.assertFalse(\n                    window._bind_button.isEnabled(), "没开后台模式时绑定按钮应置灰"\n                )\n\n                window._background_check.setChecked(True)\n                self.app.processEvents()\n                backend = window._active_backend()\n                self.assertIsNot(backend, foreground)\n                self.assertEqual(backend.name, "postmessage")\n                self.assertTrue(window._bind_button.isEnabled())\n                self.assertIn("未绑定", window._bind_label.text())\n\n                # 绑定窗口：坐标点 → 顶层窗口，成功后标签显示目标\n                with mock.patch.multiple(\n                    pm,\n                    window_from_point=lambda x, y: 0x1234,\n                    is_window=lambda hwnd: True,\n                    root_window=lambda hwnd: 0x1234,\n                    describe=lambda hwnd: "记事本 [Notepad]",\n                ):\n                    window._bind_window_at(10, 10)\n                self.assertEqual(backend.bound_window, 0x1234)\n                self.assertIn("记事本", window._bind_label.text())\n\n                # start 之前会把选中的后端交给引擎\n                with mock.patch.object(window._run, "set_backend") as set_backend, mock.patch.object(\n                    window._run, "start"\n                ):\n                    window._minimize_check.setChecked(False)\n                    window.start_clicking()\n                set_backend.assert_called_once()\n                self.assertIs(set_backend.call_args.args[0], backend)\n            finally:\n                window._shutdown()\n                self.app.processEvents()\n\n    def test_main_window_assembly(self):\n        from app.input.sendinput import SendInputBackend\n        from app.storage.config import ProfileStore\n        from app.ui.main_window import MainWindow\n        from app.win.hotkey import HotkeyManager\n\n        with tempfile.TemporaryDirectory() as tmp:\n            store = ProfileStore(Path(tmp))\n            hotkeys = HotkeyManager(self.app)\n            window = MainWindow(SendInputBackend(), hotkeys, store=store)\n            try:\n                window.show()\n                self.app.processEvents()\n\n                # 首次启动应落盘默认方案\n                self.assertTrue(store.list_names())\n                self.assertTrue(window._profiles.current_name)\n\n                # 方案能被收集并校验通过\n                profile = window._profiles.collect()\n                profile.validate()\n\n                # 拾取遮罩几何应覆盖整个虚拟桌面\n                window._picker._picker._apply_geometry()\n                self.assertGreater(window._picker._picker.width(), 0)\n\n                # 未保存标记\n                window._profiles.mark_dirty()\n                self.assertIn("*", window.windowTitle())\n            finally:\n                window._shutdown()\n                self.app.processEvents()\n\n            # 退出时应自动保存，不留下未落盘内容\n            self.assertTrue(store.list_names())\n\n    # ---------------------------------------------------------------- 拆分出来的子系统\n    def test_tray_menu_forwards_signals(self):\n        """托盘菜单项 → 信号。``QAction.triggered`` 会捎带 checked 参数，必须被丢掉。"""\n        from unittest import mock\n\n        from PySide6.QtWidgets import QSystemTrayIcon, QWidget\n\n        from app.ui.tray_icon import TrayIcon\n\n        parent = QWidget()\n        with mock.patch.object(QSystemTrayIcon, "isSystemTrayAvailable", return_value=True):\n            tray = TrayIcon(parent)\n        try:\n            self.assertTrue(tray.available)\n\n            fired: list[str] = []\n            tray.restore_requested.connect(lambda: fired.append("restore"))\n            tray.start_requested.connect(lambda: fired.append("start"))\n            tray.stop_requested.connect(lambda: fired.append("stop"))\n            tray.pick_requested.connect(lambda: fired.append("pick"))\n            tray.record_toggle_requested.connect(lambda: fired.append("record"))\n            tray.quit_requested.connect(lambda: fired.append("quit"))\n\n            actions = tray.actions()\n            self.assertEqual(len(actions), 6, "六个动作，分隔线应被跳过")\n            for action in actions:\n                action.trigger()\n            self.assertEqual(\n                fired, ["restore", "start", "stop", "pick", "record", "quit"]\n            )\n\n            tray.notify_once("dup", "只弹一次")\n            tray.notify_once("dup", "不该再弹")\n            self.assertEqual(tray._notified, {"dup"})\n        finally:\n            tray.hide()\n            parent.deleteLater()\n\n    def test_tray_degrades_without_system_tray(self):\n        """没有托盘时（远程桌面等）整个对象退化成空壳，调用方不用判空。"""\n        from unittest import mock\n\n        from PySide6.QtWidgets import QSystemTrayIcon, QWidget\n\n        from app.ui.tray_icon import TrayIcon\n\n        parent = QWidget()\n        with mock.patch.object(QSystemTrayIcon, "isSystemTrayAvailable", return_value=False):\n            tray = TrayIcon(parent)\n        try:\n            self.assertFalse(tray.available)\n            self.assertEqual(tray.actions(), [])\n            tray.notify("没有托盘时应当静默")\n            tray.notify_once("k", "同上")\n            tray.hide()\n        finally:\n            parent.deleteLater()\n\n    def test_profile_controller_recording_landing(self):\n        """录制落地：replace 连运行参数一起换；append 只追加并保留用户调好的轮数。"""\n        from app.input.sendinput import SendInputBackend\n        from app.storage.config import ProfileStore\n        from app.ui.main_window import MainWindow\n        from app.win.hotkey import HotkeyManager\n\n        with tempfile.TemporaryDirectory() as tmp:\n            window = MainWindow(\n                SendInputBackend(), HotkeyManager(self.app), store=ProfileStore(Path(tmp))\n            )\n            try:\n                recorded = Profile(\n                    name="录制方案",\n                    steps=[ClickStep(x=5, y=6), ClickStep(x=7, y=8)],\n                    repeat=1,\n                    repeat_delay_ms=0,\n                    start_delay_ms=500,\n                )\n\n                window._repeat_spin.setValue(3)\n                window._profiles.set_dirty(False)\n                window._profiles.apply_recording(recorded, "replace")\n                self.assertEqual(len(window._editor.steps()), 2)\n                self.assertEqual(window._repeat_spin.value(), 1, "替换模式应连运行参数一起换")\n                self.assertTrue(window._profiles.dirty, "录制落地后必然有未保存改动")\n\n                window._repeat_spin.setValue(3)\n                window._profiles.apply_recording(recorded, "append")\n                self.assertEqual(len(window._editor.steps()), 4)\n                self.assertEqual(window._repeat_spin.value(), 3, "追加模式不该动用户调好的轮数")\n                self.assertEqual(window._editor.current_row(), 2, "光标该停在新增的第一行")\n            finally:\n                window._shutdown()\n                self.app.processEvents()\n\n    def test_log_panel_pairs_handler_with_lifetime(self):\n        """handler 必须成对挂/摘，否则窗口销毁后 logging 会写进已释放的控件。"""\n        import logging as _logging\n\n        from app.ui.log_panel import LogPanel\n\n        panel = LogPanel()\n        root = _logging.getLogger()\n        before = len(root.handlers)\n        lines: list[str] = []\n        try:\n            panel.attach(lines.append)\n            panel.attach(lines.append)  # 重复挂载应被忽略\n            self.assertEqual(len(root.handlers), before + 1)\n\n            root.warning("hello")\n            self.assertTrue(any("hello" in line for line in lines))\n\n            panel.detach()\n            panel.detach()  # 重复摘除也应安全\n            self.assertEqual(len(root.handlers), before)\n\n            lines.clear()\n            root.warning("after")\n            self.assertEqual(lines, [], "摘掉之后不该再收到日志")\n        finally:\n            panel.detach()\n            panel.deleteLater()\n\n    # ---------------------------------------------------------------- 找图\n    def _pump(self, predicate, timeout=2.0):\n        """推动事件循环直到条件成立（计时器、队列信号都需要它）。"""\n        deadline = time.perf_counter() + timeout\n        while not predicate() and time.perf_counter() < deadline:\n            self.app.processEvents()\n            time.sleep(0.005)\n        return predicate()\n\n    def test_step_editor_adds_find_image_step(self):\n        from unittest import mock\n\n        from app.ui.position_picker import PickCoordinator\n        from app.ui.step_editor import StepEditor\n\n        editor = StepEditor(PickCoordinator())\n        try:\n            editor.set_steps([])\n            with mock.patch.object(StepEditor, "_open_dialog", lambda self, step: step):\n                editor.add_step(StepKind.WAIT)\n\n            self.assertEqual(len(editor.steps()), 1)\n            self.assertIsInstance(editor.steps()[0], WaitStep)\n            self.assertEqual(editor._table.item(0, 1).text(), "找图")\n            self.assertIn("未截取", editor._table.item(0, 2).text())\n        finally:\n            editor.deleteLater()\n\n    def test_find_image_dialog_shows_preview_and_roundtrips(self):\n        from app.ui.position_picker import PickCoordinator\n        from app.ui.step_dialog import StepDialog\n\n        encoded = _button_template().encode()\n        dialog = StepDialog(WaitStep(template=encoded, timeout_ms=15000), PickCoordinator())\n        try:\n            self.assertIn("40 × 20", dialog._template_hint.text())\n            self.assertIn("纯色", dialog._template_hint.text())\n            self.assertFalse(dialog._template_label.pixmap().isNull())\n\n            step = dialog.result_step()\n            self.assertIsInstance(step, WaitStep)\n            self.assertEqual(step.template, encoded)\n            self.assertEqual(step.timeout_ms, 15000)\n            step.validate()\n        finally:\n            dialog.deleteLater()\n\n    def test_find_image_dialog_warns_without_solid_area(self):\n        """模板里没有纯色横线时要提前告警，别让用户事后猜为什么找不到。"""\n        from app.ui.position_picker import PickCoordinator\n        from app.ui.step_dialog import StepDialog\n\n        dialog = StepDialog(\n            WaitStep(template=_gradient_template().encode()), PickCoordinator()\n        )\n        try:\n            self.assertIn("没有连续", dialog._template_hint.text())\n        finally:\n            dialog.deleteLater()\n\n    def test_find_image_dialog_refuses_to_save_without_template(self):\n        from unittest import mock\n\n        from app.ui.position_picker import PickCoordinator\n        from app.ui.step_dialog import StepDialog\n\n        dialog = StepDialog(WaitStep(), PickCoordinator())\n        try:\n            with mock.patch("app.ui.step_dialog.QMessageBox") as box:\n                dialog.accept()\n            self.assertTrue(box.warning.called)\n            self.assertIn("截取", box.warning.call_args[0][2])\n            self.assertEqual(dialog.result(), 0, "参数不合法时对话框不该关闭")\n        finally:\n            dialog.deleteLater()\n\n    def test_find_image_dialog_pick_uses_template_overlay(self):\n        from app.ui.position_picker import PickCoordinator\n        from app.ui.step_dialog import StepDialog\n\n        picker = PickCoordinator()\n        dialog = StepDialog(WaitStep(), picker)\n        try:\n            dialog.show()\n            dialog.pick_template()\n\n            self.assertFalse(dialog.isVisible(), "拖框时对话框必须让开")\n            self.assertTrue(picker.busy)\n\n            picker.cancel()  # 等价于用户按 Esc\n            self.assertTrue(dialog.isVisible(), "取消后应恢复对话框")\n            self.assertFalse(picker.busy)\n        finally:\n            dialog.deleteLater()\n\n    def test_find_image_dialog_test_match_reports_hit(self):\n        from unittest import mock\n\n        from app.ui.position_picker import PickCoordinator\n        from app.ui.step_dialog import StepDialog\n\n        dialog = StepDialog(\n            WaitStep(template=_button_template().encode()), PickCoordinator()\n        )\n\n        def fake_capture(picker, callback, hide_widget=None):\n            callback(_screen_with_button(origin=(-1920, -200)))\n            return True\n\n        try:\n            with mock.patch.object(\n                PickCoordinator, "capture_screen_after_hide", fake_capture\n            ), mock.patch("app.ui.step_dialog.QMessageBox") as box:\n                dialog.test_match()\n\n            self.assertTrue(box.information.called)\n            message = box.information.call_args[0][2]\n            self.assertIn("找到了", message)\n            self.assertIn("(-1850, -150)", message, "命中的应是屏幕绝对坐标")\n        finally:\n            dialog.deleteLater()\n\n    def test_find_image_dialog_test_match_explains_a_miss(self):\n        from unittest import mock\n\n        from app.ui.position_picker import PickCoordinator\n        from app.ui.step_dialog import StepDialog\n\n        dialog = StepDialog(\n            WaitStep(template=_button_template().encode()), PickCoordinator()\n        )\n\n        def fake_capture(picker, callback, hide_widget=None):\n            callback(_frame(200, 120))\n            return True\n\n        try:\n            with mock.patch.object(\n                PickCoordinator, "capture_screen_after_hide", fake_capture\n            ), mock.patch("app.ui.step_dialog.QMessageBox") as box:\n                dialog.test_match()\n\n            self.assertTrue(box.warning.called)\n            message = box.warning.call_args[0][2]\n            self.assertIn("没找到", message)\n            self.assertIn("颜色", message, "候选数为 0 时要区分「颜色都没对上」这种情况")\n        finally:\n            dialog.deleteLater()\n\n    def test_pick_coordinator_extracts_template(self):\n        """松手后要隐藏遮罩、等合成器重绘、抓图、再把请求方窗口恢复。"""\n        from unittest import mock\n\n        from app.ui import position_picker\n        from app.ui.position_picker import PickCoordinator\n        from app.win.geometry import ScreenRect\n        from PySide6.QtWidgets import QWidget\n\n        picker = PickCoordinator()\n        widget = QWidget()\n        received: list = []\n\n        def fake_capture(region=None):\n            frame = _screen_with_button()\n            return _crop_frame(frame, region.x, region.y, region.width, region.height)\n\n        try:\n            with mock.patch.object(\n                position_picker, "capture_screen", fake_capture\n            ), mock.patch.object(position_picker, "HIDE_SETTLE_MS", 0):\n                self.assertTrue(picker.request_template(received.append, hide_widget=widget))\n                self.assertTrue(picker.busy, "截取还没完成时也应算「忙」")\n\n                picker._template_picker.selected.emit(ScreenRect(*BUTTON_AT, *BUTTON_SIZE))\n                self.assertTrue(self._pump(lambda: bool(received)))\n\n            self.assertEqual((received[0].width, received[0].height), BUTTON_SIZE)\n            self.assertEqual(received[0].data, _button_template().data)\n            self.assertFalse(picker.busy)\n            self.assertTrue(widget.isVisible(), "截完后请求方窗口要恢复")\n        finally:\n            widget.deleteLater()\n            picker.deleteLater()\n\n    def test_pick_coordinator_reports_capture_failure(self):\n        from unittest import mock\n\n        from app.ui import position_picker\n        from app.ui.position_picker import PickCoordinator\n        from app.win.geometry import ScreenRect\n\n        def broken(region=None):\n            raise OSError("被系统拒绝")\n\n        picker = PickCoordinator()\n        failures: list[str] = []\n        canceled: list[int] = []\n        picker.failed.connect(failures.append)\n        try:\n            with mock.patch.object(position_picker, "capture_screen", broken), mock.patch.object(\n                position_picker, "HIDE_SETTLE_MS", 0\n            ):\n                picker.request_template(lambda template: None, lambda: canceled.append(1))\n                picker._template_picker.selected.emit(ScreenRect(0, 0, 30, 30))\n                self.assertTrue(self._pump(lambda: bool(failures)))\n\n            self.assertIn("截取模板失败", failures[0])\n            self.assertEqual(canceled, [1], "失败也应该让调用方收尾")\n            self.assertFalse(picker.busy)\n        finally:\n            picker.deleteLater()\n\n    def test_pick_coordinator_rejects_second_flow(self):\n        from app.ui.position_picker import PickCoordinator\n\n        picker = PickCoordinator()\n        try:\n            self.assertTrue(picker.request(lambda x, y: None))\n            self.assertFalse(\n                picker.request_template(lambda template: None), "取点期间不该再开拖框"\n            )\n            picker.cancel()\n            self.assertFalse(picker.busy)\n            self.assertTrue(picker.request_template(lambda template: None))\n            picker.cancel()\n        finally:\n            picker.deleteLater()\n\n    # ---------------------------------------------------------------- 快照\n    def test_save_frame_writes_png_with_correct_channels(self):\n        """快照的通道顺序必须是 RGB 而不是 BGR —— 画面偏蓝这种事光看大小发现不了。"""\n        from unittest import mock\n\n        from PySide6.QtGui import QImage\n\n        from app.ui import shot\n\n        with tempfile.TemporaryDirectory() as tmp:\n            with mock.patch.object(shot, "app_data_dir", lambda: Path(tmp)):\n                path = shot.save_frame(_screen_with_button())\n\n            self.assertIsNotNone(path)\n            self.assertEqual(path.suffix, ".png")\n            self.assertTrue(path.is_file())\n\n            image = QImage(str(path))\n            self.assertEqual((image.width(), image.height()), (200, 120))\n            self.assertEqual(\n                image.pixelColor(BUTTON_AT[0] + 2, BUTTON_AT[1] + 2).getRgb()[:3],\n                (0, 120, 212),\n                "BGRA 应按 RGB32 解读，而不是把蓝红调个个儿",\n            )\n\n    def test_save_frame_prunes_old_shots(self):\n        from unittest import mock\n\n        from app.ui import shot\n\n        with tempfile.TemporaryDirectory() as tmp:\n            with mock.patch.object(shot, "app_data_dir", lambda: Path(tmp)):\n                for index in range(shot.SHOT_LIMIT + 3):\n                    self.assertIsNotNone(shot.save_frame(_frame(8, 8 + index)))\n                shots = list((Path(tmp) / "shots").glob("*.png"))\n\n            self.assertLessEqual(len(shots), shot.SHOT_LIMIT)\n            self.assertGreater(len(shots), 0)\n\n    def test_save_frame_never_raises(self):\n        """落盘失败（磁盘满/权限）绝不能连带把宏打断。"""\n        from unittest import mock\n\n        from app.ui import shot\n\n        with mock.patch.object(shot, "app_data_dir", side_effect=OSError("磁盘满了")):\n            self.assertIsNone(shot.save_frame(_frame(4, 4)))\n\n\n# ==================================================================== 后台点击\nclass TestPostMessageBackend(unittest.TestCase):\n    """PostMessage 后端的消息构造与目标解析。\n\n    不真的往别的窗口投消息：把 ``post_message`` 和窗口查询函数全部换成假的，\n    只校验「发给了谁、发了什么消息、坐标换算对不对」。\n    """\n\n    def test_make_lparam_packs_client_coords(self):\n        from app.input.postmessage import _make_lparam\n\n        self.assertEqual(_make_lparam(0x0102, 0x0304), 0x03040102, "低 16 位 x、高 16 位 y")\n        # 点在客户区外时坐标为负，按 16 位截断即可，不能抛\n        self.assertEqual(_make_lparam(-1, -1), 0xFFFFFFFF)\n\n    def test_key_lparam_marks_keyup(self):\n        from app.input.postmessage import _key_lparam\n\n        down = _key_lparam(0x1E, up=False)\n        up = _key_lparam(0x1E, up=True)\n        self.assertEqual(down & 0xFFFF, 1, "重复次数应为 1")\n        self.assertEqual((down >> 16) & 0xFF, 0x1E, "lParam 里要带扫描码")\n        self.assertEqual(up - down, (1 << 30) | (1 << 31), "抬起要置 bit30/31")\n\n    def test_click_posts_move_down_up_in_client_coords(self):\n        from unittest import mock\n\n        from app.input import postmessage as pm\n\n        sent = []\n        with mock.patch.multiple(\n            pm,\n            is_window=lambda hwnd: True,\n            root_window=lambda hwnd: 0x1234,\n            describe=lambda hwnd: "目标 [TestClass]",\n            deepest_child_at=lambda base, x, y: 0x5678,\n            screen_to_client=lambda hwnd, x, y: (10, 20),\n            post_message=lambda hwnd, msg, wp=0, lp=0: sent.append((hwnd, msg, wp, lp)) or True,\n        ):\n            backend = pm.PostMessageBackend()\n            self.assertTrue(backend.bind_window(0x1234))\n            backend.click(500, 400, MouseButton.LEFT)\n\n        inner = pm._make_lparam(10, 20)\n        self.assertEqual(\n            sent,\n            [\n                (0x5678, pm.WM_MOUSEMOVE, 0, inner),\n                (0x5678, pm.WM_LBUTTONDOWN, pm.MK_LBUTTON, inner),\n                (0x5678, pm.WM_LBUTTONUP, 0, inner),\n            ],\n            "应先 WM_MOUSEMOVE 再按下/抬起，并投递给该点下最内层的子窗口",\n        )\n\n    def test_click_uses_button_specific_messages(self):\n        from unittest import mock\n\n        from app.input import postmessage as pm\n\n        sent = []\n        with mock.patch.multiple(\n            pm,\n            is_window=lambda hwnd: True,\n            root_window=lambda hwnd: 0x10,\n            describe=lambda hwnd: "w",\n            deepest_child_at=lambda base, x, y: base,\n            screen_to_client=lambda hwnd, x, y: (0, 0),\n            post_message=lambda hwnd, msg, wp=0, lp=0: sent.append((msg, wp)) or True,\n        ):\n            backend = pm.PostMessageBackend()\n            backend.bind_window(0x10)\n            backend.click(1, 1, MouseButton.RIGHT)\n\n        self.assertEqual(\n            sent[1], (pm.WM_RBUTTONDOWN, pm.MK_RBUTTON)\n        )\n        self.assertEqual(sent[2], (pm.WM_RBUTTONUP, 0))\n\n    def test_move_to_posts_only_mousemove(self):\n        from unittest import mock\n\n        from app.input import postmessage as pm\n\n        sent = []\n        with mock.patch.multiple(\n            pm,\n            is_window=lambda hwnd: True,\n            root_window=lambda hwnd: 0x10,\n            describe=lambda hwnd: "w",\n            deepest_child_at=lambda base, x, y: base,\n            screen_to_client=lambda hwnd, x, y: (7, 8),\n            post_message=lambda hwnd, msg, wp=0, lp=0: sent.append((hwnd, msg, wp, lp)) or True,\n        ):\n            backend = pm.PostMessageBackend()\n            backend.bind_window(0x10)\n            backend.move_to(100, 200)\n\n        self.assertEqual(sent, [(0x10, pm.WM_MOUSEMOVE, 0, pm._make_lparam(7, 8))])\n\n    def test_press_key_posts_keydown_keyup_with_scancode(self):\n        from unittest import mock\n\n        from app.input import postmessage as pm\n\n        sent = []\n        with mock.patch.multiple(\n            pm,\n            is_window=lambda hwnd: True,\n            root_window=lambda hwnd: 0x10,\n            describe=lambda hwnd: "w",\n            map_virtual_key=lambda vk: 0x1E,\n            foreground_window=lambda: None,\n            post_message=lambda hwnd, msg, wp=0, lp=0: sent.append((hwnd, msg, wp, lp)) or True,\n        ):\n            backend = pm.PostMessageBackend()\n            backend.bind_window(0x10)\n            backend.press_key(0x41)\n\n        self.assertEqual(\n            sent,\n            [\n                (0x10, pm.WM_KEYDOWN, 0x41, pm._key_lparam(0x1E, up=False)),\n                (0x10, pm.WM_KEYUP, 0x41, pm._key_lparam(0x1E, up=True)),\n            ],\n        )\n\n    def test_bind_window_rejects_dead_handle(self):\n        from unittest import mock\n\n        from app.input import postmessage as pm\n\n        with mock.patch.multiple(pm, is_window=lambda hwnd: False):\n            backend = pm.PostMessageBackend()\n            self.assertFalse(backend.bind_window(0))\n            self.assertFalse(backend.bind_window(0xDEAD))\n            self.assertIsNone(backend.bound_window)\n            self.assertEqual(backend.bound_title, "")\n\n    def test_bind_window_normalizes_to_root(self):\n        from unittest import mock\n\n        from app.input import postmessage as pm\n\n        with mock.patch.multiple(\n            pm, is_window=lambda hwnd: True, root_window=lambda hwnd: 0x2200, describe=lambda hwnd: "win"\n        ):\n            backend = pm.PostMessageBackend()\n            self.assertTrue(backend.bind_window(0x22FF))\n            self.assertEqual(backend.bound_window, 0x2200, "应归一化到顶层窗口")\n            self.assertEqual(backend.bound_title, "win")\n\n    def test_bind_point_uses_window_under_cursor(self):\n        from unittest import mock\n\n        from app.input import postmessage as pm\n\n        with mock.patch.multiple(\n            pm,\n            window_from_point=lambda x, y: 0x2222,\n            is_window=lambda hwnd: True,\n            root_window=lambda hwnd: 0x2200,\n            describe=lambda hwnd: "win",\n        ):\n            backend = pm.PostMessageBackend()\n            self.assertTrue(backend.bind_point(10, 10))\n            self.assertEqual(backend.bound_window, 0x2200)\n\n    def test_unbound_click_falls_back_to_window_at_point(self):\n        """没绑定窗口时应退化为「按坐标找当时最顶层的窗口」，而不是直接失灵。"""\n        from unittest import mock\n\n        from app.input import postmessage as pm\n\n        sent = []\n        with mock.patch.multiple(\n            pm,\n            window_from_point=lambda x, y: 0x9999,\n            deepest_child_at=lambda base, x, y: base,\n            screen_to_client=lambda hwnd, x, y: (1, 2),\n            post_message=lambda hwnd, msg, wp=0, lp=0: sent.append((hwnd, msg)) or True,\n        ):\n            backend = pm.PostMessageBackend()\n            backend.click(3, 4)\n\n        self.assertEqual(len(sent), 3)\n        self.assertEqual(sent[0][0], 0x9999)\n\n    def test_no_target_warns_once_and_posts_nothing(self):\n        from unittest import mock\n\n        from app.input import postmessage as pm\n\n        sent = []\n        with mock.patch.multiple(\n            pm,\n            window_from_point=lambda x, y: None,\n            post_message=lambda *args: sent.append(args) or True,\n        ):\n            backend = pm.PostMessageBackend()\n            with self.assertLogs("app.input.postmessage", level="WARNING") as captured:\n                backend.click(1, 2)\n                backend.click(3, 4)\n\n        self.assertEqual(sent, [], "没有目标窗口时不应投递任何消息")\n        self.assertEqual(len(captured.records), 1, "同一个原因只应提醒一次，不刷屏")\n\n    def test_unbind_clears_target(self):\n        from unittest import mock\n\n        from app.input import postmessage as pm\n\n        with mock.patch.multiple(\n            pm, is_window=lambda hwnd: True, root_window=lambda hwnd: 0x10, describe=lambda hwnd: "w"\n        ):\n            backend = pm.PostMessageBackend()\n            backend.bind_window(0x10)\n            backend.unbind()\n\n        self.assertIsNone(backend.bound_window)\n        self.assertEqual(backend.bound_title, "")\n\n\nif __name__ == "__main__":\n    unittest.main(verbosity=2)\n',
    'tests/test_win_integration.py': '"""Windows 集成测试：在**真实的** Win32 窗口上验证后台点击后端。\n\n和 ``tests/test_smoke.py`` 的分工\n--------------------------------\n``TestPostMessageBackend`` 把 ``post_message`` 与窗口查询函数全换成假的，只验证\n「逻辑上发给谁、发什么消息」。本文件反过来：**真的建窗口、真的投消息、真的收消息**，\n验证 ``PostMessageBackend`` 在真实 Win32 语义下确实工作。\n\n为什么非有不可\n--------------\n``app/win/*`` 在 import 阶段就调 ``ctypes.WinDLL``，所以在 Linux / macOS 上整套后台\n点击逻辑**一行都执行不到**（``test_smoke.py`` 能跑，是因为它从假函数进去，压根没碰\n真实窗口）。本文件把这块补上：自造一个带自定义 ``WndProc`` 的顶层窗口 + 子窗口，\n断言点下去之后收到的正是 ``WM_MOUSEMOVE → WM_LBUTTONDOWN → WM_LBUTTONUP``，\n投递对象是**最内层子窗口**，``lParam`` 是**客户区坐标**。\n\n用例不依赖任何外部程序（不需要 IDEA、不需要记事本），所以任何 Windows 机器都能跑，\n也就能放进 CI（GitHub 的 ``windows-latest``，或自备的 Gitea runner）。\n\n运行\n----\n::\n\n    python tests\\\\test_win_integration.py\n\n非 Windows 上整个模块会 skip（退出码 0），不影响其它测试。\n"""\n\nfrom __future__ import annotations\n\nimport os\nimport sys\nimport time\nimport unittest\nfrom pathlib import Path\n\n_ROOT = Path(__file__).resolve().parent.parent\nif str(_ROOT) not in sys.path:\n    sys.path.insert(0, str(_ROOT))\n\nIS_WINDOWS = sys.platform == "win32"\n\n# 非 Windows 上只跳过，不去 import 任何 app.*（app/win 会在 import 时报 WinDLL 不存在）\nif IS_WINDOWS:  # pragma: no cover - Windows 分支\n    import ctypes\n    import ctypes.wintypes as wintypes\n\n    from app.input.base import MouseButton\n    from app.input.postmessage import (\n        MK_LBUTTON,\n        WM_KEYDOWN,\n        WM_KEYUP,\n        WM_LBUTTONDOWN,\n        WM_LBUTTONUP,\n        WM_MOUSEMOVE,\n        PostMessageBackend,\n    )\n    from app.win import window as winmod\n\n    _user32 = ctypes.WinDLL("user32", use_last_error=True)\n    _kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)\n\n    _HWND = wintypes.HWND\n    _HANDLE = wintypes.HANDLE\n    LRESULT = ctypes.c_ssize_t\n    WNDPROC = ctypes.WINFUNCTYPE(\n        LRESULT, wintypes.HWND, wintypes.UINT, wintypes.WPARAM, wintypes.LPARAM\n    )\n\n    # ---- 窗口样式 / 消息循环常量\n    WS_POPUP = 0x80000000\n    WS_CHILD = 0x40000000\n    WS_VISIBLE = 0x10000000\n    WS_EX_TRANSPARENT = 0x00000020\n\n    PM_REMOVE = 0x0001\n    HWND_TOPMOST = -1\n    SWP_NOSIZE = 0x0001\n    SWP_NOMOVE = 0x0002\n    SWP_NOACTIVATE = 0x0010\n\n    # ---- 原型声明\n    # 不写 argtypes 的话，Python int 会按 c_int 传，64 位下句柄会被截断——必须声明。\n    _user32.RegisterClassW.argtypes = (ctypes.c_void_p,)\n    _user32.RegisterClassW.restype = ctypes.c_ushort\n    _user32.UnregisterClassW.argtypes = (wintypes.LPCWSTR, _HANDLE)\n    _user32.UnregisterClassW.restype = wintypes.BOOL\n    _user32.CreateWindowExW.argtypes = (\n        wintypes.DWORD,\n        wintypes.LPCWSTR,\n        wintypes.LPCWSTR,\n        wintypes.DWORD,\n        ctypes.c_int,\n        ctypes.c_int,\n        ctypes.c_int,\n        ctypes.c_int,\n        _HWND,\n        _HANDLE,\n        _HANDLE,\n        ctypes.c_void_p,\n    )\n    _user32.CreateWindowExW.restype = _HWND\n    _user32.DestroyWindow.argtypes = (_HWND,)\n    _user32.DestroyWindow.restype = wintypes.BOOL\n    _user32.DefWindowProcW.argtypes = (_HWND, wintypes.UINT, wintypes.WPARAM, wintypes.LPARAM)\n    _user32.DefWindowProcW.restype = LRESULT\n    _user32.PeekMessageW.argtypes = (\n        ctypes.POINTER(wintypes.MSG),\n        _HWND,\n        wintypes.UINT,\n        wintypes.UINT,\n        wintypes.UINT,\n    )\n    _user32.PeekMessageW.restype = wintypes.BOOL\n    _user32.TranslateMessage.argtypes = (ctypes.POINTER(wintypes.MSG),)\n    _user32.TranslateMessage.restype = wintypes.BOOL\n    _user32.DispatchMessageW.argtypes = (ctypes.POINTER(wintypes.MSG),)\n    _user32.DispatchMessageW.restype = LRESULT\n    _user32.SetWindowPos.argtypes = (\n        _HWND,\n        _HWND,\n        ctypes.c_int,\n        ctypes.c_int,\n        ctypes.c_int,\n        ctypes.c_int,\n        wintypes.UINT,\n    )\n    _user32.SetWindowPos.restype = wintypes.BOOL\n    _kernel32.GetModuleHandleW.argtypes = (wintypes.LPCWSTR,)\n    _kernel32.GetModuleHandleW.restype = _HANDLE\n\n    class WNDCLASSW(ctypes.Structure):\n        _fields_ = [\n            ("style", wintypes.UINT),\n            ("lpfnWndProc", WNDPROC),\n            ("cbClsExtra", ctypes.c_int),\n            ("cbWndExtra", ctypes.c_int),\n            ("hInstance", _HANDLE),\n            ("hIcon", _HANDLE),\n            ("hCursor", _HANDLE),\n            ("hbrBackground", _HANDLE),\n            ("lpszMenuName", wintypes.LPCWSTR),\n            ("lpszClassName", wintypes.LPCWSTR),\n        ]\n\n    _MOUSE_MESSAGE_IDS = frozenset(\n        {WM_MOUSEMOVE, WM_LBUTTONDOWN, WM_LBUTTONUP, 0x0204, 0x0205, 0x0207, 0x0208}\n    )\n\n    def _as_int(value) -> int:\n        """ctypes 句柄/整数 → Python int。\n\n        直接 ``int(ctypes.c_ulong(5))`` 并不安全（ctypes 的简单类型未公开\n        ``__int__``，会被当成 bytes 去解析而抛 ``ValueError``），所以统一走\n        ``.value``——和 ``app.win.window._as_hwnd`` 是同一套写法。\n        """\n        return int(getattr(value, "value", value))\n\n    def _unpack(lparam: int) -> tuple[int, int]:\n        """把消息 ``lParam`` 还原成客户区 ``(x, y)``（低 16 位 x、高 16 位 y）。"""\n        return (lparam & 0xFFFF, (lparam >> 16) & 0xFFFF)\n\n    def _mouse_records(window: "_Window") -> list[tuple[int, int, int]]:\n        return [record for record in window.messages if record[0] in _MOUSE_MESSAGE_IDS]\n\n    def _drain(limit: int = 4096) -> int:\n        """把当前线程消息队列里的消息全部派发掉，返回派发条数。"""\n        message = wintypes.MSG()\n        dispatched = 0\n        while dispatched < limit:\n            if not _user32.PeekMessageW(ctypes.byref(message), None, 0, 0, PM_REMOVE):\n                break\n            _user32.TranslateMessage(ctypes.byref(message))\n            _user32.DispatchMessageW(ctypes.byref(message))\n            dispatched += 1\n        return dispatched\n\n    def _flush(timeout: float = 2.0) -> int:\n        """排空消息队列：一直派发，直到连续两轮都没消息可派。\n\n        ``PostMessage`` 是同线程入队，``click()`` 返回时消息已经在队列里了，\n        所以正常情况一轮就够；多留一轮空转是为了防御性地等待任何迟到的消息。\n        """\n        total = 0\n        quiet = 0\n        deadline = time.monotonic() + timeout\n        while quiet < 2 and time.monotonic() < deadline:\n            dispatched = _drain()\n            total += dispatched\n            quiet = 0 if dispatched else quiet + 1\n            if quiet:\n                time.sleep(0.005)\n        return total\n\n    class _Window:\n        """一个真实的 Win32 窗口，所有到达它的消息都记进 ``messages``。\n\n        顶层窗口用 ``WS_POPUP``：没有边框和标题栏，**客户区矩形等于窗口矩形**，\n        于是屏幕坐标与客户区坐标的换算可以精确预期，断言不会因为边框宽度飘。\n        """\n\n        _serial = 0\n\n        def __init__(\n            self,\n            *,\n            parent: "_Window | None" = None,\n            x: int = 30,\n            y: int = 30,\n            width: int = 200,\n            height: int = 150,\n            style: int | None = None,\n            ex_style: int = 0,\n            title: str = "auto-click 集成测试",\n        ) -> None:\n            _Window._serial += 1\n            self.class_name = f"AutoClickIT_{os.getpid()}_{_Window._serial}"\n            self.messages: list[tuple[int, int, int]] = []\n            self.hwnd: int | None = None\n            self._registered = False\n            self._instance = _kernel32.GetModuleHandleW(None)\n\n            @WNDPROC\n            def _wndproc(hwnd, message, wparam, lparam):\n                self.messages.append((_as_int(message), _as_int(wparam), _as_int(lparam)))\n                return _user32.DefWindowProcW(hwnd, message, wparam, lparam)\n\n            # 回调必须留引用：被 GC 回收的话下次消息进来会直接把进程打崩\n            self._wndproc = _wndproc\n\n            window_class = WNDCLASSW()\n            window_class.lpfnWndProc = _wndproc\n            window_class.hInstance = self._instance\n            window_class.lpszClassName = self.class_name\n            if not _user32.RegisterClassW(ctypes.byref(window_class)):\n                raise ctypes.WinError(ctypes.get_last_error())\n            self._registered = True\n\n            if style is None:\n                style = (WS_CHILD | WS_VISIBLE) if parent is not None else (WS_POPUP | WS_VISIBLE)\n\n            handle = _user32.CreateWindowExW(\n                ex_style,\n                self.class_name,\n                title,\n                style,\n                int(x),\n                int(y),\n                int(width),\n                int(height),\n                parent.hwnd if parent is not None else None,\n                None,\n                self._instance,\n                None,\n            )\n            if not handle:\n                error = ctypes.get_last_error()\n                self.close()\n                raise ctypes.WinError(error)\n            self.hwnd = _as_int(handle)\n\n        # ------------------------------------------------------------ 生命周期\n        def bring_to_front(self) -> None:\n            """压到 z 序顶端，保证 ``WindowFromPoint`` 能找到它（CI 里别的窗口可能挡着）。"""\n            _user32.SetWindowPos(\n                _HWND(self.hwnd),\n                ctypes.c_void_p(HWND_TOPMOST),\n                0,\n                0,\n                0,\n                0,\n                SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE,\n            )\n\n        def close(self) -> None:\n            if self.hwnd is not None:\n                _user32.DestroyWindow(_HWND(self.hwnd))\n                self.hwnd = None\n            if self._registered:\n                _user32.UnregisterClassW(self.class_name, self._instance)\n                self._registered = False\n\n        # ------------------------------------------------------------ 便利视图\n        @property\n        def mouse_records(self) -> list[tuple[int, int, int]]:\n            return _mouse_records(self)\n\n        @property\n        def mouse_messages(self) -> list[int]:\n            return [record[0] for record in self.mouse_records]\n\n        @property\n        def key_records(self) -> list[tuple[int, int, int]]:\n            return [\n                record for record in self.messages if record[0] in (WM_KEYDOWN, WM_KEYUP)\n            ]\n\n\n_SKIP_REASON = "Windows 专有：需要真实的 Win32 窗口与消息循环"\n\n\nclass _WindowTestCaseMixin:\n    """公共夹具：每个用例都有一块干净的顶层窗口。"""\n\n    def setUp(self) -> None:\n        self._windows: list = []\n        # 顶层窗口放在 (30, 30)，200x150，客户区原点即屏幕 (30, 30)\n        self.top = self._new_window(x=30, y=30, width=200, height=150)\n\n    def tearDown(self) -> None:\n        for window in reversed(self._windows):\n            try:\n                window.close()\n            except Exception:  # noqa: BLE001 - 清理失败不该盖住真正的断言失败\n                pass\n        _drain()\n\n    def _new_window(self, *args, **kwargs):\n        window = _Window(*args, **kwargs)\n        self._windows.append(window)\n        return window\n\n    def _child(self, *, x: int = 20, y: int = 30, width: int = 60, height: int = 40, **kwargs):\n        """顶层窗口客户区内 ``(x, y)`` 处的子窗口。"""\n        return self._new_window(parent=self.top, x=x, y=y, width=width, height=height, **kwargs)\n\n\n@unittest.skipUnless(IS_WINDOWS, _SKIP_REASON)\nclass TestWin32WindowHelpers(_WindowTestCaseMixin, unittest.TestCase):\n    """``app.win.window`` 里那些纯 Win32 查询函数，在真窗口上的行为。"""\n\n    def test_client_screen_roundtrip(self):\n        """客户区坐标 ↗ 屏幕坐标 ↘ 客户区坐标应原样返回。"""\n        screen = winmod.client_to_screen(self.top.hwnd, 12, 34)\n        self.assertIsNotNone(screen)\n        self.assertEqual(winmod.screen_to_client(self.top.hwnd, *screen), (12, 34))\n\n    def test_popup_client_origin_equals_window_origin(self):\n        """WS_POPUP 无边框，客户区原点应正好落在窗口左上角 (30, 30)。"""\n        self.assertEqual(winmod.screen_to_client(self.top.hwnd, 30, 30), (0, 0))\n\n    def test_root_window_normalizes_child_to_top(self):\n        child = self._child()\n        self.assertEqual(\n            winmod.root_window(child.hwnd), self.top.hwnd, "子窗口应被归一化到顶层窗口"\n        )\n\n    def test_is_window_goes_false_after_destroy(self):\n        doomed = self._new_window(x=300, y=300, width=80, height=60)\n        handle = doomed.hwnd\n        self.assertTrue(winmod.is_window(handle))\n        doomed.close()\n        self.assertFalse(winmod.is_window(handle), "窗口销毁后 IsWindow 应为假")\n\n    def test_bind_window_rejects_destroyed_handle(self):\n        """句柄失效后 ``bind_window`` 必须返回 False，而不是绑定一个死窗口。"""\n        doomed = self._new_window(x=300, y=300, width=80, height=60)\n        doomed.close()\n        backend = PostMessageBackend()\n        self.assertFalse(backend.bind_window(doomed.hwnd or 0xDEAD))\n        self.assertIsNone(backend.bound_window)\n\n    def test_deepest_child_at_descends_into_child(self):\n        """子窗口在客户区 (20, 30)，点 (25, 35) 应下钻到它。"""\n        child = self._child()\n        self.top.bring_to_front()\n        self.assertEqual(\n            winmod.deepest_child_at(self.top.hwnd, 30 + 25, 30 + 35),\n            child.hwnd,\n            "应下钻到该点下最内层的子窗口",\n        )\n\n    def test_child_window_from_point_skips_invisible_child(self):\n        """不可见子窗口上真实鼠标会穿过去，投递消息也应穿过去。"""\n        self._child(style=WS_CHILD)  # 有 WS_CHILD 但不带 WS_VISIBLE\n        self.assertEqual(winmod.child_window_from_point(self.top.hwnd, 25, 35), None)\n        self.assertEqual(winmod.deepest_child_at(self.top.hwnd, 30 + 25, 30 + 35), self.top.hwnd)\n\n    def test_child_window_from_point_skips_transparent_child(self):\n        """WS_EX_TRANSPARENT 的子窗口同样会被默认跳过。"""\n        self._child(ex_style=WS_EX_TRANSPARENT)\n        self.assertEqual(winmod.child_window_from_point(self.top.hwnd, 25, 35), None)\n        self.assertEqual(winmod.deepest_child_at(self.top.hwnd, 30 + 25, 30 + 35), self.top.hwnd)\n\n    def test_child_window_from_point_returns_none_outside_child(self):\n        self._child()\n        self.assertIsNone(\n            winmod.child_window_from_point(self.top.hwnd, 150, 120), "子窗口之外不该命中它"\n        )\n\n    def test_describe_mentions_class_name(self):\n        self.assertIn(self.top.class_name, winmod.describe(self.top.hwnd))\n\n\n@unittest.skipUnless(IS_WINDOWS, _SKIP_REASON)\nclass TestBackendOnRealWindows(_WindowTestCaseMixin, unittest.TestCase):\n    """``PostMessageBackend`` 端到端：真的投消息，真的由目标窗口的 ``WndProc`` 收下。"""\n\n    def test_click_reaches_deepest_child_with_client_coords(self):\n        """旗舰用例：点击应投给**子窗口**，且 ``lParam`` 是**子窗口的客户区坐标**。"""\n        child = self._child(x=20, y=30, width=60, height=40)\n        backend = PostMessageBackend()\n        self.assertTrue(backend.bind_window(self.top.hwnd))\n\n        # 子窗口屏幕矩形 (50, 60)-(110, 100)；取 (55, 65) → 子窗口客户区 (5, 5)\n        backend.click(30 + 25, 30 + 35, MouseButton.LEFT)\n        _flush()\n\n        self.assertEqual(\n            child.mouse_messages,\n            [WM_MOUSEMOVE, WM_LBUTTONDOWN, WM_LBUTTONUP],\n            f"子窗口应依次收到移动/按下/抬起；实际收到 {child.messages!r}",\n        )\n        self.assertEqual(self.top.mouse_records, [], "消息应直接投给子窗口，不该发给父窗口")\n\n        for record in child.mouse_records:\n            self.assertEqual(\n                _unpack(record[2]), (5, 5), "lParam 必须是相对收件窗口客户区的坐标"\n            )\n        self.assertEqual(\n            child.mouse_records[1][1], MK_LBUTTON, "按下时 wParam 应带 MK_LBUTTON"\n        )\n        self.assertEqual(child.mouse_records[2][1], 0, "抬起时 wParam 应为 0")\n\n    def test_click_outside_child_targets_parent(self):\n        child = self._child(x=20, y=30, width=60, height=40)\n        backend = PostMessageBackend()\n        backend.bind_window(self.top.hwnd)\n\n        # (150, 120) → 顶层客户区 (120, 90)，在子窗口之外\n        backend.click(150, 120, MouseButton.LEFT)\n        _flush()\n\n        self.assertEqual(child.mouse_messages, [], "子窗口之外不该命中子窗口")\n        self.assertEqual(\n            self.top.mouse_messages, [WM_MOUSEMOVE, WM_LBUTTONDOWN, WM_LBUTTONUP]\n        )\n        for record in self.top.mouse_records:\n            self.assertEqual(_unpack(record[2]), (120, 90))\n\n    def test_click_passes_through_invisible_child_covering_the_point(self):\n        """不可见子窗口盖住该点时必须穿透，消息发给父窗口（端到端复现真实命中测试）。"""\n        hidden = self._child(x=20, y=30, width=60, height=40, style=WS_CHILD)\n        backend = PostMessageBackend()\n        backend.bind_window(self.top.hwnd)\n\n        backend.click(30 + 25, 30 + 35, MouseButton.LEFT)\n        _flush()\n\n        self.assertEqual(hidden.messages, [], "不可见子窗口不该收到任何消息")\n        self.assertEqual(\n            self.top.mouse_messages, [WM_MOUSEMOVE, WM_LBUTTONDOWN, WM_LBUTTONUP]\n        )\n        for record in self.top.mouse_records:\n            self.assertEqual(\n                _unpack(record[2]), (25, 35), "穿透后坐标应按父窗口客户区换算"\n            )\n\n    def test_right_button_uses_button_specific_messages(self):\n        backend = PostMessageBackend()\n        backend.bind_window(self.top.hwnd)\n\n        backend.click(100, 100, MouseButton.RIGHT)\n        _flush()\n\n        self.assertEqual(self.top.mouse_messages, [WM_MOUSEMOVE, 0x0204, 0x0205])\n        self.assertEqual(self.top.mouse_records[1][1], 0x0002, "右键按下应带 MK_RBUTTON")\n\n    def test_move_to_posts_only_mousemove(self):\n        backend = PostMessageBackend()\n        backend.bind_window(self.top.hwnd)\n\n        backend.move_to(140, 130)\n        _flush()\n\n        self.assertEqual(self.top.mouse_messages, [WM_MOUSEMOVE])\n        self.assertEqual(_unpack(self.top.mouse_records[0][2]), (110, 100))\n\n    def test_press_key_reaches_bound_window(self):\n        """后台键盘：绑定窗口应收到带扫描码的 WM_KEYDOWN / WM_KEYUP。"""\n        backend = PostMessageBackend()\n        backend.bind_window(self.top.hwnd)\n\n        backend.press_key(0x41)  # \'A\'\n        _flush()\n\n        records = self.top.key_records\n        self.assertEqual([record[0] for record in records], [WM_KEYDOWN, WM_KEYUP])\n        self.assertEqual(records[0][1], 0x41, "wParam 应是虚拟键码")\n        self.assertEqual(records[1][1], 0x41)\n\n        scancode = winmod.map_virtual_key(0x41)\n        self.assertEqual((records[0][2] >> 16) & 0xFF, scancode, "lParam 应带扫描码")\n        self.assertEqual(records[0][2] & 0xFFFF, 1, "重复次数应为 1")\n        self.assertEqual((records[0][2] >> 30) & 0b11, 0, "按下不该有 bit30/31")\n        self.assertEqual((records[1][2] >> 30) & 0b11, 0b11, "抬起应置 bit30/31")\n\n    def test_bind_point_normalizes_to_top_window(self):\n        """按点绑定：点在子窗口上，也应归一化绑定到顶层窗口。"""\n        child = self._child(x=20, y=30, width=60, height=40)\n        self.top.bring_to_front()\n\n        found = winmod.window_from_point(55, 65)\n        if found not in {self.top.hwnd, child.hwnd}:\n            self.skipTest(\n                f"(55, 65) 被别的窗口占用（class={winmod.class_name(found) if found else None}），"\n                "这是环境问题，不是被测代码的问题"\n            )\n\n        backend = PostMessageBackend()\n        self.assertTrue(backend.bind_point(55, 65))\n        self.assertEqual(backend.bound_window, self.top.hwnd, "bind_point 应归一化到顶层窗口")\n        self.assertIn(self.top.class_name, backend.bound_title)\n\n    def test_unbound_click_falls_back_to_window_under_point(self):\n        """没绑定时退化为「按屏幕坐标找当时最顶层的窗口」，而不是直接失灵。"""\n        self.top.bring_to_front()\n        if winmod.window_from_point(100, 110) != self.top.hwnd:\n            self.skipTest("(100, 110) 被别的窗口占用，这是环境问题")\n\n        backend = PostMessageBackend()\n        backend.click(100, 110, MouseButton.LEFT)\n        _flush()\n\n        self.assertEqual(\n            self.top.mouse_messages, [WM_MOUSEMOVE, WM_LBUTTONDOWN, WM_LBUTTONUP]\n        )\n        self.assertEqual(_unpack(self.top.mouse_records[0][2]), (70, 80))\n\n\nif __name__ == "__main__":\n    unittest.main(verbosity=2)\n',
}


# ============================================================
# 二进制资源（base64 硬编码）
# ============================================================
ASSETS_B64 = {
}
# <<<SYNC:END>>>

# 注意：
# 1) 这两个常量必须定义在上方标记块之后，str.index() 才会先命中真正的标记行；
# 2) 用字符串拼接构造，避免本定义行包含标记全文而造成定位歧义。
BEGIN_MARK = "# " + "<<<SYNC:BEGIN>>>"
END_MARK = "# " + "<<<SYNC:END>>>"

# sync 时遍历仓库用的排除目录（这些目录里的 .py 不该进快照）
_SKIP_DIRS = {
    "__pycache__", ".git", ".venv", "venv", "env",
    "build", "dist", ".pytest_cache", ".idea", ".vscode",
}


def _read_text(fp: Path) -> str:
    """读取文本文件，newline="" 以保留原始行尾（CRLF/LF 原样）。"""
    with open(fp, encoding="utf-8", newline="") as f:
        return f.read()


def _dump_dict(d: dict, eol: str) -> str:
    """把字典序列化成与本文件风格一致的字面量（每个键值一行）。"""
    return (
        "{" + eol
        + "".join("    %r: %r,%s" % (k, v, eol) for k, v in d.items())
        + "}"
    )


def _missing_from_snapshot(root: Path) -> list:
    """列出仓库里存在、却没被 FILES 收录的 Python 文件。

    这是给维护者兜底的：新加一个 app/ui/xxx.py 却忘了登记时，
    生成的快照会在 import 阶段直接炸，而那种报错并不好查。
    """
    missing = []
    for path in sorted(root.rglob("*.py")):
        rel = path.relative_to(root)
        if any(part in _SKIP_DIRS for part in rel.parts):
            continue
        name = rel.as_posix()
        if name == "bootstrap.py" or name in FILES:
            continue
        missing.append(name)
    return missing


def sync(verbose: bool = True) -> None:
    """用当前仓库中的最新源码刷新本脚本内嵌的 FILES / ASSETS_B64 快照。

    文件清单以本脚本中已有的键为准：只刷新内容，不自动增删文件。
    只能在原仓库目录（bootstrap.py 与源码同目录）中运行。
    """
    root = Path(__file__).resolve().parent
    self_path = Path(__file__)
    src = _read_text(self_path)

    if BEGIN_MARK not in src or END_MARK not in src:
        print("[ERROR] sync markers not found in bootstrap.py")
        sys.exit(1)

    # ---- 文本文件：按已有键刷新内容 ----
    new_files = {}
    for rel in FILES:
        fp = root / rel
        if not fp.exists():
            print("[ERROR] missing file: %s" % rel)
            sys.exit(1)
        new_files[rel] = _read_text(fp)

    # ---- 二进制资源：重新 base64 ----
    new_assets = {}
    for rel in ASSETS_B64:
        fp = root / rel
        if not fp.exists():
            print("[ERROR] missing asset: %s" % rel)
            sys.exit(1)
        new_assets[rel] = base64.b64encode(fp.read_bytes()).decode("ascii")

    changed = [rel for rel, val in new_files.items() if FILES.get(rel) != val]
    assets_changed = [
        rel for rel, val in new_assets.items() if ASSETS_B64.get(rel) != val
    ]

    # ---- 重新生成标记之间的内容 ----
    eol = "\r\n" if "\r\n" in src else "\n"
    lines = [
        BEGIN_MARK,
        "FILES = " + _dump_dict(new_files, eol),
        "",
        "",
        "# ============================================================",
        "# 二进制资源（base64 硬编码）",
        "# ============================================================",
        "ASSETS_B64 = " + _dump_dict(new_assets, eol),
        END_MARK,
    ]
    new_block = eol.join(lines)

    i = src.index(BEGIN_MARK)
    j = src.index(END_MARK)
    out = src[:i] + new_block + src[j + len(END_MARK):]

    # 统一为原文件的主流行尾，避免手工编辑产生混合行尾
    if "\r\n" in src:
        out = out.replace("\r\n", "\n").replace("\n", "\r\n")
    else:
        out = out.replace("\r\n", "\n")

    with open(self_path, "w", encoding="utf-8", newline="") as f:
        f.write(out)

    if verbose:
        print("Synced %d text files (%d changed)" % (len(new_files), len(changed)))
        for rel in changed:
            print("  ~ %s" % rel)
        print("Synced %d assets (%d changed)" % (len(new_assets), len(assets_changed)))
        for rel in assets_changed:
            print("  ~ %s" % rel)
        if not changed and not assets_changed:
            print("  (already up to date)")

        missing = _missing_from_snapshot(root)
        if missing:
            print("")
            print("[WARN] %d python file(s) exist in the repo but are NOT in the "
                  "snapshot:" % len(missing))
            for name in missing:
                print("  ! %s" % name)
            print("       add the key to FILES and run --sync again, otherwise the")
            print("       generated project will fail to import them.")


def generate(target_dir: Path, verbose: bool = True) -> list:
    """在 target_dir 下生成完整项目，返回新建文件列表。"""
    created = []

    for rel, content in FILES.items():
        fp = target_dir / rel
        if fp.exists():
            if verbose:
                print("  skip (exists)  %s" % rel)
            continue
        fp.parent.mkdir(parents=True, exist_ok=True)
        # newline="" 写入时不做行尾转换，保证与原始文件字节一致
        # （build.bat 必须是 CRLF，cmd.exe 解析多行块时依赖这一点）
        with open(fp, "w", encoding="utf-8", newline="") as f:
            f.write(content)
        created.append(rel)
        if verbose:
            print("  created       %s" % rel)

    for rel, b64 in ASSETS_B64.items():
        fp = target_dir / rel
        if fp.exists():
            if verbose:
                print("  skip (exists)  %s" % rel)
            continue
        fp.parent.mkdir(parents=True, exist_ok=True)
        fp.write_bytes(base64.b64decode(b64))
        created.append(rel)
        if verbose:
            print("  created       %s" % rel)

    return created


def main() -> int:
    if "--sync" in sys.argv:
        sync()
        return 0

    if not any(FILES.values()):
        print("[ERROR] the embedded snapshot is empty")
        print("        run `python bootstrap.py --sync` first")
        return 1

    args = [a for a in sys.argv[1:] if not a.startswith("-")]
    if args:
        target = Path(args[0]).expanduser().resolve()
    else:
        target = (Path.cwd() / "auto-clicker").resolve()

    # 目标目录里若有 bootstrap.py，说明指到了源码仓库本身：
    # 下一步会把它连同源码一起删掉，所以直接拒绝。
    if (target / "bootstrap.py").is_file():
        print("[ERROR] refusing to generate into the source checkout")
        print("        (bootstrap.py lives there; this script would delete it)")
        return 1

    print("Target: %s" % target)
    print()

    if target.exists() and any(target.iterdir()):
        print("Target directory already exists and is not empty.")
        choice = input(
            "This will DELETE EVERYTHING inside the target directory\n"
            "  (including .git/ history and any files not shipped in this snapshot).\n"
            "Type 'yes' to delete it all and regenerate: "
        ).strip().lower()
        if choice != "yes":
            print("Aborted. Nothing was changed.")
            return 0
        failures = []
        for item in target.iterdir():
            try:
                if item.is_dir():
                    shutil.rmtree(item)
                else:
                    item.unlink()
            except OSError as exc:
                failures.append("%s: %s" % (item.name, exc))
        if failures:
            # 半清状态比直接失败更危险：明确报错退出，绝不带病生成
            print("[ERROR] Failed to clear target directory:")
            for line in failures:
                print("  %s" % line)
            return 1
    else:
        target.mkdir(parents=True, exist_ok=True)

    created = generate(target)
    print()
    print("Done! Created %d files in %s" % (len(created), target))
    print()
    print("Next steps:")
    print("  cd %s" % target)
    print("  pip install -r requirements.txt")
    print("  python main.py")
    print("  # pack a single-file exe:")
    print("  build.bat")
    return 0


if __name__ == "__main__":
    sys.exit(main())
